/* 卷三的叙事结构 */
window.ARCS.push(
 {t:'随机之星', ch:'卷三 1–60', e:6, go:'xm_oasis', d:'间谍混进虚民社会：全通列车、迪喔的首都、被虚空巴士毁掉又长满植物的“绿洲”。黑金属的巨大珊瑚从天而降，“金属信徒”在暗处活动。'},
 {t:'脑灵与梦境', ch:'卷三 60–150', e:6, go:'dr_prison', d:'琳发现虚民脑中寄住着能量体“脑灵”。在梦境里，被囚禁的创造者把一条触手借给琳，沿光之大路穿过监狱、中转之地、恐惧之地。加勒市废墟决战，母球联合击退了入侵。'},
 {t:'恒星巴士', ch:'卷三 150–330', e:6, go:'v_starbus', d:'虚空传说中绕着恒星运转的巨大古老生物，本身就是一个活着的世界。琳替它找来愈石治好神经，它苏醒、复仇，成了琳的“星球要塞”。绒球的月，原来也是一头恒星巴士。'},
 {t:'南之大陆之战', ch:'卷三 330–420', e:6, go:'rq_south', d:'绒球被变幻之光笼罩。骸龙与翡翠龙远征南之冰原，印加虫群与脑灵大战，玛雅被俘又被救出，教长与玛雅原来是“创造之源”。'},
 {t:'脑灵核心', ch:'卷三 420–530', e:6, go:'v_naoling', d:'星光无法到达之地，被一层层陆地环绕的核心。虚民一百多艘战舰、恶魔、印加虫群与琳组成联军，在传送阻碍中攻进核心，脑灵“崩解”。'},
 {t:'护核者与真菌', ch:'卷三 530–750', e:7, go:'v_huhe', d:'星游者旅行到护核者之地，见到瑟与梦食；真菌经虚民的星界之门入侵母球；神民之地欢迎一切来访者；琳第一次听说了阿特兰的故乡——尔什，和它旁边的玛尔斯。'},
 {t:'连接世界', ch:'卷三 750–950', e:7, go:'v_lianjie', d:'许多世界以“门”相连、正在崩溃的巨大世界：地镜、养肢者、圆环之城、藏忆者。寄生在虚空巴士上的捕获者，记录所有合适的生物。'},
 {t:'恐惧与织梦者', ch:'卷三 950–1090', e:7, go:'v_zhimeng', d:'引力球与水球，从遥远故乡涌来的“恐惧”；愤怒即生命的怒虫；制造梦境核心的织梦者，以及让世界蒸发的蒸腾者。'},
 {t:'血雾大师', ch:'卷三 1110–1300', e:8, go:'rq_xuewu', d:'浓雾笼罩的绒球上，翡翠龙英雄血雾大师追着红色结晶冒险：翠骸龙、骸龙国度的沼泽、内林城。外来的“始境”把结晶投向绒球，翡翠龙组成了结晶排除队。'},
 {t:'镜世界', ch:'卷三 1180–1300', e:8, go:'v_jing', d:'表世界闪闪发光，弃世界堆满被抛弃之物，第三个世界藏在后面。一切都由一个叫“水银”的存在操纵——始境并不是一个种族。'},
 {t:'管道与熔毁', ch:'卷三 1250–1480', e:8, go:'mg_city', d:'学者跟着尘鳄走进巨大的管道米德加尔特：三腿柱、凝固绽放、星聚。管道外，布满裂痕的熔毁地带醒来，要把恶魔的世界当作“感染”摧毁。'},
 {t:'间谍维罗尼卡', ch:'卷三 1480–1670', e:8, go:'ex_tiangong', d:'罐装之城、尘粉世界、隐藏的工程地点、巴士藤蔓。琳的间谍扮成小孩，以“维罗尼卡”之名混进尔什的天宫学院，结识了话很多的比露。'},
 {t:'末日空间', ch:'卷三 1670–1830', e:9, go:'dr_doom', d:'尔什民的幻想与传说聚集成一个个末日空间：雾湖、吸血鬼的洋馆、曼珠沙华的庭院、甜点之地。月亮伸出桥梁，尔什被“分解”消失；天宫学院在血红的丛林上漂流。'},
 {t:'米德加尔特之旅', ch:'卷三 1720–1970', e:9, go:'v_midgard', d:'米德加尔特拖着三颗创造者的世界穿过恒星；集粒、光印、闪光生物与它们的“同神”；尖刺舰队一路逃跑。'},
 {t:'寒地与神之眼', ch:'卷三 1970–2100', e:9, go:'v_shenyan', d:'寒地的尸族与尸匠虫，灵尘像鬼魂一样飘；圆盘形的神之眼；尔什远古的暗藻冲向凝固虚空；宙螺里的鸟类起义。'},
 {t:'巴士会议与凝固', ch:'卷三 2100–2270', e:9, go:'ng_death', d:'轰天山峰上，巨型巴士聚在一起开会，宝石文明守护会议——直到一切碎裂。凝固虚空爆发，诺与琳在静止的尔什上点亮光之道；死亡战舰追杀一个又一个物种。'},
 {t:'球神与凤凰', ch:'卷三 2270–2500', e:10, go:'v_phoenix', d:'被立交桥覆盖的球神世界，光屑彗星与古战舰。恒星上的凤凰国度：推翻滚者比赛、传奇凤凰、绿噬、墟集神。雪原里戴着火把的追光生物。'},
 {t:'白色通道', ch:'卷三 2520–2670', e:10, go:'tn_sand', d:'先驱自称通道的制造者，模型沙海、守沙球与吸收石；稳定虫、边无蚀地、泥浆一族与它们的“奇迹”；无形想借尔什诞生恒古之泥。'},
 {t:'返乡之道与骨头', ch:'卷三 2670–2870', e:10, go:'bk_home', d:'返乡之道上，凤凰与藤壶礁为故乡开战；细线守护隧道之种；骨头的“神”与扭曲装置；唯一之桥上的信仰集合体；永远模拟战争的回忆巴士；沉睡的梦塑者。'},
 {t:'痛苦', ch:'卷三 2870–3010', e:11, go:'v_pain', d:'痛苦巴士制造无尽的痛苦轮回；苦钉民与恐怖寄生体；以尸体为材料的熔块，琥珀之球与永痛之王；冬创者的脑堡；群星联盟闯进“地狱”。'},
 {t:'虚空缝隙与燃星者', ch:'卷三 3010–3170', e:11, go:'v_ranxing', d:'三个虚空之间的缝隙：液体球、捕获球、模仿之星；星焰之民与焰星球、霜堡与资料库；能看到历史的燃星者。无空间带里，文明之惧游荡。'},
 {t:'奇迹之都与秩序之域', ch:'卷三 3170–3290', e:11, go:'v_haishen', d:'用燃星者残骸造出的小尔什；会变成住户建筑样式的奇迹之都；巨大的海参体内，被扭曲控制的秩序之域，众神的厅堂。'},
 {t:'梦历与希望空间', ch:'卷三 3290–3380', e:11, go:'dr_mengli', d:'骸龙在梦的泥海上扬帆，向帆上的绒球标志祷告；在希望空间里，老龙塔克认出了绒球；脱骨娃娃像黑潮一样涌来。'},
 {t:'不可预见之地', ch:'卷三 3370–3450', e:11, go:'bk_hang', d:'梦境尔什穿过细微意识的河流；碎裂的大地一直在哭泣；悬挂之城上住着只会说“天气真好”的彩云；抛弃之地的深处是抛弃之渊。'},
 {t:'领队莎琳', ch:'卷三 3450–3510', e:12, go:'bk_sarin', d:'抛弃之渊是“领队”留下的——那个领队就是莎琳。星空模拟装置、秩序之主与毁序之主；豚鼠们建造莎琳的雕像当作不迷失的灯塔。'},
 {t:'崩裂与混沌', ch:'卷三 3510–3615', e:12, go:'v_benglie', d:'崩裂虚空里的重合者与小管道；幻象世界；混合虚空的安全区；影遮与定制之环；干枯的“尔什”。'},
 {t:'静止与碰撞', ch:'卷三 3615–3702', e:12, go:'v_collide', d:'认知末日与万变之颅；颗粒生物见证了静止如何让一个虚空凝固；漂泊者之家与修补匠。星空越来越暗，两个虚空的碰撞开始了。'}
);

window.EGGS.push(
 {id:'tianding', n:'天空是有顶的', hint:'迷你尘鳄要你报暗号。暗号藏在它嘴边那个名字的名言里——去书里的搜索框说出来。', t:'迷你尘鳄要对暗号，答错两次之后，洞顶的机炮全对准了它们。学者赌了一把，报出尘鳄史上最有名的那句话——通过。后来翻到产品说明书：初始密码正是这句，功能里还有一条“监测厕所堵塞”。'},
 {id:'yaosha', n:'咬杀之道', hint:'造脑怪三句话不离一个词，多点它几下。', t:'造脑怪三句话不离“咬杀”，全书这个词出现了三百多次。树会不会咬杀？它们能当场吵起来。到了米德加尔特，熔岩般的“神”干脆开坛讲授“咬杀之道”：世上的东西只分两种，能咬杀的和不能咬杀的。'},
 {id:'shell', n:'贝壳货币', hint:'浓雾时代，血雾大师刚中了大奖。点它，再去够那份奖品。', t:'血雾大师在中奖率只有几千万分之一的抽奖坑里抽中了红结晶——往后吃成十倍胖也不愁。可那天所有东西都飘了起来，奖品也一路往天上飘，它追了十秒就喘不上气。结晶越挖越少，翡翠龙已经听“某个生物”的建议改用贝壳当钱了。'},
 {id:'zanke', n:'强盗赞克', hint:'碎石区里有一根长到云层上面的植物，顺着它一路往上爬。', t:'机器民管这根巨藤叫“赞克”：传说一个叫赞克的家伙种下一粒种子，一夜长过云层，它爬上去，从一间巨大的房子里偷了宝贝，再砍断藤蔓，让追下来的主人摔死。琳注意到故事里其实没说它是强盗……总之名字怪怪的，琳改叫它“巴士藤蔓”。'},
 {id:'goose', n:'不要烧烤', hint:'凝固虚空里有一群会说话的家禽。先闻过烧烤的味道，再去找它们。', t:'第二千章是一只鹅的尖叫开场的：学院广场上飘着香味，它喊着救命，说不要看烤鹅、不要烧烤。对它来说，看烤鹅的影像就是世上最恐怖的事。'},
 {id:'egg', n:'会分裂的煎蛋', hint:'有两个番外都和煎蛋有关，把它们都读一读。', t:'煎蛋是卷三的保留菜：聚变煎蛋、罐头里的“煎蛋”、裂变煎蛋，最后是买一个就有无数个的会分裂的煎蛋。爆哮虫一吃就卡住——后来才知道，模拟装置给它定的身份是“喜欢吃煎蛋的小机械”，所以它必须卡住。'},
 {id:'push', n:'推翻滚者比赛', hint:'凤凰的恒星旁，一群凤凰在比赛。一只接一只地给它们加油。', t:'第一位选手像陨石一样冲向地面，然后炸没了；后面的一个接一个都推不动。最后九个凤凰一起发力——那颗翻滚者真的动了，以每秒一百公里左右冲向凤凰自己的恒星，而且怎么也推不回头。解说员是一只燃烧的鸡。'},
 {id:'weather', n:'今天天气真好', hint:'悬挂之城顶上的彩云，多跟它们打几次招呼。', t:'彩云们只会互相问好、夸天气、说自己过得舒服。它们享受的一切，都是用下面悬挂之城里那些生物的美好想象换来的——而被挂着的那些，经常换。'},
 {id:'veronica', n:'维罗尼卡同学！', hint:'天宫学院里总有一个声音在喊这个名字，多点几次学院听听。', t:'全书里“维罗尼卡同学”被喊了八百多次。第一次同行，比露问它头发怎么会自己动，答案是“超能力”；问能不能一直跟着，答案是“你可能会死”——比露当成了玩笑。'},
 {id:'manzhu', n:'曼珠与沙华', hint:'末日空间里有一座开满红花的庭院，点一点，看花和叶怎么轮换。', t:'比露讲的尔什民版本：曼珠和沙华想见对方，想得快要发疯，直到一个路过的灵魂说——哪有什么沙华，不就你一个？原来每次花谢长叶，它就失忆一次，以为自己是另一个。花本来就是叶变的。'},
 {id:'salty', n:'咸点民', hint:'甜点之地的机器，快快地连用两次会怎样？', t:'已经是甜点民的居民，再被甜点机改一次，就会套上咸味的点心皮，成了“咸点民”——琳觉得这机器干脆该叫点心机。隔壁的茶会上，比露坚持说它听说过放盐的茶。'},
 {id:'vote', n:'一万票', hint:'凤凰恒星周围有一圈居住平台，一个个点过去投票。', t:'上一届的“史上最高票”是七票，主持的凤凰逼大家必须庆祝。琳的居民平台一亮相，主持人话都说不利索了：传说中的最高票——一万票，还在涨。'},
 {id:'tako2', n:'再次遇到', hint:'先在别处见过绒球，再去希望空间找那条老龙。', t:'希望空间里的塔克，一遍遍重活着自己的一生。只有第一遍遇见了绒球；之后一次次轮回，绒球再没出现，它却一直记得，还在族群里传起了对绒球的信仰。所以间谍一走近，它就觉得熟悉。'},
 {id:'faith', n:'愿绒球的光照亮前路', hint:'梦的泥海上有几艘帆船，点一艘看看帆上画着什么。', t:'骸龙用梦境塑造的帆船在泥海上航行，它们向帆上的绒球标志祷告。琳发现那团光是自己以前造出的“零”所形成的梦历。'},
 {id:'shadow', n:'无法解析', hint:'最后一个星区里有一团黑影，凑过去，再凑近一点。', t:'黑影对琳说：你到的这里只是一个角落，我真正在的地方你到不了，也不会让你到。说着它缩成了绒球大小——这是全书的最后一幕。'},
 {id:'sarin2', n:'莎琳会在这里返回', hint:'先见过起源之海的金光，再去不可预见之地尽头那间布满星空的房间。', t:'管理者们认定，琳就是那个能把莎琳叫回来的生物，把它领进布满星空的观星室：莎琳会在这里返回，试试吧。后来莎琳真的站在了那里——卷一开头挥手洒下细胞的金发小萝莉，和她放进一粒细胞里的那点意识，终于又见面了。'},
 {id:'si', n:'死！', hint:'印加虫群只会说一个词，多问它几次。', t:'琳想跟印加虫群交流，对方回过来的只有一个意思：死！于是琳让占住岩石的粉碎者一齐鼓起声囊，回了它一句——死！之后很久，这都是印加虫群唯一肯对琳说的词。'},
 {id:'bus', n:'需要转巴士', hint:'沙下有一班车，阿兹特克虫每三天坐一趟。', t:'“巴士”这个词是自己冒进琳的思绪里的，好像是一种很多生物一起搭乘的东西。于是沙下那头没有脑的巨兽成了深沙巴士：阿兹特克虫每三个昼夜搭一趟，一共六个地方。从那以后，琳见到驮着生物跑的都叫巴士——这个词全书出现了六千多次，卷一还有一章就叫《需要转巴士》。'},
 {id:'landing', n:'登陆，然后翻滚', hint:'月最近的时候，沙漠里有个离它最近的地方。', t:'月来的那一年，琳把一艘方舟改成会飞的岛，停在印加巨坑的旧址——那里离月最近——往天上打弹头。琳的标准很低：只要有一个细胞活着到达月面，就算成功。脑袋虫守着显示者的直播将信将疑：登陆以后，真的还能在上面翻滚吗？'},
 {id:'name', n:'就叫绒球好了', hint:'雪的时代，退到最远处，回头看一眼家。', t:'琳的一块小小的“碎片”漂出了大地，落在虚空里一块浮着的石头上。跑到石头另一头，琳第一次看清自己的世界：比月大得多，到处是白色的冰。有了“太阳”和“月”，它也该有个名字——起个隆重的太麻烦，看着上面白白的云和冰晶，就叫“绒球”好了。'},
 {id:'snowfluff', n:'雪做的绒球', hint:'大寒里，有一只老骸龙没有跟族群走。', t:'大寒里，骸龙们都迁走了，老塔克一个人留在碎掉的龙栖木林。它在小屋门口把雪堆成一个球，又给它捏上绒毛。看着这只雪做的绒球，它说能遇见绒球真好，然后闭上了眼睛。'},
 {id:'roar', n:'没有“闭嘴”这个词', hint:'双子岛上有个大嗓门，不嫌吵就一直点它。', t:'爆哮虫是脑袋虫的扩音器：脑袋虫的声囊吼不响，狠话都由它来喊，吼声能把天上的飞虫震下来。在它的思绪里，根本没有“累”和“闭嘴”这两个词。双子岛之战，它站在裂地者头上冲着大树喊：蒙特祖玛，翻滚着出来！'},
 {id:'dichun', n:'地蠢者', hint:'脑袋虫给恐龙大陆底下那位起了个外号。先去找脑袋虫。', t:'不知从什么时候起，脑袋虫把苏醒的创造者叫成了“地蠢者”，琳觉得挺有趣。它的宿敌蒙特祖玛只能死在它自己手里，轮不到地蠢者；真到了阵前，冲着地底吼“滚出来，可悲的地蠢者”的，照例还是爆哮虫。'},
 {id:'corner', n:'只是一个角落', hint:'把展览里的每一个世界都走一遍。', t:'卷一里，利维坦从家园树飞上夜空，琳望着看不到边的扭曲丛林，想到自己的基地也许只是其中一个小角落——世界这么大，这样才有趣呢。全书最后一幕，无法解析者对琳说的也是：你到的这里，只是一个角落。'}
);

/* 卷三：绒球上的故事 */
window.WIKI.push(
{id:'rq_south', n:'南之大陆（卷三）', c:'地理', r:'south', e:[6,7,8,9,10,11,12], ll:[-56,-14],
 s:'卷一、二里没人去过的南方。从虚空看下去，是一片白色的大陆，脑灵在南极冰原上建了基地。',
 d:'玛雅驾着战舰循着教长给的信号飞到南之大陆上空，接连被从地面射来的黑色长矛刺穿船腹——那些长矛没有任何推进的火光，却能从大地直射虚空。之后骸龙与翡翠龙组成的部队修好船舰，从南方的岛屿出发远征南之冰原；苏苏米回归并指挥翡翠龙的舰队，印加虫群也在这片冰原上与脑灵大战。脑灵消失之后，翡翠龙在南之大陆找到了大量结晶矿。',
 ch:'卷三《信号源》《登陆极地》《南极的风暴》', rel:['rq_storm','rq_blackcity','rq_platform','rq_crystalmine','maya','susumi']},
{id:'rq_storm', n:'南极的风暴 · 变幻之光', c:'现象', r:'south', e:[6], ll:[-64,-24],
 s:'笼罩绒球天空的变幻之光，从南之大陆的装置里升起。',
 d:'那段时间从虚空中看，绒球被一层不断变幻的光罩着，像极光，光是从南之大陆的装置——喷雾器里升起的，龙们在它底下精神都不正常了。翡翠龙骑着翼龙从空中平台起飞，一个个摧毁散发光芒的喷雾器；骸龙那边也解决了不少。打掉这一个，它们已经摧毁了十五个，变幻之光在轰鸣中散去，天空也终于放晴，龙们恢复正常，欢呼说是它们救下了整个世界队长却说，大陆差不多恢复了，可广阔的海上还有更多喷雾器要处理——为了王，为了这个世界的和平。',
 ch:'卷三《南极的风暴》', rel:['rq_south','rq_platform']},
{id:'rq_blackcity', n:'脑灵的黑色城市', c:'文明', r:'south', e:[6], ll:[-66,-6],
 s:'南极冰原上的脑灵基地，黑色的城市。',
 d:'脑灵是寄住在生物脑中的能量意识，它们驱使被寄生的生物在冰原上筑起漆黑的城市，并用“光团”轰炸了教长在南方岛屿上的堡垒——直到印加虫群的蠕虫反击才停下。脑灵把战舰引入梦境的陷阱，琳也在这里第一次学会抵抗被强制拖入梦境的感觉。',
 ch:'卷三《计划的过程》《登陆极地》', rel:['rq_south','dr_brainspirit','v_naoling']},
{id:'rq_platform', n:'翡翠龙的空中平台 · 火焰球', c:'文明', r:'south', e:[6], ll:[-46,-24],
 s:'翡翠龙最新的发明：在球下挂一个篮子，用火加热上方的球飞上天。',
 d:'不是每个翡翠龙都会骑翼龙，火焰球让它们也能从地面飞到空中平台上。有一次翡翠龙的士兵只能用长矛对付天上的敌人，一只翡翠龙从火焰球的篮子里跳出来，丢给队长一把传说中的弩：它们高兴的是：又能从异界拿装备了。',
 ch:'卷三《新鲜的发现》', rel:['emerald','rq_storm']},
{id:'rq_maojing', n:'毛鲸', c:'物种', r:'south', e:[6], ll:[-59,-11],
 s:'毛玉进化成的长毛鱼形生物，只有三米多长。',
 d:'冰下逃亡的通道越走越宽，地面积满温水，像一片地下湖。湖里游着毛鲸：据说是毛玉进化来的长毛鱼形生物，只有三米多长。蒙特祖玛一看见它们就明白——这湖通到外面。它抱起还没醒的玛雅潜到湖底，在一块石头旁边找到了水下通道，可就在这时，湖底冒出大串气泡，一个方形的东西从通道里浮了上来。',
 ch:'卷三《越来越深》《变化多端》', rel:['maoyu','mtzm','rq_hunzhi']},
{id:'rq_hunzhi', n:'混肢兽', c:'物种', r:'south', e:[6], ll:[-61,-17],
 s:'长着爪子、触手和腿的无鳍鱼。每一只都长得不一样。',
 d:'体长一米左右，进化来源不明，记载很少。大多数生物成年与幼体都有固定模样，混肢兽却没有：成长之后肢体数量与外貌都是“随机”的，通常三到十肢，长着爪子、触手和腿，像一条没有鳍的鱼，看着就像核信息融合出了错，却能用这些古怪的肢体敏捷地行动。它们相当凶猛：玛雅醒来正对学者说话，一头混肢兽就猛扑过去，玛雅在地上一滚躲开，翡翠龙卫兵的弩箭把它钉在了岩壁上。',
 ch:'卷三《变化多端》《行为》', rel:['rq_maojing']},
{id:'rq_crystalmine', n:'南之大陆的结晶矿', c:'地理', r:'south', e:[6,7,8], ll:[-50,-30],
 s:'脑灵消失后，翡翠龙在南之大陆挖到的大量结晶。',
 d:'翡翠龙一直以结晶为货币。南之大陆的矿让它们富了一阵，但后来结晶产量越来越低——到浓雾时代，它们已经开始改用贝壳了。',
 ch:'卷三（南之大陆篇）', rel:['rq_south','rq_xuewu','emerald']},
{id:'rq_lab3', n:'云海之峰的研究所', c:'地理', r:'east', e:[6,7,8,9,10,11,12], ll:[-6.6,73.6],
 s:'教长整天待在合金蜘蛛里研究；它的同类玛雅在这里看完了所有电影。',
 d:'琳把脑灵的大部分资料投在研究所里，让它们研究。有人怀疑：一个随机生成出来的脑袋，也能研究出东西？在一片柔软的白色上，圆滚白胖的玛雅一边翻滚一边念叨：它发现自己看的已经是最后一部电影了。和从不离开研究所的教长不同，玛雅向往一切有趣的事和探险——于是它开始造船。',
 ch:'卷三《研究小队》《向往星空》', rel:['jiaozhang','maya','rq_mayaship','cloudpeak']},
{id:'rq_mayaship', n:'玛雅的巨舰', c:'文明', r:'east', e:[6], ll:[-9,69],
 s:'照着恶魔给的图纸造出的战舰，融合了虚民与创造者的技术。',
 d:'玛雅趴在云海上读图纸，身旁的爆哮虫把它想的东西念出来：‘照着做就行，把那个装上去。’玛雅对技术本身没兴趣，但脑子足够把所有资料记下来。战舰造好后，它飞向虚空，要到那片浩瀚的世界里去翻滚。后来它在南之大陆上空遭到脑灵的长矛袭击。',
 ch:'卷三《向往星空》《信号源》', rel:['maya','baoxiao','rq_south']},
{id:'rq_tlant3', n:'学者的绒球之旅', c:'事件', r:'west', e:[6], ll:[4,-71],
 s:'虚民学者塔兰图拉驾着木质飞行器，在恐龙大陆四处考察。',
 d:'它飞过大裂谷，去了盐地——那里有极咸的生物和会尖叫的小花，它还钻到了盐的下面；去了立蝎的金字塔废墟、造脑怪的旧地，找到一份“宝藏”，结果是一颗记录之球。它在骸龙丛林里遇见了传说中的初代翡翠龙国王苏苏米，还站在一棵大树下想：这里可能就是骸龙最初的家园，塔克就是在这里死去的么？它很想挖开看看骨架还在不在，想了想还是算了，转身去下一个地方。',
 ch:'卷三《金属之内》《继续旅途》', rel:['tlant','salt','scorpion','tako','susumi']},
{id:'rq_whiteruin', n:'白骸龙废墟岛', c:'地理', r:'west', e:[6], ll:[3.5,-111],
 s:'白骸龙的旧岛成了废墟，侏儒用石板和头骨炸弹与它们周旋。',
 d:'“月的信号”传来时，白骸龙把从天而降的东西当作神来迎接，有石块载着生物升上天空——那是脑灵借着月进行的传送。白骸龙依旧相信自己“生于创造者之手”。',
 ch:'卷三（月的信号）', rel:['baihai','whiteisle','zhuru','moon_bus']},
{id:'moon_bus', n:'月是一头恒星巴士', c:'现象', r:'sea', e:[6,7,8,9,10,11,12], ll:[34,-30],
 s:'绒球的月，原来也是一头恒星巴士——被创造者攻击过、失去了意识的那种。',
 d:'月往返于两个恒星系之间，有固定的路线。很久以前月上住着大量创造者，那并不是偶然：它们是被派来“毁灭”月的，方法不是撕碎它，而是破坏它类似脑神经的结构，让它失去意识，然后在上面建立自己的生态。玛雅在月的地下看见了许多奇怪的东西，琳认为那就是月残存的器官。脑灵的战争结束后，琳在月上建起了“星界之门”。',
 ch:'卷三《恒星环绕者》《创造与绒球》《里面的谜团》', rel:['moon','v_starbus','v_gate']},
{id:'rq_mist', n:'绒之海 · 浓雾', c:'现象', r:'sea', e:[8], ll:[11,-22],
 s:'风平浪静的海上忽然漫起浓雾，从白昼一下变成黑夜。',
 d:'琳在别处研究“蒸发”的时候，绒球上发生着悠闲的事：一块十米直径、由无数绒毛构成的雪白“漂流毛玉”顺水漂着，上面坐着学者。浓雾里接连出现尖锐的石头，然后传来“嗡——”的声响。那段时间整个翡翠龙的世界都被浓雾笼罩。',
 ch:'卷三《绒之海》', rel:['rq_piaoliu','rq_xuewu','mistsea']},
{id:'rq_piaoliu', n:'漂流毛玉', c:'物种', r:'sea', e:[8], ll:[9,-17],
 s:'在海上漂流的毛玉团，直径十米，雪白一片。',
 d:'一团十米宽、雪白的东西，由无数绒毛构成，漂在海面上。大多数掠食者对这团绒毛提不起兴趣，所以它很适合搭便车。学者就坐在上面漂过了绒之海：天空湛蓝无云，海面风平浪静，它觉得今天的天气真不错——一边看，一边想着接下来该去哪里看看。',
 ch:'卷三《绒之海》', rel:['maoyu','rq_mist']},
{id:'rq_xuewu', n:'血雾大师', c:'角色', r:'north', e:[8], ll:[18,6.5],
 s:'翡翠龙的英雄。它在数千万分之一的抽奖坑里抽中了一块结晶。',
 d:'那块结晶意味着无数的财产：往后想吃啥吃啥，胖上十倍都不要紧。后来它和爆哮虫一起追着红色结晶四处冒险：浓雾丛林岛上的神殿、骸龙国度的峡谷沼泽、内林城，甚至被带到一个暗红天空的世界，在那里遇见自称“勇猛之士”的咕咕噶。它还参加过“咸甜争夺大会”——只要是新发现、没有毒的东西，都能拿去参赛。',
 ch:'卷三《飘》《这是怎么回事？》《果冻的制造者》《原形毕露》', rel:['emerald','rq_cuihai','rq_swamp','rq_neilin','v_jing']},
{id:'rq_cuihai', n:'翠骸龙', c:'物种', r:'west', e:[8], ll:[14,-46],
 s:'骸龙与翡翠龙的混血。',
 d:'骸龙与翡翠龙的混血后代，世世代代住在浓雾笼罩的骷髅岛上。学者爬上海滩时遇见一只，它并不怕这台机械，反倒很好奇，学者很快学会了它们的语言——虽然听起来每个“嘎”都一样，学者还是不小心说出了骂龙的那个。它们记不清自己的历史，只知道一直在这座危险的岛上努力活着；最近海上来了一群有很多触手、会变色的生物，专门以它们为目标，族群损失惨重——学者判断那是古鱿。一只翠骸龙一蹦一跳地带学者穿过林地，指着前方的空地告诉它：它们就在那边扎营。',
 ch:'卷三《发生了一些事》《全面袭击？》', rel:['gulong','emerald','rq_xuewu']},
{id:'rq_swamp', n:'骸龙国度的峡谷沼泽', c:'地理', r:'north', e:[8], ll:[40,6],
 s:'雪后骸龙迁到北之大陆的峡谷，峡谷末端成了一片沼泽。',
 d:'这里长着会爬树攻击的“骨架幼苗”，还有花之原野和飞龙的窝。一个被称为“长老”的生物站在百米外，看着树上几只龙拼命击打骨架幼苗，用一种翡翠龙和骸龙都不说的语言自言自语：它下令加快进攻：它们都得死，尤其是那个绿色的。',
 ch:'卷三《沼泽的幼苗》《围困》《植物与植物》', rel:['rq_gujia','canyon','gulong','rq_xuewu']},
{id:'rq_gujia', n:'骨架幼苗', c:'物种', r:'north', e:[8], ll:[41.5,5],
 s:'沼泽里的肉食植物幼苗：给自己套上真正的动物骨架，用四肢走路，还会往树上爬。',
 d:'血雾大师和三个骸龙幼仔来到一片峡谷深处的沼泽，湿地上长满绿色和棕色的小植物，零星立着十米高的大植物，每棵大植物旁边都堆着许多东西。后来树下聚满了骨架幼苗，它们只好坐在粗树枝上，烈日当空也没法挪窝。长老一声令下，幼苗的动作就变快了；血雾只能挥着树枝拼命把它们打下去，嘎嘎地喊着它们要爬上来了。',
 ch:'卷三《沼泽的幼苗》《围困》', rel:['rq_swamp']},
{id:'rq_neilin', n:'内林城', c:'文明', r:'north', e:[8], ll:[24,12],
 s:'城里长着树林的翡翠龙城市。',
 d:'树木本身也是建筑。翡翠龙从骸龙那里换来种子，都想像骸龙那样住在一棵活生生的树里，可是这些树很难种，一棵也没长成大树，只长成了歪歪曲曲的怪树——翡翠龙也没有除掉它们，于是城里就有了一道丛林。后来结晶种群从天上轰炸，中心广场被炸出一个大洞，几十个吓得发抖的翡翠龙聚在洞边，问是不是站在这里就不会挨炸。天上的声音说，这表示你们愿意加入结晶种群；有个翡翠龙小心地问起结晶化后不能生殖的事，得到的回答是：以后你们的生殖由我们统一管理，再也不用为找伴侣发愁了。',
 ch:'卷三《如何告诉同类》《无法理解的对手？》', rel:['emerald','longqimu_tree','rq_jieyu']},
{id:'rq_jieyu', n:'结晶入侵 · 结晶排除队', c:'事件', r:'north', e:[8], ll:[30,-6],
 s:'外来的“始境”把结晶投向绒球；平原上到处长出结晶。',
 d:'结晶暴风雨落下，地下的结晶毛虫想“结晶化这个世界”。始境在空中向血雾展示画面：翡翠龙的城市一座座冒着浓烟。翡翠龙成立了“结晶排除队”，在城市周边敲碎地上长出的结晶，再把满是菌类的液体洒在碎块上阻止它们再生——城市保住了，其他地方的结晶却越长越多。',
 ch:'卷三《无法理解的对手？》《继而连三》', rel:['v_jing','v_shijing','rq_neilin']}
);

