/* 卷三：虚民母球 */
window.WIKI.push(
{id:'xm_planet', n:'虚民母球', c:'地理', m:'ximin', r:'xm_main', e:[6,7], ll:[22,-20],
 s:'虚民把自己的母球变成了一块金属。除了海洋，只剩一个地方没被覆盖。',
 d:'城市挨着城市，全是金属。工厂里的“阳光”是灯模拟的，云和蓝天是立体影像，连草地都是做出来的。资料里的物种记录一条条写着：博尔巴巴兽，2551，灭绝；锤头巨隆，2517，灭绝……如今这颗星球上几乎只剩虚民一种生物。各国原本语言不同，现在慢慢统一成“全球语”，全球的虚民也越来越一模一样。虚民十个昼夜里只有一天休息日。',
 ch:'卷三《漫游》《被金属覆盖的世界》《爆炸之地》', rel:['xumin','xm_oasis','xm_ruigou','xm_diwo','xm_extinct']},
{id:'xm_ruigou', n:'瑞够', c:'文明', m:'ximin', r:'xm_main', e:[6,7], ll:[27,34],
 s:'一个中型国家，琳的间谍最初落脚的地方。',
 d:'间谍在这里漫游：工厂的水池里只养着一种长得飞快的藻类微生物，用光照催熟后加工成食品出售；街上到处是闪烁的立体影像广告，却几乎没有虚民抬头看。为了做虚币方便，间谍的包是活的。要去别的国家，必须先坐列车，再换乘全通列车。',
 ch:'卷三《漫游》《全通列车》', rel:['xm_planet','xm_train','spy']},
{id:'xm_diwo', n:'迪喔 · 首都', c:'文明', m:'ximin', r:'xm_diwo', e:[6,7], ll:[-6,-86],
 s:'第二大陆上的大国，三十多亿民口。首都号称世界十大城市之一。',
 d:'这里曾遭虚空巴士袭击，伤亡至今没有完全恢复。首都有一片空旷的区域——曾经建好的建筑被整个拔了起来。每逢虚空巴士袭击的周年纪念日，虚民都会聚集在市中心的广场上。琳觉得，虚民的哪座城市都差不多：金属的城市和大量来来往往的虚民。',
 ch:'卷三《全通列车》《爆炸之地》', rel:['xm_busattack','xm_oasis','xm_train']},
{id:'xm_train', n:'全通列车', c:'文明', m:'ximin', r:'xm_main', e:[6,7], ll:[12,-30],
 s:'横跨大陆的列车网。去国外，就得先搭上它。',
 d:'虚民的路原本都铺在地面上，车太多、地方不够，就越建越高，轨道和马路一直修到高楼之间——不少居民抱怨一开窗就是灰尘味和噪音，网上骂了很久，楼间的路却越来越多。广播提醒乘客：101站到了，请下车，再挤也不许乱来哦。车门一开，大量虚民涌下又涌上。间谍站在窗边，列车已经开到几乎能看见楼顶的高度。它要从中型国家“瑞够”去第二大陆的大国“迪喔”，就得先搭上它。',
 ch:'卷三《全通列车》', rel:['xm_ruigou','xm_diwo']},
{id:'xm_oasis', n:'绿洲', c:'地理', m:'ximin', r:'xm_diwo', e:[6,7], ll:[-16,-70],
 s:'虚空巴士袭击后留下的放射性废墟，长满了植物。被称为“世界上最后的净土”。',
 d:'当年常规武器对虚空巴士毫无作用，虚民撤空了周围城市，准备发射“90型爆弹”——可还没等发射，虚空巴士自己走了，只留下被大量放射尘污染、百年也无法居住的废墟。这就是“绿洲”的由来。它也被叫作“废墟之地”“毁灭之地”“世界之眼”“唯一一块完好的皮肤”。参观飞行器的票是三十虚币一张，排队旁边有黄牛：‘算你便宜点，五百虚币一张。’',
 ch:'卷三《爆炸之地》《绿洲》', rel:['xm_busattack','xm_planet','v_xukongbus']},
{id:'xm_busattack', n:'虚空巴士袭击', c:'事件', m:'ximin', r:'xm_diwo', e:[6], ll:[-12,-76],
 s:'虚民刚刚飞向虚空时遭遇的浩劫。',
 d:'当时虚民对虚空的探索还处于“刚刚起飞”的程度。虚空巴士杀掉了大量虚民——准确地说是吃掉，许多虚民被吸进它的体内，还有它会吃金属建筑的说法。军队对它轰炸了十几个昼夜，几座城市都被夷平了，它还是在往前走。',
 ch:'卷三《疑惑》《爆炸之地》', rel:['xm_oasis','v_xukongbus']},
{id:'xm_extinct', n:'博尔巴巴兽 · 锤头巨隆', c:'物种', m:'ximin', r:'xm_main', e:[6], ll:[24,-12],
 s:'只剩下一行资料的物种。',
 d:'在虚民的地下学院里，间谍扮成来参观的幼仔，翻看虚民的资料：“博尔巴巴兽，2551，灭绝……锤头巨隆，2517，灭绝……”一条条看下去，它明白了这颗星球为什么只剩一种生物。学院本身就是答案的一部分：阳光是灯，天空和白云是立体影像，草地是塑料，“清新空气”来自不远处的释放装置——外面常刮灰尘暴，空气太差，幼仔只能在地下长大。',
 ch:'卷三《被金属覆盖的世界》', rel:['xm_planet']},
{id:'xm_starfish', n:'小海星', c:'物种', m:'ximin', r:'xm_main', e:[6], ll:[21,42],
 s:'能传送的生物。虚民给它套上护甲，当作传送器。',
 d:'虚民在地下研究所里研究了它数百年，大部分记录都被打上“最高机密”，最机密的部分存在一台影像装置里。它和琳在“迷失之星”（也叫果冻之星）上看到的海星几乎一模一样：五根触手，冰雪般的外壳，都用小蠕虫进食。漂泊号上的传送器，以及之后的传送事故，都和它有关。',
 ch:'卷三《虚空惊遇》《怪异的交流》《突然的传送》', rel:['v_lost','xm_cube']},
{id:'xm_coral', n:'黑金属的珊瑚', c:'现象', m:'ximin', r:'xm_main', e:[6], ll:[31,22],
 s:'数百米到一公里长的巨大“珊瑚”骨架，从天而降砸进城市。',
 d:'长达数百米到一公里的巨大“珊瑚”，伴着一阵闪光凭空出现在城市上空，重重砸下：大楼倒塌，建筑被压成粉末，街上的车疯狂按喇叭却堵得水泄不通，虚民在人群里拼命往外挤，被撞倒的就再没站起来。它们大多碎裂不堪，体内的黑色长矛却完好无损。随后又出现一个像蛋一样的东西，和虚民的“加勒航天巨蛋”几乎一模一样——琳觉得那才是入侵者的主基地。还有圆锥体拖走虚民的幼仔。',
 ch:'卷三《侵略开启》《毁灭之后》《拖幼仔的小生物》', rel:['xm_jiale','xm_cube','xm_cult']},
{id:'xm_cube', n:'方块战舰', c:'文明', m:'ximin', r:'xm_main', e:[6], ll:[28,26],
 s:'两公里长的巨大方块，飘荡在城市上空。',
 d:'它的出现和海星的传送无关——琳判断它们能储藏一定的传送能量，在关键时刻再传送。“全力射击！把它轰掉！”战车、飞行器和步兵一起开火。母球联合的会议之后，城市区上空依旧飘着巨型的方块，这份寂静比战争还可怕。',
 ch:'卷三《闪光》《寄于脑中》', rel:['xm_coral','xm_union']},
{id:'xm_jiale', n:'加勒市 · 航天巨蛋', c:'地理', m:'ximin', r:'xm_main', e:[6], ll:[32,18],
 s:'天蓝色外层、布满方块结构的巨蛋，全世界只有十几座城市有这种航天设施。',
 d:'“那里是加嘞航天巨蛋。”列车从巨蛋外壳打开的大门驶进去，里面像空间站一样挤满了要飞向虚空旅游的虚民。墙大多是透明的，能看到别的房间里虚民排着队还是挤成一团往飞行器和列车上涌；飞行器装满后从外壳上打开的窗口飞出去，大多是去别处，只有列车直达虚空52区。黑金属后来复制出一模一样的“蛋”当基地，出现在城市废墟上空，下面是碎裂的珊瑚和完好无损的黑色长矛。最终的决战在加勒市的废墟里打响：黑角龙大军被多国联军压回废墟，将军让陆军停下，改用空军和导弹轰炸。',
 ch:'卷二《候车室》；卷三《第一步》《毁灭之后》《胜利的曙光》', rel:['xm_coral','xm_general']},
{id:'xm_cult', n:'黑金属团 · 金属信徒', c:'文明', m:'ximin', r:'xm_main', e:[6], ll:[24,28],
 s:'崇拜一尊雕像的团体。它们崇拜的东西，构造和自己一模一样。',
 d:'据说很多成员能直接和雕像对话，接受它的指引——那其实是寄住在脑中的“脑灵”。新闻里说军方抓到了五百名自称“金属信徒”的成员，首领正准备一场大计划。暗杀大使用的是黑色的金属箭。也有虚民认为：‘就因为我们把母球改成了金属，金属才会来毁灭我们！’这个说法很快获得了几百万的认同。',
 ch:'卷三《特别的行动》《脑中的声音》《探索》', rel:['dr_brainspirit','xm_coral']},
{id:'xm_general', n:'咕瓜将军', c:'角色', m:'ximin', r:'xm_main', e:[6,7], ll:[34,26],
 s:'穿着镶满勋章的红色服饰的老将军。',
 d:'它在会议后宣布打造新战舰去开拓殖民地：‘那边地方比我们还大，空气也新鲜……谁反对，就是跟整个族群的未来过不去！’不少民众在基地前抗议，要它停止浪费纳税者的虚币。之后它向母球联合求援，带领虚民打完黑金属之战；真菌入侵时，它也指挥了最后的决战。',
 ch:'卷三《第一步》《秘密的资料》《闪光》', rel:['xm_union','xm_jiale','xm_fungus']},
{id:'xm_union', n:'母球联合', c:'文明', m:'ximin', r:'xm_main', e:[6,7], ll:[30,10],
 s:'十多个大国组成的联合。',
 d:'虚民经历过多次战争之后，由母球上十多个大国共同建立的联盟。当初想过许多复杂的名字，最后还是选了这个最简单的。联合成立以来，母球很久没有打过仗，开会多半是为了环境和资源吵来吵去。黑金属入侵时，将军认为敌军不会马上进攻，决定去找母球联合帮忙，还把开会地点发给了绒球，希望它也来，并说明自己对虚民的态度。',
 ch:'卷三《闪光》《结果是好的》', rel:['xm_general','v_naoling']},
{id:'xm_nemo', n:'尼莫', c:'角色', m:'ximin', r:'xm_main', e:[6], ll:[27,37],
 s:'漂泊号上活下来的虚民。‘我答应过它，要活下去。’',
 d:'它穿着布满裂痕和干涸血迹的旧式护甲，最大的一道裂痕从肩膀一直延伸到腰间。它说，就因为自己答应了，对方才拼了命保护它，连命都搭上了。琳让幸存的虚民许愿；尼莫的愿望出了一点问题，但琳认为它是理智的保持者，给了它第二次机会。它很想保护自己的母球。',
 ch:'卷三《许愿需谨慎》《最后一个》《相同的想法》', rel:['xm_planet','xumin']},
{id:'xm_city', n:'虚民的城市生活', c:'文明', m:'ximin', r:'xm_main', e:[6,7], ll:[25,24],
 s:'立体影像广告、虚币、乐呵和聚变煎蛋。',
 d:'废墟外挤满了要进去的虚民：外面的要进去，里面的威胁它们会受到神的审判。小贩吆喝着乐呵和聚变煎蛋的价钱。——总有虚民瞧准机会开着小车兜售。也有不少虚民早已厌恶需要不停工作、竞争的世界，期待着世界末日的到来。',
 ch:'卷三《解决的方法》《探索》', rel:['xm_planet','xm_cult']},
{id:'xm_gate', n:'星界之门（虚民母球）', c:'文明', m:'ximin', r:'xm_diwo', e:[7], ll:[-4,-89],
 s:'广场上一扇看上去由内脏组成的半圆形大门。',
 d:'只有“内脏”才能保留传送能量，所以它和金属毫无关系。琳造了它；广场上总聚着大量虚民，只有特别身份的才能走进门里。后来虚民造出了自己的门，通往殖民地“新世界”。而被脑灵寄生的虚民，把门连到了真菌的世界。',
 ch:'卷三《新鲜的事情》《连接的物体》', rel:['xm_fungus','v_newworld','v_gate']},
{id:'xm_fungus', n:'真菌入侵母球', c:'事件', m:'ximin', r:'xm_diwo', e:[7], ll:[-2,-80],
 s:'真菌通过星界之门涌进虚民母球，金属的城市一块块变白。',
 d:'研究团报告：这种生物小得像灰尘，一落到有养分的东西上就拼命吸、拼命长，能穿透皮肤甚至一些衣物，只有封闭性的护甲才能防护，杀死它们最好用火。之后虚民研究出“真菌识别”——真菌经过星界之门时会被认出来，不会被送到新世界去。更难办的是“真菌崇拜者”：几乎都是注射过某种“疫苗”的虚民，越来越狂妄，有的跑向真菌的区域。母球逐渐变白，虚民开始迁移。',
 ch:'卷三《紧急的事件》《新的变化》《新的梦境世界？》', rel:['xm_gate','v_fungusworld','xm_deepcity','xm_general']},
{id:'xm_deepcity', n:'深海之城', c:'文明', m:'ximin', r:'xm_sea', e:[7], ll:[2,152],
 s:'建在深海管道里的城市，墙壁是号称导弹也打不破的抗压玻璃。',
 d:'‘深海的水压扛得住，导弹打过来也没事！’这则广告在居民搬进来之前几乎无时无刻地播放。一对虚民在管道墙前看见黑暗里升起一颗硕大的气泡，雄性还笑着说深海怪兽早就被电影淘汰了，“这个肯定是立体影像！”——然后，怪兽爪尖那里，裂开了一道细缝。',
 ch:'卷三《海中的生物》《接近》《海底的地震》', rel:['xm_silver','xm_fungus']},
{id:'xm_silver', n:'银鳞巨兽', c:'物种', m:'ximin', r:'xm_sea', e:[7], ll:[-4,157],
 s:'浑身银色鳞片的海中巨兽，比潜艇大三倍。',
 d:'虚民以为整片海洋早就归自己了，深海怪兽连电影里都早淘汰了。直到一对虚民在海底管道的观景墙前，看见黑暗里游出一个庞然大物：光是头就比管道还粗，二十多米，长嘴边缘露出利齿，浑身鳞甲在灯光下闪闪发亮，还有两只带长尖爪的前肢。雄性还镇定地说那一定是电影公司的立体影像。后来它用巨爪按住潜艇，爪尖嵌进合金外壳，弹头炸在身上却连一片鳞也没掉。（名字为本页所取，原文只称“巨兽”“怪兽”。）',
 ch:'卷三《海中的生物》《接近》', rel:['xm_deepcity']},
{id:'xm_farm', n:'养殖之海', c:'地理', m:'ximin', r:'xm_sea', e:[6,7], ll:[-2,140],
 s:'没被金属覆盖的海洋，也被虚民占满了。',
 d:'它们很自信：整片海早就是它们的了，不会有什么……海底有发电站之类的建筑，也有深海之城。虚民吃的主要是工厂里催熟的藻类。',
 ch:'卷三《海中的生物》《漫游》', rel:['xm_deepcity','xm_planet']}
);

window.FAUNA.push(
 {w:'xm_silver', kind:'leviathan', at:[-4,157], n:1, col:'#c8d4dc', s:6, alt:0, rad:4, e:[7], m:'ximin', swim:1},
 {w:'xm_cube', kind:'cube', at:[28,26], n:3, col:'#14161a', s:14, alt:90, rad:6, e:[6], m:'ximin'},
 {w:'xm_train', kind:'ship', at:[12,-30], n:2, col:'#d8dde2', s:3, alt:12, rad:26, e:[6,7], m:'ximin'},
 {w:'xumin', kind:'ufo', at:[24,26], n:4, col:'#d4dde3', s:2.4, alt:40, rad:8, e:[6,7], m:'ximin'}
);

/* 卷三：虚空（星区 6–8） */
window.WIKI.push(
/* ---------- 总览 ---------- */
{id:'v_void', n:'虚空', c:'地理', m:'void', r:'void', e:[6,7,8,9,10,11,12], p:[0,0,0], k:'core', kp:{r:160,c:'#8fb8ff'},
 s:'星星之间的一切。在琳看来，虚空其实就是一片大得没边的海。',
 d:'卷三以后，故事离开了绒球。琳靠传送、星游者、各种兵种在虚空中旅行，见到无数的“翻滚者”（星球）和活着的世界。这张地图把每个时代去过的地方放在一片星区里，按故事先后排开——它们之间真正的距离，往往远到无法想象。',
 ch:'卷三', rel:['v_rongqiu','v_ximin','v_starbus','v_erxi','v_midgard']},
/* ---------- 星区 6 ---------- */
{id:'v_rongqiu', n:'绒球（从虚空看）', c:'地理', m:'void', sec:6, e:[6,7,8,9,10,11,12], p:[-560,0,300], k:'planet', kp:{r:60,tex:'earth',c1:'#2f7a43',c2:'#1b5f7c',atm:'#5fa8ff',moon:1}, go:'rongqiu',
 s:'琳的母星。旅途从这里开始，也一直有兵种留在上面。',
 d:'琳在绒球世界到处都有兵种看着整个世界的发展。卷三里，绒球上依旧故事不断：南之大陆的脑灵、浓雾与结晶、血雾大师……点“进入地图”回到这颗星球。',
 ch:'卷三', rel:['rongqiu','moon_bus','rq_south']},
{id:'v_ximin', n:'虚民母球（从虚空看）', c:'地理', m:'void', sec:6, e:[6,7], p:[0,0,0], k:'planet', kp:{r:55,tex:'metal',c1:'#7c858c',c2:'#3a4a55',lights:'#ffd27a',atm:'#9fb6c8'}, go:'ximin',
 s:'一颗被金属覆盖的世界。夜面亮满了城市的灯。',
 d:'漂泊号载着琳的间谍回到这里，卷三由此开始。',
 ch:'卷二《随机之星》；卷三《第一步》', rel:['xm_planet','v_nuowa']},
{id:'v_nuowa', n:'诺瓦矿场 · 瓦砾之海', c:'地理', m:'void', sec:6, e:[6], p:[300,-20,-300], k:'rocks', kp:{r:170,n:220,s:5,c:'#8a7a68',star:'#ffd890',ring:1},
 s:'虚民太阳周围的陨石圈，一处“无法地带”。',
 d:'开往诺瓦矿场的列车上，悦耳的女声广播提醒乘客：准备好随身武器，做好上战场的准备，遇到歹徒、土匪、海盗、盗贼请全力反击，不要留情。车厢里多数虚民倒还平静，只有一位被一圈黑衣部下围着、称作“老大”的虚民看着不好惹。诺瓦矿场是最远的空间站：虚民的太阳周围漂浮着一圈被称为“瓦砾之海”的陨石带，矿场最初就是为了在这里寻找矿物而建的。后来这里掀起太空淘金热，海盗横行，一大堆不遵守法律的虚民聚集于此，有的甚至从没回过母球。',
 ch:'卷三《虚空中的矿场》《太空淘金热》', rel:['v_ximin','xumin']},
{id:'v_starbus', n:'恒星巴士 · 星球要塞', c:'地理', m:'void', sec:6, e:[6,7,8,9,10,11,12], p:[-380,60,-330], k:'planet', kp:{r:72,tex:'flesh',c1:'#6a8a52',c2:'#8a4a3a',atm:'#bfe6a0',veins:1},
 s:'绕着恒星生长的巨大古老生物——本身就是一个活着的世界。琳把它变成了自己的基地。',
 d:'母体把幼仔丢到恒星附近数十公里大的飘浮石头上，幼仔最初是史莱姆一样的变形虫，吸收石头的资源慢慢在自己身上形成一个环境——它依赖恒星，所以琳叫它“恒星巴士”。琳遇见的这一头被冻结了，地下生物正在消亡；琳找来“愈石”喂给它的免疫系统，治好了受损的神经。它苏醒后复仇，击毁了攻击它的黑金属岛屿，之后成为琳的“星球要塞”。成熟的恒星巴士会去和同类接触。',
 ch:'卷三《恒星环绕者》《治愈的方法》《复仇》《巨星之战》《星球要塞》', rel:['v_yushi','v_spike','moon_bus','v_xukongbus']},
{id:'v_spike', n:'尖刺林地 · 鼹 · 蒙奇', c:'地理', m:'void', sec:6, e:[6], p:[-300,0,-250], k:'none',
 s:'恒星巴士地底的荆棘丛林。',
 d:'鼹是这里的掠食者。鼹原本有四足着地和站立的两种，其中一种被夜里出没的生物——恒星巴士的免疫系统——灭绝了，留下的鼹至今每天用嘴拱土堵住洞穴；像莫斯一样、手特别像、因为冷而多了些毛的“蒙奇”是它们的猎物。勇者也在这里冒过险。巴士苏醒之后，丛林被岩石掩埋又清理出来，只剩满地植物残骸和一扇三米多高的大门。',
 ch:'卷三《我感觉的到》《地下的夜晚》《星球要塞》', rel:['v_starbus','c_hero']},
{id:'v_yushi', n:'愈石 · 巴士墓地', c:'地理', m:'void', sec:6, e:[6], p:[-640,-40,-120], k:'rocks', kp:{r:110,n:60,s:12,c:'#b9c9a0',glow:'#8affc0'},
 s:'能治愈恒星巴士神经的石头；年老的恒星巴士在“巴士墓地”聚集。',
 d:'恒星巴士受损的是混合结构的神经，里面有稀有材料，需要“愈石”才能修复——只要把石头交给免疫系统“吃掉”。年老的恒星巴士会往同一个地方聚集，就位后身上出现类似“星界之门”的长期传送结构，与附近几头连接在一起。琳立刻想到了连接世界。',
 ch:'卷三《治愈的方法》《巴士墓地》《漫长的周期》', rel:['v_starbus','v_lianjie']},
{id:'v_xukongbus', n:'虚空巴士 · 星游者', c:'物种', m:'void', sec:6, e:[6,7], p:[220,90,330], k:'whale', kp:{s:46,c:'#8a9aa8',glow:'#bfe6ff'},
 s:'直径十公里、在虚空中沉睡旅行的巨型生物。琳用它的神经造出了“星游者”。',
 d:'当年袭击虚民母球的就是一头虚空巴士。它能传送，能感知梦境，体内的“免疫生产器官”像二十多米长的海参，会制造或从外面抓来免疫生物。琳研究了它的传送系统，造出星界之门，又把一头虚空巴士改造成可以随意传送的“星游者”，开始了新的旅行：先确定位置，再传送过去。',
 ch:'卷三《疑惑》《一半的巴士》《出发》《路途》', rel:['xm_busattack','v_gate','v_huhe']},
{id:'v_gate', n:'星界之门', c:'琳的造物', m:'void', sec:6, e:[6,7,8], p:[-430,50,160], k:'gate', kp:{s:24,c:'#c86a6a'},
 s:'用“内脏”建成的长期传送通道。',
 d:'学会虚空巴士的传送系统后，琳造了这种门：一面巨大的半圆形大门，看上去由内脏组成——只有这种“内脏”才能保留传送能量。门原本想建在虚空中，后来建在月上和虚民母球的广场上。脑灵寄生的虚民把虚民的门连到真菌的世界，引发了真菌入侵。',
 ch:'卷三《新鲜的事情》《连接的物体》', rel:['xm_gate','moon_bus','xm_fungus']},
{id:'v_golden', n:'金色史莱姆', c:'物种', m:'void', sec:6, e:[6], p:[430,40,120], k:'blob', kp:{s:10,c:'#e8c25a'},
 s:'直径二十米、会“制造环境”的金色史莱姆。琳观察了它十年。',
 d:'直径二十米的金色史莱姆，身上的小生物会“制造环境”，琳观察了它十年的绒球时间。起初它身上长满三十厘米高的“伞树”：一根垂直的树干、巨大的伞状顶部，顶部之下结出块状物，里面的小生物就吃这个。这样的生活持续了好几年，直到琳把时间加快，才看到奇妙的变化：虫子从小丘里“种”出飘浮的球体，不停放出雾气，把整个史莱姆罩在浓雾里；雾里，金色的表面长满了软软的棕色小尖刺，像一片草原，草原间散布着大大小小的湖，几毫米大的虫子、脊椎动物和像石头的生物聚在湖边——一个完整的微型环境。',
 ch:'卷三《成长记录》《增长的金色之物》', rel:['v_starbus']},
{id:'v_prison', n:'创造者监狱', c:'地理', m:'void', sec:6, e:[6], p:[540,-30,-80], k:'planet', kp:{r:50,tex:'jungle',c1:'#4f8a46',c2:'#7a6a52',atm:'#9fe0b0'},
 s:'一颗生机盎然的翻滚者，却是关押创造者的监狱。',
 d:'平原、岩山与湖泊。对那些被‘保留’下来的生物来说，这里就是监牢，它们再也不会自由。这里有一种特别的“旋风生物”：小旋风在沼泽和岩山间缓缓飞行，自己也会成为猎物；“狂风”则是由尘土和一个核心组成、高达十米的回旋圆柱。被囚禁的创造者把一条三米长的触手交给绒球，与它同行。',
 ch:'卷三《监狱》《环境丰富的监狱》《触手可及》《狂风的传说》', rel:['c_tentacle','dr_prison','v_xuanfeng']},
{id:'v_lost', n:'迷失之星 · 果冻之星', c:'地理', m:'void', sec:6, e:[6], p:[-120,-60,480], k:'planet', kp:{r:34,tex:'jelly',c1:'#7fb0c8',c2:'#1a2430',half:1},
 s:'一面永夜、一面永昼的世界。',
 d:'因为转法特殊，这里一面永远是黑夜，一面永远是白昼，两个极端同时挂在天上。上次是琳和一位虚民舰长在传送区外偶然传送才到了这里，之后再怎么试也到不了，所以一直只有少量部队。昼夜交界处是连绵的高山，不冷不热，那位曾经的舰长就在山上建了半球形的小屋和农场，常常望着永远不变的天空感叹。上面还住着和虚民研究所里的小海星几乎一模一样的生物：海星形状、五根触手、冰雪般的外壳，也用小蠕虫进食，只是体型不同。琳一边看着虚民讨论扩建基地，一边观察着这里。',
 ch:'卷三《异结构生物》《再见迷失》', rel:['xm_starfish']},
{id:'v_icerolly', n:'冰雪翻滚者', c:'地理', m:'void', sec:6, e:[6], p:[620,30,360], k:'planet', kp:{r:32,tex:'ice',c1:'#e6f2f8',c2:'#9ab8c8',atm:'#dff4ff'},
 s:'冰封的世界，长毛的生物和避难所里的无毛生物。',
 d:'琳在探索冰雪翻滚者时，偶然发现一个通往深处的冰结洞穴，就派一个小圆盘进去，上下左右全是厚厚的冰壁。长毛生物以真菌为食；避难所里的无毛生物掌握冷冻技术，留下了一段段日记：据说它们因为一场战争离开原来的世界，在新的地方定居，后来又出了问题，只好继续往深处躲。录日记的那位自己也说不清这是在记录历史，还是别的什么——‘冷冻的历史观察者’。',
 ch:'卷三《冰雪世界的深处》《避难所》《石制的日记》', rel:['v_atlan']},
{id:'v_atlan', n:'阿特兰的漂泊空间', c:'文明', m:'void', sec:6, e:[6,7], p:[660,-60,-400], k:'station', kp:{s:22,c:'#b8a888',slab:1},
 s:'在虚空中漂泊的阿特兰。它们以为脚下的世界是活的。',
 d:'它们的家是一个长达数公里的长方块，旧金属外壳上布满出入口、窗户和突出的“码头”，码头上却一艘船也没有——看上去就是给虚民那样的无毛生物住的空间站。它们管自己叫“阿特兰”，是一个发音，没什么特别意思。和琳造的莫斯相比，最大的区别是头上有大量的毛（也有无毛的）。阿特兰原是中世纪的种族，世界末日时逃进了空间站——那空间站不是它们造的，它们是在里面从中世纪一路发展到接近虚民的技术。资源耗得太快，它们才停在虚民世界附近，坐小飞行器飞往母球；文化学家觉得那里野蛮的原住民“可以教育”。后来琳才知道，它们的故乡叫尔什。',
 ch:'卷三《漂泊的空间》《阿特兰的旅途》', rel:['v_erxi','ex_atlan','v_atlancity']},
{id:'v_junk', n:'虚空垃圾堆 · 晶蜴的国度', c:'地理', m:'void', sec:6, e:[6], p:[-720,30,350], k:'rocks', kp:{r:70,n:120,s:9,c:'#6f7378',metal:1},
 s:'一大团巨大的金属，里面住着一厘米大的晶蜴。',
 d:'晶蜴身上像结晶一样闪亮，体内是果冻般的内脏，会发出闪电般的噼啪声“咯咯”交流；它们身边的金属橄榄能在体内制造爆炸物。晶蜴把空气称为“嘎达”，认为这种无形又到处都是、会阻挠它们的东西很邪恶——直到发现封锁区里有生物依赖空气活着。',
 ch:'卷三《虚空的垃圾堆》《虚空垃圾中的原住民》《发展史》', rel:['v_jingyi']},
{id:'v_jingyi', n:'晶蜴', c:'物种', m:'void', sec:6, e:[6,7], p:[-690,60,390], k:'swarm', kp:{n:120,s:24,c:'#bff0ff'},
 s:'一厘米大的闪亮小生物。',
 d:'琳第一次见到它们，是在一堆道具中间；之后在文明平台里也见过。它们发出闪电似的声音，后退时身边的金属橄榄跟着一起退。',
 ch:'卷三《拖幼仔的小生物》《发展史》', rel:['v_junk','v_civplat']},
{id:'v_naoling', n:'脑灵核心', c:'地理', m:'void', sec:6, e:[6], p:[300,-100,640], k:'planet', kp:{r:46,tex:'dark',c1:'#1a1430',c2:'#5a3a8a',rings:3,glow:.6},
 s:'星光无法到达之地，被一层层陆地环绕的核心。',
 d:'琳把伪装成寒石的“观察石”传送到核心附近，才看清它：中心之地，外面环绕着第一层、第二层大陆。原住民“护核者”在这里守了漫长岁月，从不知道守护的意义，直到自称“脑灵”的生命出现。虚民一百多艘战舰、恶魔、印加虫群与琳组成联军，冲过传送阻碍攻进核心，脑灵“崩解”，最后还有一份详细的“战争统计”。',
 ch:'卷三《星光无法到达之地》《环绕的陆地》《原住民》《崩解》《战争统计》', rel:['dr_brainspirit','v_huhe_guard','v_guancha']},
{id:'v_huhe_guard', n:'护核者', c:'物种', m:'void', sec:6, e:[6,7,8,9,10,11,12], p:[340,-60,600], k:'none',
 s:'守护“核心”的古老生物。“非常能守护的地方”是它们的口头禅。',
 d:'它们一心只管自己的任务，直到有一天，才发现自己原来也会“惊讶”。丝线生物制造了护核者；后来琳在许多地方都遇到它们的同类。',
 ch:'卷三《原住民》《非常能守护的地方》', rel:['v_naoling','v_huhe']},
{id:'v_guancha', n:'观察石', c:'琳的造物', m:'void', sec:6, e:[6], p:[260,-70,560], k:'none',
 s:'琳最具伪装能力的兵种，模样像一块寒石。',
 d:'琳在测试怎么阻止一个区域里的传送，已经差不多弄明白了；梦境里那些隔绝空间——恐惧之地、冰原——也在核心生物的攻击下碎成了一片片。恒星巴士的神经在感知传送坐标时，也会模模糊糊地感觉到周围的区域；琳利用这一点，把观察石传送到脑灵核心‘附近’，而不是坐标本身。一个小小的物体在极寒的虚空里飞快前进，它想知道：这里离核心有多近？',
 ch:'卷三《周围的地点》', rel:['v_naoling']},
{id:'v_chuanxing', n:'穿星者', c:'琳的造物', m:'void', sec:6, e:[6], p:[120,40,180], k:'ship', kp:{s:26,c:'#4a5a52',gun:1},
 s:'炮管形的战舰，里面是琳当时威力最强的光线。',
 d:'炮口边缘一圈特制的眼睛确认目标位置。闪耀的光芒穿透黑暗的虚空，直击远方黑金属战舰的外壳。',
 ch:'卷三《再次进入梦境》', rel:['xm_cube']},
{id:'v_dreamgate', n:'通往梦境', c:'地理', m:'void', sec:6, e:[6,8,9,10,11], p:[-160,150,-560], k:'portal', kp:{c:'#9a8aff'}, go:'dream',
 s:'琳一次次被拖进、也主动进入的梦境。',
 d:'黑金属在梦境中有自己的世界，脑灵用梦境设下陷阱。点“进入地图”沿光之大路走一遍。',
 ch:'卷三', rel:['dr_road']},

/* ---------- 星区 7 ---------- */
{id:'v_huhe', n:'护核者之地', c:'地理', m:'void', sec:7, e:[7], p:[-420,0,-200], k:'planet', kp:{r:54,tex:'jungle',c1:'#2a5a3a',c2:'#6a5a42',atm:'#8affd0',glow:.15},
 s:'梦境与现实重合的古老世界：丛林小镇、会飞会自爆的榄球、灵魂的光影。',
 d:'这里曾住着干旱荒土上的智慧种族“瑟”，它们被“神明”——一个创造者——统治，几乎灭绝，最后五十个瑟随神去了新世界；“精英瑟”去附近的翻滚者发展军事，造出工厂。能吸收梦境能量的“梦食”把别的世界的梦境和生物搬到这里。琳用岩蛛、梦蛛探索，看见雾形生物袭击榄球的小镇，创造者吸取核心后苏醒。',
 ch:'卷三《护核者之地》《朦胧的世界》《猎食者》《梦食》《智能技术》', rel:['v_se','v_mengshi','v_lanqiu','v_yanzhu','v_huhe_guard']},
{id:'v_se', n:'瑟 · 精英瑟', c:'文明', m:'void', sec:7, e:[7], p:[-470,40,-150], k:'none',
 s:'护核者之地原本的智慧种族。',
 d:'瑟的飞行器能储藏梦境能量，所以它们才能乘着它飞进虚空——这项技术也是突然从它们的思绪里冒出来的。可到了新的翻滚者，它们没法增加梦境能量，甚至下不了飞行器：精英瑟一旦离开有梦境能量的地方，就像脑袋被拔掉一样。它们陷入沉思，后来有一个瑟提出办法：把飞行器里储藏梦境能量的装置拆开，做成可以携带的小装置，才得以离开——但梦境能量无法增加，也就意味着它们在新的地方无法增加同伴。',
 ch:'卷三《智能技术》《对神明的研究》', rel:['v_huhe']},
{id:'v_mengshi', n:'梦食', c:'物种', m:'void', sec:7, e:[7,8,9], p:[-360,70,-260], k:'fog', kp:{r:60,n:40,c:'#c8a8ff'},
 s:'能吸收梦境能量的能量生物。',
 d:'脑灵组建过一支阿特兰小队“梦境捕获者”，专门捕猎对梦境敏感的生物——恒星巴士、虚空巴士都在此列，但没有哪种像梦食那样特别，它们从未成功抓到过。传说梦食来自一个固体生物与飘渺生物共存的世界；织梦者的种族被梦食摧毁，自己也变成了梦食，散布在虚空中。',
 ch:'卷三《继续的计划》《梦食》《织梦》', rel:['v_huhe','v_zhimeng']},
{id:'v_lanqiu', n:'榄球', c:'物种', m:'void', sec:7, e:[7], p:[-440,-30,-130], k:'swarm', kp:{n:40,s:16,c:'#d8a85a'},
 s:'橄榄形、会飞的生物。点火，然后扑上去把自己引爆。',
 d:'护核者之地的居民：橄榄形、飘在空中，六只肢都能抓握，但因为是飘着的，每只只能带一点东西。琳的岩蛛趴在镇中心的雕像上，看它们一遍遍来祈祷，“它们要来了……必须保护我们”；后来它们一起往镇子边缘搬粘土，筑起城墙。梦境和现实在这里完全同步，在梦里，榄球是一团团影子。岩蛛还看见它们点火，再扑到火上把自己引爆；琳决定下次要在它们自杀之前抓一只活的，弄清楚为什么。',
 ch:'卷三《护核者之地》', rel:['v_huhe']},
{id:'v_yanzhu', n:'岩蛛 · 梦蛛', c:'琳的造物', m:'void', sec:7, e:[7,8], p:[-500,-60,-240], k:'none',
 s:'一米长、披着岩石甲壳的蜘蛛形兵种；梦蛛能散发影响梦境的脑波。',
 d:'岩蛛能分解矿物，靠吃石块强化和修复身体，琳造它们是想“体验”岩石生物的生态。梦蛛学的是创造者影响梦境的方式——不会像创造者那样影响巨大，但“应该能够抢一些东西”。脑越复杂的兵种越容易被发现，梦蛛在接近护核者一百多米时就暴露了。',
 ch:'卷三《护核者之地》《神秘的东西》《追寻》', rel:['v_huhe']},
{id:'v_black', n:'黑色世界', c:'地理', m:'void', sec:7, e:[7], p:[-660,60,80], k:'planet', kp:{r:26,tex:'dark',c1:'#141414',c2:'#2a2a2a'},
 s:'满地脆弱的黑色物体。',
 d:'星游者路过的一颗翻滚者。大约三成的地方铺满了黑色的东西，看上去像一大片黑色森林，但一碰就碎——琳检测后发现，它们只是大量碎屑堆出来的，和多细胞生物没什么关系。另外七成的地方，似乎还‘活着’：黑森林边缘外是一片十米高的小岩山，上面满是洞孔，偶尔会‘嗡’地响一声。',
 ch:'卷三《路途》', rel:['v_gentle','v_xukongbus']},
{id:'v_gentle', n:'温和世界', c:'地理', m:'void', sec:7, e:[7], p:[-560,-60,300], k:'planet', kp:{r:30,tex:'jelly',c1:'#4a8ad8',c2:'#2a5aa8',atm:'#9ad8ff'},
 s:'果冻一样的蓝色大地。',
 d:'一片看起来像海洋的蓝色大地，到了跟前才发现是陆地，只是软得像果冻。琳是靠星游者的随机传送找到这里的——星游者用的是修复过的虚空巴士神经系统，琳觉得那套神经的‘潜意识’会优先挑有生物的地方。这里的生物还相当兴盛，琳在这里研究了“果冻生态”。',
 ch:'卷三《温和世界》《梦境的研究》', rel:['v_black']},
{id:'v_civplat', n:'文明平台', c:'文明', m:'void', sec:7, e:[7], p:[-200,80,250], k:'station', kp:{s:28,c:'#8a9098',ball:1},
 s:'虚空中会收集周围一切的金属球。',
 d:'创造者说：“这种生物，被称之为文明平台。”那些喜欢自相残杀的“愚者”文明发展得很快，到达瓶颈也快。平台里住着焦油、晶蜴，还有一块三十米的“神的血肉”；琳在这里收集材料，造出了一公里长、一半是触手的兵种克拉肯——“虚空说到底是一片大海”。',
 ch:'卷三《梦中的交流》《里面的生物》《核心构造之地》', rel:['v_jiaoyou','v_kraken','v_jingyi']},
{id:'v_jiaoyou', n:'焦油', c:'物种', m:'void', sec:7, e:[7], p:[-170,110,220], k:'blob', kp:{s:6,c:'#1a1612'},
 s:'在零件堆里爬来爬去、身上插满零件的生物。',
 d:'像变形虫一样贴地挪动的生物，在亚种平台的狭窄通道里数量很多，琳猜它们是平台体内的原住民，从很早以前就住在这里，靠平台“分解”来访者后分到的残渣过活。它们把捡来的金属管之类的零件摆在身上，琳怀疑那是获取能量的办法；它们还能远程轰击，能把金属柱炸掉一块。岩蛛偶尔戳它一下，起初它会掉过头来瞄准，戳多了反而懒得理。',
 ch:'卷三《里面的生物》', rel:['v_civplat']},
{id:'v_kraken', n:'克拉肯', c:'琳的造物', m:'void', sec:7, e:[7,8], p:[-80,40,330], k:'squid', kp:{s:40,c:'#6a5a8a'},
 s:'一公里长、一半是触手的柔软兵种。',
 d:'琳在亚种平台里找出传送器官，再加上那里的材料，造出的新兵种：身长一公里，一半是触手，不像别的战舰，倒像一只庞大柔软的海洋生物——毕竟虚空本来就是一片大海。“克拉肯”这个名字本来就在琳的思绪里，指某种巨大的海洋生物，琳也曾拿它给绒球上的海洋生物命名。离开平台时，它从金属大地上缓缓升进满是尘雾的高空；后来它带着迷你克拉肯潜进了神民之地的禁地。',
 ch:'卷三《核心构造之地》《问题》', rel:['v_civplat','v_shenmin']},
{id:'v_fungusworld', n:'真菌的世界', c:'地理', m:'void', sec:7, e:[7,8], p:[0,-40,-420], k:'planet', kp:{r:48,tex:'fungus',c1:'#eee8f2',c2:'#b9a9c9',atm:'#f0e8ff'},
 s:'被瘟疫真菌占据的白色世界：伞状巨蘑菇、白色地毯，菌尘遮天。',
 d:'阿特兰的探险者在这里被真菌甲虫捕获。真菌通过被连错的星界之门涌入虚民母球。第二次来时，这里有一片大海，一个一公里长的物体坠入海中掀起海啸；白色、翼展一米的“洒菌鸥”成群飞起，菌尘随翅膀洒落；真菌与崇拜蒸腾者的教团交战。创造者的幼仔被关在琳战舰的水牢里。',
 ch:'卷三《白色的世界》《浓雾》《目标所在》《真菌与教团》', rel:['xm_fungus','plague','v_sajun','v_jiaotuan']},
{id:'v_sajun', n:'洒菌鸥', c:'物种', m:'void', sec:7, e:[8], p:[30,0,-380], k:'swarm', kp:{n:80,s:20,c:'#ffffff'},
 s:'像鸟一样的白色真菌生物，翼展一米。',
 d:'它们聚集在海岛边缘，飞行器一接近就成片飞起，伴随着翅膀的摆动洒下菌尘。名字是教长起的。',
 ch:'卷三《目标所在》', rel:['v_fungusworld']},
{id:'v_newworld', n:'新世界', c:'地理', m:'void', sec:7, e:[7], p:[230,40,-300], k:'planet', kp:{r:34,tex:'rock',c1:'#8a6a4a',c2:'#5a4a3a'},
 s:'虚民通过自己的星界之门开拓的殖民地，一片荒岩。',
 d:'盗贼团横行：奔疯帮（这一带最大，喜欢像疯子般狂奔，只抢一部分来保证资源稳定）、红爆团、金砂帮、滚动团……教长占了一座山洞改造成实验室，被当作敌对团体的秘密基地，不停有盗贼来攻；它发现是一个被困住的肉团在释放脑波暗示它们。',
 ch:'卷三《新世界》《袭击的持续》《团结的盗贼》《持续的影响》', rel:['xm_gate','jiaozhang']},
{id:'v_shenmin', n:'神民之地', c:'地理', m:'void', sec:7, e:[7], p:[320,-30,0], k:'rocks', kp:{r:130,n:70,s:14,c:'#9a8a78',city:1},
 s:'飘浮的岩群。它们热情地欢迎每一个来访者。',
 d:'来访者要登记文明历史、种群特点、数量、繁殖速度，还要提供细胞核信息，好安排最舒适的居所——绒球被登记为“绒球”。危险区可以采集资源；禁地像一颗小翻滚者，里面有凝胶生物“边缘眼”、幽灵护甲和血色岩壁。市长是一个“漂泊者”：不知道自己是什么生物，脑由金属和梦境能量构成。',
 ch:'卷三《欢迎来到神民之地》《加入资料》《幽灵的动作》《血色地点》', rel:['v_edgeeye','v_yuanling','v_fudao','v_kraken']},
{id:'v_edgeeye', n:'边缘眼 · 凝胶生物', c:'物种', m:'void', sec:7, e:[7], p:[360,10,40], k:'blob', kp:{s:8,c:'#8af0c8'},
 s:'它说自己是边缘的那一部分，只有自己的想法。',
 d:'凝胶生物有共同的意识，是一个整体；边缘眼却说，它是处在边缘的那一部分，只有自己的想法，所以才得了这个名字。它们遍布在重要的飘浮岩石上，负责观察、记录发生的事，再发表自己的看法。琳让探梦球给它带了一个通讯器，后来禁地停在半路，就是边缘眼告诉琳：那个“寄主”已经没那么疯了，或许还有点后悔。',
 ch:'卷三《凝胶交流》', rel:['v_shenmin']},
{id:'v_yuanling', n:'原灵', c:'文明', m:'void', sec:7, e:[7], p:[280,30,-60], k:'none',
 s:'研究梦境能量的古老分工型物种。脑灵可能因它们而生。',
 d:'脑灵是原灵生出来的一个亚种，纯粹由能量结构组成，但脑灵并不知道，原灵自己也是很久以后才发现。原灵造出了自称“神”的微型机械，几乎灭绝了制造者。线团里记载着它们毁灭的原因。',
 ch:'卷三《历史》《神的样子》《能量使用》', rel:['dr_brainspirit','v_shenmin']},
{id:'v_fudao', n:'浮岛寄主', c:'物种', m:'void', sec:7, e:[7], p:[400,-60,-40], k:'none',
 s:'唯一一种（除了裂解船）能对其他飘浮岩造成巨大影响的生物。',
 d:'神之地有无数大小不一的飘浮岩，彼此从不相撞，稳稳地悬着；除了裂解船，唯一能对它们造成巨大影响的生物就是浮岛寄主——它寄生的不是生物，而是飘浮岩。琳照着一名技术员的样子造了个间谍，混进一艘巨大的圆盘形战舰的资料库，没想到战舰突然出动，飞向禁地：市长害怕禁地里的生物，要把整个禁地轰掉。这里存着普通博物馆里看不到的资料，可神民之国的研究团队对它的繁殖和成长也所知不多；寄主之母会爆炸。琳放出把梦境感官强化到最大的“探梦球”，在禁地里感到一种和市长相当接近的梦境能量。',
 ch:'卷三《飘浮的寄生者》《问题》', rel:['v_shenmin']},
{id:'v_erxi', n:'尔什（从虚空看）', c:'地理', m:'void', sec:7, e:[7,8,9,10,11,12], p:[580,0,260], k:'planet', kp:{r:60,tex:'earth',c1:'#3f7a3a',c2:'#1a4f8a',atm:'#7fb8ff',moon:1}, go:'erxi',
 s:'阿特兰的故乡，一颗活着的巴士世界。',
 d:'琳最早是从阿特兰的回忆里认识它的。尔什附近有颗被狂沙风暴笼罩的翻滚者——玛尔斯。点“进入地图”。',
 ch:'卷三《沙尘中的历程》', rel:['ex_planet','v_mars','v_atlan']},
{id:'v_mars', n:'玛尔斯', c:'地理', m:'void', sec:7, e:[7,8], p:[720,30,420], k:'planet', kp:{r:32,tex:'sand',c1:'#b8653a',c2:'#7a3a22',atm:'#e8a070'},
 s:'尔什旁边沙尘红土的翻滚者。居民自称“玛尔斯”——战斗之神。',
 d:'当年尔什民认为它是星系里最适合居住的地方，有周全的计划移民过来，可这里整天飘洒狂沙风暴。它们说自己已经被原来的世界抛弃了：以前自称尔什的居民，现在改叫玛尔斯。地下住着“岩皮”——很可能就是古老计划送来的、经过改造的“能力者”。阿美根与艾沙的群体也在这里争地盘。',
 ch:'卷三《沙尘中的历程》《故事》《一种生物》《岩皮的记忆》《别的群体》', rel:['v_erxi','ex_ability','v_yanpi']},
{id:'v_yanpi', n:'岩皮', c:'物种', m:'void', sec:7, e:[7,8], p:[750,-10,460], k:'none',
 s:'玛尔斯地下的生物，有着微生物里的记忆。',
 d:'成群袭击玛尔斯上各个群体的岩石状生物，那些群体的武器对它们几乎没有效果。总管留下的笔记里猜测：岩皮也许就是当年计划里的能力者。琳研究了一颗金属球：脑碰到它就会放出微弱电流，激发岩皮体内的微生物，让它们“记忆分享”，所以岩皮身上才留着关于能力者的那段历史。后来在尔什的隐藏工程里，幽灵幼仔让岩皮代替尔什民替它指挥。',
 ch:'卷三《一种生物》《岩皮的记忆》《尔什的作为》', rel:['v_mars','ex_ability']},
{id:'v_lianjie', n:'连接世界', c:'地理', m:'void', sec:7, e:[7], p:[-150,0,460], k:'linked', kp:{r:70,c1:'#b8c8d8',c2:'#5a8ad8'},
 s:'许多颗翻滚者用“门”互相连接成的庞大世界——正在崩溃。',
 d:'教长说这里十分特别。门被编成一号门、二号门……地镜聚成的镜坑平原、蓝色触手地、蓝色草地平原上的养肢者、会滚的钩轮、圆环组成的巨大“城市”、把记忆装进方块的藏忆者。软体生物在执行恒星巴士的计划：分解器官，合成“遗传体”——也就是恒星巴士的幼仔。第二扇门通向一块三十米的虚空孤岛，金属做的脑袋虫正趴在上面。',
 ch:'卷三《找到它了》《探索队伍》《肢体饲养者》《圆环中的居民》《第二扇门》', rel:['v_dijing','v_yangzhi','v_yuanhuan','v_cangyi','v_yushi','v_piaofu']},
{id:'v_dijing', n:'地镜', c:'物种', m:'void', sec:7, e:[7], p:[-120,-30,420], k:'crystal', kp:{s:10,c:'#e8f4ff',mirror:1},
 s:'金字塔形的镜面生物。坑里的镜子烧焦接近之物，再把猎物吸进去。',
 d:'连接世界里“镜坑平原”的主人：整片坑洼的平原就是它们形成的，坑底的镜子会烧焦靠近的东西，再把猎物吸进去。学者一行在镜坑平原和藏着蓝色触手的“湛蓝之地”之间扎营，后来学者就站在一大片反光的镜面上，感觉特别奇怪。地镜能射出一道细小的光线照在目标身上，像用眼睛近距离观察一样获得详细情报。地下还有满是镜子的城市、地镜之王，甚至电影院。',
 ch:'卷三《探索队伍》《遭遇》', rel:['v_lianjie','v_gouluo']},
{id:'v_gouluo', n:'钩轮', c:'物种', m:'void', sec:7, e:[7], p:[-90,-50,500], k:'hookwheel', kp:{s:18,c:'#c89a88'},
 s:'像轮子一样滚动、皮肤长满倒钩的生物。',
 d:'它不想让地镜观察自己，“咕噜噜……”地朝这边滚过来。地镜没有随便攻击：“这个有危险。”“保持缓慢状态。”',
 ch:'卷三《遭遇》《到达》', rel:['v_dijing']},
{id:'v_yangzhi', n:'养肢者', c:'文明', m:'void', sec:7, e:[7], p:[-220,40,520], k:'none',
 s:'肢体是“养”出来的文明生物。',
 d:'新来到蓝色平原的文明生物，体长两到三厘米，像毛玉，偏球形多毛，自己没有肢体，只能慢慢挪；身体周围有许多“接口”，可以接上独立的、活生生的另一种生物当肢体——肢体平时养在“饲养池”里，长到成年才会被戴上，所以叫养肢者。早上戴四条满是肌肉的腿去疾奔捕猎；中午换上末端长满细小触手的两肢，做工具、盖房子；夜里再戴上不能动的第三肢，把白天多余的养分压成“养分球”存进去。双方离了对方都活不下去，但聪明的养肢者是主导者，一直想培育出更强的新肢体。',
 ch:'卷三《肢体饲养者》', rel:['v_lianjie','maoyu']},
{id:'v_yuanhuan', n:'圆环之城', c:'物种', m:'void', sec:7, e:[7], p:[-260,-20,380], k:'ring', kp:{r:22,n:7,c:'#c8b088'},
 s:'由大量圆环组成的巨大生物，体内住着微小文明。',
 d:'连接世界里有许多微小文明：居民不过一厘米大小，社会复杂，却只守着地下或某个厚重物体里的一小块安全地带，想出去看看又不敢——只有“隙虫”学会了改造别的生物当载体。传说里有一种巨大的生物，专为它们而来：它由大量圆环组成，看起来像蠕虫，其实不是。它遇到微小文明就吞进去，用体内细小的肢体和复杂的分辨系统把杂物和文明生物分开、分类，从此居民就住在它体内，于是有些微小文明干脆把它叫作“圆环之城”。',
 ch:'卷三《圆环中的居民》《了解》', rel:['v_lianjie']},
{id:'v_cangyi', n:'藏忆者', c:'文明', m:'void', sec:7, e:[7], p:[-30,60,520], k:'none',
 s:'连接世界里的微型战争文明，记忆被智能机械装进方块。',
 d:'它们能制造许多机械工具，但无法站到高处，只占据一部分区域生活，生活地点和地镜有些重叠。',
 ch:'卷三《文明的变化》', rel:['v_lianjie']},
{id:'v_piaofu', n:'飘浮岩地', c:'地理', m:'void', sec:7, e:[7,8], p:[-680,-40,-280], k:'rocks', kp:{r:120,n:90,s:10,c:'#7a7068'},
 s:'连接世界崩溃之后的样子。',
 d:'连接世界崩溃之后的样子。脑灵的传说里，那些世界会在“最后一刻”受某种影响全部混到一起，然后毁灭，变成飘浮岩地这样的地方：上面的生物大多灭绝，只有许多非细胞类生物活下来，组成全新的环境。微型机械与黑雾团在这里活动；脑灵把用完能量的石头收集起来等它们自己充满，那些“充能”似乎与这里的微型机械有关。琳回到原灵藏在飘浮岩里的旧基地翻记录，开始怀疑微型机械的来历本就和脑灵有关。来自遥远故乡的“恐惧”化作海浪袭击飘浮岩地。',
 ch:'卷三《能量使用》《白色的世界》', rel:['v_lianjie','v_fear']},
{id:'v_buhuo', n:'捕获者', c:'文明', m:'void', sec:7, e:[7], p:[100,120,560], k:'whale', kp:{s:38,c:'#7a8a7a',station:1},
 s:'寄生在虚空巴士上的群体：它们的工作就是找到合适的生物，抓住、了解、记下来——所以它们叫捕获者。',
 d:'捕获者的战舰每个部分都是兵种；码头连着虚空巴士，还有图书馆和食物广场，一只蝽般的向导带路。阿特兰罗沙莉举办了一场庆祝：这么多种生物凑在一起吃东西，难免出乱子，它们决定先别管那些小事，先庆祝自己的语言当上了主语再说。',
 ch:'卷三《采访》《故事描述》', rel:['v_xukongbus','v_rosalie']},
{id:'v_rosalie', n:'罗沙莉', c:'角色', m:'void', sec:7, e:[7], p:[140,150,600], k:'none',
 s:'捕获者里的阿特兰，庆祝的主办者。',
 d:'捕获者文明里的一个阿特兰，食物广场那场大庆祝的主办者。新闻采访它时，正好有生物吃了不适合自己种族的食物，精神失常去攻击身边的同伴。罗沙莉回答得很干脆：不同的生物混在一起吃东西，当然会出点问题。学者看着屏幕说，它们的新闻和虚民的挺像——琳说，因为都是被同一种生物教出来的文明。',
 ch:'卷三《采访》《结束和继续》', rel:['v_buhuo']},
{id:'v_atlancity', n:'阿特兰虚空城', c:'文明', m:'void', sec:7, e:[7], p:[380,140,600], k:'station', kp:{s:30,c:'#c8b898'},
 s:'阿特兰在虚空中的城市。居民一个个变得暴躁，又一个个失去了感情。',
 d:'阿特兰在虚空中的城市。前首领留下记录：一种混进来的异种生物会释放特殊的信息素，干扰它们的思维，让再好的朋友也互相猜忌、暴躁易怒，想借此挑起内战、控制整个种群；首领中断了和它们的交易，却发现还有居民在偷偷交易，影响怎么也消除不了。唯一的方法来自外面一种叫“银丝”的生物，碾碎烘烤成药能治疗精神问题。后来银丝变异，服药的居民失去了感情。这时传来了尔什的信号——“更适合居住的地方”。',
 ch:'卷三《前首领的记录》', rel:['v_atlan','v_erxi']},
{id:'v_yinli', n:'引力球', c:'地理', m:'void', sec:7, e:[7], p:[600,-80,-120], k:'planet', kp:{r:40,tex:'rock',c1:'#5a5048',c2:'#3a3430',debris:1},
 s:'一颗流浪的世界，周围的碎块被它吸引过来，却从不落下。',
 d:'附近没有恒星。登上引力球的阿特兰都没回来。它其实是由无数残骸堆成、正被重组成一头新的恒星巴士的世界：逐光者在爆坑里吸取高温液体，制物水母收集、塑造物质，蛀虫与一种叫‘结构软化’的病在神经苏醒时出现。',
 ch:'卷三《它的事情》《追逐光》《神经的信号》', rel:['v_zhuguang','v_zhiwu','v_starbus']},
{id:'v_zhuguang', n:'逐光者', c:'物种', m:'void', sec:7, e:[7], p:[630,-60,-80], k:'swarm', kp:{n:50,s:16,c:'#ffb060'},
 s:'空心的球形生物，体内储藏高温物质。',
 d:'只要爆炸发生，它们就进入爆坑吸取高温液态物。奇怪的是，它们会保护琳的机械蜘蛛。',
 ch:'卷三《追逐光》', rel:['v_yinli']},
{id:'v_zhiwu', n:'制物水母', c:'物种', m:'void', sec:7, e:[7], p:[570,-40,-60], k:'jelly', kp:{s:14,c:'#a8d8ff'},
 s:'像空水母一样、能收集和塑造物质的生物，有榴莲状的器官。',
 d:'它原本属于某群文明生物，用触手吞入接触到的东西，在体内剔除杂质、改造物质，也参与制造。那群文明生物在接近水球的时候……',
 ch:'卷三《神经的信号》《信号》', rel:['v_yinli','v_shuiqiu']},
{id:'v_shuiqiu', n:'水球', c:'地理', m:'void', sec:7, e:[7], p:[720,-20,-420], k:'planet', kp:{r:28,tex:'ocean',c1:'#123a6a',c2:'#05101e',glow:.2},
 s:'接近者都会出事的神秘存在。一个弥漫着恐惧的孤单世界。',
 d:'传说最初的描述者登上过它，什么都没发现，只有一种恐惧的感觉。后来它离开了原来的位置。第三代描述者找到一个世界，那里的生物陷入疯狂，因为恐惧互相残杀直到灭绝——它才相信故事是真实的。另一个传说里有一个被十个世界围绕的星系。',
 ch:'卷三《一个传说》《故事描述》', rel:['v_fear','v_zhiwu']},
{id:'v_fear', n:'恐惧之海', c:'现象', m:'void', sec:7, e:[7], p:[430,-120,-540], k:'fog', kp:{r:150,n:60,c:'#8a2a5a'},
 s:'从遥远故乡涌来的“恐惧”能量。',
 d:'水球当初把它们放出来，是想让它们扩散自己的意志，可恐惧之海并没有照做，只是在虚空里漂流。故事里很多生物都遇到过它，没有谁和它“交流”过，大多远远避开，也有一些在研究它。恐惧的海浪袭击飘浮岩地；小护核者得知浮岛寄主的聚集地正被它慢慢淹没，立刻全速飞去，要把这个“很不能守护的东西”解决掉。凝胶生物的军队清扫恐惧区域，留下巨大的镜子和恐惧水域。神民之国飞走了。微型机械与恐惧之海融合后，抛弃了所有原本的想法，认为自己有新的使命：前往不可预见之地。',
 ch:'卷三《恐惧的克星》《意志所在》《后面要说的事》', rel:['v_shuiqiu','v_nuchong','bk_overview']},
{id:'v_nuchong', n:'怒虫', c:'物种', m:'void', sec:7, e:[7], p:[-60,-120,-660], k:'planet', kp:{r:24,tex:'red',c1:'#8a3a2a',c2:'#3a1a14',canyon:1},
 s:'愤怒即生命。为了活下去，它们必须时刻记住愤怒。',
 d:'它们住在布满裂痕的峡谷里，岩壁上挂满大小不一的金属球，小的两米、大的十几米，光从球面的裂缝里透出来，照亮了本该漆黑的峡谷——这些球都是住宅。它们和山上的“土鳖”一直导弹对射，绒球一飞进峡谷就被围攻，稍作交流才被允许参观。恐惧能量到来时，山上那群彻底抛弃恐惧的“土鳖”开始攻击怒虫，怒虫只好躲进峡谷，因此极为仇恨土鳖。峡谷的地下矿洞里有梦境结晶，里面留着织梦者的信息——它自称是让怒虫成长起来的“神”。',
 ch:'卷三《愤怒即生命》《织梦》《具体的故事》', rel:['v_zhimeng','v_fear']},
{id:'v_zhimeng', n:'织梦者之地', c:'地理', m:'void', sec:7, e:[7,8], p:[-380,-90,-560], k:'planet', kp:{r:50,tex:'dark',c1:'#1a1e24',c2:'#3a4048',fog:1},
 s:'黑色浓雾的汪洋、石柱与淤泥的大地。制造梦境核心与护核者的种族曾住在这里。',
 d:'织梦者喜欢研究别的世界，它们发现过一个正在“蒸发”的世界：地表慢慢碎成粉末飘向空中，世界停止运转。关键是找到一种被称为“蒸腾者”的东西。这里有像大象骨架一样的骨架机械、矮小的骨架侏儒（琳叫它们“迷石”，一种寒石类生物）、地下城市和隐秘之间。三米高、身上许多触手的教团生物崇拜蒸腾者。后来这里也蒸发了，留下浓雾之海，教团在“世界巅峰”引导通向虚空的路。',
 ch:'卷三《织梦》《被困之后》《一群石头》《参观？》', rel:['v_zhengteng','v_jiaotuan','v_mengshi']},
{id:'v_jiaotuan', n:'教团', c:'文明', m:'void', sec:7, e:[7,8], p:[-330,-60,-610], k:'none',
 s:'崇拜蒸腾者的团体。教团生物三米高，以二肢站立，身上长着许多触手。',
 d:'在真菌的世界里与真菌作战的生物，用自动运转的巨大“水墙”掩护，搭起近一百米高的建筑。后来它们搬到地下，挖出巨大的空间收集资源过活，还救下了梦食的后代，在它们的梦境圆柱上加装装置，让它们能看见真实世界；可无论后代用什么方法打招呼，教团都毫无反应。恐惧能量发现，教团是唯一能安全接近蒸腾者的生物。',
 ch:'卷三《一群石头》《消耗》《真菌与教团》', rel:['v_zhengteng','v_zhimeng','v_fungusworld']},

/* ---------- 星区 8 ---------- */
{id:'v_jing', n:'镜世界 · 表世界', c:'地理', m:'void', sec:8, e:[8], p:[-400,0,-150], k:'planet', kp:{r:42,tex:'crystal',c1:'#d8f4ff',c2:'#7ab8d8',atm:'#e8faff',plats:5},
 s:'被大片结晶覆盖、看起来美丽而善良的世界——始境的大本营。',
 d:'镜世界有三个：表世界、弃世界和藏在后面的第三个，它们轮回交换。表世界里没有尸体：所有死亡和分解的东西都会出现在弃世界。“巅峰物种”住在世界周围的圆盘平台上，平台中心那颗翻滚者就是镜世界。“镜”是来自虚无、通过别的生物知晓一切的存在。最后，崩溃的镜世界飞走了。',
 ch:'卷三《另一个世界》《囚禁》《交流》《第三个世界》', rel:['v_qishi','v_peak','v_shijing','v_shuiyin','v_shuimin']},
{id:'v_qishi', n:'弃世界', c:'地理', m:'void', sec:8, e:[8], p:[-540,-40,40], k:'planet', kp:{r:34,tex:'red',c1:'#6a2a22',c2:'#2a1210',atm:'#c84a3a'},
 s:'暗红天空下，堆满被抛弃之物的世界。',
 d:'废弃物聚成海洋，残骸巨怪在其中游荡。血雾和爆哮虫被带到这里，遇见八肢的“咕咕噶”（意思是“勇猛之士”，虽然一点也不勇猛）——在这种地方待太久，只要见到能说话的生物都会很激动。还有果冻生物、“果冻的制造者”、变形虫、蛞蝓，以及一个“普通蝎子王国”的蝎子；一艘战舰的系统叫“勇气”。',
 ch:'卷三《果冻的制造者》《囚禁》《逃脱和发现》', rel:['v_jing','v_gugu','rq_xuewu']},
{id:'v_gugu', n:'咕咕噶', c:'物种', m:'void', sec:8, e:[8], p:[-520,-10,80], k:'none',
 s:'三米多高的八肢结晶生物，四足四手，头像蜻蜓。名字的意思是“勇猛之士”。',
 d:'它对血雾和爆哮虫没有任何防备——在弃世界里，威胁它们的东西都是无法交流的。',
 ch:'卷三《果冻的制造者》', rel:['v_qishi']},
{id:'v_peak', n:'巅峰物种的平台', c:'文明', m:'void', sec:8, e:[8], p:[-330,40,-260], k:'disc', kp:{r:24,c:'#c8d8e0',c2:'#7a8a98'},
 s:'镜世界周围的圆盘平台，住着活着的“巅峰物种”。',
 d:'平台上有巅峰记录洞穴、观星点和农场，晶鱿、结晶海星也在这里。始境爱看自己收藏的巅峰物种们打个不停，自己却极不喜欢战争。一个舰长的影像想让蝎子加入“扮演巅峰物种”的计划，蝎子回答说，自己本来就是巅峰物种，用不着演；两边正吵着，满是裂痕的房顶突然爆开，蝎子顺势爬了出去，眼前是暗红天空下一整片废弃物的海。后来蒸腾者追来，始境击碎了遮天的黑暗，外面却还有一层灰黑、布满裂纹、像旧石墙一样的壳，离地约一万公里，只靠镜世界高处的山脉发光照亮。',
 ch:'卷三《交流》《逃脱和发现》《管道》', rel:['v_jing']},
{id:'v_shijing', n:'始境', c:'文明', m:'void', sec:8, e:[8], p:[-380,70,-90], k:'none',
 s:'向绒球投下结晶的外来者。由各文明的高层组成的组织。',
 d:'向绒球投下结晶的外来者，由各文明的高层组成的组织，想把整个世界“结晶化”。轰炸之后，内林城中心广场的大洞旁挤着几十只发抖的翡翠龙，天上的声音说：聚在这里就表示愿意加入结晶种群；有翡翠龙听说结晶化后不能生殖，那声音回答，只是不能自行生殖——以后由它们统一管理，再也不用为找伴侣烦恼了。它们向血雾展示翡翠龙城市冒烟的画面：“你们的国家已经没了。”它们有文明培养系统和生命扭曲装置，还和印加的虫群在虚空中大战。但始境并不是一个种族——真正的始境，只有“水银”一个。',
 ch:'卷三《如何告诉同类》《无法理解的对手？》', rel:['v_shuiyin','rq_jieyu','v_jing']},
{id:'v_shuiyin', n:'水银', c:'角色', m:'void', sec:8, e:[8,11], p:[-420,90,-130], k:'blob', kp:{s:8,c:'#d8dde2',metal:1},
 s:'‘其实没有始境这个种族……始境就是我，只有我一个。’',
 d:'它由地下挖出的一个叫“聚合体”的装置制造，可以看作始境全体信念凝成的东西；它学习能力极强，比谁都适合收集和培养文明，于是成了新一代首领。很久之后，它化作一团直径三公里、闪烁银光的液体，在虚空中飞行，利用星系巴士的数据“复苏”生物。',
 ch:'卷三《唯一的？》《结束……了？》《设定》《捕获》', rel:['v_shijing','v_xiaoerxi']},
{id:'v_shuimin', n:'机械水黾', c:'琳的造物', m:'void', sec:8, e:[8], p:[-360,-30,-200], k:'none',
 s:'能变色伪装的机械载具。学者们坐着它混进结晶的城市。',
 d:'血雾驾驶的机械载具，能变色隐身，头就待在驾驶舱里。它在废弃物小山里翻出一大块金属，周围的果冻生物一拥而上，可它打爆一只之后，其余的全都逃了——血雾松了口气：原来只是一群懦弱的家伙。它还隐身混在一群六米高、六条柱子般腿的“甲龙”中间，看它们用嘴里射出的“熔解光”啃食一艘巨大的战舰。它去过结晶之城：“说实话……跟我们的城市挺像的。”也到过粉色的沼泽，见过印加的虚空蠊。',
 ch:'卷三《城市？》《火花》', rel:['v_jing','v_kongqian']},
{id:'v_kongqian', n:'虚空蠊', c:'物种', m:'void', sec:8, e:[6,8,10], p:[-300,-60,-150], k:'swarm', kp:{n:60,s:18,c:'#4a3a2a'},
 s:'印加虫群用来探索虚空的蟑螂，一米长。',
 d:'这类蟑螂对虚空环境抵抗力强，被印加同化成探索部队。它们身上穿着另一种虫“增生者”维持呼吸，体内还有一种虫用来保暖。',
 ch:'卷三《另一个旅途》《城市？》', rel:['inca']},
{id:'v_midgard', n:'米德加尔特（入口）', c:'地理', m:'void', sec:8, e:[8,9], p:[120,0,0], k:'tube', kp:{len:900,r:46,c:'#2a2a30',glow:'#8a7aff'}, go:'midgard',
 s:'虚空中巨大的黑暗管道，里面住着“管道文明”。',
 d:'虚空中巨大的黑暗管道，里面住着‘管道文明’。学者跟着尘鳄走进去的那个‘工程废墟’，就是它。米德加尔特自称它的记忆里有无数传说，都是先祖留给它的，它从没见过它们的真面目，却觉得它们无比真实；只要提供一点线索，答案就会变得清晰。学者的本体则留在一个安全的地方，琳的绒球在旁边偶尔戳一戳它，就能感觉到它机械身体在里面遇到的扭曲能量。点“进入地图”走进管道。',
 ch:'卷三《传说的物种》《研究的进行者》', rel:['mg_overview','v_midgard2']},
{id:'v_rongui', n:'熔毁地带', c:'地理', m:'void', sec:8, e:[8,9], p:[440,-40,-200], k:'planet', kp:{r:70,tex:'lava',c1:'#2a0e08',c2:'#ff5a1a',glow:.8},
 s:'直径七千多公里、布满暗红裂痕的灼热世界。它是活的。',
 d:'恶魔说，最初它是一颗黑色的、庞大的、邪恶的球体，从远处现身要撞向它们美丽的世界。地底深处有“熔毁的意志”，它的神经系统是液态的——那片炙热的海就是神经器官。它曾粉碎过另一颗世界；它认为恶魔的世界“受到了感染”，所以必须摧毁。低温生物被养出来，准备顶替这里原有的高温生物，灰烬化现象从灰尘生物说起。最后它苏醒了，要前往凝固虚空；琳用攻击石和彩色软泥让它暂停。',
 ch:'卷三《来自远方》《取代生态》《灰烬化》《粉碎》《醒来的决定》', rel:['v_demon','v_huijin','v_zhengteng']},
{id:'v_huijin', n:'灰烬造脑怪', c:'物种', m:'void', sec:8, e:[8], p:[470,10,-160], k:'none',
 s:'由灰烬组成的造脑怪。',
 d:'它们接收到从恶魔的橘色世界传来的信号，认为这信号能拯救那个世界。两只灰烬造脑怪站在火山之巅俯视滚烫的大地：它们欢呼世界终于和平了——因为世界已经没了。',
 ch:'卷三《起飞》《继续行动》', rel:['zaonao','v_rongui']},
{id:'v_demon', n:'恶魔的世界', c:'地理', m:'void', sec:8, e:[6,8], p:[580,40,30], k:'planet', kp:{r:44,tex:'red',c1:'#d86a2a',c2:'#8a2a1a',atm:'#ffb070'},
 s:'通红的世界，猩红的建筑。恶魔为战斗而团结。',
 d:'恶魔是各种体型和形态的鲜红生物，对死亡毫无畏惧，非常容易为同一个目标——战斗——团结起来。它们曾被“先知”带离米德加尔特。恶魔们以魔王的名义，在这里列队迎接玛雅，它们造出鲜红的战舰与黑金属交战，又加入了攻打脑灵核心的联军。后来熔毁地带认定它们的世界被感染，导弹接连落下，恶魔撤离，魔王的内战随之而来。',
 ch:'卷三《以魔王的名义》《火红之地》《撤离》《内战》《连接？》', rel:['c_hero','v_rongui']},
{id:'v_cold', n:'寒冷之都', c:'地理', m:'void', sec:8, e:[8], p:[300,100,280], k:'planet', kp:{r:30,tex:'ice',c1:'#eef4f8',c2:'#8aa0b0',lights:'#bfe6ff'},
 s:'因“冷冻剧变试验”冰封的城市世界。',
 d:'有人开玩笑说，这个世界以前‘美丽动民’，现在只剩‘美丽冻民’了。学者悄悄潜进一座半球形的大博物馆，从录像AI“权杖”那里听到了城市的往事，以及“记录者、旅行者”——在虚空中没有特定目标、到处旅行收集资料的旅行者——的传说，还有一个关于米德加尔特这种生物的传说。',
 ch:'卷三《寒冷之都》《曾经的国度》《改造者？》《传说的物种》《想》', rel:['v_midgard','tlant']},
{id:'v_grave', n:'败者的墓地', c:'地理', m:'void', sec:8, e:[8,11], p:[-80,-100,400], k:'planet', kp:{r:40,tex:'sand',c1:'#e8c86a',c2:'#b8903a',atm:'#ffe8a0'},
 s:'一颗金黄色的沙海世界，米德加尔特毁掉的那些文明，剩下的东西都扔在了这里。',
 d:'一片广阔的金黄沙海，天上一直飘洒着无数沙粒。罐装之城就在这里。琳第二次来的时候，这里多了些不同的风景：飞舞的沙尘上方，悬着一片巨大的、焦黑的、满是裂痕的大地——熔毁地带也到了这里。沙漠深处还有‘墓胶’：传说米德加尔特把体内的文明资料散进虚空，想召唤别的物种，墓胶就是响应的那一种，由一种柔软的物质构成，能不停地延伸、生长，最早是在一处虚空墓地里发现的。',
 ch:'卷三《败者的墓地》《墓地中增长的东西》', rel:['v_guanzhuang','v_mujiao']},
{id:'v_guanzhuang', n:'罐装之城 · 罐脑', c:'文明', m:'void', sec:8, e:[8], p:[-60,-60,440], k:'city', kp:{s:16,c:'#a8b0b8'},
 s:'很擅长“罐装”的城市：任何能产生思维的部分，都会被装进罐子里。',
 d:'窗口告诉它：语言有效，已经登记好了，下一步请去办神经压缩罐装手续。居民全是机械躯体、脑装在罐里，担任各种职位，却没有一个知道真正的统治者是什么。这个文明攻击了米德加尔特而全数毁灭，只剩这座城市被丢进墓地。城市濒临崩溃时，原来它是一艘庞大的运输舰，带着居民飞离峡谷，躲避漫天的碎裂层。',
 ch:'卷三《罐装之城》《普通的城市》《统治者？》《幻想和起飞》《飞行的奥秘》', rel:['v_grave','v_mujiao','v_caini']},
{id:'v_mujiao', n:'墓胶', c:'物种', m:'void', sec:8, e:[8], p:[-110,-130,360], k:'blob', kp:{s:12,c:'#3a2a3a'},
 s:'在虚空墓地里不断延伸增长的柔软物质。',
 d:'米德加尔特的传说里，它曾把体内的文明资料散布到虚空，想召唤别的物种来，而响应召唤的就有墓胶：一种由柔软物质构成、能不断延伸增长的生物，最初出现在一处虚空墓地——据说是漂泊物种留下的文明废墟。最初它们只是一些似乎无害的东西，在废墟上慢慢长满，后来几乎铺遍了虚空中飘浮的所有废墟，还会生成一些特别的个体，能启动废墟里遗留的东西。后来罐装之城下起了“墓胶之雨”，扭曲肉块般的怪物从沙浪中现身扑向城墙。它向脑灵传话：杀掉它，否则就出动全力攻击这座城市。',
 ch:'卷三《墓地中增长的东西》《全面袭击》《西和东》', rel:['v_grave','v_guanzhuang']},
{id:'v_caini', n:'彩色软泥 · 梦想环境塑造者', c:'物种', m:'void', sec:8, e:[8,10], p:[-20,-90,470], k:'blob', kp:{s:9,c:'#ff7ad8',rainbow:1},
 s:'传说它能实现所有生物的愿望——不管是最不起眼的低层居民，还是一整颗庞大的世界。',
 d:'彩泥生活在凝固缝隙里，会让某个地方被彩色的光芒照耀；脑中有强烈愿望的生物进入光芒，就会被它入侵、“锁定”。研究者认为它并不是在帮谁实现愿望，只是在利用许愿者学习。传说它毁灭过米德加尔特管道里的一个文明。琳用它让熔毁地带暂停。',
 ch:'卷三《奇异之物》《彩色的愿望》《传说的末尾》《推测和行动》《一部分》', rel:['v_rongui','ng_qiushen']},
{id:'v_dust', n:'尘粉世界', c:'地理', m:'void', sec:8, e:[8], p:[-300,90,330], k:'planet', kp:{r:38,tex:'dust',c1:'#c8a060',c2:'#7a5a3a',atm:'#e8c890',fog:1},
 s:'满是尘粉的世界，伟大工程的一处工程地点。',
 d:'琥珀色的尘粉其实是珀岩记录者：它们以和尘粉一样小的颗粒形态生活，制造记录历史的琥珀。光萤像萤火虫的洪水，摧毁了这里所有蒸腾者的东西。粘粉圆木在尘粉里游荡吞食。电影院里，真菌在看一部讲“大预言家”的纪录片。',
 ch:'卷三《巧合？》《工程的碎片》《细小的土著》《汇聚与复苏》', rel:['v_poyan','v_guangying','v_zhanfen','v_zhengteng']},
{id:'v_poyan', n:'珀岩记录者', c:'物种', m:'void', sec:8, e:[8], p:[-330,60,300], k:'none',
 s:'完美的历史记载者：在哪里生长，就把哪里的历史详细记下来。',
 d:'一个古老传说里的庞然大物：高达上百米，像巨石也像高峰，在平原上游荡从不停息，琳给它起名“珀岩”。它身上住满了生物，有的拿它当交通工具，有的干脆安家。和别的大型生物不同，它会照看身上的居民——它的脑很特殊，能接收身上每个生物的情绪，借此“监视”它们有没有加害自己的念头。它也是完美的历史记载者：在哪里生长，就把哪里的历史详细记下来。',
 ch:'卷三《最初的》《接触记录者》', rel:['v_dust']},
{id:'v_guangying', n:'光萤', c:'物种', m:'void', sec:8, e:[8], p:[-260,120,360], k:'swarm', kp:{n:200,s:30,c:'#c8ff8a'},
 s:'单颗没有智力，聚成团就有了个性；分开，就变成两种个性。',
 d:'一群像发光小颗粒的生物，散着淡淡的光，围着琳的绒球飘，像一大片萤火虫；它们告诉绒球，这里曾经有一项伟大的工程，受了严重的损伤，废墟还留着。它们也向别的生物宣传过蒸腾者信仰。后来，无数光点像洪水一样朝爆炸中心飞去，嚷着这不是复苏而是毁灭，一下子吞没了那两块正在汇聚尘粉、长成几十米大小、形状像海参的东西。',
 ch:'卷三《细小的土著》《信仰？》', rel:['v_dust','v_zhengteng']},
{id:'v_zhanfen', n:'粘粉圆木', c:'物种', m:'void', sec:8, e:[8], p:[-340,100,380], k:'none',
 s:'像一根空心圆木、内部充满粘性物质的土著。',
 d:'琳给这个世界的土著起的名字。它外表像一根圆木，内部是空心的，充满粘性物质，生活在由无数尘粉组成的世界里：在尘粉中游荡，把尘粉吞进去，吸收里面对自己有营养的东西。偶尔也会吞下没营养的东西——比如说金属蜘蛛。',
 ch:'卷三《堵塞》', rel:['v_dust']},
{id:'v_hidden', n:'隐藏的工程地点（虚民城）', c:'地理', m:'void', sec:8, e:[8], p:[-560,70,300], k:'city', kp:{s:22,c:'#c8ccd0',float:1},
 s:'虚民世界附近，一座复制出来的虚民之城。',
 d:'这里几乎见不到飞行器，只有地面交通。伟大的工程收藏着虚空中各种生命的造物——建筑、日用品、交通工具、武器，但没有生物；为了补全“生态位”，真菌扮演植物、释放毒气，奇布查虫扮演微生物。爆哮虫和学者在电影院里被吓得半死，在塔楼集市里有人叫卖会分裂的煎蛋。米德加尔特的幽灵幼仔能随意拼出各种城市环境；最后城市失去引力，金属雕像迈步行走。',
 ch:'卷三《隐藏地点》《失踪者》《启动的原因》《塔楼》《幽灵幼仔》《倒塌》', rel:['c_baoxiao','v_youling','v_chibcha2']},
{id:'v_chibcha2', n:'奇布查虫（工程地点）', c:'物种', m:'void', sec:8, e:[8], p:[-590,40,260], k:'none',
 s:'黑暗丛林里，传来像笛子一样的声音。',
 d:'学者在黑藻真菌林里听见一阵像笛子一样的声音，怪异得不像唱歌，便顺着声音找过去，爆哮虫在它肩上小声说那东西肯定有古怪。声音的来源是一群奇布查虫。爆哮虫放出脑波和它们交流，它们说自己在这里过着很正常的生活：收集细小的尘粉当食物，建造地下窝穴，根本不知道什么真菌。可学者听到的那个脑波，又是怎么回事？',
 ch:'卷三《细微的虫》《源头》', rel:['chibcha','v_hidden']},
{id:'v_youling', n:'幽灵幼仔', c:'物种', m:'void', sec:8, e:[8], p:[-520,100,330], k:'fog', kp:{r:16,n:12,c:'#d8e8ff'},
 s:'米德加尔特的幼仔，最初是幽灵一样的形态。',
 d:'米德加尔特的幼仔本来只待在凝固虚空，刚出生时不是实体：一团透明的东西，像能量又像空气，和梦境生物差不多。它能“篡改”创造者的模拟装置，随意搭出城市——爆哮虫说这大概是在伪装自己。爆哮虫一发导弹轰塌塔楼，无数透明“幽灵”从烟尘里飞出，盘成漩涡升到快一公里高，一阵强光过后，天上多出许多钉满钉子的铁皮岛。它穿不透东西，所以用吸尘器似的工具就能吸起来，前提是追得上。琳认为是它自己溜进了隐藏工程；幽灵形态长到一定年龄后，蒸腾者——一种共生生物——会来为它塑造躯体。',
 ch:'卷三《幽灵是什么？》《幽灵幼仔》《整体的计划》', rel:['v_hidden','v_zhengteng','mg_overview']},
{id:'v_erxihidden', n:'尔什的隐藏工程', c:'地理', m:'void', sec:8, e:[8], p:[-150,140,560], k:'city', kp:{s:20,c:'#d8c8b8',float:1},
 s:'一座幻想中的“尔什之城”，以及完全由食物组成的点心之岛。',
 d:'第一批尔什民“偶然”来到时，惊讶于这是一座没有居民的城市。它们把百货商场搬空改成住处，出食口“嘀嘀嘀咔”就端出热腾腾的肉排饭——原料其实来自商场地下那些灰黑色的小生物。直升机飞到传说中的“点心之岛”：泥土是巧克力，草地是糖，小湖里是果酱，还有饼干和蛋糕的小屋。尔什民通过“玛尔斯通道”进来。',
 ch:'卷三《尔什造物》《食物？》《原始的食材》《玛尔斯通道》《组合》', rel:['v_erxi','v_yanpi']},
{id:'v_vine', n:'巴士藤蔓 · 碎石区', c:'地理', m:'void', sec:8, e:[8], p:[500,90,480], k:'vine', kp:{len:520,c:'#5a7a3a'},
 s:'碎石区里一棵巨大的植物——虚空藤蔓的主干，尔什民在上面建了城。',
 d:'尔什在虚空中旅行时经过这里，一部分尔什民决定留下，后来改造成了“机器民”。最大的石头叫奥林匹斯石，凝固生物最早就是在那里发现的。主干上有战斗塔、列车（广播先报了个离谱的倒计时，又改口说是三百六十秒后进站），以及能检测凝固虚空的“凝固探测器”。蒸腾者对主干发动过最大的入侵。',
 ch:'卷三《古怪的机器》《主干》《生岩》《蒸腾》《凝固的联系》', rel:['v_jiqimin','v_huanxing','v_yiyin','v_zhengteng']},
{id:'v_jiqimin', n:'机器民', c:'文明', m:'void', sec:8, e:[8], p:[540,70,520], k:'none',
 s:'被改造成机器的尔什民。改造有个小缺陷：会疯。',
 d:'被改造成机器的尔什民。改造技术有个小缺陷：被改造者会疯——思维慢慢变化，忘掉自己曾是细胞生物，失去“感情”，变成纯粹按理智或利益行动的存在。普通尔什民大多愿意无偿帮朋友一点小忙，机器民却不管对方曾经多亲密，都要相应的报酬；记忆还在，性格却完全不是从前的尔什民了。它们一般把巴士藤蔓叫作“赞克”，取自一个有名的故事：强盗赞克种下能长到云层之上的种子，一夜长成直升天际的藤蔓，爬上去偷了一间巨大房屋里的东西。',
 ch:'卷三《游荡》《机器疯》', rel:['v_vine']},
{id:'v_huanxing', n:'幻形学徒', c:'物种', m:'void', sec:8, e:[8], p:[470,110,510], k:'none',
 s:'和尔什民差不多大的凝固生物，学习能力极强，会变形。',
 d:'一种凝固生物。从这里开始，凝固虚空的生物通常被叫做‘怪物’：最早出现的只有几米大，行动迟钝，不会攻击，可以随便抓；后来的却非常巨大，会主动攻击会动的东西，有的甚至能摧毁大型战舰。幻形学徒被抓进研究所后，学会了尔什民的语言，又学会变成尔什民的模样——最初很拙劣，后来以假乱真。被它替换掉的事情接连发生，最早是被一个研究员发现的：对方问它到底是谁，它一脸无辜，说自己就是自己。',
 ch:'卷三《凝固的接触》《机器的反击》', rel:['v_vine','v_yiyin']},
{id:'v_yiyin', n:'异音', c:'角色', m:'void', sec:8, e:[8,10], p:[560,120,450], k:'none',
 s:'机器民探测凝固虚空时，收到的一段“异常的声音”。',
 d:'最初叫“51号异音”，意为高智能生物发出的声音。它通过影像装置说话，声音像一个雌性尔什民；装置老出故障，旁边一个机器模样的幻形学徒踹了它好几下。它代表凝固虚空那边发出过“邀请”。很久以后琳才在残留的器官里知道，异音的本体早已死去。',
 ch:'卷三《去交流》《异音》《邀请？》《残留的声音》', rel:['v_vine','v_huanxing']},
{id:'v_volcano', n:'火山岩', c:'琳的造物', m:'void', sec:8, e:[8], p:[380,120,560], k:'planet', kp:{r:16,tex:'lava',c1:'#3a2a22',c2:'#ff8a3a',glow:.5},
 s:'直径约六公里、像一块火山石的战舰。',
 d:'一块直径六公里左右的攻击石，表面布满像火山一样的突起，琳更爱管它叫‘火山岩’——这些火山真的能像火山那样喷发。它身上的火山一齐爆发时，喷出的浓烟其实是无数微型兵种，包住飞来的海胆爆弹，让它们在碰到表面之前就炸开。后来机器民认定琳和异音是一伙的，想扣押火山岩，琳就让它飞出碎石区，继续旅行。',
 ch:'卷三《火山岩》《有个性的飞行器》《参观》', rel:['v_vine']},
{id:'v_zhengteng', n:'蒸腾者', c:'物种', m:'void', sec:8, e:[7,8,9], p:[660,-60,380], k:'station', kp:{s:40,c:'#8a5a3a',rust:1},
 s:'像锈蚀的巨大金属，能蒸发一切。',
 d:'它的战术很简单：蒸发。导弹、战舰、一切它想蒸发的东西。它的集结地点像一座城堡，比绒球上任何山峰都庞大；琳用无数高速石块轰击，摧毁了二十多座基地。蒸腾者之城的地下藏着克隆体制造点——伤害克隆体，会让尔什的民众出现相同的受伤记忆。它也是米德加尔特幼仔的共生者，为幽灵幼仔塑造躯体。',
 ch:'卷三《被困之后》《启动》《撞击》《蒸腾》《挪动的都市》', rel:['v_youling','v_jiaotuan','v_vine']}
);

/* 卷三：虚空（星区 9–12） */
window.WIKI.push(
/* ---------- 星区 9 ---------- */
{id:'v_midgard2', n:'米德加尔特的旅途', c:'事件', m:'void', sec:9, e:[9], p:[-200,0,0], k:'star', kp:{r:120,c:'#ffd27a',tube:1},
 s:'巨大的管道拖着三颗创造者的世界当卫星，以每秒十六万公里飞行，钻进了一颗直径两百万公里的恒星。',
 d:'恒星通常比翻滚者大得多，连米德加尔特在它面前也显得渺小。它抓来的三颗卫星都曾属于创造者，其中一颗熔岩卫星能隐形，还能把高温液体构成的“山”当弹药发射。琳的兵种在管道身上一路观察：恒星里好奇的焰锯、长方堡上的集粒、千公里闪电翻腾的风暴区……米德加尔特所到之处，管道里的文明一成长到某种程度就会被它毁掉，于是诞生了只收集不发展的“半文明”。',
 ch:'卷三《恒星之中》《星中的生物？》《第三颗》《外面》《风暴？》', rel:['v_midgard','v_yanju','v_jili','mg_overview']},
{id:'v_yanju', n:'焰锯', c:'物种', m:'void', sec:9, e:[9], p:[-100,40,90], k:'swarm', kp:{n:60,s:40,c:'#ffb040'},
 s:'在恒星里出现的生物，对琳的兵种好奇而不是敌意。',
 d:'在恒星里出现的生物，琳暂时叫它们‘焰锯’。它们对琳的兵种没有敌意，更像是好奇，在兵种旁边绕着飞，看不出任何攻击的想法——当然，琳也不知道它们到底在想什么。这是一种全新的生物，无法归进琳之前遇到的任何种类，勉强算是比较接近梦境生物。',
 ch:'卷三《不同的焰光》', rel:['v_midgard2']},
{id:'v_jili', n:'集粒 · 长方堡', c:'文明', m:'void', sec:9, e:[9], p:[160,-40,-250], k:'cube', kp:{s:40,c:'#6a6a72',grid:1},
 s:'像细小颗粒的“半文明生物”，住在一块叫长方堡的金属构造上。',
 d:'长方堡的表面林立着无数方形金属结构。集粒驱使六肢蜥蜴般的造物去收集来自恒星的物质，却从不在此基础上继续发展。它们不知道自己最初怎么诞生，只知道从一开始就生活在一块飘浮在虚空中的东西上；卫星越来越近时，它们也不愿意离开。',
 ch:'卷三《外面》《作用》《堡？》《相同的生物》《简单的过去》', rel:['v_midgard2']},
{id:'v_storm9', n:'千公里闪电的风暴', c:'现象', m:'void', sec:9, e:[9], p:[400,60,-150], k:'fog', kp:{r:110,n:40,c:'#8ab8ff',lightning:1},
 s:'上千公里长的闪电在星空下翻滚，碎屑跟着闪光一起乱舞。',
 d:'米德加尔特前方出现的一片区域，直径大概有数百万公里，强烈的闪电和无数碎石搅在一起不停旋转。虚空里的风暴琳记过不少，这种却没见过，只是看着像风暴才这么叫。米德加尔特在几千公里外停住了，那颗变成熔岩世界的卫星却带着长方堡继续往里走，堡里的集粒还在拼命修引擎。',
 ch:'卷三《风暴？》', rel:['v_midgard2']},
{id:'v_guangyin', n:'光印', c:'物种', m:'void', sec:9, e:[9], p:[-460,-60,300], k:'planet', kp:{r:34,tex:'dark',c1:'#141a24',c2:'#3a4a6a',lights:'#8ad8ff'},
 s:'无脑、自动增生、只会不停建造的“生物”，用光在地面上印出巨大的建筑。',
 d:'它们的行为像被设定好的程序，因此也被认为只是某个文明遗留的产物。光印的文明靠到处游荡的“印记虫”缓缓修复；蝼蛄般的“回收会”能在地下无痕行动。琳和一个玩具熊模样的创造者一起，看着光印的城市被“大地的力量”吹飞。',
 ch:'卷三《指引》《光的指引》《这是一种……》《修复的文明》', rel:['v_huishouhui']},
{id:'v_huishouhui', n:'回收会', c:'物种', m:'void', sec:9, e:[9], p:[-430,-90,340], k:'disc', kp:{r:10,c:'#6a5a4a',c2:'#3a3028'},
 s:'直径百米左右的圆盘形群体生物。',
 d:'一个圆盘形的生物，专门在虚空中寻找创造者死后留下的造物——创造者偶尔会出意外，造物却多半还活着——有价值的就回收带走。它们只用脑波探测地表，所以对地上的情况知道得不多。这一次它回收到了好东西，却因为卫星卷进了虚空漩涡，找不到回去的路。体内有能千变万化的细胞，储存大量核信息；后来琳看见它被光印的“棉花”用光罩住捕捉。',
 ch:'卷三《回收负责》《进一步了解》《新的状态》', rel:['v_guangyin']},
{id:'v_shanguang', n:'闪光生物 · 同神', c:'文明', m:'void', sec:9, e:[9], p:[-540,40,-280], k:'planet', kp:{r:40,tex:'crystal',c1:'#fff8d8',c2:'#c8b87a',lights:'#fff0a0',glow:.4},
 s:'把死者的记忆和知识集中起来，造出“残响建造系统”的文明。',
 d:'这个系统被称为“同神”——共同思维产生的神明。它统御整个文明，管理所有物质的生产和建造，不会疲倦，也不会像别的智能那样想杀光制造者。闪光生物的探险队陆续出发：尖刺舰队、困在荆棘世界的队伍、好战的混合军队、幽灵舰队……一个首领飘到高处，全身光点闪烁，整座城市的建筑都跟着它一起闪动。',
 ch:'卷三《闪光之物》《淹没》《建造奇迹》《繁荣和探索》', rel:['v_jianci','v_jingji','v_headstation']},
{id:'v_jianci', n:'尖刺舰队', c:'文明', m:'void', sec:9, e:[9], p:[-300,100,-430], k:'ship', kp:{s:16,n:9,c:'#c8b878',spike:1},
 s:'舰船上长满尖刺、看似很能打，却不喜欢战斗。',
 d:'在虚空中四处捕捉生物的舰队。它们用一种黏性的捕捉球抓走了米德加尔特群山里的凤凰，琳趁机把一个三十厘米的石块兵种混进球里，跟着进了刺舰的监狱：一面柔软的透明墙，三面坚固的金属墙，石块和凤凰关在一起，听路过的尖刺讨论各种话题。被熔岩卫星追赶时，它们以每秒三百公里的速度逃跑——在虚空里，这实在太慢了。',
 ch:'卷三《尖刺》《试图的逃跑》《游荡》《神的领域？》', rel:['v_shanguang','v_midgard2']},
{id:'v_jingji', n:'荆棘世界', c:'地理', m:'void', sec:9, e:[9], p:[-660,-20,-480], k:'planet', kp:{r:24,tex:'rock',c1:'#5a4a3a',c2:'#2a3a22',spikes:1},
 s:'一支探险队被困在这里。',
 d:'一片长在虚空里的荆棘丛：每根尖刺几十到几百米长，纠缠成直径上千公里的一团，里面住着造型奇特、种类繁多的生物。闪光生物的探险队对这些实体生物好奇极了，把堡垒停在边缘，用带来的迷你系统很快建起殖民地。后来迷你系统出了异常，它们想联系母世界修复，“超远距离通讯器”却忽然失效。如今这里只剩原始部落，只知道这里曾被闪光的都市覆盖过。',
 ch:'卷三《荆棘的诞生》《本地居民》《袭击》', rel:['v_shanguang']},
{id:'v_headstation', n:'头颅形空间站', c:'地理', m:'void', sec:9, e:[9], p:[-150,-110,-520], k:'skull', kp:{s:22,c:'#c8b8a8'},
 s:'一颗三十公里大、看上去像尔什民头颅的空间站。',
 d:'一颗三十公里大、看上去像尔什民头颅的空间站。空间站里最激烈的战斗，一方是居民，另一方是空间站本身——它的建造系统模仿了闪光生物过去的技术：把死者的记忆和知识聚到一起。一支尔什民挖掘队挖到地下发现了它，装甲被它控制，全队覆没；系统却没有就此作罢，而是研究它们的大脑，造出一个拥有整支队伍记忆的新个体，叫“一号”。变形生物统合全族对抗系统，被尔什研究的白星也在这里出逃。最后，越来越近的熔岩卫星把山体一块块砸过来，穿梭机满载平民逃离，计划的时限只剩三分钟。',
 ch:'卷三《空间站》《它们的过去》《一号》《变形的闪光》《计划范围》', rel:['v_shanguang','ex_baixing']},
{id:'v_vortex9', n:'恒星坍缩的漩涡', c:'现象', m:'void', sec:9, e:[9], p:[300,-120,400], k:'vortex', kp:{r:80,c:'#b88aff'},
 s:'有生物记得，穿过它好像能到过去或者未来？',
 d:'虚空中有许多漩涡，散发着强大的引力吸引周围的一切，通常被认为是恒星坍缩自然形成的。可也有一些是被造出来的：被吸进去的东西不会出事，而是出现在另一个新的地方。有史以来，接近漩涡的物体大多消失了，少数“活”了下来，抵达漩涡的对面——有一种生物就待在那边，等待机会。也有生物记得，穿过它好像能到过去或者未来。被运送的比露卡在了时间的缝隙里，只听见一个声音叫它等着，一直等到永恒的尽头。',
 ch:'卷三《漩涡对面》《空间内》《有一个地方》', rel:['c_bilu']},
{id:'v_handi', n:'寒地', c:'地理', m:'void', sec:9, e:[9], p:[420,0,250], k:'planet', kp:{r:36,tex:'ice',c1:'#c8d0d8',c2:'#4a5058',lights:'#8affd0'},
 s:'星光明亮却永夜的寒冷世界。尸族在这里种菜、建村落、造城。',
 d:'“09号寒地移动站”是一座直径三百米的半球形展览馆，装着最新的“跳跃”能力，能接入附近的“洞口”实现零距离移动。研究站成了废墟，尸族——依尔什民而生的会动的干尸——包围了展览馆，像一片尸体组成的大海。它们的城市看似宝石般绚丽，其实由尸族菌构成，城里飘着影子。三角号战舰最后用火焰清扫了平原。',
 ch:'卷三《寒地》《干瘪的》《寒地的瘟疫》《尸城》《天降之火》', rel:['v_shizu','v_shijiang','v_lingchen','c_veronica']},
{id:'v_shizu', n:'尸族', c:'物种', m:'void', sec:9, e:[9], p:[450,-20,290], k:'swarm', kp:{n:150,s:30,c:'#8a7a5a'},
 s:'微生物把尔什民慢慢变成不到一米高的干瘪生物。',
 d:'一个被抓的尔什民记下了全过程：它们被关在窄小的气泡里，偶尔才给一点吃的；尸族里多数个体基本没什么智力，只听极少数智慧个体的指挥。微生物杀死它的细胞，改变骨骼，吸干水分，同时强化外皮和骨架……它写着写着惊呆了：尸体居然在那里种菜，还会造房子。后来比露和琳趴在一块大石头上看那座用岩石堆成的村子，尸族围着一个坑洞，短暂地打开了一道通往凝固虚空的裂痕。',
 ch:'卷三《转化》《平凡的尸生》《建造》', rel:['v_handi','v_shijiang']},
{id:'v_shijiang', n:'尸匠虫 · 聚魂蝽', c:'物种', m:'void', sec:9, e:[9], p:[390,30,210], k:'none',
 s:'三米多长、两肢、黑色，会组装尸族的“工匠”。它们是聚魂蝽的幼体。',
 d:'它们不用声音交流，体内的交流器官运作时才发出声响。作为聚魂蝽的幼虫，尸匠虫从神之眼出发，到许多世界“历练”、收集生物信息，大多只解析野生动物——直到有一群解析了尔什民。成虫聚魂蝽能把这个世界许多生物的“灵魂”收拢到一起。',
 ch:'卷三《尸体的工匠》《成虫》《决定》《奇妙的事情》', rel:['v_shizu','v_shenyan','v_lingchen']},
{id:'v_lingchen', n:'灵尘', c:'物种', m:'void', sec:9, e:[9], p:[480,40,230], k:'fog', kp:{r:30,n:18,c:'#c8d8ff'},
 s:'附着在生物身上的细微尘粉，像鬼魂一样飘。',
 d:'每个颗粒内部都有纵横交错的组织结构，和细胞差不多复杂。琳和比露身上没有。灵尘不能一直维持，太久不进食就会消散——一团灵尘说完“你们必须把这些情报送给研究团！”就散了。比露骂那些尔什民：‘这群笨蛋，居然怕鬼怕成这样！’',
 ch:'卷三《一些时日》《一个计划》《影子和虫子》', rel:['v_handi','v_shijiang']},
{id:'v_shenyan', n:'神之眼', c:'地理', m:'void', sec:9, e:[9], p:[620,-60,40], k:'disc', kp:{r:70,c:'#7a7a74',c2:'#3a3a38',eye:1},
 s:'圆盘形的“超级生物”。尔什民叫它波吕斐摩斯。',
 d:'灰色的大地，没有恒星，也看不见群星，只有发光物在周围晃荡；碎石平原上有排列整齐、刻满文字的巨大墓地石碑。它会慢慢形成一个巨大的“引力圈”，以后不管什么传送移动都会被吸过来，并且无法离开。内部住着尔什的远古生物，还有最古老的暗藻。',
 ch:'卷三《连接之眼》《神之眼初行》《形成》《神之眼》《很有想法》《试图联络》', rel:['v_anzao','v_shijiang']},
{id:'v_anzao', n:'暗藻', c:'物种', m:'void', sec:9, e:[9], p:[650,-80,0], k:'none',
 s:'尔什远古的藻类。很少生物知道自己何时认识“自我”，暗藻记得那一刻。',
 d:'远在尔什的恐龙出现之前，它们就以细小的神经结构聚成庞大的网络，在海上蔓延。不同的群体各信自己的理论，陷入漫无止境的菌类战争，直到古老陆地上的“衰退病毒”让它们衰退。之后它们用想象创造世界、修改规则。最后，暗藻骑上鱼骨架，一路游进了凝固虚空。',
 ch:'卷三《文明和泥潭》《远古时期》《灭亡和新生》《用想象创造》《坍塌中》', rel:['v_shenyan','ex_planet']},
{id:'v_zhouluo', n:'宙螺', c:'物种', m:'void', sec:9, e:[9], p:[540,120,-80], k:'whale', kp:{s:28,c:'#b8a888',shell:1},
 s:'研究团在虚空中发现、拿来当战舰用的生物。',
 d:'它在虚空中到处飘荡、收集碎屑，可以很久不进食；它有前往有细胞生物的世界的习惯。研究团给逃离尔什监控的队伍准备了宙螺。船员困在幻境里，不饿不困地过了不知多久；鸟类在宙螺体内起义，基地里飘满了鸟类的幽灵。‘爪子就是力量，鸟喙就是真理！’',
 ch:'卷三《坍塌中》《家畜的愤怒》《飘起》《宙螺》《鸟类的王国》', rel:['ex_birds','v_hongtian']},
{id:'v_hongtian', n:'轰天山峰 · 巴士会议', c:'地理', m:'void', sec:9, e:[9], p:[100,60,540], k:'planet', kp:{r:56,tex:'moss',c1:'#4a8a3a',c2:'#2a4a22',atm:'#a0e080',storm:1},
 s:'乌云密布的绿色世界。巨型巴士聚集在这里开会。',
 d:'大地覆盖着一层又一层地衣或苔藓般的东西，裂缝里能看到很多层结构；最壮观的是“轰天山峰”。巴士会议是巨型巴士——活的世界——与身上居民的会议，雾绵负责监视，等巴士聚齐。宝石文明自认是会议的守护者。一颗暗红色的巴士被吞噬后，所有文明一齐攻击管道……然后一切都“碎掉了”，凝固虚空爆发。',
 ch:'卷三《发现》《缺席的会议》《看着会议》《守护和出击》《碎掉了》', rel:['v_wumian','v_gem','v_budai','v_silver']},
{id:'v_wumian', n:'雾绵', c:'物种', m:'void', sec:9, e:[9], p:[60,100,480], k:'fog', kp:{r:70,n:40,c:'#d8e8d0'},
 s:'像海面一样的庞大生物，体内纵横交错。',
 d:'一个像海面一样的庞大生物，体内是纵横交错的管道，管壁上长满各种不知用途的结构组织，其中有许多像藤壶的窝，住着一种像苍蝇的生物，琳叫它们“组拆蝇”——专门组装或拆解东西。它想抓谁进来，就让组拆蝇临时组装出工具——比如一把巨大的钳子，用完就拆掉。它把暗藻切成许多几米大的小块，命令它们一直盯着某处的集结，直到聚齐为止，之前不许离开。最后被宝石文明的战舰光柱击中而崩溃。',
 ch:'卷三《看着会议》《雾绵与袭击》《召回》', rel:['v_hongtian','v_anzao','v_gem']},
{id:'v_gem', n:'宝石文明', c:'文明', m:'void', sec:9, e:[9], p:[240,-60,720], k:'planet', kp:{r:32,tex:'crystal',c1:'#bfe8ff',c2:'#5a8ad8',dome:1},
 s:'闪亮的结晶地表上耸立着像中世纪建筑的城市，外面罩着一层巨大的透明防护。',
 d:'第六颗巴士上的世界：闪亮的结晶地表上立着许多方形的矮建筑，像尔什民的中世纪城镇，材料光滑得像塑料，琳从没见过这种构成方式。建筑之间是一到几十米粗的透明管道，里面流着发光的液体，在全城输送。它们不久前入侵布袋的世界、抓走了暗藻。舰队像闪亮的宝石或玻璃，最大的旗舰直径一公里多，像一颗蓝宝石；总管给它们起了这个“没什么创意”的名字。九颗巴士聚到不到一百万公里的范围里开会，它们自认是会议的守护者，连别的巴士也要护着：管道的焰光烧向暗红巴士时，它们丢下一圈盾形巨石把火球包住，直到熄灭，只留下一个大坑。',
 ch:'卷三《闪亮的世界》《华丽的舰队》《开始召唤》《守护和出击》', rel:['v_hongtian','v_wumian']},
{id:'v_budai', n:'布袋', c:'物种', m:'void', sec:9, e:[9], p:[-300,0,580], k:'swarm', kp:{n:40,s:30,c:'#b8a070',big:1,sack:1},
 s:'扭动着布袋般身躯的虚空生物。',
 d:'传说两个尔什民在“飘浮山矿区”挖矿时发现了它们——那里只有这一种生物，在虚空矿山之间飘来飘去、吸食碎屑。一测，智力竟有50上下，能很快看懂尔什民的举动并作出回应，可日常生活里根本用不上这份聪明。两人为“它们能否发展出文明”争了起来：没有手，又生在虚空，看来没戏；于是把一批布袋搬去A7-0931。在引力下它们飞不起来，只能在地上挪，但身体四个角能抓东西，用得了尔什民的工具。后来布袋有了照着尔什民样子建的城市，广告牌上却只播战事和新种诞生的消息——它们本就不是很纯粹的个体生物。‘好像是很久以前做过的……试验。’',
 ch:'卷三《飘在虚空的布袋》《低等的新种》《布袋的城市》《追向虚空》', rel:['v_hongtian']},
{id:'v_silver', n:'银色世界', c:'地理', m:'void', sec:9, e:[9], p:[320,80,620], k:'planet', kp:{r:30,tex:'metal',c1:'#e8eef4',c2:'#a8b0b8',glow:.5},
 s:'地表一望无际都是耀眼的光泽，出现时连群星都暗了。',
 d:'出现时连周围的群星都黯淡下去的一颗巴士世界，直径一万公里，地表一望无际都是耀眼的银色，却有平原、山脉、峡谷，被叫作“白银”。它的居民驾着筏子般的银色飞行器——像许多圆柱捆在一起——截住了正坠向绿色世界的尔什民战舰，并宣称：既然是它们救了尔什民，尔什民就得一辈子记着这份恩情。它们抓了不少生物，给尔什民穿上自己的衣物；尔什民慢慢懂了驾驶的知识，最后乘着那些银色筏子离开。',
 ch:'卷三《银色之地》《按想象行事》《新世界》', rel:['v_hongtian','v_dim']},
{id:'v_dim', n:'昏暗世界', c:'地理', m:'void', sec:9, e:[9], p:[-60,120,660], k:'planet', kp:{r:24,tex:'dark',c1:'#2a2a24',c2:'#4a4a40'},
 s:'稀薄的空气、正常的引力、极低的温度，地表像在室内一样看不见天。',
 d:'一颗暗红色的巴士，地表整个被阴影罩着：空气稀薄，引力正常，冷得厉害。从外面看还有些亮处，可一落到地上就像走进了屋里，头顶的星星全看不见，只有四周隐约晃动的巨大黑影。别的巴士地表都比较亮，这颗不但自己不发光，好像还把外面的光挡住了。尔什民的银筏经过时被击落，就掉在了这里。',
 ch:'卷三《昏暗的世界》《那的光芒》', rel:['v_silver']},
{id:'v_ningu_gate', n:'通往凝固虚空', c:'地理', m:'void', sec:9, e:[9,10], p:[660,-100,520], k:'portal', kp:{c:'#3a3a3a',dark:1}, go:'ningu',
 s:'巴士会议碎裂之后，凝固虚空爆发了。',
 d:'点“进入地图”进入几乎一切都静止的虚空。',
 ch:'卷三《碎裂》《击穿》', rel:['ng_overview']},

/* ---------- 星区 10 ---------- */
{id:'v_phoenix', n:'凤凰的恒星', c:'地理', m:'void', sec:10, e:[10], p:[0,0,0], k:'star', kp:{r:110,c:'#ff9a3a',plats:7},
 s:'一座建在恒星上的国度：蜂窝平台、居住平台、三公里的橘色液态神殿。',
 d:'古老的传说里，这颗恒星曾被十个比它宽上数倍的“圆环”围绕。凤凰在恒星周围建起平台，汲取恒星的能源；平台上有像足球场一样的比赛场，有“推翻滚者比赛”。琳给它们设计居民平台，得到了“传说中的最高票数一万票”。凤凰的恒星将要毁灭的消息传来时，所有凤凰都比以往更激动。',
 ch:'卷三《星光上的平台》《恒星住民》《以前的生物》《欢呼？》《发展》《语录》《转播》', rel:['v_feng','v_gas','v_xuji','v_xiaojingling']},
{id:'v_feng', n:'凤凰', c:'物种', m:'void', sec:10, e:[10,11], p:[150,60,80], k:'bird', kp:{s:14,n:24,c:'#ff7a2a'},
 s:'好战的恒星居民。身体是大量不规则的细小颗粒，没有大脑，记忆也不在核心里。',
 d:'最早的凤凰只是在平台上活动的颗粒凝聚物。它们按控制引力的能力分等级：天生不能控制引力的叫“劣等种”，能让自己飞起来的叫“初级种”……当你飞得和导弹一样快、爆炸比导弹更猛烈、还不在乎自己的命，“为什么不自己去作战呢？”它们与旋风生物同源，打过数场传奇战役，十万凤凰的军队遮星蔽空。',
 ch:'卷三《传奇的一生》《远古的生活》《恍惚的记忆》《覆盖》《凤凰的战争》', rel:['v_phoenix','v_xuanfeng','v_guanxing','v_xuji']},
{id:'v_xiaojingling', n:'恒星小精灵', c:'物种', m:'void', sec:10, e:[10], p:[-120,50,140], k:'swarm', kp:{n:120,s:22,c:'#ffe08a'},
 s:'一到十厘米大小的凝固混合物，背后一对两倍体长的翅膀。',
 d:'一到十厘米大小的凝固混合物，没有固定形状，会根据环境改变自身；背后一对展开有体长两倍、厚一毫米的“翅膀”，不管有没有空气，只要移动就以每秒一百次以上的频率扇动，翅膀本身能产生微弱的引力，所以在任何环境下都能快速移动。这是琳来到凤凰那里第一眼看见的生物：它们是凤凰的搬运工，听凤凰用特定的语言指挥——不是凤凰特意养的，只是偶然发现很有用。球神那边也出现过它们。和几只燃烧的鸡一起，它们把琳的彗星钻头推到了平台上。',
 ch:'卷三《比赛项目》《教育》', rel:['v_phoenix']},
{id:'v_gas', n:'气态巨星 · 蓝色竹林', c:'地理', m:'void', sec:10, e:[10], p:[440,-40,160], k:'planet', kp:{r:70,tex:'gas',c1:'#8ab8d8',c2:'#4a6a9a',moon:1},
 s:'凤凰后来把它丢进了凝固虚空。它的一颗卫星上，长着一大片蓝色的竹林。',
 d:'竹林里住着像蓝色火龙果的生物，它们自称“天相异变”之后一直修炼，获取从气态巨星落下的“天之精华”，变得更快、更强、更长寿，以求永远的生命。从那以后，它们就一直活在一片漆黑里。所有生物都在慢慢变成灰尘。',
 ch:'卷三《气态球》《迷途竹林》《天之精华》《只有灰烬，没有重生》《现在》', rel:['v_phoenix','v_mechmoon']},
{id:'v_mechmoon', n:'机械卫星 · 灰尘之海', c:'地理', m:'void', sec:10, e:[10], p:[540,40,300], k:'planet', kp:{r:24,tex:'metal',c1:'#7a7a74',c2:'#4a4a44'},
 s:'一颗三千公里的小卫星，地下是两百米深的灰尘之海。',
 d:'有同情心的“灰尘拯救者”曾看着这里的生物一个个灰尘化，无法逆转，只好试着做点什么。巨大的机械吸收生物灰尘获得了记忆，想向凤凰复仇；凤凰十几个一组撞击机械，它们奇怪怎么变弱了，结论是：毁灭的力量还不够。',
 ch:'卷三《拯救？》《机械的过去》《增援》《传说的？》《承载着梦想与希望》', rel:['v_gas','v_feng']},
{id:'v_xuanfeng', n:'旋风生物', c:'物种', m:'void', sec:10, e:[6,10], p:[-160,-60,250], k:'vortex', kp:{r:30,c:'#c8c0a8',small:1},
 s:'旋风、飓风、龙卷风、熔岩风暴——风暴本身就是生物。',
 d:'在一个位于星系边缘的世界里，旋风、狂风、风暴不是现象，而是生物：以一个方形或圆形的核心为生命中心，再裹上不断回旋的碎屑和灰尘作为“身体”。它们从何而生没有记录，研究者猜测来自很久以前一场席卷整个星系的特别风暴，让某个世界地表的基础物质活了过来。创造者监狱里就有很多种，琳把它们的名字翻译成熟悉的词语。凤凰与它们“趋同进化”，其实同源。最初的旋风很单纯，与绿噬混合太久才有了复杂的想法；它们曾把墟集神当作神来崇拜。',
 ch:'卷三《狂风的传说》《气态中的生态》《无之凝聚》《同类的战争》', rel:['v_feng','v_prison','v_lvshi','v_xuji']},
{id:'v_lvshi', n:'绿噬', c:'物种', m:'void', sec:10, e:[10], p:[-260,30,180], k:'fog', kp:{r:80,n:40,c:'#5ac85a'},
 s:'吞噬整个星系的绿色浓雾。',
 d:'被它占领的世界不分昼夜弥漫着遮天蔽日的浓雾，城市里的生物躯壳像机械一样活动。凤凰身上混进它的尘粉就会神经异常，但能用引力护住身体。最后无数旋风包围了每一个被侵占的世界，把绿雾卷进自己体内——绿雾失去了思维。凤凰又把绿噬留下的躯壳变成真正的生物。',
 ch:'卷三《导师》《第一场》《清扫》《新的感觉》《苏醒》', rel:['v_xuanfeng','v_feng']},
{id:'v_guanxing', n:'观星之印 · 穿星之印', c:'物种', m:'void', sec:10, e:[10], p:[240,140,-60], k:'bird', kp:{s:60,n:1,c:'#8ab8ff',starry:1},
 s:'巨大的凤凰，透明的翅膀上闪着星空一样的光。',
 d:'它从双翼洒下无数“凤翼飞弹”，威力和尔什民的聚变弹相当，不同的是炸开的烟云是凤凰的样子；它能在一颗翻滚者上“印下星空”。它们冲着对手喊：退路没有了，逃也逃不掉，前面只有末日。它一直用多种凝固生物的语言广播。',
 ch:'卷三《观星之印》《逃离》《完美的计划？》《凤凰与舰长》', rel:['v_feng','v_xuji']},
{id:'v_xuji', n:'墟集神', c:'物种', m:'void', sec:10, e:[10], p:[-320,80,320], k:'blob', kp:{s:40,c:'#4a3a4a',tentacles:1},
 s:'古老而强大的生物，能用触手从空中直接拉出建筑。',
 d:'名字是琳把‘废墟之主’（废主）和“器官集合体”合起来起的，“神”则因为旋风生物崇拜它。最早的墟集神只是几米大、聚着大量器官的凝结物。它会分裂成废主、器官集合体，以及“碎片种”——其中一些忽然醒悟“这么收集没有任何意义”，成了“懒惰种”。废主喜欢收藏和交换，曾和凤凰打过传奇之战。',
 ch:'卷三《收藏品》《废墟与器官》《世界之一？》《碎片种》《懒惰》', rel:['v_feng','v_guanxing','v_xuanfeng']},
{id:'v_snow', n:'雪原世界', c:'地理', m:'void', sec:10, e:[10], p:[-460,-60,-150], k:'planet', kp:{r:36,tex:'ice',c1:'#f4f6f8',c2:'#c8ccd0',lights:'#ffb04a'},
 s:'凤凰在这里飞不起来。追光生物戴着火把，永远无法离开雪原。',
 d:'两肢生物、飘浮生物等十多种生物统称“追光生物”：它们完全无法自行反凝固，只能靠寄生在身上的炉火类生物“火把”放出反凝固场，被吸取养分直到死亡。一米高、能跳的“雪光”几十个一群，头领顶着火把。一座三千多米高的雪山顶上有建筑，每级台阶都有一米高。血山的外壳裂开，里面是一头全身透明的光龙。',
 ch:'卷三《雪原》《山顶的建筑》《只有光明》《最后一步》《雪原边境》《穿透》', rel:['v_huobanao','ng_luhuo','guanglong']},
{id:'v_huobanao', n:'火把之脑', c:'物种', m:'void', sec:10, e:[10], p:[-430,-20,-110], k:'none',
 s:'没有行动能力、只待在原地发号施令的“脑”，可能是最后一个。',
 d:'其他火把是因为它才变成火把的样子。它感知力极强，指挥的不是自己的身体而是别的物种；炉火里的怀疑个体开始质疑警报指令，它就转而控制那些不会怀疑的个体。琳决定让它活下来。',
 ch:'卷三《模仿命令》《协助》《准备躲避》', rel:['v_snow']},
{id:'v_ancestor', n:'先祖之地 · 三个世界', c:'地理', m:'void', sec:10, e:[10], p:[-200,-100,-420], k:'planet', kp:{r:34,tex:'jungle',c1:'#3a5a3a',c2:'#5a4a3a',fog:1},
 s:'‘这三个世界是一起诞生的，什么都是共用的。’',
 d:'绒球、先祖之地和“三号界”曾共同诞生、同步变化——绒球缺氧的时候，有部分细胞生物来到了这里。先祖之地有沼泽，有十米高、被小鸟们当成怪物的翡翠龙骨架。把“末忆线”发射出来的生物想再造三号界；一枚枚“多界之骨”导弹体内装着储藏整个世界的装置，穿过风暴般的“末日海”。阿特兰也把这里当作最初的翻滚者。',
 ch:'卷三《过去》《多界之骨》《先祖的沼泽》《过去的毁灭》《模拟的发展》', rel:['rongqiu','v_zhujie','v_moriha','ng_quanyan']},
{id:'v_zhujie', n:'诸界之骨 · 多界之骨', c:'物种', m:'void', sec:10, e:[10], p:[-420,60,-380], k:'ship', kp:{s:30,c:'#e8e0c8',bone:1},
 s:'空心骨架里装着许多十几厘米的装置，每个装置里都是一个完整的世界。',
 d:'装置类似琳的“梦境之脑”，里面有复杂的生物、文明和生态。诸界之骨的指挥室里有一个负责控制所有世界的文明，它们能修改别的世界的规则，却改不了自己的世界——那里到处飘着数百米、雪白云朵般的东西。',
 ch:'卷三《多界之骨》《内部的我们》《守护的信息》', rel:['v_ancestor']},
{id:'v_moriha', n:'末日海', c:'现象', m:'void', sec:10, e:[10], p:[-620,0,-300], k:'fog', kp:{r:110,n:40,c:'#6a7a8a',lightning:1},
 s:'充满风暴的地方，像在暴风里行动。',
 d:'强烈的气流让人无法自由动作，只有特制的导弹不受影响。“末忆线”就生活在这里，它从末日中诞生。',
 ch:'卷三《转移？》《过去的毁灭》', rel:['v_ancestor']},
{id:'v_tunnel_gate', n:'通往白色通道', c:'地理', m:'void', sec:10, e:[10], p:[260,100,-440], k:'portal', kp:{c:'#f4f4f0',white:1}, go:'tunnel',
 s:'凤凰找到的古老通道。',
 d:'一大群凤凰聚在一片雪白的虚空里，围着唯一不那么白的地方：一个一百多米宽、表面显示着复杂图案的圆形物体。据说这是一条古老的通道，先驱们曾经从这里去过许多不可思议的地方；有只凤凰说着能聚在这里很荣幸，说到一半又改口，说它们才不觉得荣幸。点“进入地图”。',
 ch:'卷三《古老的通道》', rel:['tn_overview']},
{id:'v_wuyi', n:'边无蚀地', c:'地理', m:'void', sec:10, e:[10], p:[500,-90,-320], k:'disc', kp:{r:100,c:'#6a6a64',c2:'#4a4a46',mud:1},
 s:'没有边界、会腐蚀一切的灰色泥地。它也许是活的。',
 d:'它没法被远距离感知，接近之前什么都看不到。花朵生物带着琳以每秒五十米的速度在上面游荡了两个绒球昼夜，地下深处满是“爆吞”——它们是边无蚀地制造出来、专门吃花朵的怪物。泥浆一族也在这里：数十上百公里的古代泥浆、射出长矛和钻头的泥浆领主，以及红色的“红浆”。',
 ch:'卷三《边无蚀地》《依赖腐烂之物》《蚀地的怪物》《泥浆的传说》', rel:['v_huaduo','v_nijiang','tn_overview']},
{id:'v_huaduo', n:'花朵生物 · 爆吞', c:'物种', m:'void', sec:10, e:[10], p:[540,-60,-260], k:'none',
 s:'漂流的花朵身上有一整套复杂的生态。',
 d:'它们忍不住想：这算奇迹吗？是无数个偶然凑出来的吗？有生物研究它后得出结论：花朵不可能“自然”产生这种生态。它离开前留下了“爆吞”，不停追猎遇到的每一朵花，吃下去分解掉。后来花朵被制造装置改造，体型变大，能感觉到周围空间的“波动”。',
 ch:'卷三《花朵的起源？》《发疯》《逃离》《多次改造》', rel:['v_wuyi','v_wending']},
{id:'v_nijiang', n:'泥浆与“奇迹”', c:'物种', m:'void', sec:10, e:[10], p:[460,-120,-380], k:'blob', kp:{s:30,c:'#6a5a4a'},
 s:'奇迹不一定是好事：稳定的恒星突然炸掉，恐龙忽然说出虚民的语言，都算奇迹。',
 d:'古代泥浆的记忆像博物馆一样要慢慢“阅览”，它们不认为那些记忆是自己的。奇迹生物在虚空中埋下许多“奇迹”，都要经过最初、生长、完成三个阶段——模型沙海就是其中之一。古代泥浆被奇迹折磨，决定阻止所有奇迹；红浆的大军打败了它。无形想以尔什为载体诞生“恒古之泥”。',
 ch:'卷三《泥浆的传说》《连续发生的奇迹》《阻止奇迹》《红浆的国度》《无形之形》', rel:['v_wuyi','tn_wuxing','ex_planet']},
{id:'v_wending', n:'稳定虫的空间站', c:'文明', m:'void', sec:10, e:[10], p:[620,40,-120], k:'station', kp:{s:24,c:'#a85a5a',flesh:1},
 s:'表面覆盖着血肉般物质的空间站。“稳定是唯一的真理。”',
 d:'表面覆盖着血肉般物质的空间站，信条是“稳定是唯一的真理”。稳定虫是一种凝固混合生物，曾把血肉生物的脑部毁掉；它们“永远稳定”——变化无数，却怎么也变不了。琳的微型兵种在站里找到一间像博物馆的大厅：到处是罩着半球透明罩的艺术品，正中是一个直径三十多米的生物，五片血红色“花瓣”围着闪着白光的“花蕾”，形状和三号界一模一样。刚要检测，稳定虫就从四周的出入口涌了出来。后来成千上万的绒球与数千艘血肉覆盖的飞行器打了一场小仗。',
 ch:'卷三《一种生物》《血肉？》《永恒与稳定》《爱好稳定》《稳定的中心》', rel:['v_huaduo']},
{id:'v_xixian', n:'细线的海洋翻滚者', c:'地理', m:'void', sec:10, e:[10], p:[-80,120,540], k:'planet', kp:{r:40,tex:'ocean',c1:'#1a4a7a',c2:'#0a2a4a',atm:'#7ab8ff'},
 s:'一片平静的海洋。海床上飘浮着无数细线，代表着“隧道之种”的思维。',
 d:'细线接受了寻找“返乡之道”的任务，却不知道任务来自谁。它们一直想把奇迹制裁凝聚起来交给隧道之种，让崩塌已久的虚空隧道复苏。海洋里无数扭曲的触手其实也是水构成的；它说那是另一片海，比这里还要大得多，任务的源头就住在那里。',
 ch:'卷三《观察》《任务源头》《海》《共同目标》《海下的荒漠》', rel:['bk_home','tn_overview']},
{id:'v_bone', n:'骨头的王国 · 废弃场', c:'文明', m:'void', sec:10, e:[10], p:[180,-120,580], k:'rocks', kp:{r:90,n:60,s:10,c:'#e8e0c8'},
 s:'骨头的文明，与废弃场里进化出来的“神”。',
 d:'骨头没有细胞结构，身体却也分成许多器官。食物仓库里有一只寄居蟹般的生物不断进化，与扭曲装置融合——像昆虫的蛹一样瓦解又重构，成了以“扭曲”为信仰的“神”，最后化作一块巨大的“钻石”飞离。废弃生物与骨头打了一场惨烈的战争，来自凝固虚空的“混合”现象让一切变成末日。',
 ch:'卷三《另外的种族》《异星来客？》《废弃生物》《新的想法》《伟大的造物》《最后的活物》', rel:['v_bridge']},
{id:'v_bridge', n:'唯一之桥', c:'文明', m:'void', sec:10, e:[10], p:[-460,-40,480], k:'bridge', kp:{len:360,c:'#8a7a6a'},
 s:'在虚空中漂流的巨桥，上面住满了文明。',
 d:'合成生物诞生在“虚空杂物堆”，永远杀不完，见到东西就往自己身上装。研究者把自己的神经连上合成生物，操纵大群同类，成了最早的“统一信仰”。后来又有随机信仰（“民之初，性随机”）、平静之国——一团肉块控制军队，向桥上所有文明宣战。巴士生物据说曾把唯一之桥传送到有食物的地方。',
 ch:'卷三《集合之源》《庞然大物》《早期》《诞生》《平静》《特殊崇拜》', rel:['v_bone','v_warbus']},
{id:'v_warbus', n:'战争巴士 · 回忆巴士', c:'地理', m:'void', sec:10, e:[10], p:[640,-40,520], k:'planet', kp:{r:40,tex:'sand',c1:'#c8a878',c2:'#7a6a52'},
 s:'一颗陷在回忆里、永远模拟着那场战争的巴士。',
 d:'地表是沙漠，沙粒聚成战争生物；地下六十六层，洞壁是溶解重组过、像黑色果冻的器官。半蟹民——像尔什民和蟹的组合——拿着光剑满洞穴找维罗尼卡和诺。“战争的回忆”是一种飘荡在虚空的能量；一颗“蛋”里装着能给大量虚空生物发送信号的思维发送器。',
 ch:'卷三《残留》《遭遇》《陷入》《危险生物》《风暴之眼》《变异》', rel:['v_bridge','c_veronica','ex_nuo']},
{id:'v_buke_gate', n:'通往不可预见之地', c:'地理', m:'void', sec:10, e:[10,11,12], p:[-660,120,120], k:'portal', kp:{c:'#e8d8ff',pale:1}, go:'buke',
 s:'另一个虚空。',
 d:'从返乡之道一路往里，就到了规则完全不同的地方。点“进入地图”。',
 ch:'卷三', rel:['bk_overview']},

/* ---------- 星区 11 ---------- */
{id:'v_pain', n:'痛苦巴士', c:'地理', m:'void', sec:11, e:[11], p:[-300,0,0], k:'planet', kp:{r:50,tex:'red',c1:'#8a1a1a',c2:'#3a0808',fog:1,atm:'#ff4a4a'},
 s:'一颗喜欢创造痛苦的巴士。地表的生物只能活在痛苦的轮回里。',
 d:'它一直把能量思维生物吸引到地表上来；接近的生物都会对地表生物产生异常强烈的同情心。地上有三十米高的透明罐子与培育仓，裂缝里涌出鲜红的雾气，地下是通红的、满是残缺生物的“鲜红地狱”。琳发射了大量“满足针”，被扎中的生物都感到满足——大地却变得极为愤怒，红雾像鲜血一样从地面涌出。后来它与一颗废品倾泻球相撞。',
 ch:'卷三《异常》《思维的墙壁》《痛苦的世界》《轮回》《鲜红的地狱？》', rel:['v_dump','v_painland','v_canlie']},
{id:'v_dump', n:'废品倾泻球', c:'地理', m:'void', sec:11, e:[11], p:[-120,60,140], k:'planet', kp:{r:22,tex:'rock',c1:'#6a6058',c2:'#3a342e',debris:1},
 s:'一个真正的“废品站”，专门抛弃许多文明的遗物。',
 d:'直径接近一百公里。一群生物被迫不停产生废品，否则整个世界就会出问题。‘它管的不只是一个文明留下的东西，是很多个。’',
 ch:'卷三《倾泻物》《危险品》《碰撞》', rel:['v_pain']},
{id:'v_canlie', n:'残猎者', c:'物种', m:'void', sec:11, e:[11], p:[-260,40,60], k:'swarm', kp:{n:30,s:30,c:'#8a6a5a'},
 s:'“残留追猎者”，喜欢收集文明毁灭前发射出去的最后希望。',
 d:'全名“残留追猎者”。许多文明在毁灭前都会留下点什么：历史和技术、几个可能让文明复兴的幼仔、一艘载满幸存者的飞行器……残猎者专门收集这些最后的希望。它曾藏在痛苦巴士里一只幼虫的体内，到处宣扬巴士的邪恶；琳把幼虫改造成自己的兵种，又留着它的意识，好向它问话——它对身份暴露并不惊讶，只是没想到自己会死。一百个“总部”坠毁在痛苦巴士的地表上。',
 ch:'卷三《另一种猎手》《追猎之物》《过去》', rel:['v_pain']},
{id:'v_painland', n:'痛苦之地', c:'地理', m:'void', sec:11, e:[11], p:[-520,-40,-150], k:'rocks', kp:{r:120,n:50,s:16,c:'#8a2a2a',glow:'#ff4a3a'},
 s:'痛苦能量聚集的地方，可以储藏也可以爆发——非常适合当武器。',
 d:'有闪烁结晶的华丽洞穴，里面的水母会“诉说”痛苦；苦钉民在“痛苦陆地”上，用针状战舰把陆地扎穿。群星联盟把这里叫作“地狱”。',
 ch:'卷三《痛苦之地？》《痛苦的结晶》《聚集地》《传说中的地狱》', rel:['v_kuding','v_xingmeng']},
{id:'v_kuding', n:'苦钉民', c:'物种', m:'void', sec:11, e:[11], p:[-560,80,60], k:'ship', kp:{s:22,n:6,c:'#c8c0b8',needle:1},
 s:'地道的虚空生物：不靠任何东西，就在虚空里自己长大。',
 d:'它们必须连进梦境体内才能产生生活必需的物质，于是被“恐怖寄生体”寄生——先是微生物，后来寄生在它们的梦境里，化作一棵“柳树”。‘不能再让它管着我们了！’寄生体控制了苦钉民所有的造物，唯独没控制住苦钉民本身。',
 ch:'卷三《结束寄生》《攻击》《解锁》《击落》《设计》', rel:['v_painland']},
{id:'v_amber', n:'琥珀之球 · 熔块', c:'地理', m:'void', sec:11, e:[11], p:[-200,-100,-350], k:'planet', kp:{r:40,tex:'amber',c1:'#e8a03a',c2:'#8a4a1a',isles:6},
 s:'琥珀生物的世界，浮岛上的都市。它的源头是一个以尸体为材料的文明。',
 d:'“熔块”从不收集建筑材料，用的全是同类的尸体：低温死去的熔块变成“原冷石”，偶尔变成“星空之惠”。它们升华进一个“火球”，从不研究自身。熔创者体内像大量齿轮；琥珀外壳的橘红小虫是这里最常见的生物。琥珀生物捕获了传说中的“永痛之王”，要把它放到地底核心……最后它们跟着新世界冲进了“永痛之渊”，只活下来一个琥珀，一遍遍呼唤着深爱之物。',
 ch:'卷三《建立》《星空的恩惠》《抵达？》《古老的平静》《永痛之渊》《无边》', rel:['v_pain','v_dongchuang']},
{id:'v_dongchuang', n:'冬创者 · 脑堡', c:'物种', m:'void', sec:11, e:[11], p:[-430,-120,-400], k:'planet', kp:{r:24,tex:'ice',c1:'#d8f0ff',c2:'#6aa8c8',glow:.3},
 s:'住在直径不到一毫米的冰晶洞穴里的小生物；以及把最脆弱的脑放在最外面的“脑堡”。',
 d:'琳管它叫“永冬创造者”：常年困在严寒与痛苦中、死了又活的创造者，于是简称冬创者；既然另有一个“熔创者”，琳猜两者都跟琥珀创造者脱不了关系。它的脑很复杂，能听懂许多创造者的语言，包括“核信息”。冰层里有个十多米宽的“储藏室”，飘满一厘米大小、刻满信息的小石块。皮肤通常是生物的第一道防线，脑堡却反过来：外围是没有记忆、死后被快速替换的脑细胞，内部是透明物质构成的迷宫。冬创者是“小创造者”之一，群星联盟见它们学什么都快，给了它们正式公民的身份和教育；只有它一个进了痛苦之地，同伴们不知去向。',
 ch:'卷三《永冬之中》《冰层的生态》《脑堡》《成长》《复苏》', rel:['v_amber','v_xingmeng']},
{id:'v_xingmeng', n:'群星联盟', c:'文明', m:'void', sec:11, e:[11], p:[0,120,-300], k:'ship', kp:{s:20,n:14,c:'#d8dde8'},
 s:'横跨多个星系的庞大帝国。',
 d:'上万艘战舰来到“地狱”入口，带着“空间坍塌弹”——据说能让空间恢复成最原始的状态：传送能量。联盟把武器分成“步兵级”“战斗级”等等。它们很尊敬巴士生物，也相信会回答问题的“宙脑”，虽然每次都要犹豫讨论一阵才下决定。后来整个联盟被“静止”了。',
 ch:'卷三《传说中的地狱》《接触》《坍塌？》《宙脑》《传递的方式》', rel:['v_zhounao','v_painland','v_liquid']},
{id:'v_zhounao', n:'宙脑', c:'物种', m:'void', sec:11, e:[11], p:[120,-60,-500], k:'planet', kp:{r:28,tex:'rock',c1:'#7a7068',c2:'#4a443e'},
 s:'会回答疑问者许多问题的世界——看上去只是一颗荒芜的岩石翻滚者。',
 d:'它在一个文明里做着和从前一样的事——当“预报者”：报告周围的威胁、灾害和资源，从不说假话，在群星联盟时也是如此。后来它主动找上琥珀创造者，说要制造一个“奇迹”：愿意就合作，不愿意就先解决掉对方再做。它的奇迹是把一个满是和平生物的世界送进痛苦之地，至于会出现什么，它没说。小宙脑后来陪琳去找调停者，被救回平台的生物却大多不信任它。',
 ch:'卷三《宙脑》《交流？》《发明？》《源头》', rel:['v_xingmeng','v_tianlan']},
{id:'v_tianlan', n:'天蓝色世界', c:'地理', m:'void', sec:11, e:[11], p:[300,40,-450], k:'planet', kp:{r:36,tex:'jungle',c1:'#6ab8e8',c2:'#3a7ab8',atm:'#bfe8ff',fluffy:1},
 s:'直径六千多公里，纵横的藤蔓间生活着毛茸茸的天蓝色生物。',
 d:'一颗直径六千多公里的天蓝色世界：地表爬满纵横的藤蔓，藤蔓间生活着无数天蓝色、毛茸茸的小生物——这是宙脑的世界。琥珀创造者用裂空团组装的“神器”开启通道时，它突然出现在琥珀球附近；创造者起初以为神器不靠谱、连错了地方，可神器从来也弄不来这么大的东西，于是派出琥珀物质组成的部队登陆调查。宙脑认为，把这个住满和平生物的世界推进痛苦之地，一定会出现奇迹。后来，琥珀生物的身体大部分被琥珀物质替代，只留下极少的神经——它们原本就来自这里的藤蔓。',
 ch:'卷三《第二次接触》《制造》《变化》', rel:['v_zhounao','v_amber']},
{id:'v_liquid', n:'虚空的缝隙 · 液体球', c:'地理', m:'void', sec:11, e:[11], p:[220,-60,-60], k:'planet', kp:{r:30,tex:'ocean',c1:'#2a8ab8',c2:'#0a3a5a',blob:1},
 s:'三个虚空之间的缝隙，以及在这里漂浮的“意识的聚集体”。',
 d:'液体球与痛苦巴士碰撞融合后，景色完全变了：珊瑚和植物般的生物丛生在海床上，潜艇在被红色浓雾染成鲜血般的水域中前进。“捕获球”平时像一片正常的海洋，有巴士接近时就分解一切，重新变回液体球去袭击。资料库曾把群星联盟的“空间维持场”转移到自己身上，和联盟对换了位置。',
 ch:'卷三《海洋》《重构的世界》《快速重组》《不正常》《虚空之间》', rel:['v_xingmeng','v_mimic','v_pain']},
{id:'v_mimic', n:'模仿之星 · 疯狂战场', c:'地理', m:'void', sec:11, e:[11], p:[400,-20,-150], k:'planet', kp:{r:26,tex:'jungle',c1:'#5aa85a',c2:'#2a5a2a',spikes:1},
 s:'遍布绿色“模仿者”的世界；这个星系最远的第七颗翻滚者叫疯狂战场。',
 d:'模仿者模仿得很像，又不太像——它提醒大家：别看它们像一群只会过日子的无害机器，其实很阴险。第七颗又冷又黑，却很热闹：战争生物里会出现吃同类尸体、继承记忆的“食尸者”；第六颗的地底遍布一个控制一切“点数”的巨大器官。',
 ch:'卷三《模仿？》《战场》《已经诞生》《点数核心》', rel:['v_liquid']},
{id:'v_seabeast', n:'虚空海兽', c:'物种', m:'void', sec:11, e:[11], p:[520,80,120], k:'swarm', kp:{n:100,s:40,c:'#4a8ab8'},
 s:'数百万只海兽同时朝琳的翻滚者吐出火球。',
 d:'它们从一个连接远处虚空的通道而来，躲在废弃物里伏击。冰川一样排成长队缓缓移动的虚空巴士，在“扔掉”什么。',
 ch:'卷三《出没点》《海兽与巴士》《扔的位置》《同伴》', rel:['v_xingyan']},
{id:'v_xingyan', n:'星焰之民 · 焰星球', c:'文明', m:'void', sec:11, e:[11], p:[300,120,200], k:'star', kp:{r:22,c:'#ff7a3a',n:5},
 s:'痴迷高温的高温生物——它们都从恒星中诞生。',
 d:'‘群星之神……’所有星焰之民像尔什民蹲下抱头一样崇拜它。它们遵循焰星球的指引去“白金矿场”采集石块。焰星球光往体内加燃料迟早会熄灭，分裂成多个却能一直燃烧。它们那时自称“永焰者”，不断追求极热；后来寒冷灾难降临，一个巨大的同类“星焰堡”屈服于寒冷，变成了“霜堡”。',
 ch:'卷三《同类》《温暖的过去》《抵抗》《永燃》', rel:['v_shuangbao','v_ranxing']},
{id:'v_shuangbao', n:'霜堡', c:'地理', m:'void', sec:11, e:[11], p:[100,-140,240], k:'planet', kp:{r:34,tex:'ice',c1:'#f0f8ff',c2:'#a8c8e0',atm:'#e8f8ff'},
 s:'曾经的“星焰堡”，向寒冷屈服的世界。',
 d:'焰星球回来时，天空亮起无数光辉，它们认为霜堡是背叛者。后来“资料库”占据了霜堡，冰晶般的小型机械包围了坠落的飞行器；地下雪原里，雪地造脑怪似的幼仔一路唱着歌：它们要回家，去找那个传说里的家，再危险也不怕。',
 ch:'卷三《过程与谜团》《过去的寒冷》《霜堡之旅》《外面》', rel:['v_xingyan','v_ranxing']},
{id:'v_ranxing', n:'燃星者', c:'物种', m:'void', sec:11, e:[11], p:[-80,-60,420], k:'star', kp:{r:46,c:'#ff4a1a',flare:1},
 s:'古老的高温生物，最喜欢把寒冷的世界变成熊熊燃烧的世界。',
 d:'它身边像一片活动的“无空间带”，会把传送能量挤开，所以无法直接把东西传送到它身上。它的“远古空间”能看到历史，却不能回到过去；它经历过好几次“终末”，在每次终末后带着最终形态的能力重新开始。它曾与永焰一起在虚空里到处跑，看过许多奇妙的东西。最后它慢慢熄灭了，残骸被琳用来造出“小尔什”。',
 ch:'卷三《燃星》《研究》《过往》《星焰的相遇》《观察过去》《结束》', rel:['v_xingyan','v_xiaoerxi','v_nospace']},
{id:'v_nospace', n:'无空间带 · 文明之惧', c:'地理', m:'void', sec:11, e:[11], p:[560,-100,360], k:'fog', kp:{r:120,n:40,c:'#2a2430'},
 s:'过去文明密集的时代，充斥着向往又恐惧星空的文明。',
 d:'“文明之惧”生物在这里不停吞噬、摧毁舰船。“荒魇”会把战场残骸记录下来，飞到另一个地方造出一模一样的战场废墟当陷阱。也有文明发展到巅峰：像一团燃烧的金色火焰、其实是低温固体的“燃金”，造出了“无边之垒”。白树长着坚固的树皮和内部的金属结构，长大后会脱离地表飘进虚空。',
 ch:'卷三《废墟》《树木中》《阻止》《开启》', rel:['v_ranxing','v_baishu']},
{id:'v_baishu', n:'白树', c:'物种', m:'void', sec:11, e:[11], p:[640,0,430], k:'tree', kp:{s:24,c:'#f0ece0'},
 s:'它们发誓一代一代守在这里，直到最后。',
 d:'最初在“陆地”上像普通树木一样靠根系吸收养分，同时在体内储藏大量矿物；长到一定程度后脱离地表，飘到虚空中，发生很大的变化。',
 ch:'卷三《树木中》《研究》', rel:['v_nospace']},
{id:'v_xiaoerxi', n:'小尔什', c:'琳的造物', m:'void', sec:11, e:[11], p:[-360,100,380], k:'planet', kp:{r:30,tex:'earth',c1:'#4a8a4a',c2:'#2a5a8a',atm:'#9ad0ff'},
 s:'用燃星者的残骸造出的一颗“尔什”，花了差不多一个绒球年。',
 d:'一切都要求“完美”，外表和内在都与真实的尔什接近，里面有不会活动的仿巴士内脏。它在远古空间里逆流航行了两个多绒球年，遇到喜欢谈论天气的古代生物“未蛸”、感染空间站的肉块，以及三颗陆块一模一样、环境却完全不同的“尔什”。',
 ch:'卷三《远处》《天气……很好》《家园？》《三颗世界》', rel:['v_ranxing','v_qijizhidu','ex_planet']},
{id:'v_qijizhidu', n:'奇迹之都', c:'文明', m:'void', sec:11, e:[11], p:[-520,40,250], k:'city', kp:{s:24,c:'#d8c8a8',float:1},
 s:'在虚空中漂泊的建筑群，遇到谁就变成谁的建筑样式。',
 d:'它是奇迹生物的交流点之一。招呼来客的说法是：这里什么都可能有，连虚空的真理、一切的最终答案也说不定。猿类发现了它的作用；后来它在琳眼前迅速崩溃，碎成粉末。黑白色、由数十米片状物组成的“修理者”一直在清理奇迹。',
 ch:'卷三《回忆与奇迹》《普通的奇迹》《现象》《扭曲与奇迹》《修理者》', rel:['v_xiaoerxi','v_xiuli']},
{id:'v_xiuli', n:'修理者 · 黑白片', c:'物种', m:'void', sec:11, e:[11], p:[-620,-80,400], k:'crystal', kp:{s:16,c:'#e8e8e8',c2:'#141414',flakes:1},
 s:'一堆数十米大的黑白片状物组合成的生物。',
 d:'金色球体告诉琳：“这个生物有点可疑。”据修理者自己说，尔什和巴士们曾试图造出些什么，创造之海又试图扭曲它们的造物，这些能量在奇迹的作用下混在一起，再掺进空间里找到的部件，才成了它。琳见到的好几处远古空间，都是它修补出来的——只要开始修，那些空间就会自己慢慢长大。后来它在远古空间里读到了自己的来历，觉得自己已经成功了，不再去干扰奇迹生物的复苏，只想继续在虚空中游荡。',
 ch:'卷三《修理者》《可疑？》《停止》', rel:['v_qijizhidu']},
{id:'v_haishen', n:'海参 · 秩序之域', c:'地理', m:'void', sec:11, e:[11], p:[0,0,560], k:'whale', kp:{s:80,c:'#4a3a3a',seacuc:1},
 s:'巨大的海参状生物，体内是被“扭曲”完全控制的秩序之域。',
 d:'秩序之域分成许多层：第99层是“众神的厅堂”——白银地面、金色光辉、上百米的石柱，原本放置虚空中各种“超级生物”的强大意识；更深处是“遗忘之席”，太久没出现的生物，影子就被放到那里。还有“漏洞之地”、血色的隐藏层、修正液的海洋。防御者负责清除漏洞生物和逃离者；金属尔什民一层层占领了所有地方。',
 ch:'卷三《计划》《秩序区域》《众神？》《侵略》《过去的计划》《修正的进攻》', rel:['v_chuangzao','v_wanliu']},
{id:'v_wanliu', n:'万流之台', c:'地理', m:'void', sec:11, e:[11], p:[260,-120,600], k:'disc', kp:{r:50,c:'#d8dde2',c2:'#9aa0a8'},
 s:'许多扭曲点产生的“暖流”汇聚成的平台，直径一百多公里。',
 d:'虚空中一块银色的平台，直径一百多公里，厚度只有几百米，表面布满裂痕和坑洞，由许多扭曲点产生的“暖流”汇聚而成。上面长着几万个十米高、像藤壶一样的“思维”，它们互相制造武器厮杀，几乎全死光了；最后的胜者被自己造得太聪明的造物杀死。只剩边缘一个长得像蘑菇的，靠不停把自己伪装成别的东西活了下来。曾有一个程度很高的文明探索过整个虚空暖流，把这里称为“废弃物终点站”。',
 ch:'卷三《留下》《寻找》《感知》', rel:['v_haishen']},
{id:'v_chuangzao', n:'创造之海', c:'地理', m:'void', sec:11, e:[6,11,12], p:[440,60,620], k:'planet', kp:{r:44,tex:'ocean',c1:'#3ac8d8',c2:'#0a6a8a',atm:'#bff8ff',glow:.4},
 s:'传说所有创造者都是从这里来的，地表几乎全是海。',
 d:'传说所有创造者都是从这里来的，这颗翻滚者的地表几乎全是海。创造者专门猎食翻滚者那么大的巨型生物，不断创造、再吞噬庞大的生态，来扩充自己的细胞信息库；它们造出数不清的物种，总有些活下来、旅行到各处，所以无愧“创造者”之名——它们最想要的是一个完美的生态、完美的世界，不在乎它在真实还是梦境里。脑灵照老样子靠近这颗翻滚者，结果整支部队一下子就被毁掉了，上面的创造者都十分强大。以尔什为主的生物曾用武器把它推进了某个地方；它收集了虚空中几乎一切的数据——那些数据也可以说就是它的意识。',
 ch:'卷三《虚空之中》《武器》《新旅行目标》《隐藏的入口》', rel:['creator','v_haishen','dr_bridge']},

/* ---------- 星区 12 ---------- */
{id:'v_benglie', n:'崩裂虚空 · 重合者', c:'地理', m:'void', sec:12, e:[12], p:[0,0,0], k:'rocks', kp:{r:260,n:200,s:12,c:'#6a6070',shards:1},
 s:'分崩离析的虚空。它在崩塌后期不断复制正常虚空的事物。',
 d:'“在不知不觉中，世界已经分崩离析了。”重合者是来自这里的漂流文明，使命是把所有碎裂的空间重合起来：调查每个碎块的数据，整合成混合的空间环境。它们的意识和尔什“相同”。重合者被小管道——“经历掠夺者”——不断袭击，最终灭亡，又以小管道的形式活了下来；米德加尔特的调查员把它们做成了历史幻象。',
 ch:'卷三《缓慢的崩裂》《重合》《小管道》《远古》《最后的飘荡》《记录和寄托》', rel:['v_xiaoguan','v_huanxiang','c_sarin']},
{id:'v_xiaoguan', n:'小管道 · 经历掠夺者', c:'物种', m:'void', sec:12, e:[12], p:[140,60,100], k:'tube', kp:{len:90,r:8,c:'#6a5a5a'},
 s:'获取别人“经历”的小型管道。幼仔也有数十米。',
 d:'重合者是一群从原本的空间出走、在虚空中漂流的生物，漂流途中最要命的威胁，正是这些小型管道，被它们叫作“经历掠夺者”——一直在袭击它们，夺取它们的经历。琳在圆盘形遗迹里打开的东西中，还发现一个只有几十米大、像迷你模型的小管道，造型和大的一模一样。它们快速恢复的能力来自身上类似微型机械的东西，身上还长出不少重合者文明的技术产物。重合者发现，自己种族的历史就在一个小管道身上——上面住着处于不同时期的重合者。',
 ch:'卷三《小管道》《捕获》《了解》《远古》《熟悉之物》', rel:['v_benglie']},
{id:'v_huanxiang', n:'幻象世界', c:'地理', m:'void', sec:12, e:[12], p:[-300,40,-150], k:'planet', kp:{r:40,tex:'dark',c1:'#3a2a5a',c2:'#8a6ab8',hollow:1,glow:.4},
 s:'换了一种样子的米德加尔特虚空：一切飘忽不定，各种时代混合在一起。',
 d:'莎琳的分身当年从虚空的裂痕进出“真实世界”和“幻象世界”，有一次深入太久，回来时入口消失了，它在那里看到了自己。“吞噬幻象的翻滚者”地壳只有几公里，内部是巨大的空心；多余的幻象生物被聚集到这里慢慢处理掉，调查员沉睡在薄薄的地层里。',
 ch:'卷三《连接的时代》《形成》《真实的幻象》《出口》《离开》《调查员？》', rel:['v_benglie','c_sarin']},
{id:'v_paixing', n:'拍星器 · 护门者', c:'物种', m:'void', sec:12, e:[12], p:[300,-60,-300], k:'star', kp:{r:60,c:'#f8f8ff'},
 s:'一颗白色恒星。地表上有用四肢走路、专门“拍恒星”的车形生物。',
 d:'恒星偶尔会“爆闪”，拍星器就拍下那一刻。护门者负责堵住一处会毁掉整颗翻滚者的“虚空泄露”；守得太久，不少个体觉得泄露只是传说，分裂出去组成了部落，只有一群一直坚持着。很久以前米德加尔特飞进过这颗恒星。',
 ch:'卷三《组装》《拍摄》《拍摄阻止》《侵蚀？》《入侵》', rel:['v_xinhao']},
{id:'v_xinhao', n:'信号幽灵', c:'物种', m:'void', sec:12, e:[12], p:[380,80,-120], k:'jelly', kp:{s:16,n:7,c:'#cfe8ff'},
 s:'在信号中诞生、像半透明水母的生物，几十米大。',
 d:'附近有很多早已灭亡的文明废墟，它们来自不同文明，但发出的信号混在一起，生出了这种幽灵。据莎琳说，是一种挺有趣的生物。',
 ch:'卷三《信号》《减速》', rel:['v_paixing','c_sarin']},
{id:'v_pantian', n:'攀天城', c:'物种', m:'void', sec:12, e:[12], p:[540,0,-440], k:'blob', kp:{s:30,c:'#6a4a5a',tentacles:1},
 s:'巨大的触手团，内部是大量更小的触手。',
 d:'一团巨大的触手，叫‘攀天城’。它把‘车轮’救走之后，琳原本以为它还会再对莎琳出手，它却没有，而是一路飞离恒星，往深空去。琳一边跟着，一边试着钻进它里面：触手内部是更多更小的触手，组成类似肌肉的结构，撑着外面的大触手转动。十多亿公里外，十个银色的圆环叠在一起，构成一件武器。',
 ch:'卷三《逃》《储藏》《武器》', rel:['v_rings']},
{id:'v_rings', n:'十个银色圆环', c:'现象', m:'void', sec:12, e:[12], p:[160,-120,-540], k:'ring', kp:{r:40,n:10,c:'#d8dde2',stack:1},
 s:'停在离恒星十几亿公里远处、一动不动的巨大物体。',
 d:'“准备好了。”',
 ch:'卷三《武器》', rel:['v_pantian']},
{id:'v_hunhe', n:'混合虚空 · 安全区', c:'地理', m:'void', sec:12, e:[12], p:[-500,-60,200], k:'vortex', kp:{r:120,c:'#ffe8a0',light:1},
 s:'一个上百万公里、闪耀着强光缓缓旋转的漩涡。',
 d:'尔什曾为脆弱的生物造过一个“安全区”，大概有十光年以上；“异生者”向它所有的领地发射雾球，被击中的区域长出越来越大的土丘般的怪东西，安全区文明就此灭亡。尔什想起来，当年造这个混合虚空，其实是想造一个“旅行空间”。',
 ch:'卷三《混合物》《安全》《安全区的最后》《困住》《过去的旅行》', rel:['ex_planet','v_yingzhe']},
{id:'v_yingzhe', n:'影遮', c:'物种', m:'void', sec:12, e:[12], p:[-620,60,-60], k:'shadow', kp:{s:40},
 s:'一种“活动的环境”。它攻击时，周围的一切感知都被遮蔽。',
 d:'一种“活动的环境”：外壳像一层气泡，把内部和外面隔开；它发动攻击时，周围的一切感知都会被遮蔽。里面没有寻常的生物结构，而是一片会变化的区域，像慢得多的混沌区域——几千秒才换一次景色：有时是飘满方块的一片白，方块摸得到，下次一变就瞬间消失；有时什么也没有。这里住着“影民”，有像尔什民的、像动物的、像植物的，都被黑色火焰般的东西完全包裹；影民恢复后会变回原本的“寄舰”。尔什也来过这里。',
 ch:'卷三《影内》《攻击》《回忆物》《变化》《移动》', rel:['v_dingzhi']},
{id:'v_dingzhi', n:'定制之环 · 凝结文明', c:'文明', m:'void', sec:12, e:[12], p:[-420,120,-320], k:'ring', kp:{r:20,n:3,c:'#e8c25a'},
 s:'像金色圆环一样的舰长，与它们早已离开的凝结文明。',
 d:'凝结文明从混沌中捕获信息，发明了“定制之环”去获取想要的内容，比如一种能量和另一种接触会发生什么。它们离开后，许多定制之环还在履行使命。废墟里最常见的是结晶构成的树枝。凝结生物曾在尔什地表放下“陆地裂解器”，遭到干瘪的“荒民”猛烈反击。',
 ch:'卷三《汇聚点》《环中生物》《废墟》《识别》《疑惑》《完美的》', rel:['v_kuxing','v_yingzhe']},
{id:'v_kuxing', n:'枯星', c:'地理', m:'void', sec:12, e:[12], p:[-300,-120,-420], k:'planet', kp:{r:36,tex:'sand',c1:'#c8a87a',c2:'#8a6a4a'},
 s:'一颗没有水分的“尔什”，地表是干枯的裂谷与山峰。',
 d:'定制之环的驱逐光束落在上面毫无效果。地下的水池里慢慢长出藤蔓一样的东西——它干枯的原因就在这里。它可以用思维驾驶。混沌战舰里，一颗新构成的“尔什”迅速发展，尔什民们在问：要继续生活在痛苦的现实，还是在虚拟世界获得永恒的快乐？',
 ch:'卷三《干枯》《枯星深处》《移动方式》《构造的新世界》《享乐》', rel:['v_dingzhi','ex_planet']},
{id:'v_renzhi', n:'认知末日 · 万变之颅', c:'现象', m:'void', sec:12, e:[12], p:[300,100,250], k:'skull', kp:{s:40,c:'#d8d0c0'},
 s:'如果智慧生物一直认知、思考正常虚空，“末日”就会接近，让一切归于寂静。',
 d:'相信认知末日的文明决定让所有文明远离对现实的认知。认知者的世界里，所有生物认知到的都是同一个世界。万变之颅从外面看是巨大的尔什民头骨——每个生物看到的样子都不一样，尔什民看到的是自己的头骨。“事件卡片”记录灾难发生的瞬间；它们认为莎琳会把认知末日传到虚空各处。',
 ch:'卷三《认知》《认知的另一边》《卡片》《内部》《追寻之末》', rel:['v_zhuixun','c_sarin']},
{id:'v_zhuixun', n:'追寻之月', c:'地理', m:'void', sec:12, e:[12], p:[420,160,180], k:'planet', kp:{r:20,tex:'rock',c1:'#c8c8c0',c2:'#8a8a84'},
 s:'不可预见之地里生成的、模仿正常虚空翻滚者的“翻滚者”。',
 d:'它长得像尔什的卫星，大小也接近，所以莎琳叫它‘月’。莎琳很早以前在不可预见之地碰见过它，出于好奇还在上面研究了一阵。后来莎琳飞到一些卡片面前，只隔几米，卡片告诉它其中的关系：造卡片的文明受了追寻之月的影响，把自己封闭起来，靠自己造的维生设备和虚拟现实，把追寻之月的样子仿了出来，让整个文明住在里面。',
 ch:'卷三《追寻》《认知结果》', rel:['v_renzhi','c_sarin']},
{id:'v_keli', n:'颗粒生物', c:'物种', m:'void', sec:12, e:[12], p:[80,-140,380], k:'swarm', kp:{n:300,s:40,c:'#c8c8d8'},
 s:'极古老的观察者。它的文明是忽然“停止”的。',
 d:'殖民地的建筑完整，居民也完整——只是像突然停住了一样。它亲眼看过“寂静的末日”卷过许多文明：凝固虚空很久以前并不凝固，是静止扩散之后才变成这样。它对抗了静止很久很久，最后还是没能阻止。它见证了两个虚空的众多变化，以及管道这种生物的一生。',
 ch:'卷三《寂灭》《转变》《蔓延》《静止的原初》《最后》', rel:['v_shiwu','v_huangwo','v_piaobo']},
{id:'v_shiwu', n:'噬物之星', c:'物种', m:'void', sec:12, e:[12], p:[-80,-60,540], k:'planet', kp:{r:34,tex:'flesh',c1:'#6a4a4a',c2:'#3a2a2a'},
 s:'碎裂的翻滚者陆块铺满尸骸，又重新连在一起，成了一个巨型生物。',
 d:'碎裂的翻滚者陆块铺满尸骸，又重新连在一起，成了一个巨型生物，文明生物叫它“噬物之星”。静止的世界里组装东西很容易：把各种内脏、躯壳和材料拼在一起。文明生物太过寂寞，对着一动不动的躯壳讲述它们的历史，躯壳便开始活动。它渴望生长，变得更大，用猎物的材料造出“永动之光”射向远处，第二次瞄得准多了。荒涡把它拆开，放进城市的生态园，可它没有死：丢些资源在它表面，它就长出颜色丰富、形态各异、像花一样的结构，荒涡慢慢从研究它怎么长，变成研究怎么让它长得好看。',
 ch:'卷三《生长》《学习》《活动》《完全生长》《行为》', rel:['v_keli','v_huangwo']},
{id:'v_huangwo', n:'荒涡 · 静止之源', c:'文明', m:'void', sec:12, e:[12], p:[260,-40,580], k:'disc', kp:{r:90,c:'#5a5048',c2:'#0a0a0a',hole:1},
 s:'建在一个直径六千多公里、厚只有数百米的巨大洞口周围的文明。',
 d:'它们把尸体和废弃物丢进洞口“轮回之地”，相信它们会经过轮回回来——洞口涌出的碎块正是文明繁荣的来源。后来洞口有了新名字：“静止之源”。在颗粒生物的指引下，荒涡把城市设施换成“永久活动之物”，对抗静止；复骸者挖掘远古巨型生物的器官，只复苏单个器官；一场“静止与活动的战争”开始了。',
 ch:'卷三《大型的文明》《漩涡》《静止扩散》《对抗静止》《静止的场面》《最后的静止》', rel:['v_keli','v_shiwu']},
{id:'v_piaobo', n:'漂泊者之家 · 末日之眼', c:'物种', m:'void', sec:12, e:[12], p:[-460,60,460], k:'tube', kp:{len:520,r:34,c:'#5a5a6a',glow:'#ffb04a'},
 s:'一根特别的管道：它不培育文明，身上却住满了漂泊的生物。',
 d:'它去的地方越来越特别，身上的文明不断替换，越来越强大。最长久的居民是“末日之眼”——一种针对个性生物文明的灭世型生物，早期像真菌一样小而无害，长到足够大后开始观察……最后它像一层皮肤一样从管道上脱离。在崩溃之界里，漂泊者之家度过了最后的旅途，研究那里的一切，也发现那里有东西在研究它。',
 ch:'卷三《漂泊》《虚空之间的旅途》《最后的研究》《崩溃》《隐藏》', rel:['v_xiubu','v_keli']},
{id:'v_xiubu', n:'修补匠', c:'物种', m:'void', sec:12, e:[12], p:[-660,0,540], k:'crystal', kp:{s:20,c:'#a8a8b8'},
 s:'认为虚空像飘在“无”中的气泡，要修补边缘漏气的地方。',
 d:'它们住在崩溃之界的边境，很清楚这个虚空正在缩小。它们只能活在特别规则的空间里，在正常虚空中会直接消散；模仿外界的生物让它们产生了离开的渴望。它们的大本营融合了大量空间，让这些空间失去“支撑”——两个虚空因此更接近了。',
 ch:'卷三《修复》《变形》《目的》《位置》《异常》《感知与变化》', rel:['v_piaobo','v_wufa','v_collide']},
{id:'v_wufa', n:'无法解析者', c:'物种', m:'void', sec:12, e:[12], p:[-200,160,660], k:'shadow', kp:{s:30,shrink:1},
 s:'像一团巨大的影子，能投影在任何东西上，甚至遮蔽整颗翻滚者，却没有实体。',
 d:'它靠一种隐秘的、直径一米多的空间通道在许多空间间移动，墙上细小的黑点是更小的通道，连着修补匠和各种生物的思维。它的意思是：你很可能了解一切——也正因为如此，你不能了解一切。它说，虚空的碰撞大概会持续十个尔什年，然后进入完全融合的状态——到那时，或许会冒出全新的规则和全新的生物。',
 ch:'卷三《解析？》《碰撞之初》', rel:['v_xiubu','v_collide']},
{id:'v_march', n:'三月', c:'琳的造物', m:'void', sec:12, e:[12], p:[120,40,720], k:'planet', kp:{r:40,tex:'rock',c1:'#8a8478',c2:'#5a564e',moons:2},
 s:'琳的兵种：一颗直径一千公里的小型翻滚者，带着两颗三十公里的卫星。',
 d:'琳的兵种：一颗直径一千公里的小型翻滚者，带着两颗三十公里的卫星。它去调查一道一千公里长、数公里宽、伸出许多枝杈般细小裂痕的巨大裂痕。随后数千万矛状飞行器落在三月和两颗卫星上——那是“裂口的文明”：落地时凶猛地直接撞上地表，里面的生物出来后却不知道做什么，只在荒凉的岩石原上到处游荡。琳抓了几只研究，发现它们是颗粒生物当年派出的探索队的后代——有不少成员不愿再走，在虚空各处定居，有的发展成了庞大的文明。三月能感知到无法解析者现身时的空间变化。',
 ch:'卷三《起源》《裂口的文明》《消失》', rel:['v_wufa','c_lin3']},
{id:'v_collide', n:'虚空的碰撞', c:'事件', m:'void', sec:12, e:[12], p:[0,0,820], k:'cracks', kp:{r:200,c:'#cfd8ff',c2:'#ffd27a',glass:1},
 s:'星空越来越暗了。两个虚空的碰撞开始了。',
 d:'琳的“眼睛”分布在虚空中许多地方，看着这一切；她已经把许多东西移到了安全的位置。直接接触裂痕的生物会受到较大的影响；有的区域出现凝固，有的地方出现前所未有的东西，可能诞生于某种新的规则。txt 到这里就结束了。',
 ch:'卷三《碰撞之初》', rel:['v_wufa','v_xiubu','v_march']}
);

/* 卷三：梦境（t 为沿光之大路的位置 0–1，off 为偏移） */
window.WIKI.push(
/* ---------- 时代 6：黑金属与脑灵的梦 ---------- */
{id:'dr_road', n:'光之大路', c:'现象', m:'dream', r:'dr6', e:[6,8,9,10,11], t:.015, off:[0,30,0], k:'none',
 s:'完全黑暗的世界里，一条发着光的大道。道路两侧是星空。',
 d:'每次进入这个梦境，琳都出现在光之道路的开端。道路通常有数十米宽；到了“边缘之地”，却只剩半米宽，弯弯曲曲、上下起伏。光之大路的任务快要结束，尽头就要到了；绒毛被要求拿出自己的证明。这张地图用这条路把各个梦境串在一起——这是示意，并不是说它们真的在一条路上。',
 ch:'卷三《梦中的天国》《边缘之地》', rel:['dr_edge','c_tentacle','dr_brainspirit']},
{id:'dr_tianguo', n:'梦中的天国', c:'地理', m:'dream', r:'dr6', e:[6], t:.05, off:[-140,-20,40], k:'island', kp:{r:60,c:'#2f6a3a',c2:'#5a4a3a',houses:12},
 s:'丛林里住着几十户虚民的梦。',
 d:'虚民的梦：丛林里零零散散住着几十户人家，白天在林间听虫鸣闻花香，夜里看星星，不用工作，邻里关系很好，常在花园里聊天、玩过去的游戏。东西大多是石头和木头做的，却也有能连网的立体影像装置。琳借来连接梦境的那个虚民叛徒也住在这里，虽然是新来的，很快就融入了。有很多房子没有虚民住。琳造了一颗足够大的绒球再次进入，找了间空房子，用影像装置上网查资料——之前那颗绒球太小，打不开这些装置。',
 ch:'卷三《梦中的天国》', rel:['dr_road']},
{id:'dr_prison', n:'梦中的监狱', c:'地理', m:'dream', r:'dr6', e:[6], t:.11, off:[150,10,-30], k:'cube', kp:{s:70,c:'#2a2a34',cells:1},
 s:'无尽的监牢和狱卒。一个被囚禁的“创造者”在这里叫琳“绒毛”。',
 d:'它们遇到的每一个活物都会被‘保留’在这里；可对被保留的生物来说，这里是一座永远不会结束的监牢。那为什么又要造一个放它们出去的机关？有守卫向上面报告：这批里面有几个特别的。琳和创造者谈了很多，还逃出了囚禁之地。',
 ch:'卷三《监狱》《难得的交流》《逃出囚禁之地》《监狱风云》', rel:['c_tentacle','v_prison']},
{id:'dr_zhuan', n:'中转之地', c:'地理', m:'dream', r:'dr6', e:[6], t:.16, off:[-120,40,-60], k:'island', kp:{r:30,c:'#5a5a6a',c2:'#3a3a48'},
 s:'‘绒毛，你做到了。’',
 d:'琳打开了通道，在这里等创造者回来；还没到约好的五个昼夜，创造者就出现了：‘绒毛，你做到了。’它说，绒球杀掉了一个时代里的“愚者”，愚者倒下，真正的通道才会显现，管理者也正是由此回到居所。在等待的时候，琳也看了一部分黑金属入侵的往事：是不是某个虚民不小心接触了虚空巴士留下的金属，行为才开始变得怪异？琳猜，脑灵也许能借那块金属直接寄生到虚民身上，于是决定去母球上把它找出来。',
 ch:'卷三《通路》《找到通路》《建筑中的世界》', rel:['c_tentacle']},
{id:'dr_juso', n:'居所与构造之地', c:'地理', m:'dream', r:'dr6', e:[6], t:.2, off:[160,-30,50], k:'island', kp:{r:70,c:'#e8c87a',c2:'#b8903a',orbs:30},
 s:'强烈的阳光和沙漠，天上飞满了互相玩耍的光团。',
 d:'强烈的阳光下是一片沙漠，天上飞满了光团，像在互相玩耍：晃动、旋转、变成各种形状，完全没注意到绒球和创造者的触手。创造者说，它们没有自己的世界，所以住进自己喜欢的世界里；这里时不时会冒出几个迷路的愚者，它们也不在意。绒球觉得它们虽然快乐，却总在重复同样的事；创造者说不，它们会经常换花样——在尝试别的物种的娱乐。',
 ch:'卷三《居所与构造之地》', rel:['c_tentacle']},
{id:'dr_era', n:'时代的杀戮者', c:'地理', m:'dream', r:'dr6', e:[6], t:.24, off:[-150,0,30], k:'island', kp:{r:44,c:'#6a5a42',c2:'#4a3a2a',castle:1},
 s:'中世纪战争的梦。‘哈哈，上酒！’',
 d:'在梦里，虚民可以任选一个时代、一个身份，想做什么就做什么。一位中世纪领主正大口喝酒，嚷着下个昼夜就去打某个伯爵的领地，一定大获全胜；绒球和创造者躲在床底下看着。创造者说，看那个沉浸在小小欲望里的愚者——下一刻它的触手就穿透了领主的胸膛，周围的仆从扑上去大喊“领主”。创造者的意思是：要找到真正的出路，这些欲望就得被湮灭。',
 ch:'卷三《不同的时代之中》《时代的杀戮者》《历史的见证》', rel:['c_tentacle']},
{id:'dr_edge', n:'边缘之地', c:'地理', m:'dream', r:'dr6', e:[6], t:.28, off:[110,-60,-40], k:'none',
 s:'光之大路的尽头：一条只有半米宽、弯弯曲曲的路。最后的试炼。',
 d:'光之大路的尽头，路面从几十米宽缩成半米左右，弯弯曲曲、上下起伏，一不小心就会跌进无尽的黑暗——创造者说，那和死没什么区别。好在会飘的绒球和只是一根触手的创造者都不怕。这是最后的试炼。路的尽头是一扇黑色金属门，绒球把通行证那颗小球塞进门底的小孔，小球弹回来，门缓缓升起：后面的光路像树枝一样分岔纵横，叫“光网”——创造者说，过了测试的愚者大都在这里迷了路，而它认得路。',
 ch:'卷三《边缘之地》《边缘之处》', rel:['dr_road','c_tentacle']},
{id:'dr_fear', n:'恐惧之地', c:'地理', m:'dream', r:'dr6', e:[6], t:.32, off:[-170,-40,-80], k:'island', kp:{r:66,c:'#3a0e12',c2:'#1a0a0a',deadtrees:1,sky:'#8a1a1a'},
 s:'血色的天空、迷宫和枯树。创造者的恐惧形成的世界。',
 d:'血色的天空下着蒙蒙细雨，雾气不浓却从不散去；大地像腐烂的泥浆，混着骨头，偶尔是布满裂痕的灰色石地和几棵枯树。这里的寒冷、饥饿和疲倦都和现实一模一样。它会随创造者的恐惧变化：创造者一不那么害怕，世界就立刻换一副模样，好让它继续恐惧——恐惧维持者让这里一直维持着恐惧。创造者原以为出口很近，结果和绒球迷了路。杀死核心生物后，世界不再变化，停在一片爬满畸形肉块的样子；创造者说，现在它对这些只剩厌恶。墙上留了一句话，让它去把那个核心生物找出来。',
 ch:'卷三《恐惧之地》《恐惧的路途》《恐惧中的生态》《恐惧维持者》《退出恐惧》', rel:['c_tentacle','dr_brainspirit']},
{id:'dr_brainspirit', n:'脑灵', c:'物种', m:'dream', r:'dr6', e:[6,7], t:.35, off:[60,70,0], k:'fog', kp:{r:40,n:24,c:'#c8a8ff'},
 s:'住在生物脑中的特别能量体。黑金属背后的东西。',
 d:'琳在虚民的脑中发现了它们，暂时把它们称作“脑灵”。它们有些类似琳弄出来的“梦境生物”——比如有自己意识的勇者、恶魔。脑灵也许是在虚空巴士侵略虚民母球时混进来的；它们与“核心生物”配合设下梦境的陷阱，想要实现自己的“愿望”。后来琳知道，脑灵是原灵生出来的一个亚种，纯粹由能量结构组成，只是它们自己不知道。',
 ch:'卷三《寄于脑中》《意识与能量》《脑中声音》《计划的过程》', rel:['xm_cult','v_naoling','v_yuanling','rq_blackcity']},
{id:'c_tentacle', n:'创造者的触手', c:'角色', m:'dream', r:'dr6', e:[6], t:.13, off:[-60,30,40], k:'none',
 s:'被囚禁的创造者，把一条三米长的触手交给绒球，一路同行。它叫琳“绒毛”。',
 d:'创造者是来自虚空、翻滚者级别的巨型生物。这一位被关在一颗生机盎然的翻滚者——创造者监狱里：透明墙壁后是一间间十几米见方的牢房，关着各式各样的囚犯，比如一团由无数细微发光物组成的光雾，绒球一靠近它就猛撞上墙，响声大得像撞上了硬物。这位创造者把一条三米长的触手交给绒球，一路同行，叫琳“绒毛”。它在梦境里与绒球一起走过光之大路，也在监狱的平原、岩山上与绒球同行，告诉琳故乡的路线。',
 ch:'卷三《监狱》《交流》《触手可及》', rel:['v_prison','dr_prison','creator']},
/* ---------- 时代 8 ---------- */
{id:'dr_sculpture', n:'雕塑之地', c:'地理', m:'dream', r:'dr8', e:[8], t:.4, off:[0,-40,120], k:'island', kp:{r:80,c:'#f0f0f0',c2:'#d8d8d8',statues:24},
 s:'一片广阔的白色梦境空间，无数生物雕塑团聚在一起，围着某个物体。',
 d:'‘这些……是这个世界本来的生物？’学者和一只虚空蠊站在一片广阔的白色梦境空间里，无数生物雕塑一群群聚着，各自围住一样东西。那根被分工型结晶生物围着的柱子——学者认得它们——只剩一半，大约五米；虚空蠊说，现实里这些结晶生物已经占了大半座城市。这里的情形和现实对应，柱子彻底消失的时候，也许就是它们灭绝的时候。旁边十只半米高、长得几乎一样、像马陆的生物，围着一个十米高的结晶漏斗。别的生物围着的东西大多完整。空间里还有门。',
 ch:'卷三《雕塑之地》', rel:['v_jing','v_kongqian']},
/* ---------- 时代 9：末日空间 ---------- */
{id:'dr_doom', n:'末日空间', c:'地理', m:'dream', r:'dr9', e:[9], t:.45, off:[0,60,0], k:'island', kp:{r:56,c:'#4a3434',c2:'#2a2020',doom:1},
 s:'尔什民的神话、鬼怪、传说与幻想，聚集成一个个“末日”。',
 d:'它兴奋地猜，大家是不是像电影里那样闯进了未知的末日空间——听起来好酷。很久以前，一些生物被创造出来，帮那个存在看管这些空间，换来永生：“当初我接受了它的提议，它让我一直活下去……但现在感觉有些无聊。”空间之间可以坐火箭传送；在“末日边界”，原本互不相连的空间搅在了一起。后来，末日里也发生了末日。',
 ch:'卷三《有历史的建筑》《空间》《差不多了》《边界》《另一个卫星》', rel:['dr_wuhu','dr_library','dr_vampire','dr_sweet','c_bilu','c_veronica']},
{id:'dr_wuhu', n:'雾湖', c:'地理', m:'dream', r:'dr9', e:[9], t:.47, off:[-150,-20,40], k:'island', kp:{r:50,c:'#4a6a5a',c2:'#6a7a8a',lake:1,fog:1},
 s:'一款游戏里的场景，世界干旱之后在沙漠中忽然冒出来的湖。',
 d:'一款游戏里的场景：世界干旱之后，一个尔什民的祖辈离开城市，在沙漠里旅行，最后找到了水——直径可能有几公里的雾湖，周围是密集的丛林。现实里也有一个雾湖，地形看上去就像游戏场景上盖了一层沙，而游戏出售时还没有旱灾，据说那时也没有这个湖。一群偷猎者迷迷糊糊地从上百公里外走到湖边，想抢房车，被比露全砍倒了。比露进到游戏里很失望：这不是游戏吗？怎么一只怪物都没有！——然后墙外传来了奇怪的声音，会说尔什语的镇长笑着说：这里就是尔什上早已消失的月亮。',
 ch:'卷三《错开的世界》《游戏？》《游戏之内》《小镇》《不同的空间》', rel:['dr_fei','c_bilu']},
{id:'dr_fei', n:'废土', c:'地理', m:'dream', r:'dr9', e:[9], t:.5, off:[150,10,-30], k:'island', kp:{r:46,c:'#7a5a42',c2:'#5a3a2a',ruins:1},
 s:'布满建筑碎片和车辆残骸的街道；雾湖边缘布满裂痕的红色砖墙。',
 d:'雾气弥漫的大湖边，布满裂痕的红砖墙围着一座爬满藤蔓的老洋馆，钟楼断了，横倒在院子里。据说摸了馆里的某幅画就能去废土：画里总是两个穿得很华丽的幼年尔什民，有的画还会晃一晃，扑出一个摇摇晃晃的小家伙，把比露吓得躲到间谍身后。穿过去之后，是满街建筑碎片、车辆残骸和淡淡放射尘的城市——比露想看的变异怪物没有，只有一群胖得过得很好的“鬣狗”，在几十米外探头探脑。',
 ch:'卷三《废弃建筑》《传说中的》《废土》《红色的地方》', rel:['dr_library']},
{id:'dr_library', n:'地下图书馆 · 火箭', c:'地理', m:'dream', r:'dr9', e:[9], t:.52, off:[-130,-50,-50], k:'island', kp:{r:40,c:'#5a4a3a',c2:'#3a2a1a',rocket:1},
 s:'‘原来末日有这么多种……’',
 d:'庞大的书架之间吊着巨大的灯，每幅画都通向一个末日。一枚三层的圆柱形火箭能“连接”不同的末日空间，比露在第三层等得睡着了。',
 ch:'卷三《地下》《画》《什么方法》《收集》', rel:['dr_fei','dr_vampire']},
{id:'dr_vampire', n:'吸血鬼的洋馆', c:'地理', m:'dream', r:'dr9', e:[9], t:.55, off:[140,20,40], k:'island', kp:{r:40,c:'#3a2a3a',c2:'#2a1a22',manor:1},
 s:'一个“有故事的吸血鬼”，和它金发的妹妹。',
 d:'游戏主角就是模仿传说中的吸血鬼造的，听说它们怕大蒜——可是比露没带，它本来也不爱吃。这里的蚊子吸了血不自己消化，而是吐出来，酿成一种含水量极少的东西。比露读完日记哭了起来：‘好惨，好可怜……’神话生物“红”（红白）是大小姐的仆从；它问间谍：“你也能联络它们吗？”',
 ch:'卷三《吸血的生活》《以前的生活》《恢复》《最后一天》《狩猎巴士》', rel:['dr_manzhu','dr_library']},
{id:'dr_manzhu', n:'曼珠沙华的庭院', c:'地理', m:'dream', r:'dr9', e:[9], t:.58, off:[-120,30,60], k:'island', kp:{r:44,c:'#3a3a3a',c2:'#2a2a2a',flowers:'#d8203a',souls:1},
 s:'淤泥小道、雾气、红色的花，“灵魂”在植物之间飘过。',
 d:'一条淤泥小道穿过浓雾，两边密密麻麻开满红色的花，像铺了红地毯，取自尔什民关于地狱的传说。比露一路喊冷：花红红的，看着好像挺暖和，其实冷得要命。间谍递给它一副照着螳螂虾眼睛做的眼镜——戴上就能看见河边、岸上飘着一团团半透明的东西，大概算是“灵魂”，冷就是它们吸走热量造成的。尔什民的灵魂传说太丰富了，相信有灵魂，个性再强的生物也能悍不畏死地作战。',
 ch:'卷三《灵魂》《建设中》《流动》', rel:['dr_vampire']},
{id:'dr_tower', n:'淹没高峰上的高楼', c:'地理', m:'dream', r:'dr9', e:[9], t:.6, off:[140,-40,-40], k:'island', kp:{r:30,c:'#2a5a8a',c2:'#1a3a5a',tower:1},
 s:'它对着水感叹：为什么到处都是大海呢？',
 d:'“海洋末日”是一个很好懂的末日：海水淹没了整个世界，最后的居民逃到高处建起城市，过了一阵连那里也被淹了，从此全世界再没有陆地，大家只能住在船之类漂浮的东西上。这栋一百多米高的楼就建在被淹没的山峰上，一半泡在水里。末日空间的最后一天，比露和间谍站在楼顶，四周是望不到边的海，比露对着水抱怨：为什么到处都是海呢？',
 ch:'卷三《最后一天》《决定》', rel:['dr_doom']},
{id:'dr_sweet', n:'甜点之地', c:'地理', m:'dream', r:'dr9', e:[9], t:.63, off:[-140,10,-20], k:'island', kp:{r:52,c:'#e8b8c8',c2:'#c88a5a',sweets:1},
 s:'金属饼干构成的平原，居民都被“甜点机”变成了甜点民。',
 d:'一片金属饼干构成的平原，中间立着一座甜点城堡。进化空间的尔什民偶然闯进这个幻想空间，从没吃过甜点，却被香气引进城堡，挖起饼干和巧克力碎屑往嘴里塞——城里的甜点含有致幻物质，吃多了就疯疯癫癫，各自看见不同的幻觉，只是幻觉里的地面都铺满食物，于是吃个不停。居民都被“甜点机”变成了甜点民，生活目标就是把别的生物也变成甜点、传播自己感受到的痛苦：‘把它也变成甜点，变成我们自己人！’花园里有一场茶会：比露问有没有盐，店员说喝茶不放盐；比露不服气，坚称它听说过放盐的茶。',
 ch:'卷三《甜点到处都是》《甜点》《点心》《偶然的想象》《不同地方的茶会》', rel:['dr_doom','c_bilu']},
{id:'dr_seaweed', n:'海藻民的村落', c:'地理', m:'dream', r:'dr9', e:[9], t:.645, off:[120,-60,60], k:'island', kp:{r:30,c:'#3a6a5a',c2:'#e8e0c8',bones:1},
 s:'满地鱼类和海生物的尸体，房屋是用大量鱼骨组装的。',
 d:'空气里满是海腥味，来自遍地的鱼和海生物的尸体。居民全身披着海藻，几乎看不清身形和脸，琳叫它们“海藻民”。它们用大量鱼骨搭起大小不一的房子，从骨头缝里能看见珊瑚骨架和大螺壳做的家具；有的在捡贝壳，有的在屋旁种植物，有的养着一大群海蟑螂，也有闲逛的一见间谍就扑过来，被它一戳就倒。比起之前遇到的那些，这里算是正常的生态。附近还有一座满是骷髅小动物的迷宫，和一口飘着眼球的“火锅”。',
 ch:'卷三《充满海腥味》《突击》《新区域》《食客》', rel:['dr_doom']},
{id:'dr_toys', n:'彩色道路 · 绒毛玩具', c:'地理', m:'dream', r:'dr9', e:[9], t:.655, off:[0,-80,-100], k:'island', kp:{r:36,c:'#ff9ad8',c2:'#8ad8ff',toys:1},
 s:'幻想空间：到处是鲜艳的彩色和看上去很可爱的绒毛玩具。',
 d:'间谍和比露走在一条到处是鲜艳彩色的道路上，两边堆满看起来很可爱的绒毛玩具。比露嘀咕这里看着挺华丽，可惜没什么好吃的。绒毛玩具其实是肉食生物，只是平时不攻击，所以从旁边走过去很安全——可琳觉得这里并不安全，因为除了绒毛玩具之外还有别的东西。琳还发现，脑袋虫一类的生物有一种感知空间的能力，琳暂时叫它‘空间记忆’：它不能单独运作，要靠一些情况来触发；玛雅、教长和间谍在这里遇到的一种很像脑袋虫的生物，都有这种能力。',
 ch:'卷三《探测空间》《小型空间》《清扫》', rel:['dr_doom','c_maya']},
/* ---------- 时代 10 ---------- */
{id:'dr_dreamshaper', n:'梦塑者', c:'物种', m:'dream', r:'dr10', e:[10], t:.7, off:[0,0,140], k:'whale', kp:{s:60,c:'#8a7ab8',sleep:1},
 s:'沉睡的巨大生物。醒来时身边全是梦里的东西——可它们一次也没醒过。',
 d:'梦塑者梦中的事物都是随机的。从梦塑者碎片中诞生的“碎片生物”学着梦中的文明，过上了神一般的生活；造物主毁在自己的造物上——碎片生物反抗了它们。从尸体中又诞生出全新的生物。空中飘着一些几十米大的小梦塑者，它们什么也不干，只是在想象。',
 ch:'卷三《梦中造物》《追寻梦想之物》《融合》《出去》《捕获》', rel:['dr_ronglian','dr_hunter']},
{id:'dr_ronglian', n:'熔链', c:'物种', m:'dream', r:'dr10', e:[10,11], t:.72, off:[-120,40,0], k:'ring', kp:{r:30,n:5,c:'#ff8a3a',chain:1},
 s:'“超级分工型物种”，转眼就能拼出各种武器。',
 d:'“超级分工型物种”，转眼就能拼出各种武器。它由外面的“锁链”——一圈圈圆环——和里面的碎片生物“核心”组成，原是两个意识，如今已是一个完整的生物：锁链负责战斗和收集材料，把虚空里遇到的东西打碎丢进核心；锁链一想象，核心就把想到的东西造出来，第一次慢，之后就快了。“风暴之眼”就是它们设计的武器之一。一群圆环想追求‘真正的梦境’，所有生物的梦境汇聚的地方。梦想猎手撞断了锁链；熔链散架时，燃烧的碎片像流星雨一样坠向一颗苍夷的巴士——痛苦巴士，它到最后都只在不停地问“为什么”。',
 ch:'卷三《风暴之眼》《真正的梦境》《碰撞》《结果》《地表》', rel:['dr_hunter','v_pain','v_warbus']},
{id:'dr_hunter', n:'梦想猎手', c:'物种', m:'dream', r:'dr10', e:[10], t:.735, off:[110,-40,-30], k:'blob', kp:{s:10,c:'#c8b878'},
 s:'像一团粘在锁链上的浆糊。一生下来就装满了知识——只为猎杀追梦者。',
 d:'一种巴士生物，样子像一团粘在锁链上的浆糊，本质上很像体型被定住、内脏却继续长到成熟的虚空巴士幼仔。传说很久以前有一类生物，意识从不接触现实，只活在想象里，周围的环境却会变成它们想象的样子——“不可预见之地”就是这样来的，梦塑者等都是它们的后代。梦想猎手一生下来脑子里就装满了知识，唯一的用处是猎杀这些追寻梦想的东西：让它们活不下去，也让梦想断掉。问它为什么，它说不这么做，它们一定会重走老路——把梦想追到尽头，就会引来大规模的毁灭。最近很多生物在找“远古空间”，猎手的数量也跟着增加了。',
 ch:'卷三《追寻》《追求与猎杀》《塑梦的地方》', rel:['dr_ronglian','dr_dreamshaper']},
/* ---------- 时代 11 ---------- */
{id:'dr_mengli', n:'梦历 · 梦的泥海', c:'地理', m:'dream', r:'dr11', e:[11], t:.8, off:[0,-40,0], k:'island', kp:{r:110,c:'#5a4a3a',c2:'#3a2e24',mud:1,ships:4},
 s:'它们决定朝那个方向航行，盼着那里有希望，也盼着绒球的光照着路。',
 d:'“梦历”是死去之物留下的梦境能量所形成的历史。在一片梦境能量构成的泥海上，骸龙塑造的梦境帆船扬帆航行——不靠风力，船帆上画着绒球的标志，骸龙们对它祷告。有一个创造者的梦历一直在吞噬别的梦历，在它们身上悄悄放下“吸取球”。一个快得惊人的骸龙“跳跃者”在泥海海面上奔跑跳跃，挡住了数百米的入侵光团。',
 ch:'卷三《梦境的旅途》《吞噬》《航行》《光芒》《扩散》《抵挡》', rel:['dr_jumper','dr_zero','gulong','dr_galaxy']},
{id:'dr_jumper', n:'跳跃者', c:'角色', m:'dream', r:'dr11', e:[11], t:.82, off:[90,20,40], k:'none',
 s:'它说要把绒球的希望带到每一个地方去。',
 d:'一艘载着骸龙的帆船被一团旋风追上，梦境弩箭射它毫无效果，船尾被卷碎、光屑纷飞，骸龙们对着帆上的绒球标志拼命祈祷，越祈祷船跑得越快，却还是不够快。这时一个骸龙从天而降，喊着“绒球会照亮一切”，抡起比自己还大的斧头劈进旋风中心，旋风随之散开。它落进海里，再猛地一跃跳上船，船上的骸龙欢呼它是伟大的跳跃者。琳发现它的情绪里“杂念”非常少，不像船上那些总在东想西想的骸龙；它说要把绒球的希望带到每一个地方去。',
 ch:'卷三《光芒》《抵挡》', rel:['dr_mengli']},
{id:'dr_zero', n:'零', c:'琳的造物', m:'dream', r:'dr11', e:[10,11], t:.83, off:[110,40,70], k:'fluffglow', kp:{s:8,c:'#fff4d8'},
 s:'琳以前造出的、和琳性格一模一样的生物。',
 d:'琳以前造出的、和琳性格一模一样的生物。跳跃者旁边那颗绒球一样的光团，是“零”所形成的梦历。琳一接近就能感觉到，它的思维和自己有“共鸣”的部分——它可能在这里充当着跳跃者和骸龙们的信仰对象。数百米宽的光团入侵时，小小的零和一个骸龙挡在前面：这里的战斗主要靠情绪压制对方，只要自己的情绪稳得住，就挡得住。后来这片地方的生物一夕之间全死了，飘着的化成粉末，等待的砂鲼一动不动，琳和零却毫发无伤；还是零先提议，去找白星或凤凰问问。返乡之道上，琳也和零一起走过。',
 ch:'卷三《抵挡》《过去》《延伸的光芒》', rel:['dr_mengli','dr_jumper','bk_home']},
{id:'dr_galaxy', n:'微缩银河', c:'现象', m:'dream', r:'dr11', e:[11], t:.84, off:[-140,60,-60], k:'vortex', kp:{r:46,c:'#c8d8ff',disc:1},
 s:'一块直径接近十公里、厚三百多米的漆黑圆盘，上面闪着无数光点。',
 d:'说是微缩型的银河，它也不算很小。',
 ch:'卷三《修复》', rel:['dr_mengli']},
{id:'dr_zhaoji', n:'召集者 · 遥远回响', c:'角色', m:'dream', r:'dr11', e:[11], t:.86, off:[130,0,-50], k:'none',
 s:'第一个到达“遥远回响”的生物，召集别的生物去完成“混合虚空”的目标。',
 d:'混合后的虚空，也不是谁都喜欢——巴士生物就不赞成。召集者召集大量生物与巴士开战，战后“遥远回响”被彻底摧毁，参战的生物分散到了虚空中——只有一个意识没有离开。召集者的空间里，“绒球世界”在不断颤抖。',
 ch:'卷三《分散》《召集者》《虚空中的数据》', rel:['v_hunhe','dr_bridge']},
{id:'dr_bridge', n:'创造之海的意识桥梁', c:'地理', m:'dream', r:'dr11', e:[11], t:.88, off:[-110,-40,40], k:'island', kp:{r:90,c:'#f8f8f4',c2:'#e8e8e0',flat:1},
 s:'这里是第三处，才是真正没有尽头的地方。',
 d:'一望无际的白色大地。琳原本以为这会是一趟孤独的旅途，却有很多“同伴”：“前进！滚动！前进！”被琳叫作“黑夜”的生物体内保存着相关的记忆；一个像白色沙砾堆起来的生物以极快的速度发射细碎沙砾，杀死了琳的绒球。',
 ch:'卷三《隐藏的入口》《桥》《渐变》《思维》《另一个生物》', rel:['v_chuangzao','dr_zhaoji','dr_tunnel']},
{id:'dr_tunnel', n:'末日隧道', c:'物种', m:'dream', r:'dr11', e:[11], t:.9, off:[100,60,30], k:'tube', kp:{len:200,r:20,c:'#3a3050',glow:'#c88aff'},
 s:'土生土长的不可预见之地物种，和创造之海一样，想搭一座“桥梁”通向正常虚空。',
 d:'它造出的桥梁从来不够长，于是一直用各种方法“窥视”正常虚空。它游荡在大小不一的“希望空间”之间，潜入别的意识重温记忆的生活里观察，却通常不去影响它们。它的居民们发现自己的“虚空”是有限的，文明一次次在绝望中崩溃，于是开始研究“希望”。',
 ch:'卷三《另一个生物》《末日》《集中的希望》《痛苦与希望》《重温记忆》', rel:['dr_hope','dr_bridge']},
{id:'dr_hope', n:'希望空间', c:'地理', m:'dream', r:'dr11', e:[11], t:.93, off:[0,-50,110], k:'island', kp:{r:90,c:'#4a7a3a',c2:'#6a5a42',hope:1},
 s:'一遍遍重启的空间。里面的生物跟着主意识轮回，不断被安排新的身份。',
 d:'骸龙的希望空间里，耸立着一座座三十多米高的岩石建筑和骸龙城堡；它提醒塔克：食物快吃完了，得搬家了。骸龙一直充满希望，主要是因为它们对绒球的信仰。造脑怪依旧不值得信赖，拿十个美杜果就能换一个“世界的秘密”。脱离轮回的“脱离者”、像黑潮一样涌来的“脱骨娃娃”、把希望“分离”的红色绒球……世界崩溃后，骸龙的城市在一片白雾的“海洋”上重建，岩石岛变成了密集的雨林。',
 ch:'卷三《前往方法》《不同的过去》《想知道这个世界的秘密吗？》《找到》《入侵》《进展》', rel:['dr_tako','dr_doll','dr_lastland','dr_tunnel']},
{id:'dr_tako', n:'塔克（希望空间）', c:'角色', m:'dream', r:'dr11', e:[11], t:.95, off:[-90,30,60], k:'none',
 s:'“我没想到……真能再次遇到。”',
 d:'被卫兵拦下的间谍听到上方传来塔克的声音：“让它上来。”塔克似乎认识琳——即便琳此刻是间谍的样子。当琳告诉它，间谍就是绒球时，它的情绪激动得一塌糊涂。琳告诉塔克外面脱骨娃娃的威胁，它很震惊，没想到外面有那么多奇异的事情。',
 ch:'卷三《老龙》《熟悉》《准备》', rel:['tako','dr_hope']},
{id:'dr_doll', n:'脱骨娃娃', c:'物种', m:'dream', r:'dr11', e:[11], t:.97, off:[120,-30,-40], k:'swarm', kp:{n:200,s:50,c:'#141414'},
 s:'全身黑色、只有半米高的生物，十多万只像黑潮一样涌来。',
 d:'一种黑色的娃娃，数量多到十几万，像在地上奔涌的黑潮。它们冲向银光闪闪的湖上那座用冰造的“冰镇”，这一次尔什民没有逃，拿着步枪站在冰屋上开火。琳用“光墙”留出缺口，把大部分娃娃引进坑里、引到立蝎的国度：地下隧道狭窄，人海战术不管用，立蝎挥着刃化的肢体一群群地砍。特别的娃娃穿着衣服，能让头颅飘起来，会用自己造的微型枪械远距离攻击，还懂得针对琳。天空中出现了一幅越来越大的“画”，画里是无数的脱骨娃娃；琳要找的是“画的核心”。',
 ch:'卷三《不太熟悉》《头》《捕捉》《画》《画中》', rel:['dr_hope']},
{id:'dr_lastland', n:'最后之地', c:'地理', m:'dream', r:'dr11', e:[11], t:.99, off:[-60,40,-90], k:'island', kp:{r:44,c:'#e8c86a',c2:'#b8903a'},
 s:'它们把这里叫做最后之地：最后的希望，也是最后的光。',
 d:'尔什民的希望空间，它们管这里叫最后之地：最后的希望，也是最后的光。穿着奇妙服饰的尔什民把维罗尼卡带到建在金色平原上的家园——一路的草地都是绿的，只有城镇四周的草长成了金色。房屋多在几十米高，白色、像塑料做的，有金字塔形、螺壳形，还有两个方块用尖角叠在一起的形状；街上的居民大多穿着银色或金色的衣服，好奇地打量着维罗尼卡。“脱离猎手”组织猎杀的不是脱离者本身，而是为了它们的肉。还有一个只有数百成员、缅怀过去的小组织“感叹会”。',
 ch:'卷三《最后之地》《猎物》《感叹》《特殊的脱离》', rel:['dr_hope','c_veronica']}
);

/* 卷三：尔什 */
window.WIKI.push(
{id:'ex_planet', n:'尔什', c:'地理', m:'erxi', r:'ex_eu', e:[7,8,9,10,11,12], ll:[22,-10],
 s:'尔什民（阿特兰的后代）的故乡——它本身是一颗活着的巴士，一颗“爱好研究的巴士”。',
 d:'尔什民管巴士生物叫“超级星球”。尔什有自己的神经系统，“诺”是它在地面上的化身。很久以前尔什离开了原本的星系，两极的冰雪开始融化，大量冰水化作汹涌的海啸席卷世界，北极的冰洋变成了新大陆。它针对米德加尔特准备了一个很久以前就开始的大计划；它被月亮“分解”过，进过凝固虚空，在“旅行空间”里漂泊，还想起了自己曾直面过创造者的本质。',
 ch:'卷三《沙尘中的历程》《召唤错误？》《大体的过程》《回忆》', rel:['ex_nuo','ex_atlan','ex_moon','ex_frozen','ex_travel','v_erxi']},
{id:'ex_atlan', n:'阿特兰的历史', c:'文明', m:'erxi', r:'ex_eu', e:[7], ll:[36,16],
 s:'尔什民远古的样子：中世纪的种族，国王、精锐、原族与猛犸。',
 d:'琳在回忆结晶里扮演过一个王室成员：一场灾难来临，国王让两群阿特兰躲开——一群是和“琳”一同出海的精锐，另一群执行“海居计划”移居深海。“神”毁灭了国度；尔什教团的阿特兰拿着弩箭追来，琳扮演的角色被射穿了头……在虚空中漂泊的阿特兰一直在找“先祖之地”，一个阿特兰去了玛尔斯，立刻从潜意识里觉得：这里不是。',
 ch:'卷三《真神与假神》《海居》《逃脱行动》《记忆的古代》', rel:['ex_haiju','v_atlan','v_mars','ex_planet']},
{id:'ex_haiju', n:'海居计划', c:'事件', m:'erxi', r:'ex_sea', e:[7], ll:[-6,-28],
 s:'一群信任国王的阿特兰，移居到了深海里。',
 d:'这个计划变数太多，死得也多，所以国王把自己的孩子送去了安全得多的出海计划。这么看，它们的祖先有不少都躲过了那场灾难。——后来的尔什上，还有古老的头足类自称“最接近尔什的生物”。',
 ch:'卷三《真神与假神》《海居》', rel:['ex_atlan','ex_closest']},
{id:'ex_ability', n:'能力者', c:'文明', m:'erxi', r:'ex_eu', e:[7], ll:[30,40],
 s:'感染特殊微生物、体能被强化，代价是寿命很短。',
 d:'很久以前，尔什有过一个计划：把一些有特殊能力的居民送到玛尔斯来生活，这些经过改造的能力者能适应那里的环境——地下的“岩皮”可能就是它们。在尔什民的城市里，能力者被当成影视里的英雄：挨了一梭子子弹也毫发无伤，赤手空拳就把劫匪按倒在地，还总要得意地啰嗦一堆话。社长是尔什上的一个角色，它每晚“梦游”，梦里的自己会写下接下来的计划，其中之一就是成立一家专门制造“英雄”的能力者公司。',
 ch:'卷三《一种生物》《岩皮的记忆》', rel:['v_mars','v_yanpi']},
{id:'ex_closest', n:'最接近尔什的生物 · 变幻蛸', c:'物种', m:'erxi', r:'ex_sea', e:[9], ll:[-12,-35],
 s:'一种非常古老的软体生物，用尔什民的分类算是头足纲。',
 d:'海底的洞穴里，回荡着海洋的气味，爬满了非常古老的海生物；一个声音说，它们是被留下来的。它们自称‘最接近尔什的生物’，是一种很古老的软体类，按尔什民的分法属于头足纲。比起尔什常见的章鱼，琳觉得它们更像绒球上的古鱿。有些尔什民认为章鱼智力很高，限制它们的不是智力，而是寿命。它们靠变换体色交谈，还能改变形状，琳叫它“变幻蛸”。',
 ch:'卷三《地深之处》《最接近的生物》', rel:['ex_haiju']},
{id:'ex_ameirun', n:'阿美润根', c:'文明', m:'erxi', r:'ex_am', e:[8,9], ll:[38,-100],
 s:'过去就很发达，现在也还是尔什最发达的地区之一。',
 d:'南极那边和“羽齿”交易得来的东西全被运出去，卖到了这里，价格大概能买几千万箱苹果——苹果在尔什是很普遍、很便宜的水果。英雄塑造计划后来也搬到这里继续进行，整片大陆都由形形色色的超级英雄守着，据说连足以毁掉虚空的异星生物都败在它们手下。',
 ch:'卷三《贩卖？》《继续飞》', rel:['ex_hero','ex_kong']},
{id:'ex_hero', n:'英雄塑造计划 · 超级英雄', c:'文明', m:'erxi', r:'ex_am', e:[8,9], ll:[36,-94],
 s:'广告上写着：想当漫画里那种有超能力的英雄吗？来这里就行。',
 d:'实验室的研究员提出了‘用尔什民的大脑操纵巴士生物的身体’的可能性，这就是英雄塑造计划——一种为了制造特种士兵的计划：世界已经统一，大战消失了，小冲突却还常有。英雄总部的大厅里：‘今天抓了几个坏蛋？’它报告说一共六个，逃掉的那个也抓回来了，还踢了一脚，应该没死。后来这些英雄在凝固边缘变异成了“巴士侠”。',
 ch:'卷三《英雄？》《英雄总部》《适应》', rel:['ex_ameirun','ng_busman','ex_mother']},
{id:'ex_south', n:'南极大陆', c:'地理', m:'erxi', r:'ex_s', e:[8,9,10,11,12], ll:[-76,10],
 s:'曾被厚重冰雪覆盖。尔什离开原来的星系后，冰开始融化。',
 d:'大量冰水化作汹涌的海啸席卷了整个世界。冰化之后，这片大陆上出现了很多新物种——尔什民原以为它们一直躲在冰层下，后来发现了大空洞，才认为它们可能都是从洞里钻出来的。这里有一号基地、研究站和机械岛，偷猎者集团也在这里活动。',
 ch:'卷三《极南之地》《普通地交流》《继续》《黑色的环境》', rel:['ex_kong','ex_mother','ex_nautilus']},
{id:'ex_kong', n:'南极大空洞', c:'地理', m:'erxi', r:'ex_s', e:[8,9], ll:[-80,40],
 s:'一个可以通往地下深处的巨大洞穴，还在探索之中。',
 d:'琳觉得它可能是尔什特意制造出来的。坐“引力电梯”下去，是漆黑的丛林和“一号基地”；导游欢迎大家来到一号基地，说这里可以好好欣赏地下风景。基地附近游荡着一只“试验失败的怪物”——‘严格说，试验算是成功了，只是控制上出了点问题。’长鸟毛的“羽齿”这阵子在学着自己种苹果树。',
 ch:'卷三《大空洞》《电梯》《黑色的环境》《基地》《移动》《羽毛与交易》', rel:['ex_south','ex_ameirun']},
{id:'ex_mother', n:'巴士生物母体', c:'物种', m:'erxi', r:'ex_am', e:[8], ll:[-76,-34],
 s:'英雄总部地下实验室的水槽里，一头浮游着的十多米长的白壳生物，四条节肢外加一条触手般的软肢，远看有点像大象。',
 d:'个体从母体产出时大约十厘米，被放进特制的培育液里成长。在它的信息里，尔什民得到了“泥潭”的坐标：一颗直径三千公里左右、有类似尔什大气的世界——它们为此准备了很久。特丽提研究的“暗藻文明”资料也来自一个巴士生物。',
 ch:'卷三《成长过程》《想去的地方》《文明和泥潭》', rel:['ex_hero','ex_teliti','v_anzao']},
{id:'ex_tiangong', n:'天宫市 · 天宫学院', c:'文明', m:'erxi', r:'ex_eu', e:[8,9,10,11,12], ll:[45,12],
 s:'尔什民的“巅峰”：发展程度、外观景色，和几乎为零的犯罪率。',
 d:'学院训练精锐，学生大多接受过基因强化，未来从事擅长领域的工作。琳的间谍以“维罗尼卡”之名入学，和比露一起去过丛林的实战训练、北极场景环境模拟场（还没开放，被赶了出来）。后来学院被“异常跳跃”带进了凝固边缘，又回到原位；研究团在学院地下发动袭击。',
 ch:'卷三《天宫》《原始的发现》《那让我们欢迎新生》《模拟场所》《相关之物》《训练》', rel:['c_veronica','c_bilu','ex_teliti','ng_academy','ex_research']},
{id:'ex_teliti', n:'特丽提', c:'角色', m:'erxi', r:'ex_am', e:[8,9], ll:[44,14],
 s:'穿白色衣服的研究员。琳的间谍自称是它远房亲戚的孩子。',
 d:'特丽提说，这是它远房亲戚的孩子，自己跑来这里还没找到住处，所以先带着。维罗尼卡这个名字，就来自特丽提那位真正的远房亲戚。特丽提研究的是远古的“暗藻文明”。它所在的地方大规模招募“英雄”，收了昂贵学费，广告说只要肯练谁都能当；其实全看大脑是否“适应”，测一下就知道。英雄的身体来自实验室深处一头像大象的巴士生物母体：外壳坚固、什么温度都扛得住，定期在体内造出没有繁殖能力的个体。它的神经只用来储存记忆，并把过去文明和“泥潭”的信息发给尔什民。',
 ch:'卷三《适应》《天宫》《文明和泥潭》《撤离》', rel:['c_veronica','ex_tiangong','v_anzao']},
{id:'ex_wushou', n:'蜈手', c:'物种', m:'erxi', r:'ex_eu', e:[9], ll:[46,10],
 s:'形状、大小都像手掌，却是蜈蚣的近缘。',
 d:'形状和大小都像一只手掌，却是蜈蚣的近亲，所以琳叫它“蜈手”。几只蜈手偷偷爬进电梯，跳到比露背后咬了它；和别的蜈蚣一样它们有毒，毒素还能让生物僵化，于是比露僵在原地，任背上的几只慢慢啃——这次离死还比较远，不过毒素迟早会影响呼吸。被治好的比露盯着间谍手里挣扎的那只，发誓要把它们全都捏碎。',
 ch:'卷三《手和长》', rel:['c_bilu']},
{id:'ex_xiafeng', n:'峡风要塞', c:'文明', m:'erxi', r:'ex_n', e:[8,9], ll:[78,-24],
 s:'招牌上写着：峡风要塞，冒险、娱乐、怀旧，一次全有！',
 d:'招牌上写着：冒险、娱乐、怀旧，一次全有。有人问，为什么要在一块刚冒出来的大陆上怀旧？回答是：这个不用在意。整座小镇特意照着从前的样式建造：灰色砖块铺的道路，低矮的石质房屋，最高的建筑是挂着一口金色大钟的钟楼；街上没有常见的交通工具，只有长满毛的大型生物拉着木车；写着“酒吧”的屋前，木门在寒风里晃个不停——的确挺怀旧的。这片大陆曾经是冰洋。',
 ch:'卷三《曾是冰洋的大陆》', rel:['ex_north']},
{id:'ex_north', n:'北极大陆', c:'地理', m:'erxi', r:'ex_n', e:[8,9,10,11,12], ll:[80,20],
 s:'曾是冰洋的大陆。它的地下深处，是一片广阔的荧光丛林。',
 d:'曾是冰洋的大陆，地下深处是一片广阔的荧光丛林，到处是发光的植物，各种生物在林子里跑来跑去。这里的生物大多是尔什或绒球那边的亚种，“白星”却两边都不像：全身闪着洁白的光，样子和青年尔什民差不多，没有五官和毛发，头上长着许多像头发的触手，跑得飞快。据说它在“市场”上能卖出很高的价钱，所以一队偷猎者尔什民一直在黑暗里追它。在一个史前生物干枯的躯干里，琳找到了一些细胞——那是一个早已干枯的创造者。',
 ch:'卷三《白色的》《树上》《大陆？》《创造镜像》', rel:['ex_baixing','ex_xiafeng']},
{id:'ex_baixing', n:'白星', c:'物种', m:'erxi', r:'ex_n', e:[8,9,10,11], ll:[76,32],
 s:'全身闪着洁白光泽、像青年尔什民却没有五官和毛发的生物，头上的触手像头发。',
 d:'偷猎者说它能卖出很高的价格。新的白星从一朵白色的花心里爬出来。琳把干枯创造者的细胞聚在一起，它们迅速增长——“创造者镜像计划”。创造者似乎认为，白星是一个“错误”：它不应该出现，更不应该能解读微生物里的信息。被研究员折磨之后，它变异成七米多长、覆盖坚韧外壳的巨兽出逃；白星的肉块还会吞食学生，按照它的样子仿形。很久以后，白星带琳走过了返乡之道。',
 ch:'卷三《白色的》《白星的生态》《创造镜像》《有点不同》《出逃》《新的指引》', rel:['ex_north','v_headstation','bk_home']},
{id:'ex_fleet', n:'尔什舰队 · 湮灭舰', c:'文明', m:'erxi', r:'ex_eu', e:[8,9], ll:[20,-50],
 s:'湮灭舰：自杀型的舰船，装着威力最强的爆炸物和扭曲引擎。',
 d:'它由机械民操控，用来奇袭、摧毁大规模目标。尔什民的战术是先在蒸腾者之城的地面轰出坑，再让湮灭舰进坑炸掉整座城市——就算炸不掉那一千公里的整座城，至少也能掀掉它一层皮。云层密布的天空里，一艘艘庞大的物体从地表升起，穿过大气飞向虚空。',
 ch:'卷三《外部的轰击》《集结与袭击》《结束和启程》', rel:['v_zhengteng','ex_moon']},
{id:'ex_research', n:'研究团', c:'文明', m:'erxi', r:'ex_eu', e:[9], ll:[40,22],
 s:'想彻底摧毁“那根管道”——米德加尔特——的组织。',
 d:'“最后一步：把那根管道彻底毁掉。”它们准备了各种武器：能把对方分解成多个小块、放进不同空间的“裂解”，能阻挠器官运行的“遮蔽”……它们为逃离尔什监控的队伍准备了宙螺；它们发现某种梦境能量能启动基地里埋藏的交通工具——那是鹅的梦。它们的“探索队”从来没有解散过。',
 ch:'卷三《摧毁的步骤》《武器》《试验的目的》《收藏的队伍》', rel:['v_zhouluo','ex_birds','ex_tiangong']},
{id:'ex_clown', n:'电视机里的小丑', c:'角色', m:'erxi', r:'ex_am', e:[9], ll:[32,-84],
 s:'一大群恐怖分子的指挥。“改变这个世界……改变我们的命运……”',
 d:'房间尽头有一台很古老的电视机，不断回放着一个小丑的影像，翻来覆去说着要“改变命运”。比露戳了戳屏幕没反应，才认出这是老式电器。琳绕到背后一测：电视本身就是小丑的本体，里面是复杂的智能机械，和比露的闹钟用同一种结构，两者一接就能互读数据。原来它是那座空间站系统的一小块，没继承全部记忆，只带着一点性格——比如爱折磨囚犯。恐怖分子都听它指挥，但它并不是老大，是某个首领偶然捡来出主意用的。它说维罗尼卡是“高层次连接体”，能连上更高层次的世界。‘它从很远的虚空来，以前大得能控制万物，现在嘛，只是一台电视机。’',
 ch:'卷三《连接体》《命运？》《算是熟悉》', rel:['c_veronica']},
{id:'ex_jiaojing', n:'脚鲸', c:'物种', m:'erxi', r:'ex_sea', e:[9], ll:[-12,-142],
 s:'让鲸类长出手脚、又保持庞大体型的计划生物。',
 d:'顺着冲上海滩那头鲸鱼的记忆，间谍和比露来到尔什民的海底。外面珊瑚铺满海床、鱼群成片，基地里却只剩冷冰冰的墙和发浑的空气，满是尔什民管它叫“腥臭”的味道——这是研究团的海洋生物合成研究所，研究把尔什民之类的陆地生物和海洋生物的核信息混在一起。脚鲸就是这里的计划：通过调控细胞核信息，让鲸鱼“返祖”长出手脚，又保持庞大体型。最初并不顺利。后来一头庞大的脚鲸把总管办公室的墙撞穿，海水涌入，整个基地就此被淹没。',
 ch:'卷三《鲸鱼》《离开这个世界》《最后的准备》', rel:['ex_planet']},
{id:'ex_moon', n:'尔什的月亮', c:'地理', m:'erxi', r:'ex_sea', e:[9], ll:[0,60],
 s:'月亮上出现了建筑，凝固生物的大军从那里涌出。它向尔什伸出了桥梁。',
 d:'尔什舰队与凝固生物在虚空中激战，它们终于找到了：敌军就是从那里冒出来的。湮灭舰在月球上爆炸，淹没了刚出现的建筑。月亮离尔什还不到一万公里，伸出的桥梁足以填满这个距离——然后桥断了。那是“工程地点”的月亮。',
 ch:'卷三《月亮》《成功？》《俘虏与月亮》《消失》', rel:['ex_split','ex_fleet']},
{id:'ex_split', n:'尔什被分解', c:'事件', m:'erxi', r:'ex_eu', e:[9], ll:[10,0],
 s:'那道光是什么？——很多尔什民最后想的就是这个。',
 d:'刺眼的光柱从卫星表面射来，舰队在恐惧中躲避；虚空里飘散着无数粉末，它们原本是战舰、护卫机和导弹。地面上的居民大多抱着日常的心态，还惦记着手头的事。“预言里的末日，就是这个？”“尔什被分解了……消失了？”后来尔什回到了本来的星系，民众又过上了正常的生活。',
 ch:'卷三《那是什么光》《最后的战术》《分解》《难以置信》', rel:['ex_moon','dr_doom']},
{id:'ex_frozen', n:'凝固的尔什 · 光之道', c:'事件', m:'erxi', r:'ex_eu', e:[9], ll:[38,40],
 s:'尔什被凝固了。只有一条一百公里长的街道上，数以千万计的炉火从天而降。',
 d:'琳和诺在一片漆黑中穿过被凝固的街道和地铁站，固定不动的尔什民之间，偶尔有凝固生物在啃食东西。“光之道”照亮了建筑，驱散了漆黑，又一点点消散，只剩十多米宽。南极的“反凝固发生器”启动时，整个南极像迎来了白昼。一段时间后，凝固慢慢解除——从小的东西到大的东西。',
 ch:'卷三《迷途之地》《车厢》《风暴与光之道》《消散的光》《明亮的大陆》《阻止》', rel:['ng_luhuo','ex_nuo','ex_nautilus','ex_niuyao']},
{id:'ex_nautilus', n:'鹦鹉螺号 · 噬光农场', c:'琳的造物', m:'erxi', r:'ex_s', e:[9], ll:[-84,4],
 s:'凝固飞行器的试作品，钻进了柔软的“噬光农场”。',
 d:'诺说噬光农场不过两三米厚，鹦鹉螺号却往下钻了差不多三百米，四周还是没完没了的软物质，时不时闪一下光芒又熄灭。农场之下是冰原，冰原下有那个装置的碎片。鬼火后来给它涂上了新的涂装；它在凝固虚空里飘浮，用触手缠住凝固生物的残骸，提取强效的反凝固成分。',
 ch:'卷三《凝固飞行器》《农场之下的冰原》《围起来》《骨头》《涂层》', rel:['ex_frozen','ng_guihuo']},
{id:'ex_niuyao', n:'扭腰城', c:'文明', m:'erxi', r:'ex_asia', e:[9], ll:[38.5,101],
 s:'一座居民相当多的尔什民城市，算是最发达的之一。',
 d:'一座居民相当多、算是最发达之一的尔什民城市。它原本在尔什的‘分身’上，被管道吞噬后，碎成大块贴在了管道壁上。后来鹦鹉螺号在凝固虚空里飘过它的上空：街道空荡荡的，交通工具都还在，一个居民也没有。琳把触手伸进一栋大楼，发现办公室里的影像装置还开着。',
 ch:'卷三《旧时代的碎块》', rel:['ex_frozen']},
{id:'ex_nuo', n:'诺', c:'角色', m:'erxi', r:'ex_eu', e:[9,10,11,12], ll:[42,2],
 s:'代表尔什的存在——尔什民模样的化身。',
 d:'‘我管它叫炉火。’诺带琳认识凝固虚空，在一片纯粹的漆黑中一起飘浮，跳进广阔的峡谷。它钻进“脑根”让古战舰活过来；在战争巴士地下六十六层，它用手在黑色柔软的地面上做“手术”，把一部分掰开提取出来。有一次，一个两米五高的尔什民站在湮灭舰上，把诺的脑袋砸碎了。',
 ch:'卷三《炉火》《落地》《起航》《新生物》《接近》', rel:['ex_planet','ng_luhuo','v_warbus']},
{id:'ex_travel', n:'旅行空间', c:'现象', m:'erxi', r:'ex_eu', e:[10,11,12], ll:[0,-20],
 s:'它们解释说，虚空越来越危险，所以它们的世界要带着大家去一个新的安全地方。',
 d:'公告说，虚空越来越危险，我们的世界要带大家去一个新的安全地方；在意也没用，请大家照常过日子。这个空间是琳和尔什反复调整后做成的，比尔什本身还大，飞出去约一万公里才碰得到边缘；底部有一座三百多米宽、像岛屿一样的移动装置，再加上调节装置，让地表保持尔什民能适应的环境。印加虫群分出约十亿只同行，一部分待在沙漠和丛林里，一部分住在自己用大型运输虫拼成的虫形空间站里。尔什带着大家绕过空间风暴前进。它后来想起：当初造“混合虚空”并不是为了做武器，而是想造一个够异常的空间，被“弹”出正常虚空，去外面远行。',
 ch:'卷三《旅行的空间》《停止》《过去的旅行》', rel:['ex_planet','v_hunhe']},
{id:'ex_crack', n:'天空的断裂现象', c:'现象', m:'erxi', r:'ex_eu', e:[10], ll:[28,-6],
 s:'官方说，调查显示这种‘断裂现象’很稳定，没什么大危害，请大家别担心。',
 d:'比露急得直嚷，非要维罗尼卡同学说清楚：到底是什么变化，怎么一下子就没了？后来裂痕里落下了凝固物质构成的爆炸物；泥浆在城市里到处挖掘，“全体市民紧急撤离！”',
 ch:'卷三《向着奇迹之星》《红色亚种》《神器？》《奇迹的目标》', rel:['v_nijiang','c_bilu']},
{id:'ex_endsign', n:'末日现象', c:'事件', m:'erxi', r:'ex_eu', e:[12], ll:[20,30],
 s:'凝固慢慢解除，然后是热浪、地震与巨大的裂痕。',
 d:'比露问维罗尼卡同学：这就是末日现象吗？要不要像平常那样，华丽地把它解决掉？车流涌动的大道上浓烟升腾，气温不断升高，地面裂开吞没公路。诺、维罗尼卡和比露追着一个直径一米多、会飘浮的圆盘——管理者的意识就藏在里面。',
 ch:'卷三《末日现象》《炎热》《变化》《追击》《继续》', rel:['ex_nuo','c_bilu','c_veronica']}
);

window.FAUNA.push(
 {w:'ex_baixing', kind:'quad', at:[76,32], n:2, col:'#f4f8ff', s:1.3, alt:0, rad:2, e:[8,9], m:'erxi', biped:1, glow:1},
 {w:'ex_jiaojing', kind:'leviathan', at:[-12,-142], n:2, col:'#5a6a7a', s:5, alt:0, rad:4, e:[9], m:'erxi', swim:1},
 {w:'ex_fleet', kind:'ship', at:[20,-50], n:5, col:'#c8ccd0', s:3.2, alt:70, rad:6, e:[8,9], m:'erxi'},
 {w:'ex_hero', kind:'flyer', at:[36,-94], n:3, col:'#d84a3a', s:1.2, alt:0, rad:3, e:[8,9], m:'erxi'},
 {w:'ex_birds', kind:'flyer', at:[42,22], n:6, col:'#f4f0e8', s:.9, alt:0, rad:2, e:[9], m:'erxi'}
);

/* 卷三：米德加尔特（管道内部）与白色通道 —— z 为沿管道的位置，ang 为绕轴角度（0=脚下），h 为离壁高度 */
window.WIKI.push(
/* ================= 米德加尔特 ================= */
{id:'mg_overview', n:'米德加尔特', c:'地理', m:'midgard', r:'mg8', e:[8,9,10,11,12], z:150, ang:0, h:60, k:'none',
 s:'虚空中巨大的黑暗管道。管道里的文明一成长到某种程度，就会被它毁掉。',
 d:'寒冷之都的权杖讲过一个传说：一群来自遥远虚空的生物一直在执行一件事——旅行到虚空的边缘；还有另一个叫米德加尔特的生物。管道内部住着尘鳄等许多“管道文明”，于是诞生了只收集、不发展的“半文明”。最初的看守员检测出，管道里的凝固虚空物种身上都有“管束”，去掉它，那个物种就会远远飞离管道。米德加尔特的幼仔最初是幽灵般的形态，由蒸腾者塑造躯体。它是一团巨大的谜，也是最终极的奇迹——能“探究”时间：一枚导弹击中它，它就能分析这枚导弹来之前经过了哪里。',
 ch:'卷三《传说的物种》《记录》《集粒》《探究》《袭击》', rel:['v_midgard','v_midgard2','v_youling','mg_city','ng_mixu']},
{id:'mg_city', n:'尘鳄之城', c:'文明', m:'midgard', r:'mg8', e:[8], z:1500, ang:0, h:0, k:'city', kp:{s:60,c:'#e8f0f4',crystal:1},
 s:'晶草遍地的城市。路过的尘鳄可能被跳起的晶草刺穿。',
 d:'尘鳄的皮肤是白色的，像结晶一样闪亮，却是软的，所以路过“晶草”时有可能被扎穿。城市的地底是一条废弃的商店街，只留下一些……学者在这里拆开一只三腿柱，才发现里面是血肉之躯。组装厂、研究所和观测室都和这座城市有关。',
 ch:'卷三《研究的进行者》《更加地了解》《秘密的发现》', rel:['mg_chene','mg_tripod','c_xuezhe','mg_mini']},
{id:'mg_chene', n:'尘鳄', c:'物种', m:'midgard', r:'mg8', e:[8], z:1650, ang:-14, h:0, k:'none',
 s:'看上去像绒球上的鳄鱼，走路时身上会掉下大量白色尘粉。',
 d:'名字是学者起的。它们和三腿柱交战，启用了能把敌我全部“凝固”的武器“凝固绽放”，再靠比敌人更快醒来的“苏醒精锐”取胜。一个刚孵出来的尘鳄急着赶去城市报信，结果被告知：这事大家早知道了，它出生得晚了点。',
 ch:'卷三《研究的进行者》《更加地了解》《有名的蛋》', rel:['mg_city','mg_freeze','mg_egg']},
{id:'mg_mini', n:'迷你尘鳄 · 斯拉哥达毕', c:'物种', m:'midgard', r:'mg8', e:[8], z:1720, ang:12, h:0, k:'none',
 s:'问答储藏型的迷你尘鳄。嘴边写着一行小字。',
 d:'一只只有几厘米大的机械小尘鳄，顺着洞穴的岩石爬出来，开口就要对方回复代号，自己先报了一句“九鳌零九”。学者问了声“代号？”就被判错；机械尘鳄跟着念出“九鳌零九”，又错了——洞顶的机炮全对准了它们。最后学者赌了一把，喊出“天空，是有顶的”，居然答对了。它的权限几乎和研究所所长一样，能打开只认“符合者”的检测门；学者被搜身时，把它藏在体内一个特殊舱室里才没被发现。嘴边写着一行小字，读作“斯拉哥达毕”——就是那个说出“天空是有顶的”的尘鳄。它在尘鳄的历史上很有名，那句话被当作名言；后来还有尘鳄以它为名开了一家公司。生活在管道里，天空当然是有顶的。',
 ch:'卷三《洞穴的调查》《逃离》', rel:['mg_chene','mg_mech']},
{id:'mg_mech', n:'机械尘鳄', c:'物种', m:'midgard', r:'mg8', e:[8], z:1780, ang:-22, h:0, k:'none',
 s:'“为什么？你……怎么知道？”',
 d:'它和学者一起调查洞穴和研究所。它启动一个像多孔石一样的遥控器后，路两边的两台尘鳄机甲动了起来，却没有攻击谁，而是走到大门下，合力把大门抬了起来。后来它被始境击中，控制系统受了影响，被学者带着飞走，一路上不停地重复：它们在偷凝固绽放，必须阻止它们，必须保护凝固绽放。学者问它为什么懂那些生物的语言、到底是谁，它却反问学者是怎么知道的。最后，它们一起看到星聚照亮整座城市。',
 ch:'卷三《洞穴的调查》《星光》', rel:['mg_mini','mg_xingju']},
{id:'mg_tripod', n:'三腿柱', c:'物种', m:'midgard', r:'mg8', e:[8], z:2600, ang:28, h:0, k:'tripod', kp:{s:14,c:'#8a8a90'},
 s:'尘鳄的敌人。金属的外壳其实是穿在身上的护甲，里面是血肉之躯。',
 d:'尘鳄的敌人。外面那层金属，其实是穿在身上的护甲，里面是血肉之躯。不扮演尘鳄的时候，它们说话少了很多感情，像机械一样一句一句地回答。学者问它们在做什么，它们说在进行‘回收物种’的行动，可能会影响到别的物种，但学者这种生物，不在回收对象之中。',
 ch:'卷三《怪异的生物》《回收》《武器系统》', rel:['mg_chene','mg_freeze']},
{id:'mg_freeze', n:'凝固绽放', c:'现象', m:'midgard', r:'mg8', e:[8], z:2250, ang:-30, h:0, k:'crystal', kp:{s:30,c:'#9ab8d8',frozen:1},
 s:'凝固裂缝的尖端技术：按下“暂停”，把整场战争冻住。',
 d:'它能把所有敌军凝固，缺点是友军也会被凝固——整个尘鳄族都凝固了。尘鳄的后手是：有一种方法能比敌军更快“醒来”。',
 ch:'卷三《更加地了解》《了解》', rel:['mg_chene','mg_tripod']},
{id:'mg_god', n:'炙热的“神” · 咬杀之道', c:'物种', m:'midgard', r:'mg8', e:[8], z:3050, ang:0, h:0, k:'blob', kp:{s:24,c:'#ff6a2a',hot:1},
 s:'一个炙热的巨物，它说着“咬杀之道”。',
 d:'尘鳄城里出现了一个近百米高、像熔岩又像聚变核心的发光巨物，周围的空气在升温，精锐尊它为“神”。学者、机械尘鳄和始境冒着熔岩雨跑到它脚下，等来的却是一副造脑怪的腔调：“这个世界上只有两种东西——能被咬杀的和不能被咬杀的，你属于哪种？”始境说，神原本说话缓慢冷静，旁边还有两个造脑怪的信号；导弹落下后，那两个信号像是和神融到了一起。“咬杀”成了它最爱用的词。它冲着里面吼：在干什么？想被咬杀吗？赶紧出来！它说自己记得改造者——一颗像恐龙蛋的东西——还想把它咬杀掉。后来它被冷冻导弹冻成雕像，尘鳄打算用“抛弃导弹”把它扔进虚空。',
 ch:'卷三《它们在想什么?》《指引？》《咬杀之道》《种族和信仰》', rel:['zaonao','mg_city']},
{id:'mg_lab', n:'看管员的研究所 · 观测室', c:'地理', m:'midgard', r:'mg8', e:[8], z:3300, ang:160, h:0, k:'station', kp:{s:40,c:'#5a6068'},
 s:'管道里的研究所，最初由神秘的“看守员”建造。',
 d:'对米德加尔特的研究最初就是由这群生物进行的。观测室有一面墙完全是屏幕；学者和尘鳄在这里盯着画面，看那枚“星聚追踪弹”一路飞到满是巨石的沙漠，找到一动不动盘在石间的星聚，停在几公里外。标本室用透明的墙隔开一个个房间，摆着不会动的标本——也有会动的，比如一只像扇贝、叫“吞”的生物，能用“撕裂力量”扯碎靠近的东西吞进去。金属蜘蛛看着它说：‘这东西滚不动。’琳很在意这里的“资格记录”是从哪里来的。',
 ch:'卷三《异常》《记录》《也许是祖先》', rel:['mg_overview','mg_xingju']},
{id:'mg_xingju', n:'星聚', c:'物种', m:'midgard', r:'mg8', e:[8], z:4000, ang:180, h:-120, k:'eel', kp:{s:60,c:'#1a1e3a',stars:1},
 s:'传说中的看管员。蛇形、像鳗鱼，皮肤闪烁着绚丽的光点。',
 d:'传说它会飞到管道之外汇聚星光，再飞回来照亮黑暗的天空——所以叫“星聚”。实际上它并不汇聚星光，也不会飞太远。它来自凝固虚空，从米德加尔特里诞生、又“出走”：从只有数米的“扇贝”，长成数百米到一公里，甚至数公里。勇者驾着章鱼形的飞行器在管道里追了它很久。',
 ch:'卷三《星光》《传说的看管员》《逃脱？》《解析》《事后的调查》', rel:['mg_lab','c_hero']},
{id:'mg_canyon', n:'变化峡谷', c:'地理', m:'midgard', r:'mg8', e:[8], z:4600, ang:0, h:0, k:'canyon', kp:{s:80,c:'#4a4248'},
 s:'这里的引力一直在变，一会儿轻得要飘起来，一会儿又重得抬不起脚。',
 d:'冒险家队长说，这条峡谷的引力从不安分：忽轻忽重，毫无规律。地上那些看似普通的石头其实是活的——引力一轻就飘上半空，引力一沉便整块砸落，靠这个捕猎。所以队伍只能趁沉重的时候一步一挪地赶路，一变轻就得马上找掩体。十只尘鳄的队伍已经被砸扁了一只，学者刚抬头，就看见一块石头正朝自己飘来。',
 ch:'卷三《遭遇》', rel:['mg_egg','c_xuezhe']},
{id:'mg_egg', n:'有名的蛋', c:'现象', m:'midgard', r:'mg8', e:[8], z:4850, ang:20, h:0, k:'egg', kp:{s:6,c:'#efe6d0'},
 s:'学者重重地摔在一座巨大峡谷的底部，旁边有一颗刚孵化的蛋。',
 d:'学者被一头巨大的尘鳄吞下，又因为尘鳄不爱吃机械被吐了出来，重重摔在峡谷底部。它站起来拍拍尘土，检查自己有没有哪里坏了，抬头感叹这还真是高。峡谷里，一个刚从蛋里孵出来的尘鳄告诉它：它要赶去城市，告诉所有尘鳄，它们就要被毁灭了，大批军队会来侵略。可它出生得太晚了——尘鳄的国度那时已经被毁得差不多了。',
 ch:'卷三《蛋》《有名的蛋》', rel:['mg_chene','mg_canyon']},
{id:'mg_hall', n:'金色的大厅', c:'地理', m:'midgard', r:'mg8', e:[8], z:5400, ang:210, h:0, k:'station', kp:{s:36,c:'#e8c25a',gold:1},
 s:'六个始境走进一艘战舰——里面比外面大得多。',
 d:'六个始境走进一艘战舰。从外面看它并不算非常巨大，到了里面才发现，里面比外面大得多。始境们冒出很多疑问：是不是中了幻觉，是不是改造者用了什么东西在捉弄它们？通道一直笔直地往前延伸，好像没有尽头；往回飞，也看不到入口。它们只知道，有谁在这里记录了一些东西。',
 ch:'卷三《金色的大厅》', rel:['v_shijing']},
{id:'mg_xiulian', n:'修炼生物 · 天守部族', c:'文明', m:'midgard', r:'mg9', e:[8,9], z:6000, ang:-30, h:0, k:'none',
 s:'身穿青色铠甲的生物。它们自称天守部族，世代守在这里，一边练功强身，一边说要练出本事保卫世界。',
 d:'它们和恶魔打仗，迎接“新的魔王”：修炼者们拍着胸脯说，不管来什么魔怪都能对付，修炼以后实力翻了一倍；它们的师父则对远道而来的客人说，天之能量这种东西，只能碰运气。管道内爆发凝固虚空时，大片凝固生物发疯般从空中飞下，被修炼生物一个接一个地打落。',
 ch:'卷三《呼唤》《准备》《红点》《爆发？》', rel:['c_hero','mg_crack']},
{id:'mg_crack', n:'凝固缝隙', c:'地理', m:'midgard', r:'mg9', e:[8,9], z:6700, ang:90, h:0, k:'crack', kp:{s:90,c:'#050508'},
 s:'冰冷、没有空气的“巨大洞穴”。',
 d:'一进来，所有生物的第一感觉都是：这是个巨大的洞穴。温度像虚空一样冰冷，既无空气也无引力，四周是颜色古怪的“洞壁”和无数飘浮的透明液体。琳原本只想打开入口、放一小部分兵种进来看看，没想到它把整座城市都“吞”了进去；刚从凝固中恢复的机械脑灵站在城市最高处，担心地问绒球能不能出去，琳也不知道。琳的绒球在数十米宽的狭窄区域里研究蒸腾者的金属块；被困的脑灵一直想回到遥远的虚空里，去见同伴。管道里还出现过“凝固虚空爆发”的现象：像爆炸一样不断涌出凝固物体。',
 ch:'卷三《初步探索》《突变》《那个东西》《依旧连接》', rel:['mg_xiulian','ng_overview']},
{id:'mg_fortress', n:'文明毁灭军队构成的堡垒', c:'现象', m:'midgard', r:'mg9', e:[8,9], z:7400, ang:150, h:0, k:'station', kp:{s:50,c:'#3a2a2a',spikes:1},
 s:'对大多数文明来说只是个传说，很少有生物见过它的真正样貌。',
 d:'由毁灭文明的军队构成的堡垒。对大多数文明来说它只是一个传说，很少有谁见过它的样子；不过在米德加尔特里面，看守员的研究所对它研究过不少。它平时以黑色液态物质的形态潜伏在地下，需要的时候就从地底冒出来，迅速成形。',
 ch:'卷三《制造的堡垒》', rel:['mg_lab']},
{id:'mg_exit', n:'管道的出口 · 三颗卫星', c:'地理', m:'midgard', r:'mg9', e:[9], z:9000, ang:0, h:120, k:'none',
 s:'管道外，是被它抓来当卫星的三颗创造者的世界。',
 d:'米德加尔特身边绕着三颗卫星，都是它从创造者那里抓来的世界。前两颗琳早就在观察，第三颗直到后来才看见：琳在管道头部的高山上看火雨时，恒星的焰光忽然散开，就像之前在管道尾部见过的那样，光散开以后，那颗卫星就出现了。熔岩卫星有一种奇妙的隐形效果：琳在它的地表上看得见虚空里的探险队，从虚空看过来，它却好像不存在；不过只隐形了一小会，它又重新显现，继续往前走。',
 ch:'卷三《第三颗》《穿梭行动》', rel:['v_midgard2','mg_overview']},

/* ================= 白色通道 ================= */
{id:'tn_overview', n:'白色通道 · 虚空隧道', c:'地理', m:'tunnel', r:'tn', e:[10], z:200, ang:0, h:60, k:'none',
 s:'古老的时代，虚空里有很多独立空间；有的出入口连着相距极远的位置。',
 d:'虚空隧道被认为是很多能影响空间的生物共同建造的：它们把大大小小的空间融合在一起，组成这条巨大的隧道。最后利用通道的是“无边虚空帝国”。后来隧道崩塌，只剩一段段残片，比如这条白色通道——它能容纳进数千颗凤凰恒星那么大的恒星。凤凰追着死亡战舰闯了进来，‘不可能……得想办法！’',
 ch:'卷三《古老的通道》《伟大的先驱》《倒退的旅行》《过去的隧道》', rel:['tn_empire','tn_xianqu','tn_sand','v_tunnel_gate']},
{id:'tn_empire', n:'无边虚空帝国', c:'文明', m:'tunnel', r:'tn', e:[10], z:700, ang:-40, h:0, k:'none',
 s:'领土极其广阔，却没有任何传送技术。',
 d:'在领地间旅行要经过漫长的岁月，发现通道后才有了快速穿梭的方法。它们以为先驱给它们提供了传送装置——其实先驱是在控制通道。帝国把先驱炸成很多碎片，带回去研究；后来所有成员都说要“赎罪”，要毁掉整个帝国。只有一个像蜈蚣的研究员觉得古怪：一直以来，胆敢怀疑先驱的生物都活不了太久。帝国离开白色通道，进入了崩溃期。',
 ch:'卷三《伟大的先驱》《赎罪》《怀疑》《想法》《沉睡期》', rel:['tn_xianqu']},
{id:'tn_xianqu', n:'先驱', c:'物种', m:'tunnel', r:'tn', e:[10], z:1400, ang:30, h:0, k:'jar', kp:{s:10,c:'#f4f0e8'},
 s:'自称通道的制造者，很欢迎走进通道的生物。百米大小。',
 d:'先驱一直被认为是伟大、无私的——但无私就等于可疑。它们很久以前来到白色通道，并不是建造者；它们想和整条通道合为一体，做掌控通道的神。它们说自己一直在帮助所有物种，而这件事就快完成了。模型沙海上一个一米多高的罐子，其实就是先驱的一部分；琳在这里和“小先驱”交流。',
 ch:'卷三《先驱？》《了解》《长久的试炼》《帮助的结束》《不能脱离》', rel:['tn_empire','tn_shousha']},
{id:'tn_sand', n:'模型沙海', c:'地理', m:'tunnel', r:'tn', e:[10], z:2400, ang:0, h:0, k:'dunes', kp:{s:300,c:'#f8f6f0'},
 s:'不管走到哪里，都是一片由“模型”构成的白色沙海。',
 d:'“永恒记录场”生成的砂砾模型：检测进入隧道的一切事物，把它们做成模型。模型沙海本身是奇迹生物埋下的“奇迹”之一。琳的陨石舰队和这片沙海一起漂流，一千艘死亡战舰追了上来；“旅途尚未可知，希望永不湮灭。”',
 ch:'卷三《模型沙海的生物》《突然开启》《接着的旅途》《最远的领地》', rel:['tn_record','tn_xianqu','v_nijiang']},
{id:'tn_shousha', n:'守沙球', c:'物种', m:'tunnel', r:'tn', e:[10], z:3000, ang:-20, h:20, k:'orb', kp:{s:12,c:'#f0e8c8'},
 s:'古老时代的物种之一。它的“职务”是守着沙。',
 d:'它告诉琳那时候的虚空：几乎所有生物长途旅行都靠“空间移动”。它成为通道的意识后，和之前的“通道脑”一样给生物“任务”，为了培养继承者——从成为意识的那一刻起，它就感觉自己迟早会消散。它第一次培养的继承者，就是先驱。击退强敌后，通道脑消失了，守沙球的种群也崩溃，再没有恢复。',
 ch:'卷三《虚空的奇迹》《现在》《那次的崩溃》《装置》', rel:['tn_xishou','tn_brain','tn_xianqu']},
{id:'tn_xishou', n:'吸收石', c:'物种', m:'tunnel', r:'tn', e:[10], z:3400, ang:120, h:0, k:'rock', kp:{s:16,c:'#d8d4cc'},
 s:'像石头一样、数十米大小、几乎不会移动的生物，贴在隧道的边缘。',
 d:'几十米大、像石头一样几乎不动的生物，常常贴在虚空隧道的出入口附近。只有它们会年复一年地啃坏隧道，隧道的异变也恰好是在它们出现之后开始的，所以守沙球总觉得那场崩溃是它们干的——虽然它们只会让隧道慢慢萎缩，守沙球也从没亲眼见过它们造成大的破坏。崩溃期里，组成隧道的无数小空间一个个脱离，再也合不回去。至于巴士类生物的起源，也许正是吸收石这类生物。',
 ch:'卷三《吸收》《那次的崩溃》《原始化》', rel:['tn_shousha']},
{id:'tn_brain', n:'通道脑', c:'物种', m:'tunnel', r:'tn', e:[10], z:3900, ang:200, h:0, k:'none',
 s:'通道的意识，能弥漫在通道各处。',
 d:'它是通道的意识，能弥漫在通道各处，却没察觉巴士在跟养着它的生物交谈：巴士用直接与神经交流的方法告诉它们通道的真相，定好了作战计划，它们照旧装作若无其事。这些生物明白，成年的自己在通道里待得太久，再也离不开了；巴士答应把它们的后代带出去，于是计划的第一步，是它们集体在巴士表面自杀。通道脑的最后一击，利用了通道产生的“灾害”，本想把一部分意识灌进巴士的神经，结果只打掉了巴士一部分躯体，意识落进了放出“预知能量”的器官。那些器官脱落后留在通道里，一直缓缓地放出少量预知能量，巴士本身则逃走了。',
 ch:'卷三《现在》《逃跑》《三个意识》', rel:['tn_shousha']},
{id:'tn_storm', n:'侦测旋风', c:'物种', m:'tunnel', r:'tn', e:[10], z:4300, ang:180, h:-150, k:'vortex', kp:{r:50,c:'#e8e8f0'},
 s:'一团会飘动的风暴，经过的生物都会被它收录资料。',
 d:'它从开始以来就一直飘荡在整个虚空隧道里，像一团会走的风暴，路过的生物都被记下，资料传给制造装置。守沙球最早见它时只有几百米宽，后来涨到恒星那么大，能大也能小；隧道崩塌时它的信号越来越少，最后断了，守沙球只好造了替代品。琳顺着它的“躯体”找去：那是一根长上千万公里、只有几十米宽的线，由元初凝聚拧成——它能让自身引力消失，以一种近似梦境能量的状态活着，和恒星凤凰相同。它每放出一团旋风，身体就短一点，放出的旋风是继承记忆的独立生物。它很可能在通道脑与通道融合时成了控制者之一，琳把它改叫“元初旋风”。',
 ch:'卷三《古老巴士》《深处的控制》《元初的旋风》《信号地》', rel:['tn_record']},
{id:'tn_record', n:'永恒记录场', c:'现象', m:'tunnel', r:'tn', e:[10], z:4800, ang:-60, h:0, k:'station', kp:{s:30,c:'#e8e8e0',three:1},
 s:'三个部分：生成砂砾模型的装置、检测一切进入者的装置、收集资源的装置。',
 d:'想制造奇迹的物种在虚空隧道里留下的装置，分三部分：生成砂砾模型的、收集资源的，以及最重要也最复杂的——尽可能检测进入隧道的每一个物体的所有细节。这些装置会“进化”，随隧道的变化慢慢增强，制造者盼着它们迟早长成真正的奇迹；模型的材料来自隧道里四处飘荡的碎屑，最后只留下适合保存的。物种离开后，只留下能开关空间通道的守沙球看管这片模型沙海、挡住侵略者。并不是所有装置都没出过错误：它们的根本目标“制造模型”从没变过，别的方面却偶尔会变——比如大小的调整。有一阵，制造装置不再用房屋之类的东西，而是用空气制造模型，世界上的空气从那以后变得稀薄。',
 ch:'卷三《吸收》《最后的生物》《大体上的世界》', rel:['tn_sand','tn_feizhuan']},
{id:'tn_feizhuan', n:'飞砖', c:'物种', m:'tunnel', r:'tn', e:[10], z:5500, ang:180, h:-200, k:'flock', kp:{n:30,s:10,c:'#d8d0c0',brick:1},
 s:'把自己弄成方形砖块、长着一对不扇动的蝙蝠翅膀的生物。',
 d:'它们过去更像蝙蝠，也有过文明，最狂热的活动是模型雕刻——把雕刻当信仰，幼仔一出生就被教着要做伟大的雕刻师。一个想当雕刻师的考古学家挖出了一台奇怪的机器，覆盖它的尘土全是机器做出来的微小雕刻，连内脏都雕好了，远胜所有工匠；据说这也是它们毁灭的开端。如今它们在末世里努力活着，为了不被收集装置抓走，借地下的大型模型制造厂把自己改成了方形。翅膀不扇动，靠翅尖喷气飞，落地后再用翅膀爬。它们说根本没有‘最后一个’，它们从来没找到过最后一个。',
 ch:'卷三《三号界？》《模型》《做法》', rel:['tn_record','tn_third']},
{id:'tn_wuxing', n:'无形', c:'物种', m:'tunnel', r:'tn', e:[10], z:6000, ang:40, h:0, k:'blob', kp:{s:16,c:'#c83a3a'},
 s:'不是“无形之物”，而是“有无数形体之物”。',
 d:'它的本体由一种只有虚空隧道空间里才生得出来的“隧道残留物质”构成，只能待在特定的空间里。隧道还在时，它能在整条隧道里畅游。红浆会变形这件事，它很早就在研究了；琳用砂砾聚成的爪子捏住这头三十多米的生物，它就从沙海的空间里钻走了。它的计划：借尔什诞生“恒古之泥”。',
 ch:'卷三《无形》《原始的碎屑》《新的剧情》《无形之形》《隔离空间的战斗》', rel:['v_nijiang','ex_planet']},
{id:'tn_third', n:'第三界 · 三号界', c:'地理', m:'tunnel', r:'tn', e:[10], z:6900, ang:0, h:200, k:'none',
 s:'三个世界之一。绒球接近到一万公里以内时，无数小型导弹般的弹幕飞射而来。',
 d:'它说，所谓的‘第三界’根本不存在，找来找去，只会找到一个又一个仿制品。传说里，它和绒球、先祖之地共同诞生，共享一切。',
 ch:'卷三《三号界？》《花朵的起源？》《过去的毁灭》', rel:['tn_feizhuan','ng_ancestor','rongqiu']}
);

/* 卷三：凝固虚空 */
window.WIKI.push(
{id:'ng_overview', n:'凝固虚空', c:'地理', m:'ningu', r:'ng', e:[9,10], p:[0,0,0], k:'core', kp:{r:120,c:'#3a3a40',dark:1},
 s:'几乎所有事物都处于“静止”状态的虚空。即便如此，这里也有很多生物。',
 d:'大多数凝固生物都有特殊的能力，能让周围的虚空保持“正常”，或者能在静止中活动。凝固虚空和正常虚空交界的地方叫“入口”。巴士会议碎裂时，凝固虚空像爆炸一样涌出大量凝固物体——“凝固虚空爆发”。很久以后琳才从颗粒生物那里知道：凝固虚空很久以前并不凝固，是“静止”扩散之后才变成这样。',
 ch:'卷三《击穿》《依旧连接》《静止的原初》', rel:['v_ningu_gate','ng_luhuo','v_keli']},
/* ---------- 凝固边缘（时代 9） ---------- */
{id:'ng_edge', n:'凝固边缘 · 末日丛林', c:'地理', m:'ningu', r:'ng9', e:[9], p:[-900,0,-200], k:'island', kp:{r:170,c:'#7a1e1e',c2:'#3a2420',trees:'#a02a2a'},
 s:'凝固虚空周边生成的空间。天宫学院被“异常跳跃”带到了这片血红色的丛林。',
 d:'它们暂时把这现象叫做‘异常跳跃’：被击中的一瞬间被传送走，到了一个完全陌生的地方。这里有正常的氧气和引力，到处是鲜红的藤蔓和凝固的血迹。屠杀犯、在游乐园中心不停挖掘的帮派、仓库里的“原住民”、能驾驶的机甲……这些空间是尔什很久以前设计好的“红雾计划”，所以都是红通通的。',
 ch:'卷三《异常跳跃》《队伍》《染红的熟悉之物》《挖掘工》《扩展的地方》', rel:['ng_academy','ng_busman','ex_tiangong','c_veronica','c_bilu']},
{id:'ng_academy', n:'天宫学院的漂流', c:'文明', m:'ningu', r:'ng9', e:[9], p:[-860,90,-140], k:'city', kp:{s:26,c:'#d8dde8',float:1},
 s:'广播提醒同学们：学院马上就要起飞了。',
 d:'整座学院飞了起来，往大门外踏出一步就会从高空坠落。学院卡在树顶，学生们把树顶炸掉，继续在末日丛林上空旅行，又漂到一片如云层般的浓雾海洋上。中心的“交易广场”可以买卖武器，装备库里还有一批没测试过的新武器。校长说，这一切全是尔什干的。',
 ch:'卷三《起飞》《过程》《飘着的》《类似的光》《从那里》《都是它》', rel:['ng_edge','ex_tiangong','ng_liudu']},
{id:'ng_busman', n:'巴士侠', c:'物种', m:'ningu', r:'ng9', e:[9], p:[-960,20,-110], k:'none',
 s:'用巴士生物材料制造的“超级英雄”，在这里发生了“巴士生物化”的变异。',
 d:'遗忘侠、白侠、恐龙侠、炸弹侠、铃铛侠、谢特侠……它们之间用脑部的通讯结构发送类似脑波的信号，嘴却还会自然地动。铃铛侠报上名号，反问对方是哪路神仙。“在下姓红。”对方问它是不是来挑战的；它客客气气地说不敢，只是奉大小姐的命令，把对方打趴下再拖回去。',
 ch:'卷三《变异的侠》《首领侠？》《特定的变异》《狩猎巴士》', rel:['ex_hero','dr_doom']},
{id:'ng_huanying', n:'幻影团', c:'物种', m:'ningu', r:'ng9', e:[9], p:[-800,-20,-270], k:'blob', kp:{s:6,c:'#8ad8ff',holo:1},
 s:'学会了立体影像的液体团。尔什最早放进来的生物之一。',
 d:'每座建筑都有一套生成“影像居民”的系统，幻影团从这些影像身上学会了很多东西，还学会了生成影像本身。它们没想到：这里的一个立体影像有了自我意识，而且想杀了它们。“对。”它倒是很干脆：那在这之前，先把它们杀掉就行。',
 ch:'卷三《真实的幻影》《活的影像》《拆解》《幻影控制》', rel:['ng_edge']},
{id:'ng_liudu', n:'流毒岛', c:'物种', m:'ningu', r:'ng9', e:[9], p:[-1000,130,-320], k:'island', kp:{r:22,c:'#5a6a4a',c2:'#4a3a2a',float:1},
 s:'看起来像飘浮的小岛，其实是一群生物。',
 d:'天宫学院炸掉卡住它的树顶，再次在末日丛林上空航行时，学生们看见周围飘着许多二三十米大的“岛”：岛上长着茂密的丛林和小山，山上的清泉像瀑布一样从高空洒下，挂出一道道彩虹。它们其实是一群生物，那清泉般的水混着剧毒，下方丛林的生物喝了或被洒到就会死；为了不让尸体被吃掉，水里还混着一种植物的种子。一座十米直径、还没成熟的流毒岛飘到了学院上空，学生的飞弹竟被它一闪躲开，接着它带着音爆般的轰鸣掠过——那根本不是流毒岛，而是伪装成小岛的某种战机。',
 ch:'卷三《飘着的》《异星？》', rel:['ng_edge','ng_academy']},
/* ---------- 凝固虚空本体（时代 9） ---------- */
{id:'ng_luhuo', n:'炉火', c:'物种', m:'ningu', r:'ng9', e:[9,10], p:[-420,0,100], k:'swarm', kp:{n:180,s:60,c:'#ffb04a',glow:1},
 s:'一米大小、像石块一样跳动着光芒的生物。它光照的范围内，一切正常。',
 d:'诺给它起名叫‘炉火’，说它是活动在凝固虚空入口一带的生物。凝固虚空里大多数生物都有让周围保持正常的能力。后来在被凝固的尔什上，一条一百公里长的街道上，数以千万计的炉火从天而降，照亮了街道，驱散凝固的漆黑——“光之道”。雪原上的“火把”也是炉火的一类。',
 ch:'卷三《炉火》《风暴与光之道》《消散的光》', rel:['ex_nuo','ex_frozen','ng_snow']},
{id:'ng_guihuo', n:'鬼火', c:'物种', m:'ningu', r:'ng9', e:[9,10], p:[-430,70,190], k:'swarm', kp:{n:90,s:50,c:'#7aff9a',glow:1},
 s:'像绿色鬼火一样、不受凝固影响的小生物。',
 d:'凝固虚空一片纯黑，琳的绒球带着“炉火”和诺飘在其中，像坐在一颗在阴影里移动的光球里。光的边缘偶尔会出现小生物，最常见的就是这种像绿色鬼火的东西：它们不受凝固影响，经常从漆黑中飘进光里，又飘出去。它们是极少数能在“死亡静止场”中活动的凝固生物——光是防止凝固还不够，还要能伪装；它们给鹦鹉螺号涂上了全新的“涂装”。',
 ch:'卷三《落地》《被聚集的残骸》《涂层》', rel:['ng_death','ex_nautilus']},
{id:'ng_death', n:'死亡战舰 · 死亡静止场', c:'文明', m:'ningu', r:'ng9', e:[9,10,11,12], p:[-200,0,300], k:'ship', kp:{s:40,n:7,c:'#2a2624',skull:1},
 s:'用大量残骸般的东西拼成的战舰，头骨形，追杀一个又一个物种。',
 d:'它在死亡静止场的深处航行，那里到处是正常虚空生物的残骸，也有很多细胞生物的残骸。它的光束会让目标崩溃分解；它拿着一份“灭绝名单”。命令只有一个：出发，把它们彻底灭绝。琳后来成了一艘死亡战舰的舰长，在凝固虚空中航行，顺着漆黑的河流飞了数亿公里。一百艘死亡战舰组成的舰队，以及米德加尔特虚空里更多的部队，后来与凤凰大战。',
 ch:'卷三《中心地带》《舰长》《控制战舰》《阴影》《凤凰的战争》', rel:['ng_galaxy','ng_lost','ng_river','v_feng']},
{id:'ng_galaxy', n:'银河舰长', c:'角色', m:'ningu', r:'ng9', e:[9], p:[-160,40,340], k:'none',
 s:'一艘死亡战舰的舰长。',
 d:'一艘死亡战舰的舰长。战舰本来在追琳留下的半截凝钻，想夺统领的“失落宝藏”，却突然接到别的任务，转向别处。在一个像胃一样不停蠕动的舱室里，五个尔什民贴着天花板，和战舰高层的凝固生物“尖锐”——一团直径一米左右的黑雾——商量。问清楚舰内的各种状况后，舰长决定出发，去灭绝凝固虚空中的一系列物种。尔什民用混着“凝固排斥物质”的子弹打它，没有火花，也没有声响。',
 ch:'卷三《舰长》《银河舰长》《捕捉银河》', rel:['ng_death']},
{id:'ng_lost', n:'失落军团 · 真菌区域', c:'文明', m:'ningu', r:'ng9', e:[9], p:[-120,-80,420], k:'planet', kp:{r:22,tex:'fungus',c1:'#c8b8a8',c2:'#5a4a3a',ribs:1},
 s:'巨大的肋骨之间，菌丝搭成桥梁，连着一个一公里多的球体。',
 d:'真菌在这里生活了一段时间，菌丝组成混着反凝固物质的坚韧外皮，里面是菇状物、球状物和许多甲虫。失落军团的统领在脑内积累了足够的反凝固物质后醒来，却根本不知道“死亡静止场”是什么地方。肋骨一具具被凝固、挤压成尘埃，琳拿走了统领的“失落宝藏”。',
 ch:'卷三《真菌区域》《失落的残留》《统领》《直到消亡》《钻入死亡》', rel:['ng_death']},
{id:'ng_heichun', n:'黑鹑的砖墙', c:'物种', m:'ningu', r:'ng9', e:[9], p:[-280,-60,480], k:'cube', kp:{s:30,c:'#141414',wall:1},
 s:'十米长、三米厚的黑色“砖块”砌成的墙——每块砖都是黑鹑。',
 d:'凝固虚空里的一面面高墙，几公里长宽，由十米长、三米厚的黑色“砖块”层层砌成。每块砖都有生活设施和引擎，里面住着十几只长得像鹌鹑的黑鹑——它们擅长组装东西，平时砖块连成一片，危急时便各自分离四散逃走。几百座这样的墙，就是黑鹑的国度。死亡战舰来时，黑鹑们知道自己完了，能做的只剩向神祈祷；最后一块砖也被消灭后，战舰便离开去灭绝下一群物种。',
 ch:'卷三《鸟类的同盟？》《防御墙》《邀请》', rel:['ng_death','ex_birds']},
{id:'ex_birds', n:'有智慧的家禽', c:'物种', m:'ningu', r:'ng9', e:[9,10], p:[-560,90,380], k:'swarm', kp:{n:60,s:30,c:'#f0ece0'},
 s:'鹅、鹌鹑、火鸡、渡渡鸟……被改造得有了智慧，也一直被当成食物、发泄品和坐骑。',
 d:'研究团用药物大大缩短了鸟类孵化和成年的时间。从补给箱里苏醒的渡渡鸟智力很高，还有很高的权限，一出来就能指挥基地的系统。它们在宙螺里起义：鸟类们高喊口号：爪子就是力量，鸟喙就是真理，灵长类统统要臣服在它们翅膀底下。在联合球上，鸟类被当作发泄品，被踢来踢去当“鹅球”；也被当成学前玩伴。“嘎嘎嘎！我不要看烤鹅不要烧烤不要……”',
 ch:'卷三《逃跑的鸟类》《家畜的愤怒》《宙螺》《鸟类的王国》《联合球》《增长》', rel:['v_zhouluo','ng_lianhe','ng_heichun']},
{id:'ng_lianhe', n:'联合球', c:'文明', m:'ningu', r:'ng9', e:[9,10], p:[-500,40,420], k:'station', kp:{s:30,c:'#c8ccd0',ball:1},
 s:'尔什民在凝固虚空附近的居所。',
 d:'它的解释是：很多民众对现在的生活不满，总得给它们找点东西发泄。联合球的用水来自“资源星系”的冰冻小行星。琳告诉它们，十多光天外就有一面“水墙”，它们居然完全没有发现。这里有一个像博物馆一样的“虚空展览所”，还有一艘“五星级酒舰”。',
 ch:'卷三《联合球》《歧视？》《不喜欢异星生物？》《熟悉之物》', rel:['ex_birds','ng_waterwall','ng_resource']},
{id:'ng_waterwall', n:'水墙', c:'现象', m:'ningu', r:'ng9', e:[9], p:[-660,-40,540], k:'wall', kp:{s:120,c:'#3a8ab8'},
 s:'距离联合球十多光天的地方，一面不知从哪来、似乎没人管理的“水墙”。',
 d:'头骨形的死亡战舰被尔什民控制之后，老塔领着士兵找到了能把被奴役的同胞传送出来的舱室。它们在水墙附近建起一整套自动工事：每个传送出来的尔什民先被角落里的麻醉枪击晕，再检查脑里有没有“情绪放大器”——有就送出去做手术取出，没有就输液恢复，再叫醒，全程由机械搬运。几百个同胞就这样被救了出来。只是尔什民受不了战舰里那些像内脏一样蠕动的通道，装好监控就全撤了——它们没想到，还有许多凝固生物藏在里面。',
 ch:'卷三《熟悉之物》《试图》《拯救行动》《救助的状况》', rel:['ng_lianhe','ng_death']},
{id:'ng_resource', n:'资源星系 · 阿波罗', c:'地理', m:'ningu', r:'ng9', e:[9], p:[-720,80,300], k:'rocks', kp:{r:120,n:150,s:5,c:'#d8e8f0',ice:1},
 s:'联合球的用水来源：亿万颗冰冻小行星。还有尔什民最初飞向虚空时的探测器。',
 d:'被称作“资源星系A”，是联合球的用水来源：这里飘着几亿颗冰冻小行星和无数岩石，联合球把冰球裂解后运回去。幽姆舰长让它们来找一件冻在这里的东西，却没说具体位置。它们对着它看了半天，猜这是不是最早的那个……好像叫阿波罗？那艘三百多米的探索舰却只花了不到半个尔什昼夜就找到了它：一颗三公里宽的冰球表面，立着一根圆筒，正是尔什民第一次飞上虚空时造的那批有名的航天器之一，连内部结构都一样，积满灰尘。其实它是新造的——工作空间里的尔什民故意把它做旧，做工好到很难看出来。',
 ch:'卷三《新诞生》《追寻物品》《古老之物》', rel:['ng_lianhe','ex_planet']},
{id:'ng_river', n:'漆黑的河流', c:'地理', m:'ningu', r:'ng9', e:[9], p:[-320,-100,620], k:'river', kp:{len:900,c:'#0a0a0e',drake:1},
 s:'凝固虚空中一条长得不知道尽头的黑色河流。',
 d:'琳的死亡战舰送巴士海葵穿过凝固虚空，先遇到一颗直径约六千万公里、表面完全停住不动的凝固恒星，十万公里内有一股看不见的斥力把东西挡在外面；绕开之后，就看到了这条河。它由一种像液体的凝固物质翻滚而成，里面裹着各种来自正常虚空的东西：巨大的岩石、仿佛被冻住的爆炸、见过的迷你恒星——像是专门把这些杂物冲出去。河边趴着一个近一公里长、形如飞龙低头喝水的东西，也全由凝固物质构成。死亡战舰顺着它一路飞了数亿公里，河流还在继续蔓延——“越长越有趣”。同时，尔什民在“历史扮演”的空间里追问：究竟发生过什么，才让全球那么多国家、那么多种思想合成了一个？',
 ch:'卷三《不单纯的荒漠》《排除污染》《历史与河流》', rel:['ng_death','ng_hezao']},
{id:'ng_hezao', n:'合造的世界', c:'地理', m:'ningu', r:'ng9', e:[9], p:[-150,40,720], k:'planet', kp:{r:30,tex:'rock',c1:'#5a5a60',c2:'#8a8a94',glow:.5},
 s:'巴士海葵非常想接触的一颗世界。',
 d:'一颗和尔什很像、有着大片海洋的世界，只是海洋已经被气球生物切成一块块，像蛋糕一样飘在空中。巴士海葵一靠近就激动得不停发信号：“这是我的！我要接触它！”琳把它装进一艘货车形的小飞行器，降落在干枯的海床上：那里有海底山脉，有珊瑚般密密丛生的生物，偶尔还趴着或飘着几十上百米长的大家伙。海葵嚷着扑向气球生物，被琳用透明的“绳索”拉住。后来世界半径一百公里内出现了大量发光物，堆在它的表面，光芒越来越强。',
 ch:'卷三《合造的世界》《被启动的世界》《形态》', rel:['ng_haikui','ng_qiqiu']},
{id:'ng_qiqiu', n:'气球生物 · 生命床', c:'物种', m:'ningu', r:'ng9', e:[9,10], p:[-80,0,640], k:'swarm', kp:{n:50,s:50,c:'#e8d8c8',balloon:1},
 s:'固执的艺术家：‘完美也好，不完美也好，都是生来就有的！’',
 d:'它们觉得找到的海葵应该维持被发现时的姿态，不喜欢就直接丢掉，绝不改动；它们还把找到的所有飞龙都摆成了某种样子。幼仔出生在“生命床”——一块由各种凝固物质混合成的巨大陆块，看起来像“稳定大陆”。正常虚空的物质会“污染”生命床。后来它们遮蔽了球神世界的天空，固执地要摧毁让它们“厌恶”的东西。',
 ch:'卷三《生命床》《驳回》《气球与球》《固执的转变》', rel:['ng_haikui','ng_qiushen']},
{id:'ng_haikui', n:'巴士海葵', c:'物种', m:'ningu', r:'ng9', e:[9], p:[-180,60,560], k:'blob', kp:{s:10,c:'#ff9ab8',tentacles:1},
 s:'死亡战舰都想得到的东西——一颗可以培养成“凝固巴士”的种子。',
 d:'死亡战舰想得到的东西：一颗能在凝固虚空里长成“凝固巴士”的种子。舰长们一致打算让它长成一颗巴士，再把工作空间里的尔什民和尔什生物放上去，养出一套正常虚空和凝固虚空混在一起的生态。琳带着它在凝固虚空里飞了几百万公里，途中见到一颗完全凝固、不再发光的恒星，十万公里外就有一股斥力挡着。它一见合造的世界就激动地嚷“这是我的”，扑向把巨型海葵当艺术品的气球生物——气球生物认定，完美和不完美都是与生俱来的，不能改。',
 ch:'卷三《古老之物》《不单纯的荒漠》《被启动的世界》', rel:['ng_death','ng_qiqiu','ng_jianzhang']},
{id:'ng_jianzhang', n:'舰长类生物', c:'物种', m:'ningu', r:'ng9', e:[9,10,11], p:[-250,30,520], k:'none',
 s:'各种凝固生物都可能变成“舰长”。',
 d:'舰长类生物不是“正常”的生物，而是一种集合体，任何凝固生物都可能变成它。起因是琳称作“光屑彗星”的东西：像一颗巨大的光球划过天空，拖着上千公里长、由无数发光粉末组成的尾巴，光屑本身能反凝固。凝固生物沾上光屑，就会立刻去找同样被寄生的同伴，不论什么种类都当作自己人一起生活；身体越长越像，最后融合在一起，成为舰长。它们的“命令器官”由凝固物质构成，能发出影响各种生物的信息——琳用它强迫凤凰说话。野生的舰长生活在生命床上；有一个舰长长得很像尔什民的手指。',
 ch:'卷三《舰长类生物》《继续扮演》《港口》', rel:['ng_comet','ng_haikui']},
{id:'ng_factory', n:'工作空间 · 工厂', c:'地理', m:'ningu', r:'ng9', e:[9], p:[-520,-80,640], k:'station', kp:{s:26,c:'#6a6058',factory:1},
 s:'死亡战舰把抓来的尔什民关在许多空间里做工：每座工厂五千个，总数差不多十亿。',
 d:'问它们为什么在这里干活，它们也说不上来，只知道不干不行。后来工厂以老鼠为主：很多很多老鼠占满地面，一只装着炸药的十厘米老鼠扑倒了三米高的“监工”。也有尔什民在“历史扮演”的空间里，一遍遍演出过去的历史。',
 ch:'卷三《艰辛的世界》《简单的构成》《到那那那那》《思维的去向》', rel:['ng_death','ng_phoenixhero']},
{id:'ng_phoenixhero', n:'凤凰（工厂的英雄）', c:'角色', m:'ningu', r:'ng9', e:[9], p:[-480,-40,680], k:'bird', kp:{s:10,n:1,c:'#ff6a2a'},
 s:'一头熊熊燃烧、翅翼闪耀的凝固生物，想当英雄。',
 d:'它发誓不惜一切代价保护、拯救大家——这是英雄的义务，也是有强大力量的责任。它佩戴着一本电子书，书替它说着激昂的话语，它就展开双翼在尔什民之雨中飞舞。它看起来很适合恒星，其实不能直接碰触恒星环境。（和恒星上的凤凰同名，却不是同一种生物。）',
 ch:'卷三《来自恒星》《燃烧的头领》《想当英雄》《英雄凤凰》《碎裂的空间》', rel:['ng_factory','v_feng']},
/* ---------- 时代 10 ---------- */
{id:'ng_comet', n:'光屑彗星', c:'现象', m:'ningu', r:'ng10', e:[9,10], p:[300,140,-220], k:'comet', kp:{len:420,c:'#ffd8ff'},
 s:'像一颗巨大的光球划过天空，拖着上千公里、由发光粉末组成的尾巴。',
 d:'它划过时，漆黑的凝固虚空会被照得通亮——虽然很多凝固生物根本没有视力。光屑本身有反凝固效果，它的出现导致了舰长类生物。彗星里有一个数百公里的大洞“泉眼”，光屑就从那里飞散。轰击塔每六十秒发射一次，从来没能打进彗星。彩泥一直在等它。',
 ch:'卷三《舰长类生物》《被照亮的凝固》《泉眼》《彗星之内》《彗星之花》', rel:['ng_jianzhang','ng_qiushen','v_caini']},
{id:'ng_qiushen', n:'球神的世界', c:'地理', m:'ningu', r:'ng10', e:[10], p:[620,0,0], k:'planet', kp:{r:90,tex:'dark',c1:'#4a4448',c2:'#8a7a6a',bridges:1},
 s:'整个世界被无数“立交桥”覆盖，桥与球神之间有很强的斥力，因此飘浮在空中。',
 d:'桥梁多由凝固混合物构成。大多数物种信仰“球神”——有的说它是世界之心，有的说是别的什么；它学会了穿过凝固缝隙，到处创造智慧。至于上一次文明为什么灭绝，球神觉得是因为文明太依赖能改变环境的“彗星土”。一颗大半由凝固物质构成的球体，空气里充满尘土，到处是无数文明物种留下的废墟。尔什民从历史空间里来到这里，在一座桥上建起管道相连、供应氧气和水的小镇。',
 ch:'卷三《提升的机会》《世界上的桥梁》《抛弃了它》《灭绝它们》《适应生物的环境》《初步》《带到》', rel:['ng_zhushen','ng_naogen','ng_guzhan','ng_button','ng_comet']},
{id:'ng_zhushen', n:'柱神', c:'物种', m:'ningu', r:'ng10', e:[10], p:[620,0,0], k:'pillar', kp:{len:520,c:'#141418'},
 s:'球神世界上伸出的漆黑巨柱，算是“稳定大陆”的一部分。',
 d:'柱神身上经常出现凝固虚空的缝隙，涌出大量会自动融合的“记忆岩”，所以它不停增长。球神去不了没有缝隙的地方时，就需要柱神帮忙。古战舰曾袭击柱神、几乎毁掉它所有的文明，还想弄断它；柱神把意识转移走才活了下来。后来一根两万多公里、比柱神更尖锐的漆黑“长矛”出现了，它甚至可以贯穿整个球神。',
 ch:'卷三《提升的机会》《第一次的灭绝》《决定的想法》《穿梭》', rel:['ng_qiushen','ng_guzhan']},
{id:'ng_naogen', n:'脑根 · 天才', c:'物种', m:'ningu', r:'ng10', e:[10], p:[680,-70,140], k:'none',
 s:'它说那些东西专吃智慧，会把它散出去的智慧吃掉。',
 d:'像地瓜一样的物种，专门袭击正在增长智慧的生物：侦测能力极强，一察觉附近有谁在变聪明，就在体内生成专门针对其神经和思维结构的毒气，杀完一带所有的生物才进入沉睡。后来文明物种发现了沉睡的脑根，把它当食物吃——吃下去智力会明显上升，据说许多文明历史上的天才和发明家都吃过它。球神说它们是吞噬智慧的家伙，对它们却意见不大，因为它们会把吞下的智慧还回来。诺钻进脑根之后，古战舰活了过来。',
 ch:'卷三《脑根与天才》《起航》', rel:['ng_qiushen','ng_guzhan','ex_nuo']},
{id:'ng_guzhan', n:'古战舰', c:'文明', m:'ningu', r:'ng10', e:[10], p:[460,90,220], k:'ship', kp:{s:80,n:1,c:'#3a3430',skull:1,wreck:1},
 s:'古老的死亡战舰，由凝固生物的残骸堆起来，遮星蔽日。',
 d:'古老的死亡战舰，由凝固生物的残骸堆起来，遮星蔽日。它每隔几十个尔什年才出现一次，活动时期叫“执行任务期”，大概几百绒球年，之后进入休息。它曾在一个世界的最后战役里出现，所有物种都激动起来。苏醒后，它以每秒十一万公里的速度追向那颗彩色的彗星：诺在驾驶，船上十个刚醒来的“天才生物”被拿来当动力源，彼此猜疑，以为这是别的文明的阴谋。彗星每次穿梭两个虚空，都会出现在随机的位置，飞过之处会被暂时染成思维里最复杂的色彩；古战舰追进那片彩色时，前方还有十艘形状各异的漆黑死亡战舰，也一直追着它往返。',
 ch:'卷三《古代之物》《最后的战舰》《航行中》《苏醒的目标》《古代与现代》', rel:['ng_zhushen','ng_comet','ng_death']},
{id:'ng_button', n:'按钮生物', c:'文明', m:'ningu', r:'ng10', e:[10], p:[720,40,-100], k:'none',
 s:'长得像刺猬、对凝固虚空研究最深的文明。一场为了留住自己文明的阴谋。',
 d:'它们能主动打开凝固缝隙。它们照着“教程”做：用感知器官寻出一处独立的小空间，确立它的性质，再试着扩张它。它问：放进这颗湮灭炸弹，它就能一直扩张下去吗？‘不行，里面得先有很多物质——有了东西，才有地方。’‘塞一颗恒星进去，炸了看看？’',
 ch:'卷三《激活》《建立教程》《扩展》《活下去的阴谋》《更大的地方》', rel:['ng_qiushen']},
{id:'ng_pinecone', n:'松果', c:'地理', m:'ningu', r:'ng10', e:[10], p:[900,-40,260], k:'planet', kp:{r:30,tex:'rock',c1:'#6a5038',c2:'#3a2818',scales:1},
 s:'凝固虚空里的一个自然天体——任务的发送源。',
 d:'琳在松果上找到许多被困的生物：负责设计码头的、设计建筑的、负责环境的……被琳叫作“骨象”的本土生物杀死粘土里的“计划生物”，其实是想拯救这颗松果。创造者告诉琳，松果和彗星一样是必须被毁掉的目标，只是因为计划者在这里，才排在最后。',
 ch:'卷三《最后的松果》《松果的裂谷》《任务源》', rel:['ng_qiushen']},
{id:'ng_ancestor', n:'先祖之地', c:'地理', m:'ningu', r:'ng10', e:[10], p:[320,-80,520], k:'rockworld', kp:{r:110,c:'#c8ccd0',c2:'#6a7078'},
 s:'墟集神的先祖所在的世界：一块十多万公里、形状不规则的巨大石头。',
 d:'凤凰飞进圆环转移，过了两三个昼夜，却被转移到了这里——墟集神一眼就认出了它。这里有引力，大约是绒球的七成，凤凰的“力量”只能维持几秒，飞起来又摔回地上。“三个世界一起诞生，什么都是共有的。”先祖之地就是三个世界之一，另外两个是绒球和“三号界”。雪原、先祖的沼泽、绒球泉眼都在这里。',
 ch:'卷三《穿过》《雪原》《观察世界》《先祖的沼泽》《过去的毁灭》', rel:['ng_snow','ng_quanyan','rongqiu','tn_third','v_xuji']},
{id:'ng_snow', n:'雪原 · 追光生物', c:'地理', m:'ningu', r:'ng10', e:[10], p:[260,-30,560], k:'none',
 s:'白色颗粒铺成的大地，像一片白色的沙漠。追光生物戴着火把，永远无法离开雪原。',
 d:'两肢生物、飘浮生物等十多种生物统称“追光生物”：它们完全无法自行反凝固，只能靠寄生在身上的炉火类生物“火把”放出反凝固场，被吸取养分直到死亡。一米高、能跳的“雪原追光者”（雪光）几十个一群，头领顶着火把。一座三千多米、没入云中的雪山顶上有建筑，每级台阶都有一米高。血山的外壳裂开，里面是一头全身透明的光龙。',
 ch:'卷三《雪原》《山顶的建筑》《只有光明》《最后一步》《雪原边境》《穿透》', rel:['ng_huobanao','ng_luhuo','guanglong','ng_ancestor']},
{id:'ng_huobanao', n:'火把之脑', c:'物种', m:'ningu', r:'ng10', e:[10], p:[320,-20,580], k:'none',
 s:'没有行动能力、只待在原地发号施令的“脑”，可能是最后一个。',
 d:'它没有行动能力，只待在原地发号施令，可能已经是最后一个。其他火把是因为它才变成火把的样子——火把并不是正常的分工型物种。它感知力极强，指挥的不是自己的身体而是别的物种；炉火里的怀疑个体开始质疑警报指令，它就转而控制那些不会怀疑的个体，炉火因此分裂成两群，怀疑者把“接到信号就听”的那些赶了出去。穿星之印飞到先祖之地上空，一路循着信使火把来的方向轰炸。琳觉得它有趣，决定让它活下来，建议它每次只派几十个火把去引凤凰的炸弹，自己则去查那个被改动过的传送圆环。',
 ch:'卷三《模仿命令》《协助》《准备躲避》', rel:['ng_snow']},
{id:'ng_quanyan', n:'绒球泉眼', c:'地理', m:'ningu', r:'ng10', e:[10], p:[380,-60,460], k:'pit', kp:{r:24,c:'#5a7a4a'},
 s:'先祖之地上一个直径一公里的坑洞。周围有许多“绒球的事物”。',
 d:'琳的骸龙形兵种飞过来，最先看到的是一种叫“气蚁”的凝固生物。泉眼里的空气带着恐龙大陆丛林的微生物、植物种子，甚至侏儒排泄物的碎屑——它曾经连着恐龙大陆。可周围那些看似来自绒球的东西其实都不是：泉眼底部是一个巨大的“合成装置”，铺满了正常虚空物质碎屑构成的“沙滩”。有一群生物很擅长“驯服”这类工厂，让它们只会制造而不会思维。',
 ch:'卷三《懒惰》《泉眼》《接通？》《工厂》《驯服》', rel:['ng_ancestor','west','zhuru']},
{id:'ng_moriha', n:'末日海', c:'现象', m:'ningu', r:'ng10', e:[10], p:[100,0,720], k:'fog', kp:{r:120,n:40,c:'#6a7a8a',lightning:1},
 s:'充满风暴的地方，在里面活动就像在暴风里行动。',
 d:'强烈的气流让人无法自由动作，只有特制的导弹不受影响。“末忆线”生活在这里，它从末日中诞生；把末忆线发射出来的生物，期望它影响别的生物，帮它们再造“三号界”。',
 ch:'卷三《转移？》《过去的毁灭》《模拟的发展》《类似的创造物》', rel:['ng_ancestor','ng_zhujie','tn_third']},
{id:'ng_zhujie', n:'诸界之骨 · 多界之骨', c:'物种', m:'ningu', r:'ng10', e:[10], p:[0,80,640], k:'ship', kp:{s:30,n:3,c:'#e8e0c8',bone:1},
 s:'空心骨架里装着许多十几厘米的装置，每个装置里都是一个完整的世界。',
 d:'装置类似琳的“梦境之脑”，里面有复杂的生物、文明和生态。它自称也来自“三个世界”之一——除了绒球和先祖之地之外的那个。诸界之骨的指挥室里有一个负责控制所有世界的文明，它们能修改别的世界的规则，却改不了自己的世界——那里到处飘着数百米、雪白云朵般的东西。',
 ch:'卷三《多界之骨》《内部的我们》《守护的信息》', rel:['ng_ancestor','ng_moriha']},
{id:'ng_mixu', n:'米德虚空', c:'现象', m:'ningu', r:'ng10', e:[10,11,12], p:[860,100,-420], k:'fog', kp:{r:150,n:30,c:'#1a1420'},
 s:'米德加尔特的虚空。死亡战舰的大军来自这里。',
 d:'而这只是米德加尔特虚空里很小的一支。琳也不知道死亡战舰到底有多少，只知道打起来的规模，比住在一颗恒星上的凤凰大得多。很久以后，琳又发现了“米德虚空二”：景象都是固态的，和米德一的动态景象发生着“共鸣”。',
 ch:'卷三《虚空的奇迹》《凤凰的战争》《消失》《过去之物》', rel:['ng_death','v_feng','mg_overview']}
);

/* 卷三：不可预见之地（t 为沿细微意识之河的位置） */
window.WIKI.push(
{id:'bk_overview', n:'不可预见之地', c:'地理', m:'buke', r:'bk11', e:[10,11,12], t:.3, off:[0,90,0], k:'none',
 s:'与正常虚空规则不同的另一个虚空。‘这里的所有东西，都是从思维里生出来的。’',
 d:'这里的根基是‘想象’：在这片虚空里，想象能改变自己。这里没有星空，却也不是一片漆黑，常能见到各种飘浮物。它和凝固虚空正好相反：凝固虚空在越来越接近正常虚空，它却在慢慢远离。古老的传说里，它曾和正常虚空接触过，离开后再也没有真正地接触过。',
 ch:'卷三《慢慢远离》《前往》《分散》', rel:['bk_home','bk_mengerxi','bk_shadow','v_buke_gate']},
/* ---------- 时代 10：返乡之道 ---------- */
{id:'bk_home', n:'返乡之道', c:'地理', m:'buke', r:'bk10', e:[10], t:.04, off:[0,-20,0], k:'island', kp:{r:90,c:'#8a8070',c2:'#6a6458',cliff:1,fog:1},
 s:'曾经连接虚空隧道和另一个地方的空间。许多生物来这里追寻家园，最后死在这里。',
 d:'虚空隧道崩塌后，进入隧道的生物迷失在正常虚空和零碎的小空间里，渐渐忘了自己来自哪里——可只要接近这个空间，体内的某些东西就会“觉醒”。悬崖下翻腾着浓雾，“砂鲼”在雾中飞舞；“只要离开这个空间……”白星说。这里有空间的“塑造装置”、制造塔与制造体，地下的“融合体”不断把制造体与自己融为一体。在通路里待得太久，思维和记忆都会丢掉，白星就是这样在半途迷失的。',
 ch:'卷三《雾上》《边缘》《曾经连接的家园》《塑造》《融合体》《逃离》', rel:['bk_shafen','bk_light','bk_tenghu','ex_baixing','dr_zero']},
{id:'bk_shafen', n:'砂鲼', c:'物种', m:'buke', r:'bk10', e:[10], t:.06, off:[90,-60,40], k:'flock', kp:{n:14,s:12,c:'#b8a888',ray:1},
 s:'皮肤像砂石聚成、翼展十多米的生物，在悬崖下的浓雾里翻腾。',
 d:'皮肤像砂石聚成、翼展十多米的生物，在悬崖下的浓雾里翻腾。它们原本负责运送制造体，不用捕食，靠沿途灯塔射出的光柱指路、吃灯塔给的发光物；没有灯塔，它们会在漫长的通路里迷路。后来不再有新的制造体出现，它们失去了生活目标，不少就在原地发呆；闲得发慌的砂鲼还会自己去调查，通过制造塔第一次“看”到了空间外面的样子。通路崩塌时，飘浮的制造体会全部死亡，一直在等待的那头砂鲼也死了。',
 ch:'卷三《雾上》《变化》《延伸的光芒》', rel:['bk_home']},
{id:'bk_light', n:'光之原住民', c:'物种', m:'buke', r:'bk10', e:[10], t:.09, off:[-80,30,-50], k:'swarm', kp:{n:6,s:40,c:'#8affd8',cube:1},
 s:'像极光一样不断闪烁的光，整体是一米多的方块。',
 d:'一群像极光一样不停闪烁的光，整体是方形的，只有一米多大，像一个极光做成的方块。身上会随时冒出几个“光眼”：耀眼的蓝色小点，射出一两秒的强光，那就是它们的视线，只要躲开就不会被发现。白星嘴上说这些原住民很危险，人却越凑越近，像电影里的特工一样在石块间扭身穿行。据它说，抓到一只，能比抓常见的透明生物得到更多‘能量’，更久地不被石化，足够穿过这个空间。它们听不见别人说话，别人也听不懂它们；琳第一次见时，五只正围着一座海天使雕像。',
 ch:'卷三《光之原住民》', rel:['bk_home','ex_baixing']},
{id:'bk_tenghu', n:'藤壶礁', c:'物种', m:'buke', r:'bk10', e:[10], t:.12, off:[60,40,80], k:'rocks', kp:{r:40,n:30,s:8,c:'#8a8a7a',barnacle:1},
 s:'像一栋“公寓”的生物，身上附着的藤壶般的东西就是它的居民。',
 d:'像一栋“公寓”的生物：一块礁石般的东西上密密麻麻附着藤壶似的居民。这些“藤壶”本质是坚硬外壳包着肉质躯体，也是一种类似细线的生物，躯体中心储存大量细胞生物的核信息——不是给自己用，而是通过附着处底部的细管启动礁石；那块礁石其实是一个结构精密的飞行器。被琳炸倒后，它们一边喊着“杀光你们”一边不断自杀。约一万个藤壶礁与十万凤凰激战，凤凰们气的是，对方居然挡着不让它们回故乡。',
 ch:'卷三《新的躯体》《合作？》《聚集与交战》', rel:['v_feng','bk_qiji']},
{id:'bk_qiji', n:'奇迹制裁', c:'现象', m:'buke', r:'bk10', e:[10], t:.15, off:[-60,-40,60], k:'ring', kp:{r:16,n:1,c:'#ffd8a0',flute:1},
 s:'奇迹生物造出的武器，用来“制裁”失控的奇迹。',
 d:'奇迹有无尽的可能性，也包括失控的可能性。所有奇迹都要经过漫长的发展到完成阶段，结束后，那一片所有执行奇迹的东西都会停下来。一件“笛子状”的奇迹制裁曾被凤凰围绕；它的启动被阻止了，因为细线也……',
 ch:'卷三《污染得清除》《攻击》《命运》《消散的世界》', rel:['bk_tenghu','v_xixian','v_nijiang']},
/* ---------- 时代 11 ---------- */
{id:'bk_expedition', n:'遥远远征队', c:'事件', m:'buke', r:'bk11', e:[11], t:.22, off:[0,-30,60], k:'none',
 s:'一百多个尔什民，从“未来”出发，走进不可预见之地。',
 d:'它们的故事要从未来说起，跟希望空间里那些巨大的尔什民有关。它们穿上装备拿起武器，在灰尘铺盖的平原上走了十个尔什昼夜，‘这是我们到过的最远的地方’；后来变成一群半透明的“尔什民”，失去了灯的指引，陷入迷惘。“荒漠收集者”专门收集这些生物，把它们带到合适的地方。',
 ch:'卷三《远征》《出发》《边缘》《穿过》《也许》《收集》', rel:['bk_lastworld','c_veronica']},
{id:'bk_lastworld', n:'最后的世界', c:'地理', m:'buke', r:'bk11', e:[11], t:.26, off:[-150,-20,-40], k:'planet', kp:{r:80,tex:'dream',c1:'#d8c8e8',c2:'#8a7ab8',glow:.3},
 s:'“这是最后的世界。它到达了这里。”一颗直径一万多公里的翻滚者。',
 d:'据说这是“未来的未来”。想到达地表要经过复杂的程序——测“期望值”。首领在一栋三层豪华房屋里：“我知道我们来自异常的时空。”“期望值”的真相，是动物的期望值。生活在周围虚空中的“变异民”对地表的战争不太清楚，很多在一开打时就搬了出来。',
 ch:'卷三《未来的未来》《通过》《异常之地的生活》《正常的生物》', rel:['bk_expedition']},
{id:'bk_mengerxi', n:'梦境尔什', c:'地理', m:'buke', r:'bk11', e:[11,12], t:.33, off:[140,10,0], k:'planet', kp:{r:70,tex:'earth',c1:'#8ab8a0',c2:'#7a8ac8',dream:1,vortex:1},
 s:'不可预见之地里的一颗“尔什”，有着尔什的一部分记忆。它也认识琳。',
 d:'它的引擎看起来像一个巨大的漩涡，旁边堆着大量棉花一般的燃料。“这些燃料到底能支撑多久呢？”它穿过细微意识构成的河流——梦境能量的液体一接近就被推开，像有一层透明的罩子。数十米长、木质的探测器在气墙周围探索，巨大的“空气墙”砸在地表上，却没有留下任何痕迹。后来它成了“所有世界的核心地带”，被星空模拟装置围绕。',
 ch:'卷三《修复》《出发》《最后》《击中》《避让》《了解旅途》', rel:['ex_planet','bk_simu','bk_hall']},
{id:'bk_daowen', n:'导师 · 大蚊', c:'物种', m:'buke', r:'bk11', e:[11], t:.36, off:[-110,40,40], k:'mentor', kp:{s:16,c:'#6a6070'},
 s:'像一颗覆满鳞片的球、直径三百多米的导师，以及它造出的约六米长的大蚊。',
 d:'导师原本是凤凰乐园里出现的“访客”：一种只有一米多大的凝固生物，像幻影一样在凤凰的居所里时隐时现，凤凰没有“幻觉”这个概念，当成新奇现象去抓，终于围住一个，它才显出实体。很长一段时间里，“导师”一直在巨大的尸体中——过去的‘唯一具象’换了个新名字，叫“意识具象”。它从那里长出像远射灯一样的结构，照向极远的地方，照出去的不是光而是“意识”，被照到的东西会变成完全不同的样子。琳看到这些生物出现，忽然想到了那个损坏点原本是什么。梦境尔什用数据库升级时，混进去的导师数据造出了一群大蚊，梦境尔什的防御对它们无效——导师“回归”了。',
 ch:'卷三《生成》《导师》《启动》《文明》', rel:['bk_mengerxi']},
{id:'bk_crying', n:'碎裂的大地', c:'地理', m:'buke', r:'bk11', e:[11], t:.4, off:[-160,-50,30], k:'rocks', kp:{r:70,n:60,s:16,c:'#8a8070',peel:1},
 s:'“它一直都在哭泣。”一块六百多公里的大地，表面在一点一点地剥离。',
 d:'它看上去也像一块浮在虚空里的大石头。',
 ch:'卷三《碎裂》', rel:['bk_shadow']},
{id:'bk_shadow', n:'遥远之影 · 碎影', c:'物种', m:'buke', r:'bk11', e:[11,12], t:.43, off:[60,120,-60], k:'shadow', kp:{s:70,pale:1},
 s:'不可预见之地里极强大的意识，一个就能覆盖巨大的范围。“碎影”是它的碎片。',
 d:'末日隧道也说不清它到底是生物还是某种“现象”。碎影从带它出来的生物那里学到了很多——它首先得知自己是遥远之影的碎片。碎影用梦境能量造了一个尔什民模样的躯体；它去过尔什和绒球世界，在第三颗世界找到了教导它的生物。它在寻找这片虚空里还没被发现的规则。和碎影交流之后，琳对自己是怎么诞生的，又有了新的想法。',
 ch:'卷三《教导》《漫长的时光》《接触》《第三颗世界》《规则》《到那个什么那那那》', rel:['bk_overview','dr_tunnel','c_lin3']},
{id:'bk_hall', n:'智慧之厅 · 金色殿堂', c:'地理', m:'buke', r:'bk11', e:[11], t:.47, off:[120,-40,60], k:'city', kp:{s:20,c:'#e8c86a',temple:1},
 s:'地下洞穴里三根十多米的柱子；倒满了浮雕雕塑的金色殿堂。',
 d:'“这就是传说中的智慧之厅？”一群尔什民聚在地下深处的宽广洞穴里，面前是三根十多米高的柱子，柱顶各立着一尊岩石般的生物雕像。它是琳用收集来的数据升级梦境尔什时冒出来的功能：很多尔什民学不会新的身体控制方式，用不了“思维移动”，在不可预见之地有些地方就寸步难行，这里就是教地表居民在这里生活的。梦境尔什遭到“议会成员”猛烈的攻击，地表出现巨大的窟窿；维罗尼卡抱着“迷你尔什”走在裂谷边缘，又走进倒满浮雕雕塑的金色殿堂——“损坏程度已经达到了……以上。”',
 ch:'卷三《数据诞生物》《冲突》《信息震撼》《抵达》《总资料》《起飞》', rel:['bk_mengerxi']},
{id:'bk_dust', n:'灰尘荒漠 · 渣地', c:'地理', m:'buke', r:'bk11', e:[11], t:.52, off:[-140,-60,-60], k:'island', kp:{r:110,c:'#9a9088',c2:'#7a726a',flat:1,dust:1},
 s:'厚厚的灰色尘土一直铺到视野尽头。',
 d:'维罗尼卡拖着被切成两半的资料室，用“思维移动”飞离梦境尔什，在大气层边缘仿佛经历了一段极其漫长的时光——跳跃成功了，落在一片厚厚的灰色尘土一直铺到视野尽头的大地上，琳管它叫“灰尘荒漠”。它坐在一块三米多的圆盘上缓缓移动，探索了三个绒球昼夜。荒漠里有个小镇，生物们在交易各种编了号的“尘”，有摊主吆喝着要拿一件稀世珍品换任意一种尘。',
 ch:'卷三《渣地》《寻找》《交易》', rel:['bk_hang']},
{id:'bk_hang', n:'悬挂之城', c:'地理', m:'buke', r:'bk11', e:[11], t:.56, off:[0,60,0], k:'city', kp:{s:60,c:'#b8b0a8',hang:1},
 s:'梦境残渣在一公里高空构成一块十公里的圆盘，下面伸出大量悬挂的建筑。',
 d:'地面上是三十多米高、残渣组成的围墙，围墙上有一个六米多的半圆形入口。城市顶端飘浮的平台是光滑的白金色，飘着很多“彩云”。悬挂之城有不少目的：第一，彻底吸收这里的所有资源；第二，进行一种“相反测试”。剩下的生物组成了一个叫“最后的意识”的组织，在资源稀缺中努力活着。',
 ch:'卷三《城市》《享受》《悬挂的终末》《维持意识的战争》《剩下的生活》《建造者》', rel:['bk_caiyun','bk_ziliao','bk_builder','bk_abandon']},
{id:'bk_caiyun', n:'彩云', c:'物种', m:'buke', r:'bk11', e:[11], t:.58, off:[60,110,20], k:'fog', kp:{r:30,n:20,c:'#ffc8e8',rainbow:1},
 s:'一团团一米多的彩色雾气。它们聊的全是打招呼的话。',
 d:'彩云们见面只会互相问好、夸天气、说自己过得很舒服，一遍又一遍。它们想要什么就有什么，从来不会对快乐感到腻。一团刚刚“觉醒”的彩云，瞬间被飞来的石块砸散了，别的彩云完全没有注意到。建造者把大量彩云放进了自己身体改造成的“地狱”里。',
 ch:'卷三《享受》《悬挂的终末》《轰炸》《融入》', rel:['bk_hang','bk_builder']},
{id:'bk_ziliao', n:'资料室', c:'琳的造物', m:'buke', r:'bk11', e:[11], t:.6, off:[-90,20,80], k:'starfish', kp:{s:16,c:'#d86a5a'},
 s:'像棘冠海星一样的载具，趴在悬挂之城的围墙边。',
 d:'琳把飘浮的资料室改造成一只“棘冠海星”：十只触腕，浑身长满棘刺。它开到最大动力赶回悬挂之城，城上的彩云依旧沉浸在享乐里没有醒——非得有谁弄醒它们，那条像蚯蚓的生物才会发动攻击。资料室没有直接落上平台，而是降在下方增生物丛林的边缘，吞掉了周围长出的增生物，又像真正的海星一样用触腕挖开残渣沙地，挖到底部，露出写满大量文字的白色地面——那是建造者关于“跳跃点”的实验记录。',
 ch:'卷三《吞食》《袭击》《挖掘》《找到》', rel:['bk_hang','bk_builder']},
{id:'bk_abandon', n:'抛弃之地', c:'地理', m:'buke', r:'bk11', e:[11,12], t:.64, off:[130,-80,-30], k:'island', kp:{r:90,c:'#5a3a3a',c2:'#3a2222',crystal:'#8a2a2a'},
 s:'也叫厌恶之地、遗弃区：一个因为“对无用之物的厌恶”而诞生的地方。',
 d:'许多生物要想象自己“被抛弃”才能抵达这里：接触跳跃点时，会觉得自己经历了一段漫长的时间，并开始想象这段期间的经历。也有特别的生物不需要——比如琳这种整个身体都是思维核心的生物。地面上到处是十多米的花状增生物，每朵上都有一个幽灵般的东西；更深处是暗红色结晶般的地面。',
 ch:'卷三《抛弃之地》《抵达和抛弃》《了解》《诞生地》《认知》', rel:['bk_abyss','bk_abu','bk_jianyun']},
{id:'bk_abu', n:'阿布', c:'角色', m:'buke', r:'bk11', e:[11,12], t:.66, off:[70,30,60], k:'none',
 s:'本体像一块布，所以琳叫它阿布。别的成员叫它“全知者”。',
 d:'本体像一块布，所以琳叫它阿布，别的成员叫它“全知者”。它原本是某个希望空间的主意识，却不是自由的：每次空间“复活”，它都附着在一个按它记忆生成的、旅途中遇见过的生物身上，像辅助脑一样只能给建议、控制不了行动；那个生物一死，它也跟着死，空间重启，再换一个。它保留着过去的记忆，空间重启也不会抹掉，所以过得很难受——附着的生物大多很蠢，活不长。直到有一次，它跟的生物活到了寿命尽头，它才发现那之后能控制那具身体了。它觉得琳想了解这里，就该去找悬挂之城的建造者——建造者本身已经不在了，但留下的东西还在。',
 ch:'卷三《寄生》《寻找》《底层》', rel:['bk_abandon','bk_builder']},
{id:'bk_builder', n:'建造者', c:'角色', m:'buke', r:'bk11', e:[11,12], t:.68, off:[-60,70,-40], k:'none',
 s:'悬挂之城的建造者。它把自己的身体改造成了一层比一层恐怖的“地狱”。',
 d:'为了收集大量“被抛弃”的情绪，建造者把身体改成地狱般的地方，尸体至少有三百米厚，大量彩云被放了进去。它说，最后活下来的是它……侵蚀结束后，建造者走出了不可预见之地——它的另一半身体，去了正常虚空，再也没有回来。后来琳才知道，抛弃之渊是“领队”留下的。',
 ch:'卷三《建造者》《脑部》《融入》《观察》《选择》', rel:['bk_abyss','c_sarin','bk_hang']},
{id:'bk_jianyun', n:'剑云', c:'物种', m:'buke', r:'bk11', e:[11], t:.7, off:[100,-20,-70], k:'fog', kp:{r:24,n:10,c:'#8a8a8a',blades:1},
 s:'一团十多米的灰色浓雾，里面伸出许多剑刃状的尖锐物。',
 d:'它甩出身上所有的剑，被琳一根根棘刺打落在地上，然后发来信号：“它已经死了。”“你想了解的对象，死了。”后来，一大群“幽灵剑”和别的透明生物追着维罗尼卡和阿布跑。',
 ch:'卷三《尸体》《建造者》《变异打算》', rel:['bk_abandon']},
{id:'bk_abyss', n:'抛弃之渊', c:'地理', m:'buke', r:'bk11', e:[11,12], t:.74, off:[0,-130,0], k:'pit', kp:{r:70,c:'#1a0a10',deep:1},
 s:'它拉扯一切的力量不是引力，而是把东西拖进‘被遗忘’的深渊。',
 d:'只要一直有生物认知到它，它就一直“生长”，幽灵剑也许就是它生长时的现象。抛弃之渊活动在一片看不到边的漆黑里，除了出现的光点，它唯一能“看”到的不是黑色的东西，就是它自己。它对琳说，琳是最后一个认知它的存在；等琳杀了它，一切就到此为止。',
 ch:'卷三《追》《引力》《分离》《认知》《发现》', rel:['bk_abandon','bk_builder','bk_jilu']},
{id:'bk_jilu', n:'记录体', c:'物种', m:'buke', r:'bk11', e:[11], t:.76, off:[-80,-90,40], k:'hive', kp:{s:20,c:'#8a7a5a'},
 s:'一个“蜂窝”，每个小孔里都有一个像文字的东西。专门记录被忽视的信息。',
 d:'阿布吃了一惊：它居然是记录体？它是以前的队员之一，样子像一个蜂窝，每个小孔里都嵌着像文字的东西。最初在虚空某个文明废墟里被找到——那个文明怎么灭亡的没有任何记载，密室和日记里留下的全是无用的内容，记录体是废墟里唯一的“活物”。它专记别人忽略的东西：一场爆炸，它记的是远处恒星引力对爆炸的那点微弱影响；一栋建筑，它数的是路上的灰尘。要先输入某种生物的思维和感知方式，它才知道这种生物会漏看什么。它会修补自己、补充能量，最大的嗜好是把收集到的“没用”信息送还给对方。领队觉得它有趣，就把它带进了队伍。它们认为，任何生命都不可能记下一切；它就是为此而生的。',
 ch:'卷三《增生的地面》《记录多余之物》《自我抛弃》', rel:['bk_abyss','bk_abu']},
/* ---------- 时代 12：领队莎琳 ---------- */
{id:'bk_simu', n:'星空模拟装置 · 异界', c:'现象', m:'buke', r:'bk12', e:[12], t:.8, off:[0,40,0], k:'star', kp:{r:90,c:'#ffe8a8',sim:1,worlds:9},
 s:'从未被任何世界发现过的装置，大小差不多是太阳的一半，就在领队的脚下。',
 d:'它让梦境尔什上的尔什民看到正常虚空的星空——甚至是正常虚空的“未来星空”，周围还配齐了原本星系的翻滚者。尔什民在模拟装置上建立殖民地，以为自己成了虚空文明；装置里还有许多“异界”世界，住着英雄与反派。异界生物两次全面大联盟：一次对抗秩序守护者，一次对抗它们原以为很弱小、却偷猎成性的尔什民。',
 ch:'卷三《过去的生活》《命运》《战争》《装置》《发展》《远去》', rel:['bk_mengerxi','bk_order','c_sarin']},
{id:'bk_order', n:'秩序守护者 · 秩序之主', c:'物种', m:'buke', r:'bk12', e:[12], t:.83, off:[-120,20,40], k:'swarm', kp:{n:60,s:40,c:'#e8e8e0'},
 s:'“污秽又可悲的东西，统统给我在永恒的末日里灭亡！”',
 d:'秩序守护者清扫完一个世界的生物后，就把那个世界摧毁，于是所有世界都起来反抗。它们认定秩序之主永远不会消失：一小群生物让自己的“每日”不断循环、彻底封闭认知，秩序之主就此诞生。远古意识（因为负面情绪太多，显现成负面的形体）一起攻击也没能打倒它——最后是领队击毁了秩序之主，大部分生物都不知道发生了什么。还出现过崇拜秩序守护者的教派“拜秩序者”。',
 ch:'卷三《守护秩序》《秩序的残留》《自我的认知》《期间》《认知的变化》《最后的意识》', rel:['bk_simu','bk_huixu','c_sarin']},
{id:'bk_huixu', n:'毁序之主', c:'物种', m:'buke', r:'bk12', e:[12], t:.86, off:[140,-30,-30], k:'disc', kp:{r:46,c:'#7a6a5a',c2:'#4a3a2a',mountains:1},
 s:'‘你们的规则……违反掉。’一个直径三十公里多、两面隆起山峰的圆盘，像一座巨大的岛屿。',
 d:'一个直径三十多公里的圆盘，两面隆起许多山峰般的结构，远看像一座巨大的岛屿。据说它是规则的违反者、秩序的终结者——它一进入异界十万公里内，许多居民就开始反常：蒸汽城市的居民互相攻击，还在打仗的却突然停了手；靠近它的生物都会背离自己原本遵从的东西，连自己也背离。琳也收得到它的信号，不过没受多大影响；莎琳叫它“毁序之主”。它撞上异界的地面后就再也不动了，远看就像地面本来的一块。秩序守护者从远处汇聚到秩序殿堂的废墟，似乎在庆祝。',
 ch:'卷三《毁序之主》《片段》《迷失的地方》', rel:['bk_order','bk_ruin']},
{id:'bk_ruin', n:'秩序殿堂的废墟', c:'地理', m:'buke', r:'bk12', e:[12], t:.88, off:[-60,-60,-90], k:'rocks', kp:{r:70,n:40,s:14,c:'#c8c0a8',metal:1},
 s:'飘荡着数十米到数百米金属漂浮物的地方。',
 d:'飘荡着数十米到数百米金属漂浮物的地方，异界翻滚者缓缓地从这些碎片之间飞过。有一些生物据说是从碎片里诞生的：从碎屑中产生，活了下来，还开始变化。毁序之主被琳‘捕获’以后，大量秩序守护者从远处的虚空汇聚到殿堂所在的位置，显得非常激动、开心——它们之前一直受毁序之主的影响，现在总算结束了——它们自己是这样以为的。',
 ch:'卷三《碎片》《迷失的地方》', rel:['bk_huixu']},
{id:'bk_pig', n:'豚鼠与莎琳的雕像', c:'物种', m:'buke', r:'bk12', e:[12], t:.9, off:[110,30,60], k:'island', kp:{r:50,c:'#4a6aa8',c2:'#e8e0c8',statues:8},
 s:'“让迷失者不再迷失。”豚鼠们一直在建造莎琳的雕塑，当作不迷失的“灯塔”。',
 d:'一头全身闪着金光、十多米大的“豚鼠”撞开琳的蝎子，一口咬住莎琳雕像的头跑掉了。丛林里林立着各种形状的东西，有的像金属，有的像岩石、像血肉。十只豚鼠和十只仓鼠在柔软的蓝色地面和骨片之间高速奔跑，出去搜索材料的队伍常常全灭，日常生活却从不停止。',
 ch:'卷三《雕刻》《材料》《危险区域》《记忆》', rel:['c_sarin','bk_garden']},
{id:'bk_garden', n:'小花园 · 莎琳的意识', c:'地理', m:'buke', r:'bk12', e:[12], t:.93, off:[-120,10,30], k:'face', kp:{s:40,c:'#f8e8c8'},
 s:'温暖的阳光、植物丛中的小昆虫和鸟叫；以及一张一百多米大的莎琳的脸。',
 d:'维罗尼卡从空中飘落到绚丽的花圃上：阳光温暖，植物间飞着小虫，到处是鸟叫。白色小厅里坐着一个长得很像维罗尼卡的尔什民，放下书说，这里是莎琳记忆中一个平静的地方，会永远平静下去，请你也来享受吧。莎琳的“朋友”在这里袭击了琳——它有很强的“定位效果”，琳只好用花园里随便找到的石头刺穿它。“莎琳的意识”这个装置就在星空模拟装置的某处，外观是一张一百多米大的莎琳的脸，启动后自己组装成这样，有独立的运转系统和能源。一接触它，就能感到莎琳在虚空旅行中的种种念头，是它刻意存在这里的，其中也有它去迷失墓地的原因。',
 ch:'卷三《小花园》《记忆中》《找到》《意识的跳跃》', rel:['c_sarin','bk_room']},
{id:'bk_room', n:'无边会议室 · 观星室', c:'地理', m:'buke', r:'bk12', e:[12], t:.97, off:[0,50,90], k:'dome', kp:{s:26,c:'#e8e0ff'},
 s:'纯白大地上，方形的池子里盛满透彻的清水；半球形的房间墙上布满绚丽的星空。',
 d:'金发的尔什民模样的管理者们正在讨论……晚饭。它们看见琳，先是以为认识，又觉得不对。这里是以前莎琳设计的“无边会议室”，让无边的生物汇聚来探讨虚空——它曾经荒废，莎琳回来后重新激活了它。据说莎琳会从这里回来，于是琳也去试了试。在观星室里，琳感觉到了莎琳的感觉：像身处无边的……',
 ch:'卷三《接待》《回归》《最初》《数据》', rel:['c_sarin','bk_garden']}
);

/* 卷三：主要角色（跨地图） */
window.WIKI.push(
{id:'c_lin3', n:'琳（虚空中）', c:'角色', m:'void', r:'void', e:[6,7,8,9,10,11,12], p:[0,235,0], k:'fluffglow', kp:{s:12,c:'#fff4d8'},
 s:'离开绒球之后的琳：同一时间有成千上万个兵种散布在虚空各处。',
 d:'琳在虚民母球的战舰被粉碎又重组；之后它占据一头恒星巴士当作基地，用巴士的神经造出“星游者”四处旅行，又陆续造出穿星者、克拉肯、岩蛛与梦蛛、直径六公里的战舰“火山岩”。间谍化身在尔什以“维罗尼卡”的名字上学。它发现自己的意识并不在哪一个虚空里，而在一个“属于自己的虚空”中，所以才能同时控制那么多兵种。后来它的世界“三月”带着两颗卫星在管道间航行。莎琳对它说，活得越久，想要的就越简单——去找未知，去看未知；还说琳大概也是这样。故事最后，星空越来越暗，虚空的碰撞开始了，琳把许多东西移到安全的位置，静观其变。',
 ch:'卷三全篇；《最初》《起源》', rel:['lin','c_veronica','c_sarin','v_starbus','v_collide']},
{id:'c_maya', n:'玛雅（卷三）', c:'角色', m:'rongqiu', r:'north', e:[6,7,8,11,12], ll:[31,7.5],
 s:'要到浩瀚的星空里去翻滚——那颗向往星空的脑袋虫。',
 d:'它看完了最后一部虚民电影，再也没有新片可看，于是在云海上翻滚，想着接下来做什么。和整天待在合金蜘蛛里不出门的教长不同，玛雅向往一切有趣之事。它让爆哮虫背诵电影台词，然后在岛上造出一艘巨大的船舰，伴着爆哮虫的吼声升上虚空。之后它循着信号飞向南之大陆，被从地面射来的黑色长矛刺穿；教长告诉它：能联系创造之源的，只有创造之源——也就是它们自己。很久以后，它在一片沼泽上被针刺之雨刺穿全身，依然在翻滚：那东西停下了，可翻滚是不会停的。',
 ch:'卷三《向往星空》《信赖？》《再次迫降》《计划之中的计划》《停止？》《气泡》', rel:['naodai','c_baoxiao','jiaozhang','rq_south','rq_mayaship']},
{id:'c_baoxiao', n:'玛雅的爆哮虫', c:'角色', m:'void', sec:8, e:[6,7,8], p:[-500,120,350], k:'none',
 s:'玛雅的“扩音器”，后来成了学者的旅伴——话多，而且想吃煎蛋。',
 d:'它能把电影里角色的声音、语气模仿得一模一样，连那种‘我们不能在一起’的爱情台词也能吼得声情并茂。玛雅借它的嘴说话、下命令，也借它的身体跟学者一起去探险：在连接世界的虚民营地里追查伪装的侏儒，在结晶的城市里提议干脆解除伪装看看会怎样，在被真菌占据的城里一边找‘大预言家’，一边猜它们是不是想在这里拍恐怖片。在隐藏工程的虚民城里，它和学者在电影院被吓得半死。',
 ch:'卷三《向往星空》《无法唤醒》《了解》《城市？》《大预言家？》《隐藏地点》', rel:['baoxiao','c_maya','c_xuezhe','v_hidden']},
{id:'c_hero', n:'勇者 · 第二代魔王', c:'角色', m:'void', sec:8, e:[6,7,8], p:[640,100,90], k:'none',
 s:'琳造出的梦境生物，靠一颗“附属脑”存放思绪，后来成了恶魔的魔王。',
 d:'勇者没有自己的脑来安置意识，琳给它做了一颗附着在梦境之脑上的附属脑。最早的魔王是一个红绒毛球，它则是‘第二代’魔王——曾经有勇者的称号，从遥远的世界赶来管理并带领那群鲜红、好战、不畏死亡的恶魔。攻打脑灵核心时，红绒球抓起了它的头让它先回去，它请求留下来：它想亲眼看看，一个世界的最后一刻是什么样子。它也跟学者、爆哮虫一起用机械身体探索过连接世界，还在恒星巴士地底的尖刺林地和米德加尔特的管道里冒险。',
 ch:'卷三《寄于脑中》《以魔王的名义》《最后的阻碍》《了解》《内战》', rel:['v_demon','v_spike','mg_xingju','mg_xiulian','c_xuezhe']},
{id:'c_xuezhe', n:'学者（塔兰图拉）· 虚空之旅', c:'角色', m:'midgard', r:'mg8', e:[6,7,8], z:1500, ang:90, h:-60, k:'none',
 s:'那个“说想加入绒球”的虚民，后来几乎走遍了琳去过的每一个奇怪地方。',
 d:'卷三开头它还在绒球上旅行：恐龙大陆、裂谷的木质飞行器、盐地和盐下深处、立蝎的金字塔、造脑怪，最后找到的“宝藏”是一颗记录之球；它在骸龙最初的家园那棵大树下想过挖挖看塔克的骨架还在不在。后来它和教长一起看电影、研究脑灵，送玛雅的船舰升空。再后来它坐着连接舱换上“机械”身体探索连接世界，和血雾、爆哮虫走进结晶的城市，在真菌占据的城里被会动的骨架吓坏——它觉得会动的尸体比庞大的猛兽还可怕。最后它走进尘鳄的管道，听见熔岩之神开口，发现那是另一种它认识的生物的声音。',
 ch:'卷三《许愿需谨慎》《盐下深处》《金字塔之内》《信赖？》《城市？》《大预言家？》《咬杀之道》', rel:['tlant','c_baoxiao','mg_god','mg_city','rq_xuewu']},
{id:'c_veronica', n:'维罗尼卡（间谍）', c:'角色', m:'erxi', r:'ex_eu', e:[8,9,10,11,12], ll:[47.5,14.5],
 s:'琳的间谍在尔什用的名字——特丽提一位远房亲戚就叫这个名字。',
 d:'它混进天宫学院当学生，同学比露总是一口一个“维罗尼卡同学”。湮灭舰压向学院时，它从内部让战舰倒退升空，却发现自爆系统也在恢复——‘这次……大概复活不了了。’爆炸之后它大部分细胞居然还活着。后来尔什民的计划把它卷走，醒来时它已不是琳造出来的间谍，而是一个真正的尔什民，只是被琳控制着。它陪诺和比露走过尔什的末日现象，进入不可预见之地，在观星室里感觉到莎琳；故事快结束时，它和莎琳一起坐在“认知者的世界”的高楼上，看天空凭空洒下的阳光。',
 ch:'卷三《那让我们欢迎新生》《操作》《有关思维》《末日现象》《回归》《投影》', rel:['c_bilu','ex_tiangong','ex_teliti','spy','c_sarin']},
{id:'c_bilu', n:'比露', c:'角色', m:'erxi', r:'ex_eu', e:[8,9,10], ll:[43,10],
 s:'总爱拉着‘维罗尼卡同学’到处跑——天宫学院里最莽的学生。',
 d:'它第一次出场就慌慌张张地问间谍能不能一起走。它力气很大，脑子不太转：在偷猎者的仓库前它跑进浓烟里用拳头砸墙，门升起后把门后的偷猎者全踩翻在地，再一脚踹烂装着违禁品的箱子。在机甲里，一只鹅占了驾驶座，嚷着要支配整个世界；比露的回答是：等下就把你烤来吃。它曾被卷进虚空漩涡，在一片“没有尽头的地面”上待了一阵，又莫名其妙回到学院。后来在抛弃之地，琳看着阿布，想起了一点以前和比露一起旅行的日子。',
 ch:'卷三《丛林》《往上》《操作》《上去》《有关思维》《末日现象》《寻找》《追》', rel:['c_veronica','ex_tiangong','ng_qiqiu','bk_abu']},
{id:'c_sarin', n:'莎琳 · 领队', c:'角色', m:'buke', r:'bk12', e:[12], t:.985, off:[40,70,-60], k:'none',
 s:'“我一直都在旅行。”——第一卷把细胞丢进绒球的金发造物主，原来是“领队”。',
 d:'它说旅行是为了找到最后的答案，又说说不定旅行本身就算答案；活得越久，想要的就越简单——去找未知，去看未知。被它抓来改造的秩序守护者说出了“领队莎琳的旅途”：它曾回到抛弃之地改造那里，抛弃之渊就出自它手。迷失墓地里，一千只金色“豚鼠”不停雕刻莎琳的雕像，让迷失的正常虚空生物看见它就恢复神智——“让迷失者不再迷失”。星空模拟装置里有一个一百多米大、长成莎琳的脸的“莎琳的意识”。莎琳在观星室回归，与琳交谈；它说这个虚空的答案就是思维——凭空想象出不存在之物的能力。它在不可预见之地出口试着造一个躯体，结果造出一个一公里高的巨大莎琳，随即被一个发光的漩涡吸走、碎成无数碎屑。',
 ch:'卷三《秩序的储藏》《雕刻》《材料》《意识的跳跃》《回归》《最初》《出现》《投影》', rel:['shalin','c_lin3','bk_room','bk_abyss','bk_order','c_veronica']}
);

/* 补丁：卷一、二的条目延伸到卷三 */
(function(){
  var W=window.WIKI, by={};
  W.forEach(function(x){by[x.id]=x;});
  function ext(id,eras,rels){var x=by[id]; if(!x) return;
    if(eras) eras.forEach(function(e){ if(x.e.indexOf(e)<0) x.e.push(e); });
    if(rels){ x.rel=x.rel||[]; rels.forEach(function(r){ if(x.rel.indexOf(r)<0) x.rel.push(r); }); } }
  ext('moon',[6,7,8,9,10,11,12],['moon_bus']);
  ext('shalin',null,['c_sarin']);
  ext('lin',null,['c_lin3']);
  ext('naodai',null,['c_maya']);
  ext('tlant',null,['c_xuezhe']);
  ext('baoxiao',null,['c_baoxiao']);
  ext('jiaozhang',[6,7,8],['c_maya']);
  ext('susumi',[6,7],['rq_south']);
})();

/* 补充条目：卷一、二里还没收录的物种与兵种，以及卷三中间几段（黑金属之战、南之大陆、连接世界）。
   最后一段是数据修整：合并重复条目、修正引文、给卷三彩蛋挂上触发条目。 */
window.WIKI.push(
/* ---------- 卷一 · 海洋纪 ---------- */
{id:'guiwujun', n:'鬼雾菌', c:'物种', r:'sea', e:[1], ll:[-4.4,43],
 s:'岩石外层最后一个、也最厉害的大型细胞群落：长满绒毛的白色圆球。',
 d:'琳不知道“鬼”和“雾”到底是什么，只是觉得很适合这群细胞。它们的绒毛末端是硬化的，能伸得很长，捕获猎物就把绒毛刺进去，注入灰色的毒液，也能直接喷洒毒液。琳把触须弯下来对准它们猛地张开，连水带菌一同吸进去——触须里早有注酸者和爆球在等着，鬼雾菌还没弄明白发生了什么，就被大量溶解液化掉了。',
 ch:'卷一《突出》《眼球》', rel:['jingjun','origin','lin']},
{id:'rongbingjun', n:'溶冰菌', c:'物种', r:'sea', e:[1], ll:[-1.5,47.5],
 s:'能分泌液体、一下子化开身边的冰晶，因此能在冰里钻进钻出的细胞。',
 d:'冰层里的洞原来是它们弄出来的。溶冰菌躲在冰里欢快地晃动，直到琳的航母用巨锤触须猛地砸在冰壁上，把它们和冰屑一起打出来，吞噬者随即把它们吞得一干二净。它们往深处逃，可在冰里钻的速度远没有航母击碎冰的速度快。',
 ch:'卷一《离开冰层》《海中沙漠的生物们》', rel:['origin','jingjun']},
{id:'fanzhi', n:'海底基地 · 繁殖舱', c:'琳的造物', r:'sea', e:[1], ll:[-5,45.5],
 s:'琳第一座基地的核心：不停分裂基础细胞、产生各种部队的巨大球形构造。',
 d:'靠近中心的是吸收食物的食囊、分合壳质物的“溶炼厂”和储藏脂肪细胞的储藏室，每个都有航母的一半大；最中心的繁殖舱足足有航母的两倍大，外皮覆盖着坚甲和巨大的触须。它反而是构造最简单的：只管不停分裂基础细胞，让它们变成各种细胞再组合起来——只要组合成功过一次，以后细胞们就会自己照着做下去。后来铺在北之大陆上的绿毯没有繁殖舱，所以不能制造部队。',
 ch:'卷一《基地》《尖柱林之谜》', rel:['origin','lvtan','lin']},
{id:'gouchong', n:'钩虫', c:'物种', r:'sea', e:[1], ll:[-9,35],
 s:'扁椭圆形、两侧一排叶状附肢、头上一对带倒刺弯钩的节肢类。',
 d:'琳的爆弹炸中了它，它在水里摇晃着头部。别的生物感到痛楚时会逃跑或发疯，对琳来说，痛不过是一个‘被攻击了’的信号。黑夜里的钩虫和白天明显不同：再遇到吸满毒气的储气者，它们不再傻乎乎地吃下陷阱，而是纷纷躲开——不知道是黑夜的缘故，还是个体之间的差别。',
 ch:'卷一《黑夜中的光芒》《精神病》《古生代爆发》', rel:['sanyechong','ev_ext1']},
{id:'juxian', n:'巨陷虫 · 驱赶者', c:'物种', r:'sea', e:[1], ll:[-13,28],
 s:'身体本身就是沙地里一个大陷阱的巨大生物。',
 d:'它吸引想躲藏的生物钻进来，大概要等陷阱里的生物到了一定数量才开始溶解。利维坦挖不出这么大的东西，琳就组合出一种中心是圆形、能喷水移动、全身长满刺细胞触须的“驱赶者”，上百个漂在陷阱上方把它逼出来。巨陷虫想用触手再挖进沙里，琳立刻放出飞锯，高速旋转的锯齿专切它触须上的伤口。',
 ch:'卷一《异变》《冰河之下》《怪兽的时代》', rel:['lvtan_beast','sanyechong']},
{id:'rongyanrong', n:'熔岩蝾 · 击碎者', c:'物种', r:'sea', e:[1], ll:[-21,32],
 s:'吃下残杀者以后，背部亮起熔岩般红光的蝾螈类。',
 d:'它好像免疫残杀者的毒素，吃完后背部变得像熔岩一样鲜艳，颜色和残杀者的腹部十分相似，所以叫“熔岩蝾”——它把毒素藏在背部的皮层里。琳从利维坦的兵种目录里随便挑了一个用来对付重甲目标的“击碎者”：击碎者分头敲击熔岩蝾的腹部、尾部和头部，砸出一个个伤口，背上的皮一裂开，诡异的红色液体就大量涌了出来。',
 ch:'卷一《碎裂的蝾螈》', rel:['lvtan_beast','abyss']},
{id:'tanchong', n:'毯虫', c:'物种', r:'sea', e:[1], ll:[-27.5,37.5],
 s:'海沟最深处无光带里一块鲜红、扁平、方形的“地毯”。',
 d:'琳找不到它的嘴，体表上也没有触须，完全看不懂它是怎么猎食的，就叫它毯虫。被弹头们用刃状节足刮伤后，它疯狂地游出了无光带，速度快得难以想象；可一离开深处，它就慢慢停了下来，然后整个炸裂开来。琳几乎瞬间就明白了：在高压环境里它的身体缩得很紧，往上游时，压力的变化毁掉了它。',
 ch:'卷一《熔岩与疯狂》', rel:['abyss']},
{id:'chongfeng', n:'冲锋者', c:'琳的造物', r:'sea', e:[1,2], ll:[7,8],
 s:'利维坦的流线型冲刺兵种，前端是一根长长的锥角。',
 d:'它能在水中以超快的速度喷着水往前冲，还能蹿出水面好几米。浮空水母躲开了爆弹，琳就让冲锋者先潜到一定深度，再猛地往上冲，在水母反应过来之前刺穿了它的囊状身体。到了北之大陆，冲锋者在尖柱之间追逐奔逃的爬行类，每一次转弯都比上一次更利索，最后把它逼进了三根挨得紧紧的尖柱前的死路。',
 ch:'卷一《被预测的灾难》《爬与飞》', rel:['lvtan_beast','kongshuimu','spires']},

/* ---------- 卷一 · 北之大陆纪 ---------- */
{id:'kuangfeng', n:'狂蜂', c:'琳的造物', r:'north', e:[2,3], ll:[32.6,9.4],
 s:'琳照着扭曲丛林里一种凶残的小飞虫设计的蜂群兵种。',
 d:'琳把一头猎物的身体完全重组，用基础细胞在短时间里合成出一大群新的小型飞虫，起名“狂蜂”。它们成群行动，平时啃食菌丝，必要时能瞬间排成阵形：风暴之下，喷涌的水柱冲向贝希摩斯，无数狂蜂聚成一面巨大的半圆形盾牌挡在前面——盾牌被冲垮，蜂群像灰烬一样散落，却为贝希摩斯挡住了一秒多。',
 ch:'卷一《射炮步甲》《风暴之下》', rel:['jungle','behemoth','shepao']},
{id:'jichizhe', n:'疾驰者', c:'琳的造物', r:'north', e:[2], ll:[35.5,9],
 s:'能在扭曲丛林里高速奔跑、穿过各种障碍的侦察兵种。',
 d:'流经丛林的河水变小了，琳派疾驰者沿河往上游调查。河流越往上游越宽、越弯曲，不再是丛林的分界线，而是弯进了丛林深处，地势也越来越高。疾驰者不会攻击，只会跑得飞快——一个昼夜之后，它突然被笼罩在黑暗里，那感觉像是蠕虫的嘴，被吞进去的瞬间就碾碎了。这下琳反倒更想知道上游有什么了。',
 ch:'卷一《永不停息的新事物》《巴士与电影》', rel:['jungle','peak']},
{id:'shitaijia', n:'食苔甲', c:'物种', r:'north', e:[2], ll:[29.6,8.8],
 s:'闪光林地里一米多长、圆滚滚、覆盖着坚固盔甲的甲虫。',
 d:'林子里的甲虫太多了，总不能都叫甲虫，所以这一种就专门叫食苔甲。猎杀者全身散发着和苔藓一模一样的光辉，还洒满了水晶尘，与周围融为一体。食苔甲察觉时瞬间张开背甲、展开四片巨大的翅膀，可一只猎杀者已经扑上了它的背，锋利的前肢在翅膀上切出了好几道裂口，它再也飞不起来了。',
 ch:'卷一《丛林猎手》', rel:['glow','jungle']},
{id:'tairong', n:'苔螈', c:'物种', r:'north', e:[2], ll:[28.5,7.4],
 s:'白昼之初出来啃苔藓的半米长蝾螈，视力很好，总是抬头张望。',
 d:'它们没注意到头顶的扭曲树干上潜伏着一个十五厘米的小猎手——琳的狙击者。它能变色，用带钩的小刺腿趴在树干上，把咬下的树皮和木材吞进体内，用壳质物重新造成尖刺。“砰！”尖刺一瞬间洞穿了一只苔螈，正扎在心脏上，上面还混着能溶解心肌和神经的溶解液——周围的苔螈甚至没发现同伴已经死了。',
 ch:'卷一《狙击手》', rel:['glow','niuqushu']},
{id:'jufeng', n:'巨蜂', c:'物种', r:'north', e:[2], ll:[35.2,13.6],
 s:'身长两米的蜂，成片出现在山峰周围捕食。',
 d:'最近山峰的生物多了起来，主要是爱好温泉、行动不快的温泉蝾螈和温泉蟑螂，巨蜂用大颚就能轻松咬断它们的颈部，这些生物可能因此遭受灭顶之灾。从闪光林地到山峰，扭曲丛林里到处都是巨蜂。琳的收割者把翅膀刃化，迎面冲过去，把靠近的一只巨蜂切成了两段，剩下的巨蜂明白这不是它们能应付的对手，四散逃进了丛林。',
 ch:'卷一《偷猎者》《提取者》', rel:['peak','jungle']},
{id:'huijinchong', n:'灰烬虫', c:'物种', r:'north', e:[2,5], ll:[35.6,16.4],
 s:'火山周围滚烫黑水里飞快游动的小节肢类；很久以后，琳一种大型兵种也用了这个名字。',
 d:'迷雾散去，利维坦第一次见到陆地上的“山峰”：高度可能在千米以上，周围一整圈都是火烤过的焦黑，充满白色的有毒雾气——也许正是它毁灭了脑袋虫的族群。琳挖了个洞当陷阱抓到一只灰烬虫，分解后发现它的细胞能在温度突变时调整机制，不会因此死亡。卷二里，绒球面前一颗巨卵裂开，飞出一头十多米长、混合了炼狱蠕虫信息的新兵种，琳也叫它灰烬虫，让“印加虫群”拿它去对付敌方的光线。',
 ch:'卷一《火山之中》；卷二《从云海诞生的军队》', rel:['peak','lianyu','naodai']},
{id:'hongzhazhe', n:'轰炸者', c:'琳的造物', r:'north', e:[2,3], ll:[23.5,-4.5],
 s:'用气囊漂浮、尾部粗大的空中兵种，像蜻蜓产卵一样“产”下爆弹。',
 d:'外形像巨脉蜻蜓，本该长翅膀的地方换成了装满漂浮气体的气囊，粗大的尾部里有合成新型爆弹的器官——这种爆弹结合了水母的压缩气体和多种炸药成分，是琳专门为提升爆炸威力设计的。印加战争里，轰炸者夺取了全部制空权：喷沙虫死伤惨重、爆甲被大量消耗以后，再没有谁拦得住它们，爆弹像雨点一样从空中落下。',
 ch:'卷一《朝深渊进攻》《轰炸》《围攻裂地》', rel:['ev_war','inca','bujizhe','ronglie','liedizhe']},
{id:'bujizhe', n:'补给者', c:'琳的造物', r:'north', e:[2], ll:[24.5,-3.5],
 s:'体型是轰炸者两倍的空中补给兵，撒下会漂浮的绿色养分小球。',
 d:'轰炸者能迅速组合出各种爆弹，体内的养分储藏却不多。补给者一般在轰炸者群头顶绕圈飞，放出大量把养分压缩在一起的浓缩小球，轰炸者吃下就能继续制造爆弹。围攻裂地者时，轰炸者几乎耗尽了能量，琳从后面叫来补给者，给每个轰炸者喂养分。',
 ch:'卷一《轰炸》《围攻裂地》《出航之前》', rel:['hongzhazhe','liedizhe']},
{id:'ronglie', n:'融裂者', c:'琳的造物', r:'north', e:[2,3], ll:[22.5,-5.5],
 s:'混在溶解液爆弹里的小兵种：十厘米长，身体像个囊，六根节肢跑得飞快。',
 d:'每个爆弹里大约藏着十只。爆弹炸裂后它们爬出来，先用皮肤迅速吸收洒在周围、没溅到敌人的溶解液，膨胀到原来的两倍，再冲向附近的目标。对付裂地者时，它们分泌高黏性的粘液，黏在发亮的铠甲上爬行，寻找裂地者的呼吸孔，裂地者用喷气也很难把它们吹掉。',
 ch:'卷一《轰炸》《星空翻滚者的传说》《刺客之路》', rel:['hongzhazhe','liedizhe']},
{id:'dunaozhe', n:'读脑者', c:'琳的造物', r:'north', e:[2,3], ll:[20.6,-12.4],
 s:'外形像水母，用细长尖锐的触须接上别的生物的神经，读取它的思绪。',
 d:'为了弄清印加虫群到底在想什么，琳把读脑者放在一只眼虫的头上：触须刺穿皮层，找到连接身体的每一条神经线，切断以后把自己接上去，琳就能接收它的脑部信号——‘收到是一回事，看懂是另一回事’。后来琳常把穿透者注入猎物体内，让它慢慢占据大脑，再做出读脑者去控制它。',
 ch:'卷一《掀开你的脑》《生物之脑》', rel:['heifeng','inca']},
{id:'shengtan', n:'声探者', c:'琳的造物', r:'north', e:[2], ll:[19.6,-13.6],
 s:'一米长、用声音探测环境、还能发光的“炮灰型”小兵种。',
 d:'贝希摩斯在印加巨坑的边缘降落，射出倒钩触须扎进沙里稳住身体，然后放出成群的声探者。它们结构简单、可以大量制造，琳喜欢拿它们去试探有没有陷阱，或者单纯拿来耗对手的体力。声探者分散开来，沿着阶梯探索每一个洞穴，寻找印加虫群的踪迹；巨坑水里一种长颈的生物能轻松杀死一个声探者。',
 ch:'卷一《巨口中的秘密》《印加起源》', rel:['inca_pit','behemoth','inca']},
{id:'shentou', n:'渗透者 · 变形者', c:'琳的造物', r:'north', e:[2,3], ll:[22,-11],
 s:'会变色、能隐藏气味、能变成任何形状的潜入兵种。',
 d:'渗透者是琳照着记忆里“变形虫”的样子造的：一团细胞，每个细胞都包着防漏水的胶质物，没有固定的结构和器官，能穿过任何缝隙，被切成几段也没关系。可钻进印加虫群洞穴的两个渗透者还是被吃掉了。后来琳在一只蝾螈体内造出了变化更快的变形者，皮层的胶质物能完全封住气味；被印加虫群识破以后，琳又让它每隔一段时间换一种气味。琳的思绪里总冒出“史莱姆”这个词，可它从没见过那样的生物。',
 ch:'卷一《变化》《云上的水母》《树中虫穴》', rel:['inca','under']},
{id:'kongjiang', n:'空降仓', c:'琳的造物', r:'north', e:[2], ll:[26.4,-1.2],
 s:'内部充满黏糊胶质物的圆形壳质“降落舱”，让贝希摩斯能从千米高空投下陆军。',
 d:'贝希摩斯打开出兵口投下空降仓，撞击地面后它缓缓裂开，三米长的粉碎者从里面走出来开始挖掘沙地。对付深沙巴士时，空降仓又成了“锚”：深沙巴士身上粘了太多空降仓，卡在洞口钻不进去；贝希摩斯射出数十条钩线，精准地命中每一个空降仓，等粘液硬化稳固，再全力上升，把这头巨物拉离了地面。',
 ch:'卷一《一亿年前的遗失物》《深沙恐高者》', rel:['behemoth','shenshabus']},
{id:'tuke', n:'涂壳者', c:'琳的造物', r:'north', e:[2,3,4], ll:[31.6,6.6],
 s:'体内能分泌多种壳质物、再从嘴里喷射出去的“工程兵”。',
 d:'上百个涂壳者曾爬在一个巨型兵种身上，替它完成最后的工程——那个兵种需要很完美的壳，比贝希摩斯难造得多，琳还挖了一个很长的洞穴才放得下它。巨虫时代结束时，鸣石砸裂了琳用蛛丝加固的氧气堡垒，也是涂壳者去修补的。',
 ch:'卷一《往地底前进》《巨虫时代的终结》；卷二《温暖的月光》', rel:['hometree','mingshi','mingshikt']},

/* ---------- 卷一 · 恐龙大陆纪 ---------- */
{id:'cishazhe', n:'刺杀者', c:'琳的造物', r:'sea', e:[3], ll:[29.4,-103.4],
 s:'专门来刺杀瘟疫真菌的“脑”的新兵种，身上藏着许多“暗器”。',
 d:'部队的前锋，身长一米半，外表和猎食者相似，能变色、模拟气味。它们从三号岛边缘的海滩爬上岸，在铺满菌丝的地面和巨大的蘑菇之间以缓慢的步伐前进，躲开真菌的“目光”和蘑菇伞下东张西望的大眼龙。后来琳让刺杀者发出光芒，钻进瘟疫之首所在的泥质洞穴调查，一直走到连通所有岛屿的海底洞穴，在那里遇见了深渊古鱿。',
 ch:'卷一《刺客之路》《登陆战役》《深渊的洞穴》', rel:['fungus','plague','dayanlong','shenyuanguyou','wenyizhishou']},
{id:'zhenjunguai', n:'真菌怪', c:'物种', r:'sea', e:[3], ll:[30.8,-102.6],
 s:'看上去像真菌聚合体的怪物，能用双腿站起来，一挥手就打断猎食者的节肢。',
 d:'它发出像水中气泡一样的“咕……”声。瘟疫真菌竟能拼出这样的构造？琳觉得应该另有原因。真菌怪组成了瘟疫最后的军队，还有会飞的“空军”；真菌之岛的海岸燃起熊熊烈火，把它们挡在了海上，冥河巨炮把炮身抬得高高的，往火海里打特制爆弹。岛上遍地是破开的菌怪囊。',
 ch:'卷一《吞噬》《瘟疫最后的军队》《短暂的胜利》', rel:['plague','fungus','mingheju','wenyizhishou']},
{id:'dayanlong', n:'大眼龙', c:'物种', r:'sea', e:[3], ll:[29.6,-104.8],
 s:'半米长、眼睛特别大的爬行类，蹲在宽大的蘑菇伞下替真菌放哨。',
 d:'三号岛上，几乎所有真菌怪都去打仗了，只有大眼龙留在蘑菇伞下，左看右看，提防有谁闯进来。琳的刺杀者慢慢从它们中间走了过去，没有引起注意；大眼龙没看到敌人，却也一直没有离开空地。',
 ch:'卷一《刺客之路》《登陆战役》', rel:['cishazhe','fungus']},
{id:'shenyuanguyou', n:'深渊古鱿', c:'物种', r:'sea', e:[3], ll:[29,-106.4],
 s:'瘟疫之岛海底洞穴里的蓝环古鱿，比北之大陆的古鱿大两倍。',
 d:'二十厘米长，全身有不随变色改变的蓝色圆环斑纹，十只一群待在水坑里，倒过来好奇地打量刺杀者。琳本想叫它们“蓝环古鱿”，觉得没意思，就叫深渊古鱿。洞穴深处，它们围着一块结晶一圈圈排好队列，挥舞触手、变换色彩，整齐地一起跳舞——看上去实在很……诡异。',
 ch:'卷一《深渊的洞穴》《被崇拜的脑》《轰鸣之后》', rel:['guyou','cishazhe','menglian','plague']},
{id:'tanzuan', n:'探钻者', c:'琳的造物', r:'sea', e:[3], ll:[29.8,-105.6],
 s:'能钻进别的生物的“脑”里四处调查的探测兵种，有大有小。',
 d:'瘟疫之岛的地下有两个互相争斗的“脑”：大的靠地上传下来的养分不停繁殖军队，小的几乎百分之百在运转，掠取大脑的养分来产生部队——它们的军队都无视琳的探钻者，彼此争斗的执念太强烈了。微型探钻者把整个脑仔仔细细逛了一圈，再回到停在脑上方的那个较大的探钻者体内。‘它们那场没完没了的仗，该结束了。’',
 ch:'卷一《脑与脑的争斗》《结晶与决定》《宝藏的真面目》', rel:['plague','fungus','dunaozhe']},
{id:'menglian', n:'梦连者', c:'琳的造物', r:'sea', e:[3], ll:[5.6,-36.4],
 s:'“梦境连接者”的简称：伪装成古鱿、能把对方拉进梦境的兵种。',
 d:'它长得和古鱿一模一样，也有类似古鱿的能力。古鱿用变色交谈，琳也研究过——深渊古鱿和北之大陆古鱿的语言不同，能变的颜色却一样。在梦境之中的折磨里，梦连者紧紧抓住蒙特二世，任它展开翅膀连续往墙上撞了五次也甩不掉，直到对方跌落在地，一动不动。',
 ch:'卷一《梦境之中的折磨》《白色的小偷》', rel:['guyou','mtzm2','rqzj','shenyuanguyou']},
{id:'huangqunlz', n:'蝗群领主', c:'物种', r:'sea', e:[3], ll:[21,-49],
 s:'像“皇后”一样负责生产瘟疫蝗虫的水生巨物，用鳃呼吸。',
 d:'它浮出水面，身上一层薄膜膨胀到极限后炸开，大群蝗虫“哔哔”叫着飞冲而出，远处逃跑的蝗虫听见又飞了回来，围攻贝希摩斯——不过在那之前，一枚爆弹已经先飞进了蝗群，把它们炸成了一件‘艺术’。蝗虫用气孔呼吸，所以只能很小；蝗群领主用鳃呼吸，必须浮出水面才能生产，两种生物像被隔开了一样。每只蝗虫体内都有真菌。',
 ch:'卷一《瘟疫的消散》《旅途》', rel:['huangchong','plague','behemoth','art']},
{id:'yinxi', n:'音蜥', c:'物种', r:'sea', e:[3], ll:[18.4,-51],
 s:'一座几乎空了的岛上仅剩的两只大蜥蜴，会轮流跑出来敲打石块。',
 d:'岛上的大型动物只剩两只大蜥蜴和一窝小蜥蜴，足迹显示很多生物都逃到了森林后方的悬崖边，痕迹就此消失——它们跳进大海了吗？在另一座“曾是生命的岛屿”上，飘来飘去的轰炸者在一具骨架后面发现了一只同种的蜥蜴，还活着，便用节肢把它抱起来飞了回去。',
 ch:'卷一《血腥的风暴》《曾是生命的岛屿》', rel:['huangchong','behemoth']},
{id:'julunchong', n:'巨轮虫', c:'物种', r:'sea', e:[3], ll:[1.4,-43.2],
 s:'蜈蚣般的巨虫，卷成直径两米的“轮”，用背甲上的环心镰钩高速翻滚。',
 d:'双子岛的右岛上，爆哮虫与蒙特祖玛的“第一场战争”：螳螂般的绿色大军被黑色飞虫的强酸之雨压制，爆哮虫们一起对天吼叫，震落了空中的飞虫。‘翻滚，打仗，赢！’巨轮虫从原野四周冲进战场，所过之处尽是残骸与鲜血，连大型虫类都挡不住。随后大地爆震，一头庞然大物从地底破土而出，把一头巨轮虫撞上了天。',
 ch:'卷一《第一场战争》《被污染的脑》', rel:['baoxiao','mtzm2','twin','naodai']},
{id:'qieroumi', n:'切肉蚁', c:'物种', r:'west', e:[3,5], ll:[1.5,-75],
 s:'恐龙大陆上分工明确的蚁群，专从伤口和嘴钻进去，从里面吃起。',
 d:'它们和扭曲丛林的蜂系出同源，也讨厌琳那种酸液的气味：琳在飞龙尸体上洒了酸液，蚁群就绕开它，团团围住了暴君巨蜥的尸体。它们腹部能发光——在一个洞穴里，大量切肉蚁占据了左边，把整个洞穴照亮，右边站着三个白骸龙，其中一个手里拿着一块血淋淋的肉。',
 ch:'卷一《愤怒与冷静》《白色的敌人》；卷二《毁灭展开》', rel:['baojun','feilong','baihai']},
{id:'huojilong', n:'火鸡龙', c:'物种', r:'west', e:[3,4], ll:[-1.4,-83],
 s:'通身红色、一米长、十公斤重的小型恐龙，骸龙部落最常吃的猎物。',
 d:'骸龙们把猎到的火鸡龙放在棚屋中间，先用尖石把鳞皮割下来叠到一边，再切割上面的肉。“鸡”好像是一种生物，可琳还没见过。很久以后，造脑怪们围着刚苏醒的白骸龙幼仔七嘴八舌：一只说它看起来很蠢，另一只问能不能吃掉它的头。另一只觉得火鸡龙的脑袋更好吃。',
 ch:'卷一《原始龙部落》《新生的白色物体》', rel:['gulong','zaonao','tako']},
{id:'yuandinglong', n:'圆顶龙', c:'物种', r:'west', e:[3], ll:[8,-73],
 s:'头比较圆的巨大长颈龙，一头重达三十多吨。',
 d:'这片大陆是大型爬行类的世界。照琳的观察，爬行类能比节肢类长得更大：除去深沙巴士、裂地者那样的特化型生物，陆地上最大的野生节肢类是熔岩蜘蛛，圆顶龙却超过了它。名字其实是琳思绪里本来就有的。塔克小时候躲在石头后面，看着族群用木刺围攻一头老而落单的圆顶龙，首领用力投出的木刺刺穿了它的喉咙。',
 ch:'卷一《追逐到尽头》《童年的阴影》', rel:['tako','gulong','hongzhu']},
{id:'sulong', n:'速龙', c:'物种', r:'west', e:[3], ll:[0.5,-79.5],
 s:'和骸龙差不多大、聪明又擅长团队合作的猎手，只靠尖牙和利爪。',
 d:'一只骸龙举着尖木对准冲出来的速龙，对方却停在半路盯着它看——左边、右边的树丛里又各走出一头，周围还藏着十只以上。骸龙抓着树枝转身就逃，速龙追了几十米就回去了：比起几十公斤的骸龙，一头一百几十公斤的原角龙划算得多。骸龙逃跑时会用上前肢，所以比速龙快一些。',
 ch:'卷一《恐龙绝不让梨》《瓶颈与雷鸣》', rel:['gulong','yuanjiao']},
{id:'yuanjiao', n:'原角龙', c:'物种', r:'west', e:[3], ll:[-2.4,-77.6],
 s:'没有角、只有后头盾的小型角龙，1.8米长，用钳子般的嘴挖植物根系。',
 d:'琳见到的角龙类都有这种嘴，骸龙会把它切下来当挖掘工具。一只骸龙拿着沾了植物毒液的尖木一路往南，悄悄绕到一头低头吃东西的原角龙身后，猛地投出树枝——树枝精准地插在了它的屁股上，原角龙惨叫一声，疯狂地奔逃起来。',
 ch:'卷一《真菌之龙》《恐龙绝不让梨》', rel:['gulong','jiaolong','sulong']},
{id:'duntou', n:'盾头龙 · 石兽龙', c:'物种', r:'west', e:[3], ll:[3.4,-80],
 s:'头部硬化成圆球的小型四足龙，总跟在长着两颗长牙的石兽龙身边。',
 d:'石兽龙成群在林间漫步，用长牙挖开树皮、刨出矮小植物的根；盾头龙只有它们一半大，跟着吃挖出来的碎屑——两种食植者形成了简单的共生。琳觉得爬行类比节肢类弱一些：没有铠甲和液压系统，皮也不够厚。原始龙一声大叫，林子里所有生物瞬间逃光——一头身高四米的巨兽冲出了丛林。',
 ch:'卷一《扫除瘟疫》', rel:['jiaolong']},
{id:'yilong', n:'炸弹翼龙', c:'物种', r:'west', e:[3], ll:[9.5,-65.5],
 s:'荒漠岩柱上翼展七米的大翼龙，喜欢借会爆炸的植物升空。',
 d:'红冠翼龙翼展两米，能看穿飞行者的变色，一叫就飞来五只同类；它们追着飞行者到一根巨大的岩柱前，却全都吓得掉头——岩柱上栖息着炸弹翼龙。它没有牙齿，一口叼住冲过来的飞行者往胃里挤；飞行者缩成球、用倒钩钩住胃壁。几千秒后，那只“死去”的翼龙自己又动了起来：翅膀和全身长满锯齿状鳞片，头被一副黑甲包住——它的身体被改造成了琳的新兵种。附近的植物炸开、种子四溅的一瞬间，炸弹翼龙展开双翅，借着冲击力升上了天空——这就是它名字的由来。',
 ch:'卷一《荒漠生态》', rel:['feilong','baojun']},
{id:'duoji', n:'多戟龙', c:'物种', r:'west', e:[3,5], ll:[7.5,-69],
 s:'三吨多重、脾气暴躁的大型角龙，挤在荒漠中的大河边喝水。',
 d:'清澈平缓的河流吸引了众多生物，炸弹翼龙也收拢双翼在河边喝水；水下突然冲出一张长满利齿的双颚，扑向的却是翼龙。繁殖季节，雄性多戟龙在河上互相搏斗、争夺繁殖权。很多恐龙的名字琳都能在思绪里找到，也有一部分是它自己起的。卷二的河边，从毛玉变来的蓝猩和多戟角龙生活在一起，靠它们挡住肉食动物。',
 ch:'卷一《荒漠生态》《远行者》；卷二《不平的待遇》', rel:['jiaolong','lanxing']},
{id:'bosaidong', n:'波塞冬龙', c:'物种', r:'west', e:[3,4], ll:[5.5,-71.5],
 s:'半个身子泡在水里、抬起头仍有二十多米高的巨大长颈龙。',
 d:'这大概是琳见过最大的恐龙，它一动，河里就一圈圈地起浪。到了雪的年代，翡翠龙给十头波塞冬龙的胸口装上装甲、背上搭起简易木塔，弩手在塔上待命——巨龙组成比树木更高的“墙壁”，和脚下的翡翠龙大军一起冲向骸龙的军队。',
 ch:'卷一《远行者》；卷二《夕阳下的战火》', rel:['emerald','gulong']},
{id:'dianzhuru', n:'电侏儒', c:'物种', r:'west', e:[3,4,5], ll:[15.5,-83],
 s:'三十厘米长、扁脸利爪、咬人带电的小型生物，像侏儒的亚种。',
 d:'雨林上方一座常被雷劈的岩山上，几个黑影扑到绒球身上撕咬，琳把液体注满每一根毛，让毛卷成甲壳般坚固。它们的尖牙会闪光、会放电，即使绒球变色也能找到它。后来电侏儒成了翡翠龙的“猎犬”：除了吃东西，总是紧张地东张西望、聆听丛林里的细微声响，负责搜寻和护卫——侏儒的智力很高，也许还能胜任更复杂的工作。',
 ch:'卷一《雨林之上》《在黑夜种下的种子》', rel:['zhuru','emerald','yalong','rongqiu_form']},
{id:'qinshizhe', n:'侵蚀者', c:'琳的造物', r:'west', e:[3], ll:[11.5,-86.4],
 s:'形似蜘蛛的微型多细胞兵种，被注射进巨大的树叶，在叶中的管道里畅游。',
 d:'浮空之球伸出一根针刺扎穿树叶，把满载侵蚀者的红色液体注入进去。叶子里有许多“骨架”支撑，大量细胞在吸收光能，管道周围还有许多不知用途的小囊。在这个微小的世界里，侵蚀者与剑蚤不断冲突：一头大剑蚤的甲壳裂了口子，成群的侵蚀者伏在上面，借着溶解液撕咬它的外壳。',
 ch:'卷一《体内的谜团》《双重共生者》《沟通不能》', rel:['jianzao','longqimu_tree']},
{id:'laoshu', n:'酪树', c:'物种', r:'west', e:[3,4,5], ll:[-3.4,-84.6],
 s:'被感染后活了下来、能自己走路的树，性情变得平和。',
 d:'大部分受感染的植物在脑波的毁灭中倒下，剩下的被创造者吞噬，只有酪树在琳的微型兵种影响下重新长出了树叶，不再传播病毒，却保持着感染变异后能自由行动的样子。卷二里，它们跟着骸龙走到水潭边，“咕……”一声把种子洒进泥土：酪树定期释放粉末，把不同树的粉末合在一起结出种子，却没有性别之分。',
 ch:'卷一《新生中的疑惑》；卷二《复苏》《单独任务》', rel:['gulong','creator','plague']},
{id:'zhaozemu', n:'沼泽木', c:'物种', r:'west', e:[3], ll:[-9.6,-80.6],
 s:'能大幅度弯曲而不折断的沼泽树，被苏苏米改造成了投石机。',
 d:'苏苏米以前从沼泽木上取树液，用于黑夜的燃烧突袭。飞立蝎在天上不肯下来，它想到了新的用法：‘借着那些树，说不定能打中它们……’翡翠龙把整棵树拉到几乎贴地，用大片树叶编成一个碗，放上石头——一松开绳索，沼泽木瞬间弹起，石头飞上天际。',
 ch:'卷一《有关变形的问题》《宝藏》《活动的攻城锤》', rel:['susumi','mukela','lixie','scorpion']},
{id:'hongshidie', n:'红石蝶', c:'物种', r:'west', e:[3], ll:[-12.6,-78.4],
 s:'立蝎之城繁殖季节漫天飞舞、散发光能的虫子；成虫不进食。',
 d:'它们从幼虫直接变成成虫，没有“蛹”这个阶段：从幼虫背上长出来的红石蝶先趴在地上，等翅膀一点点撑开，然后只为繁殖而飞。它们散发的光能被立蝎的结晶吸收；毛玉也记得它们什么时候繁殖，就趁这时大规模冲出来猎食。看着所有立蝎都在欢呼，琳悄悄带着苏苏米退了出去。',
 ch:'卷一《首领的成就》', rel:['lixie','scorpion','susumi','maoyu']},
{id:'luoxuanying', n:'螺旋蝇', c:'物种', r:'west', e:[3], ll:[-11,-79.6],
 s:'原本住在白骸龙之岛海边、一次产下三四百颗卵的危险蝇类。',
 d:'幼虫以尸体为食，没有尸体就吃各种腐烂物，附近有活物的话还可能钻进体内吞食血肉、咬穿内脏。晶狂的部队把它们装在箱子里带到大陆，放出来的黑色小虫像烟雾一样，追着亚龙的气味飞到立蝎之城——苏苏米在一座金字塔下的广场上养着许多亚龙。这是一场“气味大作战”。',
 ch:'卷一《气味大作战》', rel:['jingkuang','yalong','susumi','scorpion']},
{id:'didanchong', n:'地弹虫', c:'物种', r:'west', e:[3], ll:[6.6,-78.6],
 s:'形状像弹头、体内有防寒脂肪的地下生物，能溶解琳基地的外壳。',
 d:'这片大陆温度不低，生物大多没有抗寒能力（毛玉有毛，是例外），所以琳怀疑它来自很冷的地方，也许是海里——它身上还留着在海里生活用的器官。琳用脑波吸引它，让细胞在它体内分裂、慢慢吞掉整只地弹虫，再从壳上挖个小洞钻出来：外面刺眼极了，它最终钻到了地面上一节空心的枯木里。',
 ch:'卷一《探索之路》《寻找脑的弹头》《夜晚偷袭者》', rel:['west','rongqiu_form']},
{id:'jueyuan', n:'掘渊者', c:'琳的造物', r:'west', e:[3], ll:[3.6,-71.2],
 s:'能迅速刨开整个盐地的大型挖掘兵种。',
 d:'盐地有一股咸湿与干枯的味道，几乎没有任何活物，琳怎么挖都不会有太大影响——‘埋在这里的东西，会再被挖出来’。同一时间，山之王带着五千白骸龙游过大海，踏上了这片荒芜的大地。掘渊者后来捡起一块还活着的分裂脑，循着它散发的信息，找到了地面上的一个沙堆。',
 ch:'卷一《被隔绝的世界》《预言队伍》', rel:['salt','fenlienao','baihai']},
{id:'yanshenghua', n:'焰生花', c:'物种', r:'west', e:[3], ll:[5.4,-108.4],
 s:'会放火烧光周围的植物和被吸引来的虫子、再把种子弹进灰烬里的植物。',
 d:'它的种子在大量灰烬的养分里毫无竞争地成长——琳有时真怀疑它们是不是无脑生物。白骸龙会挖出焰生花的种子，给“火种”添燃料。一次火种棚屋被翻乱，火种熄灭，放焰生花的头骨也不见了，看守的白骸龙怒吼着冲了出来。',
 ch:'卷一《大陆植物生态》《火种引发的问题》', rel:['baihai','whiteisle']},
{id:'jiaoshu', n:'叫树', c:'物种', r:'west', e:[3], ll:[4.2,-111.2],
 s:'白骸龙叫它“叫树”的录音树——一颗种子能卖到一千壳。',
 d:'一种能把声音录下来、再放出来的树，白骸龙叫它“叫树”，一颗种子能卖到一千壳。晶狂带着卫兵搜查洞穴，在预言者举行仪式的房间、以及周围岩壁里的房间都找到了叫树，预言者的袋子里装满了密密麻麻的种子。叫树本来就少，还动不动就莫名死掉，所以在白骸龙的城市里卖得很贵。',
 ch:'卷一《预言的末路》', rel:['yuyan','jingkuang','baihai']},
{id:'huiyinchong', n:'回音虫', c:'物种', r:'west', e:[3], ll:[3.6,-112.8],
 s:'要听到特定的声音才会醒来、每次只活跃一阵子的生物，放出强烈的脑波。',
 d:'在晶狂审判预言者一行的刑场上，回音虫醒了过来，尖锐的叫声迅速传遍全场。普通的白骸龙只是捂着头觉得难听，被绑着的一百个白骸龙——包括预言者——却像发了疯一样大叫挣扎。晶狂只打稳赢的仗，一直离它远远的，可地上还是有个装死的白骸龙猛地跳起来，持刃刺向它的颈部。',
 ch:'卷一《疯狂的声音》《怪中有怪》', rel:['yuyan','jingkuang']},
{id:'paokexia', n:'泡壳虾', c:'物种', r:'west', e:[3], ll:[4.8,-115.2],
 s:'三米长的大型生物——白骸龙水下房屋里的气泡，就是它们造的。',
 d:'它们把卵放在黏在地面的气泡里，大概能防止海生寄生虫。白骸龙在石制大笼子一样的“海底农场”里饲养它们：用海藻把气泡粘走，掏出卵塞进别的气泡，再拿空出来的气泡补充房屋里的空气。泡壳虾吐的黏液很结实，不用力过猛气泡就不会破；它们也不会攻击白骸龙。',
 ch:'卷一《守城者》《最终兵器？》', rel:['baihai','whiteisle']},
{id:'chuandichong', n:'传递虫', c:'物种', r:'west', e:[4], ll:[4,-111.8],
 s:'白骸龙拿来“记账”的五厘米会变色的蜂类。',
 d:'它们每吃完一种种子，腹部就会显出一种鲜艳的斑点，告诉同类附近有什么食物：每种种子一种颜色，斑点的大小代表数量。白骸龙用它们记录储藏物的出入。后来有人从阳台上撒下一把从城堡顶上抓来的“传递虫”——那里可没有种任何植物；对方却说，那只是长得很像传递虫的另一个种类。',
 ch:'卷二《命运之物》《决裂》', rel:['baihai','whiteisle']},

/* ---------- 卷二 ---------- */
{id:'jingmaoyu', n:'晶毛玉 · 针毛玉', c:'物种', r:'west', e:[4,5], ll:[5,-73.5],
 s:'毛尖带着结晶、更耐寒的毛玉；以及毛硬化得像针一样的针毛玉。',
 d:'雪的年代，琳发现毛玉里出现了一种智力很高的种类，是“创造者毛玉”和晶毛玉杂交的后代：它们会跟踪、观察翡翠龙，看翡翠龙怎么生火。地下城堡的走廊上，琳的间谍撞见一群毛竖起来的针毛玉，侏儒大叫一声“哇哦！”，拿着骨棒冲了出来——它们之间的战争已经持续了很多年。后来琳的结晶构造体大多做成针毛玉的样子：扁球形、长满小尖刺，虫群难以下口。',
 ch:'卷二《冰雪之战》《变化》《偷袭》', rel:['maoyu','zhuru','emerald']},
{id:'banyu', n:'半鱼', c:'物种', r:'east', e:[5], ll:[-1,53.5],
 s:'银甲龙饲养的半站立鱼类，听得懂命令，负责推船和搬运。',
 d:'它们宽大的脚踩着沼泽，用前肢推着陷进泥里的船；脑容量比重大约0.7，智力不算高，银甲龙要在船上一直吆喝，它们才肯动。它们和银甲龙的关系，很像电侏儒和翡翠龙。地下深处的岩壁画上，半鱼也在往一个方向搬运方形的东西，旁边还画着一条特别大的鱼。',
 ch:'卷二《新的颜色，新的习惯》《地下的地下》《被定制的生命》', rel:['yinjia','silvercity']},
{id:'moni', n:'模拟者', c:'琳的造物', r:'east', e:[5], ll:[-7.6,78.6],
 s:'几乎能完全模仿任何东西——气味、形态、颜色——的跟踪兵种。被它黏上，就甩不掉了。',
 d:'岛上的脑袋虫以为已经把“琳”全部排除了，琳却依旧知道它们在哪：在那片看着光溜溜的结晶表面上，留着探雾者离开后布下的模拟者。它形态像史莱姆，即使被脑波扫过也不会被发现，个体比单细胞大得多，不容易被吹落，在低温和高温里都能生活。它们一路混进“创造之船”，贴着墙壁缓缓移动，来到许多金色箱子飞来飞去的“十字路口”。',
 ch:'卷二《无法排除的间谍》《创造之船》《构造制造装置》', rel:['creator2','spy']},
{id:'tianjing', n:'天鲸', c:'物种', r:'east', e:[5], ll:[-8.6,69.2],
 s:'在云海上跳跃、吸食云雾的透明巨兽。',
 d:'“嘭！”它从云海里跳出来，又落回云上，挥动扁平的尾巴慢慢前进。云朵般透明的身躯、扁平的鳍和尾巴，一张用来吞雾气的大嘴——琳没见过“鲸”，只知道这个词形容很庞大的生物。云上也有可怕的肉食者：“天噬”把一头天鲸的内脏整个吸进嘴里，最后只剩一层缓缓漂浮的透明外皮。',
 ch:'卷二《天之海》《云上居民》《大气的冲突》', rel:['cloudsea','guanglong','daqi']},
{id:'zhiyunzhe', n:'织云者', c:'物种', r:'east', e:[5], ll:[-12.4,66.6],
 s:'构成云海的各种微生物的统称。',
 d:'有的制造胶质物，有的分泌和收集轻气体，有的在外层收集水分，或者喷气让云海移动。它们彼此好像没什么关系，有的还会互相吃，却偏偏住到了一起，造出了云海这种东西；每个地区的云海里，微生物的构成都不一样。间谍在云下荒漠捏下一小块云吃进去，发现它和高空的云海很像，只是杂质和微生物更多。',
 ch:'卷二《云下荒漠》《暗中水道》', rel:['cloudsea','tianjing']},
{id:'yunbuchong', n:'云步虫', c:'物种', r:'east', e:[5], ll:[-6.6,71.6],
 s:'身长五米、步伐和身体都像云一样软绵绵的透明坐骑。',
 d:'白骸龙的哈斯将军骑着它在云海上集结军队，进攻被“像是蝎子一样的怪物”占领的学院。云步虫能跑，却不会飞，空水母撞过来时也躲不开；将军也没打算躲，一晃手中三十厘米长的银色合金棒，它顿时伸展成一米八长、头部尖锐的银色长矛。',
 ch:'卷二《云上的战争》《遭遇》《金色援军》', rel:['cloudpeak','baihai','kongshuimu']},
{id:'shengwuta', n:'生物之塔', c:'文明', r:'east', e:[5], ll:[-9.4,69.8],
 s:'一艘船里贯穿船身的三米粗柱子——召集生物的装置。',
 d:'船舱里堆满透明罐子，每罐里泡着一个类似“控制者”的生物，它们的脑波通过管子汇进生物之塔。这艘船先飞起来又落到远方，只是为了争取时间——那时塔还没有完成。看到印加虫群一动不动，雕像们确实想过用这艘船把它们碾碎。',
 ch:'卷二《大气召集》', rel:['tianchuan','creator2','inca']},
{id:'pangshou', n:'庞兽', c:'物种', r:'east', e:[5], ll:[-13.2,65.8],
 s:'三米多长、披着沙色铠甲的毛虫状生物，会把自己卷成球钻进沙里。',
 d:'它吃完一块漂浮的云海，就缩成一个球在沙地上急速旋转，整个隐进沙砾——其实是钻进了沙下一个宽敞的洞穴，那里有好多隧道往更深的黑暗里延伸。白骸龙的资料里提到过它，却没有详细内容。间谍找到它时，它正卷成一团睡在一个隧道口，身下露出一截像手指骨一样的白色物体。',
 ch:'卷二《云下荒漠》《遗留物》', rel:['zhiyunzhe','cloudsea']},
{id:'yanshiguai', n:'岩石怪', c:'物种', r:'east', e:[5], ll:[-17.4,77.6],
 s:'大量一米多的岩块黏成的蠕虫状巨兽，身体两侧各有一排带倒钩的石头“肢体”。',
 d:'它从沙下爆出，露出地面的部分就有六米多高，把创造者的雕像一个个撞飞、扯断——最初的雕像有几百个，和尘魔打仗损失了一部分，又被它攻击，最后只剩十几个。它外表很像月上的沙砾怪，那些岩块其实是它的甲壳。后来它钻出地面，没有吃那些尸体，只是趴在沙地上晒太阳。',
 ch:'卷二《毁灭的金属》《遥远的谜团》', rel:['chenmo','creator2','shaliguai']},
{id:'haigui', n:'海鬼', c:'物种', r:'sea', e:[5], ll:[-4,-28],
 s:'背上插着一根燃烧的“火把”、像石头一样的生物，成群在深海里飘来。',
 d:'黑暗的海床上亮起一点光，接着周围的水里到处都亮了起来，像无数火把在水中燃烧。它们有类似节肢类的内脏，外壳是岩石般的壳质物。火把其实是根空心管，里面塞满它们自己的排泄物：底部把水分吸干往上推，顶部点燃——外面有一层透明的壳，所以在水里也能烧。每一团火光附近都跟着大群怪鱼，一起包围了贝希摩斯，却没有进攻。',
 ch:'卷二《深渊的绑架者》', rel:['behemoth']},
{id:'donggua', n:'冬瓜（侏儒）', c:'物种', r:'west', e:[5], ll:[4.6,-112.6],
 s:'银甲龙传说里记载的一种生物——其实就是侏儒。',
 d:'银甲龙的远征队登上白骸龙的旧岛，来到布满裂痕、长满植物的“王之城堡”，想去见证真正的创造者。有生物激动地认出来：这就是传说里记载的‘冬瓜’！阳台上的冬瓜大叫一声“哇哦！”，扔下一个像球一样的东西——它在队长手里猛地爆开，把队长震倒在地。后来一大群冬瓜拿着骨棒和球状物体冲到停船的浅水处，在船边跳来跳去，却怎么也爬不上船。',
 ch:'卷二《银色远征者》《矮小崛起》《最后的测试》', rel:['zhuru','yinjia','whiteisle']},
{id:'lanxing', n:'蓝猩', c:'物种', r:'west', e:[5], ll:[7.2,-70.6],
 s:'长满蓝色绒毛、两米长、尾巴毛茸茸的生物——很难想象它们是从毛玉变来的。',
 d:'它们和脾气暴躁的多戟角龙生活在一起，角龙替它们挡住肉食动物——蓝猩是大型翼龙最喜欢的猎物。一个闪着金光的毛玉沿着河流急速飞来检索目标，被打了下来；两个蓝猩分别抓住它的头和尾，用力拉扯，毛玉愤怒地发出声音：‘待遇……不公平……’',
 ch:'卷二《不平的待遇》', rel:['maoyu','duoji','jiaolong']},
{id:'shaliguai', n:'沙砾怪', c:'物种', r:'moon', e:[4,5], moon:[18,40],
 s:'月上的生物：许多小沙砾的聚合体，靠空气里飘荡的灰尘为食。',
 d:'体内没有器官，体表有很多小孔，通过细胞运动吸收空气中的水分和食物，像原始的滤食生物。月上的生物大多不用氧气，被带到绒球上可能会因为不适应大气而死——除了创造者和沙砾怪。琳让利维坦待在月上的灰烬之岛，大量吸收、分解那里的灰尘作为养分。',
 ch:'卷二《生命的尘土》《环球旅行》', rel:['moon','baigaojun','baigao']},
{id:'baigaojun', n:'白膏菌', c:'物种', r:'moon', e:[4], moon:[-10,-20],
 s:'月上水坑里分解灰尘、制造白膏的菌类——创造者带着的就是它们。',
 d:'这里的白膏跟琳从前见过的不同：里面有一种基础的毒素，会破坏细胞的合成系统，对月上和绒球上的生物都有效，对它们自己却没有作用——它们造白膏是为了储藏，不是给别的生物吃的。琳打算让陨石洞穴里的“萝卜”大量繁殖，挑出能和白膏菌共生的种类，再培育出能在虚空中生活的生物。',
 ch:'卷二《生命的尘土》《目标确定》《无数的日出》', rel:['baigao','moon','creator']},

/* ---------- 卷三：虚民母球 · 黑金属之战 ---------- */
{id:'xm_heijiao', n:'黑角龙 · 肯陶', c:'物种', m:'ximin', r:'xm_main', e:[6], ll:[33,14],
 s:'黑金属入侵母球时的“骑兵”：头盾坚硬、成群狂奔冲锋的黑色角龙。',
 d:'虚民看到对方骑乘冲锋，不由得有些奇怪——虚民觉得，只有最原始的生物才会这么打仗，那是它们不知多少年前就抛弃了的方法。金属弹头打在黑角龙的头盾上溅起无数火花，战车主炮把一些庞大的角龙炸飞，与此同时，无数巨大的黑色长矛从天而降。黑角龙只是“肯陶”里的主要物种：和骸龙的群落一样，肯陶也驯服了许多当地生物用于战斗。',
 ch:'卷三《原始的部队》《逼近》《战舰建成》', rel:['xm_coral','xm_cult','xm_tiefu','xm_jiale']},
{id:'xm_tiefu', n:'铁蝠', c:'物种', m:'ximin', r:'xm_main', e:[6], ll:[35,17],
 s:'被肯陶驯服的飞行生物：翼展五米多，身上覆盖着薄薄的金属片，牙齿能粉碎金属。',
 d:'它们长得像毛玉进化成的“蝙蝠”。据说原本是橄榄形的，翅膀短小、固定不能动，是黑金属把它们改造成了更适合灵活作战的样子，性格却没变：大规模冲向目标，用嘴里的牙撕裂一切。虚民的机甲很克制地上的黑角龙，面对铁蝠的围攻却完全无法抵抗，飞行机甲部队一下就崩溃了。',
 ch:'卷三《逼近》《胜利的曙光》', rel:['xm_heijiao','xm_coral']},
{id:'xm_huanwu', n:'唤雾者', c:'琳的造物', m:'ximin', r:'xm_main', e:[6], ll:[31,14.5],
 s:'鲨鱼形状的飞行兵种，从原本是“鱼鳃”的地方放出大量活着的雾气。',
 d:'第二场战斗，天空不再鲜红，整个战场被一层浓雾笼罩。黑金属和虚民都陷入了迷惑，庞大的黑角龙停止冲锋，在地上疑惑地移动——琳却看得非常清楚，因为这些雾气都是活的，下一刻就向黑金属发起了冲锋。虚民其实认识这种鲨鱼，只能说它们“忘记了”。',
 ch:'卷三《笼罩》', rel:['xm_heijiao','xm_union','c_lin3']},
{id:'xm_xuanfu', n:'悬浮王9000 · 信使', c:'文明', m:'ximin', r:'xm_main', e:[6], ll:[33.5,20],
 s:'虚民军队的圆盘形飞行器，以及负责传递命令的飞行器“信使”。',
 d:'通讯中断后，将军冲进前线指挥室，下令出动信使联络附近所有部队：“发起进攻！”五架悬浮王9000在焦烟弥漫的天空下掠过，目标是远处城市里那头庞大的怪物——巨型晶蜴。飞近时驾驶员发现，怪物身下有一个极速旋转的钻头正钻进它的腹部：“它好像是在帮我们……”',
 ch:'卷三《轰隆》《临场指挥》《全力全开》', rel:['xm_jiale','v_jingyi','xm_union']},

/* ---------- 卷三：绒球 · 南之大陆 ---------- */
{id:'rq_ranjin', n:'燃尽者', c:'物种', r:'south', e:[6], ll:[-60,-4],
 s:'脑灵的部队：五十多米高、头上有三个洞、下半身没有肢体而飘浮在空中。',
 d:'教长带着玛雅飞过南之大陆，一片平原上爬满了“枯萎者”：它们啃食尸体和一切由细胞构成的东西，让整个世界慢慢枯萎下去，连菌类都少了——据说脑灵偶尔会对某些世界这样做。真正的战斗部队在更远处：成千上万的燃尽者整齐地排列着，像在等待什么。它们看上去有点像瘟疫之首，负责攻击绒球表面的生命，体型不算巨大，却含有大量能量，“它们可以把这个世界烧掉”。',
 ch:'卷三《加入它们？》《被染色的世界》', rel:['rq_south','rq_blackcity','c_maya','jiaozhang']},

/* ---------- 卷三：虚空 · 星区七 ---------- */
{id:'v_xiaohuhe', n:'小护核者', c:'物种', m:'void', sec:7, e:[7,8,9,10,11,12], p:[-370,70,-150], k:'swarm', kp:{n:46,s:34,c:'#fff2a8'},
 s:'发着光、飞得飞快、嘴碎得不得了的小梦境生物——口头禅是“守护不能”。',
 d:'它们在创造者的梦境空间里绕着一棵巨大的“树”飞来飞去，被关进笼子也能逃出来，到处啰嗦不断。雾气类掠食者最爱吃发光的梦境生物，却抓不到它们。它们会判断一样东西“能不能守护”：不能守护的地点就立刻离开，不能守护的活物就冲上去试图杀死——杀不掉，就展开连续的信息轰炸，足以让造脑怪发疯。教长据此造出了“小护核者枪”。后来它们几乎一路跟着琳：它急着嚷：这些东西太碍事了，快扔掉，不然就没法守护了。',
 ch:'卷三《神之地的疑问》《很有效果》《击中》', rel:['v_huhe','jiaozhang','v_lingjian','c_lin3']},
{id:'v_lingjian', n:'零件战舰 · 智能机械', c:'物种', m:'void', sec:7, e:[7], p:[-100,40,440], k:'ship', kp:{s:16,c:'#8a8f96'},
 s:'八十多米长、表面布满密集细碎金属零件的“战舰”，虚民的导弹都炸不坏。',
 d:'它和许多小型飞行器一起进攻虚民营地，琳的绒球射出长矛般的绒毛，穿透了所有小飞行器。藏忆者里流行制造“智能机械”，用它们做包括战斗在内的各种事情。琳俘获了一个智能机械，拿教长送来的“小护核者”装置拷问它；它带琳找到了三号门，自己却非常害怕门后的黑暗世界，一个劲地说不能去、别往前走、快回去。',
 ch:'卷三《袭击》《文明的变化》《很有效果》《门的那边》《没有如果》', rel:['v_lianjie','v_cangyi','v_xiaohuhe','v_door3']},
{id:'v_door3', n:'三号门 · 黑暗世界', c:'地理', m:'void', sec:7, e:[7], p:[-210,-50,520], k:'portal', kp:{c:'#3a3a52',dark:1},
 s:'一扇“门”：门后没有光、几乎没有引力，冷得能让氧气变成液体，空气里满是尘埃。',
 d:'印加虫群的部队先进去了。零件战舰太大进不了门，琳只让它的一小部分跟着。黑暗世界里，琳只见到了一种生物——“飘浮皮”：飘在空中的一块又软又薄的皮，不是细胞做的，而是一种很轻的物质，到了门这边的细胞生物区域就会慢慢融化。琳把一块带回虚民营地的地下研究所，用低温装置保存起来。',
 ch:'卷三《门的那边》《特殊的武器》《更多的资料》', rel:['v_lianjie','v_lingjian','inca']},
{id:'v_ruanjiao', n:'软胶战舰 · 探索石', c:'物种', m:'void', sec:7, e:[7], p:[-620,30,-340], k:'blob', kp:{r:24,c:'#9ad8c8'},
 s:'凝胶生物直径七百米的胶块“战舰”；以及琳从攻击石里放出、四处搜寻的探索石。',
 d:'飘浮岩区里，微型机械聚成的“机械雾团”只要发现琳的部队稍微一动，就会在探测到的瞬间把目标击毁。琳全面进攻时，软胶战舰飞得远远的，像是有意躲开这场战争；打完了又慢慢飞回来，像来检查战况。它靠近一块攻击石时，攻击石猛地飞出，绕到了它的身后……之后琳放出大量探索石，飞往机械雾团的位置，寻找微型机械藏在岩石里的基地。',
 ch:'卷三《没有硝烟的战场》《火光之后》《侦测与追踪》', rel:['v_piaofu','v_edgeeye','v_shenmin']}
);

